//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

/******************************************************************************\
* Author: Nick Mudge <nick@perfectabstractions.com> (https://twitter.com/mudgen)
* EIP-2535 Diamonds: https://eips.ethereum.org/EIPS/eip-2535
/******************************************************************************/

import {LibDiamond, IDiamondCut, IDiamondInit, IDiamondPause} from "../libraries/LibDiamond.sol";
import {LibAccessControl} from "../libraries/LibAccessControl.sol";
import {Versionable} from "../lib/Versionable.sol";

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

/// @author TermLabs
/// @title DiamondCutFacet
/// @notice Facet for managing diamond upgrades and pause functionality
/// @dev Implements EIP-2535 Diamond Standard for adding, replacing, and removing functions
/// @dev Provides pause/unpause functionality to halt diamond operations in emergency situations
contract DiamondCutFacet is
    IDiamondCut,
    IDiamondInit,
    IDiamondPause,
    AccessControl,
    Versionable
{
    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when diamond is already paused
    error AlreadyPaused();

    /// @notice Thrown when attempting to initialize diamond roles that are already initialized
    error DiamondRolesAlreadyInitialized();

    /// @notice Thrown when diamond is not paused
    error NotPaused();

    /// @notice Thrown when caller is not the deployer wallet
    error OnlyDeployerCanCall();

    /// @notice Thrown when function is called outside of the deployment block
    error OnlyCallableInDeployBlock();

    address immutable deployerWallet;
    uint256 immutable deployBlockNumber;

    constructor() {
        deployerWallet = msg.sender;
        deployBlockNumber = block.number;
    }

    /// @notice Initializes diamond access control roles and supported interfaces
    /// @dev This function is intended to be called only via delegatecall during diamond
    ///      construction. The msg.sender check ensures it can only be called from within
    ///      the diamond contract itself, preventing external role hijacking attacks.
    /// @dev Registers ERC-165 and IDiamondCut interface support
    /// @param devopsWallet_ Address to be granted the DEVOPS_ROLE
    /// @param adminWallet_ Address to be granted the ADMIN_ROLE
    function initDiamond(address devopsWallet_, address adminWallet_) external {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (ds.diamondRolesInitialized) revert DiamondRolesAlreadyInitialized();
        if (msg.sender != deployerWallet) revert OnlyDeployerCanCall();
        if (block.number != deployBlockNumber)
            revert OnlyCallableInDeployBlock();

        _grantRole(LibAccessControl.DEVOPS_ROLE, devopsWallet_);
        _grantRole(LibAccessControl.ADMIN_ROLE, adminWallet_);

        // Register supported interfaces for ERC-165
        ds.supportedInterfaces[type(IDiamondCut).interfaceId] = true;
        ds.supportedInterfaces[type(IERC165).interfaceId] = true; // ERC-165 interface ID

        ds.diamondRolesInitialized = true;
    }

    /// @notice Add/replace/remove any number of1 functions and optionally execute
    ///         a function with delegatecall
    /// @param _diamondCut Contains the facet addresses and function selectors
    /// @param _init The address of the contract or facet to execute _calldata
    /// @param _calldata A function call, including function selector and arguments
    ///                  _calldata is executed with delegatecall on _init
    function diamondCut(
        FacetCut[] calldata _diamondCut,
        address _init,
        bytes calldata _calldata
    ) external override onlyRole(LibAccessControl.DEVOPS_ROLE) {
        LibDiamond.diamondCut(_diamondCut, _init, _calldata);
    }

    /// @notice Pauses the diamond contract
    /// @dev Only callable by accounts with ADMIN_ROLE
    /// @dev Reverts if the diamond is already paused
    function pauseDiamond() external onlyRole(LibAccessControl.ADMIN_ROLE) {
        if (LibDiamond.diamondStorage().diamondPaused) revert AlreadyPaused();

        LibDiamond.diamondStorage().diamondPaused = true;
        emit DiamondPaused();
    }

    /// @notice Unpauses the diamond contract
    /// @dev Only callable by accounts with ADMIN_ROLE
    /// @dev Reverts if the diamond is not paused
    function unpauseDiamond() external onlyRole(LibAccessControl.ADMIN_ROLE) {
        if (!LibDiamond.diamondStorage().diamondPaused) revert NotPaused();

        LibDiamond.diamondStorage().diamondPaused = false;
        emit DiamondUnpaused();
    }
}

contracts/facets/DiamondLoupeFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;
/******************************************************************************\
* Author: Nick Mudge <nick@perfectabstractions.com> (https://twitter.com/mudgen)
* EIP-2535 Diamonds: https://eips.ethereum.org/EIPS/eip-2535
/******************************************************************************/

import {LibDiamond} from "../libraries/LibDiamond.sol";
import {Versionable} from "../lib/Versionable.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

/// @title IDiamondLoupe
/// @notice Interface for diamond introspection functions
/// @dev Provides functions to query facet addresses and function selectors
interface IDiamondLoupe is IERC165 {
    /// @notice Struct containing facet address and its function selectors
    /// @param facetAddress The address of the facet contract
    /// @param functionSelectors Array of function selectors supported by the facet
    struct Facet {
        address facetAddress;
        bytes4[] functionSelectors;
    }

    /// @notice Gets all facet addresses and their four byte function selectors.
    /// @return facets_ Facet
    function facets() external view returns (Facet[] memory facets_);

    /// @notice Gets all the function selectors supported by a specific facet.
    /// @param _facet The facet address.
    /// @return facetFunctionSelectors_
    function facetFunctionSelectors(
        address _facet
    ) external view returns (bytes4[] memory facetFunctionSelectors_);

    /// @notice Get all the facet addresses used by a diamond.
    /// @return facetAddresses_
    function facetAddresses()
        external
        view
        returns (address[] memory facetAddresses_);

    /// @notice Gets the facet that supports the given selector.
    /// @dev If facet is not found return address(0).
    /// @param _functionSelector The function selector.
    /// @return facetAddress_ The facet address.
    function facetAddress(
        bytes4 _functionSelector
    ) external view returns (address facetAddress_);

    /// @notice Returns the current pause state of the diamond
    function diamondPaused() external view returns (bool);
}

/// @author TermLabs
/// @title DiamondLoupeFacet
/// @notice Provides introspection functions for the Diamond Standard
/// @dev Implements EIP-2535 Diamond Loupe interface for querying facet information
/// @dev These functions are expected to be called frequently by tools and interfaces
contract DiamondLoupeFacet is IDiamondLoupe, Versionable {
    /// @notice Gets all facets and their selectors.
    /// @return facets_ Facet
    function facets() external view override returns (Facet[] memory facets_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 numFacets = ds.facetAddresses.length;
        facets_ = new Facet[](numFacets);
        for (uint256 i; i < numFacets; i++) {
            address facetAddress_ = ds.facetAddresses[i];
            facets_[i].facetAddress = facetAddress_;
            facets_[i].functionSelectors = ds
                .facetFunctionSelectors[facetAddress_]
                .functionSelectors;
        }
    }

    /// @notice Gets all the function selectors provided by a facet.
    /// @param _facet The facet address.
    /// @return facetFunctionSelectors_
    function facetFunctionSelectors(
        address _facet
    ) external view override returns (bytes4[] memory facetFunctionSelectors_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facetFunctionSelectors_ = ds
            .facetFunctionSelectors[_facet]
            .functionSelectors;
    }

    /// @notice Get all the facet addresses used by a diamond.
    /// @return facetAddresses_
    function facetAddresses()
        external
        view
        override
        returns (address[] memory facetAddresses_)
    {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facetAddresses_ = ds.facetAddresses;
    }

    /// @notice Gets the facet that supports the given selector.
    /// @dev If facet is not found return address(0).
    /// @param _functionSelector The function selector.
    /// @return facetAddress_ The facet address.
    function facetAddress(
        bytes4 _functionSelector
    ) external view override returns (address facetAddress_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facetAddress_ = ds
            .selectorToFacetAndPosition[_functionSelector]
            .facetAddress;
    }

    /// @notice Returns the current pause state of the diamond
    /// @return True if the diamond is paused, false otherwise
    function diamondPaused() external view returns (bool) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        return ds.diamondPaused;
    }

    /// @notice Checks if the contract implements an interface
    /// @dev Implements ERC-165 interface detection standard
    /// @param _interfaceId The interface identifier to check
    /// @return True if the interface is supported, false otherwise
    function supportsInterface(
        bytes4 _interfaceId
    ) external view override returns (bool) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        return ds.supportedInterfaces[_interfaceId];
    }
}

contracts/facets/ERC4626InterfaceFacet.s.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {TermAtomicTxProtection} from "./base/TermAtomicTxProtection.sol";
import {ITermController} from "../interfaces/ITermController.sol";
import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";
import {LibTermStorage, TermERC4626VaultManagement, TermStorage} from "../libraries/LibTermStorage.sol";

import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";

/// @author TermLabs
/// @title ERC4626InterfaceFacet Facet
/// @notice This facet provides deposit and withdrawal functions for ERC4626 vaults
/// @dev This facet allows the TermDiamond to interact with ERC4626 compliant vaults
contract ERC4626InterfaceFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermAtomicTxProtection,
    TermMultiContextAuth,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    // ========================================================================
    // = Custom Errors  =======================================================
    // ========================================================================

    error AssetsMismatch();
    error ExpiredSignature();
    error IncorrectTargetAsset();
    error InvalidSignature();
    error InvalidVaultAsset();
    error NoAssetsReceived();
    error NoSharesReceived();
    error SharesMismatch();
    error UnapprovedVault();
    error UnsupportedSelector();
    error VaultAlreadyApproved();
    error VaultNotApproved();

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    bytes4 public constant WITHDRAW_SELECTOR =
        bytes4(
            keccak256("withdrawFromVault(address,uint256,address,bool,bool)")
        );

    bytes32 public constant VAULT_APPROVAL_TYPEHASH =
        keccak256("VaultApproval(address vault,address user,uint256 deadline)");

    // ========================================================================
    // = Modifiers ============================================================
    // ========================================================================

    /// @notice Modifier to ensure vault is approved for use (either by Term or by specific user)
    /// @param vault The address of the ERC4626 vault to check
    /// @param user The address of the user to check for vault approval
    modifier approvedERC4626VaultOnly(address vault, address user) {
        TermERC4626VaultManagement storage tevm = LibTermStorage
            .termERC4626VaultManagement();
        TermStorage storage ts = LibTermStorage.termStorage();

        // Check if vault is approved by any Term controller
        bool isTermApproved;
        for (uint8 i = 0; i < ts.approvedTermControllerList.length; ++i) {
            if (
                ITermController(ts.approvedTermControllerList[i])
                    .isTermApproved(vault)
            ) {
                isTermApproved = true;
                break;
            }
        }

        // Check if vault is term approved OR user approved
        if (!isTermApproved && !tevm.userApprovedERC4626Vaults[user][vault]) {
            revert UnapprovedVault();
        }

        _;
    }

    // ========================================================================
    // = Deploy ===============================================================
    // ========================================================================
    constructor() {
        previewMapping[this.depositToVaultHook.selector] = this
            .previewDeposit
            .selector;
        previewMapping[this.redeemFromVaultHook.selector] = this
            .previewRedeem
            .selector;
    }

    // ========================================================================
    // = Vault Functions  =====================================================
    // ========================================================================

    /// @notice Deposit assets into an ERC4626 vault
    /// @notice Consider using previewDeposit() before calling this function to account for potential slippage
    /// @param vault The address of the ERC4626 vault contract
    /// @param assets The amount of assets to deposit
    /// @param usePermit2 Whether Permit2 was used for approval
    /// @return shares The amount of shares minted
    function depositToVault(
        address vault,
        uint256 assets,
        bool usePermit2
    )
        external
        nonReentrant
        approvedERC4626VaultOnly(vault, msg.sender)
        returns (uint256)
    {
        IERC4626 vaultContract = IERC4626(vault);
        IERC20 asset = IERC20(vaultContract.asset());

        if (usePermit2) {
            // Approve via Permit2
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                assets.toUint160(),
                address(asset)
            );
        } else {
            // Transfer assets from user to this contract
            asset.safeTransferFrom(msg.sender, address(this), assets);
        }

        return _depositToVault(vault, address(asset), assets, msg.sender);
    }

    /// @notice Withdraw assets from an ERC4626 vault
    /// @notice This function uses previewWithdraw() to calculate required shares and account for potential slippage
    /// @param vault The address of the ERC4626 vault contract
    /// @param assets The amount of assets to withdraw
    /// @param usePermit2 Whether Permit2 was used for approval
    /// @return shares The amount of shares burned
    function withdrawFromVault(
        address vault,
        uint256 assets,
        bool usePermit2
    )
        external
        nonReentrant
        approvedERC4626VaultOnly(vault, msg.sender)
        returns (uint256)
    {
        return
            _withdrawFromVault(
                vault,
                assets,
                msg.sender,
                msg.sender,
                usePermit2
            );
    }

    /// @notice Withdraw assets from an ERC4626 vault
    /// @notice This function uses previewWithdraw() to calculate required shares and account for potential slippage
    /// @param vault The address of the ERC4626 vault contract
    /// @param assets The amount of assets to withdraw
    /// @param user The user address for share source
    /// @param usePermit2 Whether Permit2 was used for approval
    /// @param payoutToUser If true, assets are sent to user; if false, assets are sent to this contract
    /// @return shares The amount of shares burned
    function withdrawFromVault(
        address vault,
        uint256 assets,
        address user,
        bool usePermit2,
        bool payoutToUser
    )
        external
        onlyUserOrActiveContext(user)
        approvedERC4626VaultOnly(vault, user)
        returns (uint256)
    {
        address receiver = msg.sender != address(this) || payoutToUser
            ? user
            : address(this);

        return _withdrawFromVault(vault, assets, user, receiver, usePermit2);
    }

    /// @notice Redeem shares from an ERC4626 vault
    /// @notice This function burns exact shares and returns the corresponding assets
    /// @param vault The address of the ERC4626 vault contract
    /// @param shares The amount of shares to redeem
    /// @param usePermit2 Whether Permit2 was used for approval
    /// @return assets The amount of assets received
    function redeemFromVault(
        address vault,
        uint256 shares,
        bool usePermit2
    )
        external
        nonReentrant
        approvedERC4626VaultOnly(vault, msg.sender)
        returns (uint256)
    {
        IERC20 vaultToken = IERC20(vault);

        if (usePermit2) {
            // Approve via Permit2
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                shares.toUint160(),
                address(vaultToken)
            );
        } else {
            // Transfer shares from user to this contract
            vaultToken.safeTransferFrom(msg.sender, address(this), shares);
        }

        return _redeemFromVaultInternal(vault, shares, msg.sender);
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Deposit assets into an ERC4626 vault via flash loan hook context
    /// @dev Shares are sent to this contract (the diamond). Only callable within a flash loan context.
    /// @param input The action hook input containing user, target vault address, and deposit amount
    /// @return The amount of shares minted
    function depositToVaultHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        nonReentrant
        approvedERC4626VaultOnly(input.targetAddress, input.user)
        returns (uint256)
    {
        if (input.inputToken != IERC4626(input.targetAddress).asset()) {
            revert InvalidVaultAsset();
        }
        return
            _depositToVault(
                input.targetAddress,
                input.inputToken,
                input.maxInputAmount,
                address(this)
            );
    }

    /// @notice Redeem shares from an ERC4626 vault via flash loan hook context
    /// @dev Assets are sent to this contract (the diamond). Only callable within a flash loan context.
    /// @param input The action hook input containing user, target vault address, and shares to redeem
    /// @return The amount of assets received
    function redeemFromVaultHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        nonReentrant
        approvedERC4626VaultOnly(input.targetAddress, input.user)
        returns (uint256)
    {
        return
            _redeemFromVaultInternal(
                input.targetAddress,
                input.maxInputAmount,
                address(this)
            );
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Generate calldata for ERC4626 vault operations
    /// @param selector The function selector to generate calldata for
    /// @param vault The address of the ERC4626 vault contract
    /// @param asset The address of the asset token (unused in current implementation)
    /// @param user The user address for the operation
    /// @param amount The amount of assets or shares
    /// @param payoutUser If true, assets are sent to user; if false, assets are sent to this contract
    /// @param data Additional calldata (unused in current implementation)
    /// @return The encoded function calldata
    function generateCalldata(
        bytes4 selector,
        address vault,
        address asset,
        address user,
        uint256 amount,
        bool payoutUser,
        bytes calldata data
    ) external view returns (bytes memory) {
        if (selector == WITHDRAW_SELECTOR) {
            if (asset != IERC4626(vault).asset()) {
                revert IncorrectTargetAsset();
            }
            return
                abi.encodeWithSelector(
                    selector,
                    vault,
                    amount,
                    user,
                    false,
                    payoutUser
                );
        } else {
            revert UnsupportedSelector();
        }
    }

    /// @notice Previews an ERC4626 deposit by computing the underlying asset amount
    ///         required to mint the desired number of vault shares.
    /// @dev Uses `vault.previewMint` to determine the deposit amount for
    ///      `actionHookInput.minOutputAmount` shares. Reverts if the vault's underlying
    ///      asset is the vault itself.
    /// @param actionHookInput The action hook input where:
    ///   - `targetAddress`: the ERC4626 vault address
    ///   - `minOutputAmount`: the desired number of vault shares to mint
    /// @return A `PreviewAction` with the vault's underlying asset as input, vault shares
    ///         as output, and `isDeterministic` set to true.
    function previewDeposit(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        IERC4626 vault = IERC4626(actionHookInput.targetAddress);
        if (vault.asset() == address(vault)) {
            revert InputOutputTokenCollision();
        }
        uint256 depositAmount = vault.previewMint(
            actionHookInput.minOutputAmount
        );
        return
            PreviewAction({
                expectedInputToken: vault.asset(),
                expectedInputAmount: depositAmount,
                expectedOutputToken: address(vault),
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    /// @notice Previews an ERC4626 redemption by computing the number of vault shares
    ///         required to withdraw the desired amount of underlying assets.
    /// @dev Uses `vault.previewWithdraw` to determine the shares needed for
    ///      `actionHookInput.minOutputAmount` of the underlying asset. Reverts if the
    ///      vault's underlying asset is the vault itself.
    /// @param actionHookInput The action hook input where:
    ///   - `targetAddress`: the ERC4626 vault address
    ///   - `minOutputAmount`: the desired amount of underlying asset to withdraw
    /// @return A `PreviewAction` with vault shares as input, the vault's underlying asset
    ///         as output, and `isDeterministic` set to true.
    function previewRedeem(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        IERC4626 vault = IERC4626(actionHookInput.targetAddress);
        if (vault.asset() == address(vault)) {
            revert InputOutputTokenCollision();
        }
        uint256 redeemShares = vault.previewWithdraw(
            actionHookInput.minOutputAmount
        );
        return
            PreviewAction({
                expectedInputToken: address(vault),
                expectedInputAmount: redeemShares,
                expectedOutputToken: vault.asset(),
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    /// @notice Approve an ERC4626 vault for individual user access via signature
    /// @param vault The address of the ERC4626 vault to approve
    /// @param deadline The signature expiry timestamp
    /// @param sigData The EIP-712 signature payload for approval
    function userApproveVault(
        address vault,
        uint256 deadline,
        bytes calldata sigData
    ) external {
        if (block.timestamp > deadline) {
            revert ExpiredSignature();
        }

        TermERC4626VaultManagement storage tevm = LibTermStorage
            .termERC4626VaultManagement();
        if (tevm.userApprovedERC4626Vaults[msg.sender][vault]) {
            revert VaultAlreadyApproved();
        }

        bytes32 structHash = keccak256(
            abi.encode(VAULT_APPROVAL_TYPEHASH, vault, msg.sender, deadline)
        );

        TermStorage storage ts = LibTermStorage.termStorage();

        bytes32 digest = keccak256(
            abi.encodePacked(hex"1901", ts.eip712DomainSeparator, structHash)
        );

        (uint8 v, bytes32 r, bytes32 s) = abi.decode(
            sigData,
            (uint8, bytes32, bytes32)
        );
        address signer = ECDSA.recover(digest, v, r, s);
        if (signer != msg.sender) {
            revert InvalidSignature();
        }

        tevm.userApprovedERC4626Vaults[msg.sender][vault] = true;
    }

    /// @notice Revoke approval of an ERC4626 vault for individual user access
    /// @param vault The address of the ERC4626 vault to revoke
    function userRevokeVault(address vault) external {
        TermERC4626VaultManagement storage tevm = LibTermStorage
            .termERC4626VaultManagement();
        if (!tevm.userApprovedERC4626Vaults[msg.sender][vault]) {
            revert VaultNotApproved();
        }
        tevm.userApprovedERC4626Vaults[msg.sender][vault] = false;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    /// @notice Internal function to deposit assets into an ERC4626 vault
    /// @dev Handles the deposit process including asset transfer, validation, and share issuance
    /// @param vault_ The address of the ERC4626 vault contract
    /// @param assetToken_ The address of the vault's underlying asset token
    /// @param assetAmount_ The amount of assets to deposit
    /// @param receiver_ The address that will receive the vault shares
    /// @return shares The amount of shares minted
    function _depositToVault(
        address vault_,
        address assetToken_,
        uint256 assetAmount_,
        address receiver_
    ) internal returns (uint256) {
        IERC4626 vaultContract = IERC4626(vault_);
        IERC20 asset = IERC20(assetToken_);
        IERC20 vaultToken = IERC20(vault_);

        // Track receiver's share balance to ensure shares are received
        uint256 preShareBalance = vaultToken.balanceOf(receiver_);

        // Track contract's asset balance BEFORE deposit to ensure all assets are consumed
        uint256 preContractAssetBalance = asset.balanceOf(address(this));

        // Approve vault to spend assets
        asset.forceApprove(vault_, assetAmount_);

        // Deposit assets and receive shares
        uint256 shares = vaultContract.deposit(assetAmount_, receiver_);

        // Revoke approval to vault after deposit
        asset.forceApprove(vault_, 0);

        uint256 postShareBalance = vaultToken.balanceOf(receiver_);
        uint256 postContractAssetBalance = asset.balanceOf(address(this));

        // Ensure receiver actually got shares and prevent asset theft
        if (postShareBalance <= preShareBalance) {
            revert NoSharesReceived();
        }

        // Validate returned shares match actual balance increase
        uint256 actualSharesReceived = postShareBalance - preShareBalance;
        if (shares != actualSharesReceived) {
            revert SharesMismatch();
        }

        // Validate exact amount of assets were consumed by the vault
        uint256 actualAssetsConsumed = preContractAssetBalance -
            postContractAssetBalance;
        if (actualAssetsConsumed != assetAmount_) {
            revert AssetsMismatch();
        }

        return shares;
    }

    /// @notice Internal function to withdraw assets from an ERC4626 vault
    /// @dev Handles the withdrawal process including share transfer, validation, and asset redemption
    /// @param vault_ The address of the ERC4626 vault contract
    /// @param assets_ The amount of assets to withdraw
    /// @param user_ The address whose shares will be used for withdrawal
    /// @param receiver_ The address that will receive the withdrawn assets
    /// @param usePermit2_ Whether to use Permit2 for share transfer approval
    /// @return shares amount of shares that were burned in the withdrawal
    function _withdrawFromVault(
        address vault_,
        uint256 assets_,
        address user_,
        address receiver_,
        bool usePermit2_
    ) internal returns (uint256) {
        IERC4626 vaultContract = IERC4626(vault_);
        IERC20 vaultToken = IERC20(vault_);
        IERC20 asset = IERC20(vaultContract.asset());

        // Track receiver's asset balance to ensure assets are received
        uint256 preAssetBalance = asset.balanceOf(receiver_);

        uint256 sharesToRedeem = vaultContract.previewWithdraw(assets_);
        if (user_ != address(this)) {
            if (usePermit2_) {
                // Approve via Permit2
                Permit2Lib.PERMIT2.transferFrom(
                    user_,
                    address(this),
                    sharesToRedeem.toUint160(),
                    address(vaultToken)
                );
            } else {
                // Transfer shares from user to this contract
                vaultToken.safeTransferFrom(
                    user_,
                    address(this),
                    sharesToRedeem
                );
            }
        }

        // Track facet's share balance AFTER transfer but BEFORE withdrawal
        uint256 preShareBalance = vaultToken.balanceOf(address(this));

        vaultToken.forceApprove(vault_, sharesToRedeem);

        // Withdraw assets and burn shares
        uint256 shares = vaultContract.withdraw(
            assets_,
            receiver_,
            address(this)
        );

        vaultToken.forceApprove(vault_, 0);

        uint256 postAssetBalance = asset.balanceOf(receiver_);
        uint256 postShareBalance = vaultToken.balanceOf(address(this));

        // Ensure receiver actually got assets and prevent share theft
        if (postAssetBalance <= preAssetBalance) {
            revert NoAssetsReceived();
        }

        // Validate requested assets match actual balance increase
        uint256 actualAssetsReceived = postAssetBalance - preAssetBalance;
        if (assets_ != actualAssetsReceived) {
            revert AssetsMismatch();
        }

        // Validate returned shares match actual shares burned
        uint256 actualSharesBurned = preShareBalance - postShareBalance;
        if (shares != actualSharesBurned) {
            revert SharesMismatch();
        }

        if (actualSharesBurned < sharesToRedeem) {
            vaultToken.safeTransfer(user_, sharesToRedeem - actualSharesBurned);
        }

        return shares;
    }

    /// @notice Internal function to redeem shares from an ERC4626 vault
    /// @dev Handles the redemption process including share transfer, validation, and asset withdrawal
    /// @param vault_ The address of the ERC4626 vault contract
    /// @param shares_ The amount of shares to redeem
    /// @param receiver_ The address that will receive the assets
    /// @return assets The amount of assets received
    function _redeemFromVaultInternal(
        address vault_,
        uint256 shares_,
        address receiver_
    ) internal returns (uint256) {
        IERC4626 vaultContract = IERC4626(vault_);
        IERC20 vaultToken = IERC20(vault_);
        IERC20 assetToken = IERC20(vaultContract.asset());

        // Track receiver's asset balance to ensure assets are received
        uint256 preAssetBalance = assetToken.balanceOf(receiver_);

        // Track facet's share balance AFTER transfer but BEFORE redeem
        uint256 preShareBalance = vaultToken.balanceOf(address(this));

        vaultToken.forceApprove(vault_, shares_);

        // Redeem shares for assets
        uint256 assets = vaultContract.redeem(
            shares_,
            receiver_,
            address(this)
        );

        vaultToken.forceApprove(vault_, 0);

        uint256 postAssetBalance = assetToken.balanceOf(receiver_);
        uint256 postShareBalance = vaultToken.balanceOf(address(this));

        // Ensure receiver actually got assets and prevent share theft
        if (postAssetBalance <= preAssetBalance) {
            revert NoAssetsReceived();
        }

        // Validate actual assets received match expected
        uint256 actualAssetsReceived = postAssetBalance - preAssetBalance;
        if (assets != actualAssetsReceived) {
            revert AssetsMismatch();
        }

        // Validate exact shares were burned
        uint256 actualSharesBurned = preShareBalance - postShareBalance;
        if (shares_ != actualSharesBurned) {
            revert SharesMismatch();
        }

        return assets;
    }
}

contracts/facets/external/TermAaveInterf.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {TermAtomicTxProtection} from "../base/TermAtomicTxProtection.sol";
import {TermFlashHookFacet} from "../base/TermFlashHookFacet.sol";
import {TermMulticallProtection} from "../base/TermMulticallProtection.sol";
import {TermMultiContextAuth} from "../base/TermMultiContextAuth.sol";
import {ActionHookInput} from "../../lib/ActionHookInput.sol";
import {PreviewAction} from "../../lib/PreviewAction.sol";
import {Versionable} from "../../lib/Versionable.sol";
import {LibTermStorage, TermStorage} from "../../libraries/LibTermStorage.sol";
import {ITermController} from "../../interfaces/ITermController.sol";

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {IPriceOracleGetter} from "@aave/core-v3/contracts/interfaces/IPriceOracleGetter.sol";
import {IPool} from "@aave/core-v3/contracts/interfaces/IPool.sol";
import {IPoolAddressesProvider} from "@aave/core-v3/contracts/interfaces/IPoolAddressesProvider.sol";
import {IPoolDataProvider} from "@aave/core-v3/contracts/interfaces/IPoolDataProvider.sol";
import {ICreditDelegationToken} from "@aave/core-v3/contracts/interfaces/ICreditDelegationToken.sol";
import {DataTypes} from "@aave/core-v3/contracts/protocol/libraries/types/DataTypes.sol";

/// @author TermLabs
/// @title TermAaveInterfaceFacet
/// @notice Provides interface functions for interacting with Aave V3 protocol
/// @dev Implements all major Aave operations with onBehalfOf pattern
contract TermAaveInterfaceFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermAtomicTxProtection,
    TermMulticallProtection,
    TermMultiContextAuth,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    // Function selectors for full signature versions (used in generateCalldata)
    bytes4 private constant WITHDRAW_SELECTOR =
        bytes4(
            keccak256(
                "aaveWithdrawOnBehalfOf(address,address,uint256,address,bool)"
            )
        );
    bytes4 private constant BORROW_SELECTOR =
        bytes4(keccak256("aaveBorrow(address,address,uint256,address,bool)"));

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when deadline has expired
    error Expired();

    /// @notice Thrown when credit delegation allowance is insufficient
    error InsufficientCreditDelegationAllowance();

    /// @notice Thrown when Aave pool address is zero
    error InvalidAavePoolAddress();

    /// @notice Thrown when amount is zero
    error InvalidAmount();

    /// @notice Thrown when asset address is zero
    error InvalidAssetAddress();

    /// @notice Thrown when aToken address is zero
    error InvalidATokenAddress();

    /// @notice Thrown when delegator address is zero
    error InvalidDelegatorAddress();

    /// @notice Thrown when invalid rate mode is provided
    error InvalidRateMode();

    /// @notice Thrown when user address is zero
    error InvalidUserAddress();

    /// @notice Thrown when variable debt token address is zero
    error InvalidVariableDebtTokenAddress();

    /// @notice Thrown when repaid assets don't match expected amount
    error RepaidAssetsMismatch();

    /// @notice Thrown when supply amount doesn't match expected amount
    error SupplyAmountMismatch();

    /// @notice Thrown when supply doesnt use up all provided
    error SupplyAssetMismatch();

    /// @notice Thrown when unsupported selector is provided for calldata generation
    error UnsupportedSelector();

    /// @notice Thrown when withdrawal amount doesn't match expected amount
    error WithdrawalAmountMismatch();

    // ========================================================================
    // = Modifiers ============================================================
    // ========================================================================

    modifier approvedAavePoolOnly(address aavePool) {
        TermStorage storage ts = LibTermStorage.termStorage();
        bool termApproved;
        for (uint8 i = 0; i < ts.approvedTermControllerList.length; ++i) {
            if (
                ITermController(ts.approvedTermControllerList[i])
                    .isTermApproved(aavePool)
            ) {
                termApproved = true;
                break;
            }
        }
        if (!termApproved) {
            revert InvalidAavePoolAddress();
        }
        _;
    }

    // ========================================================================
    // = Deploy ===============================================================
    // ========================================================================

    constructor() {
        previewMapping[this.aaveRefinanceInHook.selector] = this
            .previewAaveRefinanceIn
            .selector;
        previewMapping[this.aaveRefinanceOutHook.selector] = this
            .previewAaveRefinanceOut
            .selector;
    }

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Approve credit delegation on Aave using EIP-712 signature
    /// @param aavePool The address of the Aave pool
    /// @param asset The address of the underlying asset to delegate borrowing for
    /// @param amount The amount to delegate for borrowing
    /// @param deadline The signature expiration timestamp
    /// @param v The recovery id of the signature
    /// @param r Half of the ECDSA signature pair
    /// @param s Half of the ECDSA signature pair
    /// @dev Enables this contract to borrow on behalf of the delegator using a signature
    /// @dev Only callable by multicall initiator to ensure proper access control
    function aaveApproveDelegationWithSig(
        address aavePool,
        address asset,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external approvedAavePoolOnly(aavePool) onlyMulticallInitiator {
        if (deadline <= block.timestamp) revert Expired();
        if (asset == address(0)) revert InvalidAssetAddress();
        if (amount == 0) revert InvalidAmount();

        // Get reserve data to find variable debt token address
        (, address variableDebtTokenAddress) = _lookupReserveTokens(
            aavePool,
            asset
        );

        // Now call delegationWithSig on the debt token
        ICreditDelegationToken debtToken = ICreditDelegationToken(
            variableDebtTokenAddress
        );

        // Execute delegationWithSig (can be called by anyone with valid signature)
        debtToken.delegationWithSig(
            initiator(),
            address(this),
            amount,
            deadline,
            v,
            r,
            s
        );
    }

    /// @notice Supply assets to Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to supply to
    /// @param asset The address of the underlying asset to supply
    /// @param amount The amount to be supplied
    /// @dev `onBehalfOf` must have approved this contract to spend `amount` of `asset`
    function aaveSupply(
        address aavePool,
        address asset,
        uint256 amount,
        bool usePermit2
    ) external approvedAavePoolOnly(aavePool) {
        if (asset == address(0)) revert InvalidAssetAddress();

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                amount.toUint160(),
                asset
            );
        } else {
            // Transfer assets from the user to this contract
            IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        }
        _aaveSupplyInternal(aavePool, asset, amount, msg.sender);
    }

    /// @notice Supply assets to Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to supply to
    /// @param asset The address of the underlying asset to supply
    /// @param amount The amount to be supplied
    /// @param onBehalfOf The address that will spend tokens and receive aTokens
    /// @dev `onBehalfOf` must have approved this contract to spend `amount` of `asset`
    function aaveSupply(
        address aavePool,
        address asset,
        uint256 amount,
        address onBehalfOf,
        bool usePermit2
    )
        external
        onlyUserOrActiveContext(onBehalfOf)
        approvedAavePoolOnly(aavePool)
    {
        if (asset == address(0)) revert InvalidAssetAddress();

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                onBehalfOf,
                address(this),
                amount.toUint160(),
                asset
            );
        } else {
            // Transfer assets from the user to this contract
            IERC20(asset).safeTransferFrom(onBehalfOf, address(this), amount);
        }
        _aaveSupplyInternal(aavePool, asset, amount, onBehalfOf);
    }

    /// @notice Withdraw assets from Aave on behalf of another user via aToken transfer
    /// @param aavePool The address of the Aave pool to withdraw from
    /// @param asset The address of the underlying asset to withdraw
    /// @param amount The amount of aTokens to transfer and withdraw
    /// @dev This is a workaround since Aave doesn't support direct withdraw on behalf
    /// @dev `user` must have approved this contract to spend their aTokens
    function aaveWithdrawOnBehalfOf(
        address aavePool,
        address asset,
        uint256 amount
    ) external approvedAavePoolOnly(aavePool) {
        _aaveWithdrawOnBehalfOfInternal(
            aavePool,
            asset,
            amount,
            msg.sender,
            true
        );
    }

    /// @notice Withdraw assets from Aave on behalf of another user via aToken transfer
    /// @param aavePool The address of the Aave pool to withdraw from
    /// @param asset The address of the underlying asset to withdraw
    /// @param amount The amount of aTokens to transfer and withdraw
    /// @param user The address of the user on whose behalf to withdraw
    /// @param payoutToUser If true, transfer withdrawn assets to `user`
    /// @dev This is a workaround since Aave doesn't support direct withdraw on behalf
    /// @dev `user` must have approved this contract to spend their aTokens
    function aaveWithdrawOnBehalfOf(
        address aavePool,
        address asset,
        uint256 amount,
        address user,
        bool payoutToUser
    ) external onlyUserOrActiveContext(user) approvedAavePoolOnly(aavePool) {
        _aaveWithdrawOnBehalfOfInternal(
            aavePool,
            asset,
            amount,
            user,
            payoutToUser
        );
    }

    /// @notice Borrow assets from Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to borrow from
    /// @param asset The address of the underlying asset to borrow
    /// @param amount The amount to be borrowed
    /// @dev Debt is assigned to `onBehalfOf`, but borrowed assets go to `to`
    /// @dev Requires credit delegation if `onBehalfOf` != `to`
    function aaveBorrow(
        address aavePool,
        address asset,
        uint256 amount
    ) external approvedAavePoolOnly(aavePool) {
        _aaveBorrowInternal(aavePool, asset, amount, msg.sender, true);
    }

    /// @notice Borrow assets from Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to borrow from
    /// @param asset The address of the underlying asset to borrow
    /// @param amount The amount to be borrowed
    /// @param onBehalfOf The address that will incur the debt
    /// @param payoutToUser If true, transfer borrowed assets to `onBehalfOf`
    /// @dev Debt is assigned to `onBehalfOf`, but borrowed assets go to `to`
    /// @dev Requires credit delegation if `onBehalfOf` != `to`
    function aaveBorrow(
        address aavePool,
        address asset,
        uint256 amount,
        address onBehalfOf,
        bool payoutToUser
    )
        external
        onlyUserOrActiveContext(onBehalfOf)
        approvedAavePoolOnly(aavePool)
    {
        _aaveBorrowInternal(aavePool, asset, amount, onBehalfOf, payoutToUser);
    }

    /// @notice Repay debt to Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to repay to
    /// @param asset The address of the underlying asset being repaid
    /// @param amount The amount to repay
    /// @param usePermit2 Whether Permit2 was used for token approvals
    /// @dev `onBehalfOf` spends their tokens to repay their own debt
    function aaveRepay(
        address aavePool,
        address asset,
        uint256 amount,
        bool usePermit2
    ) external approvedAavePoolOnly(aavePool) {
        if (asset == address(0)) revert InvalidAssetAddress();

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                amount.toUint160(),
                asset
            );
        } else {
            // Transfer assets from the user to this contract
            IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        }
        _aaveRepayInternal(aavePool, asset, amount, msg.sender);
    }

    /// @notice Repay debt to Aave on behalf of a user
    /// @param aavePool The address of the Aave pool to repay to
    /// @param asset The address of the underlying asset being repaid
    /// @param amount The amount to repay
    /// @param onBehalfOf The address that will spend tokens and whose debt will be repaid
    /// @param usePermit2 Whether Permit2 was used for token approvals
    /// @dev `onBehalfOf` spends their tokens to repay their own debt
    function aaveRepay(
        address aavePool,
        address asset,
        uint256 amount,
        address onBehalfOf,
        bool usePermit2
    )
        external
        onlyUserOrActiveContext(onBehalfOf)
        approvedAavePoolOnly(aavePool)
    {
        if (asset == address(0)) revert InvalidAssetAddress();

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                onBehalfOf,
                address(this),
                amount.toUint160(),
                asset
            );
        } else {
            // Transfer assets from the user to this contract
            IERC20(asset).safeTransferFrom(onBehalfOf, address(this), amount);
        }
        _aaveRepayInternal(aavePool, asset, amount, onBehalfOf);
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Flash hook that refinances a user out of an Aave position by repaying
    ///         their debt and withdrawing their collateral.
    /// @dev Repays `input.maxInputAmount` of `input.inputToken` debt on behalf of the user,
    ///      then withdraws `input.minOutputAmount` of `input.outputToken` collateral from the pool.
    /// @param input The action hook input where:
    ///   - `user`: the borrower whose Aave position is being refinanced out
    ///   - `inputToken`: the loan asset to repay
    ///   - `maxInputAmount`: the repayment amount
    ///   - `outputToken`: the collateral token to withdraw
    ///   - `minOutputAmount`: the collateral amount to withdraw
    ///   - `targetAddress`: the Aave pool address
    function aaveRefinanceOutHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        nonReentrant
        approvedAavePoolOnly(input.targetAddress)
    {
        address aavePool = input.targetAddress;
        address loanAsset = input.inputToken;
        uint256 amount = input.maxInputAmount;
        address collateralToken = input.outputToken;
        uint256 collateralAmount = input.minOutputAmount;
        address borrower = input.user;

        _aaveRepayInternal(aavePool, loanAsset, amount, borrower);
        _aaveWithdrawOnBehalfOfInternal(
            aavePool,
            collateralToken,
            collateralAmount,
            borrower,
            false
        );
    }

    /// @notice Flash hook that refinances a user into an Aave position by supplying
    ///         collateral and borrowing against it.
    /// @dev Supplies `input.maxInputAmount` of `input.inputToken` as collateral on behalf of the user,
    ///      then borrows `input.minOutputAmount` of `input.outputToken` from the pool.
    /// @param input The action hook input where:
    ///   - `user`: the borrower opening the Aave position
    ///   - `inputToken`: the collateral token to supply
    ///   - `maxInputAmount`: the collateral amount to supply
    ///   - `outputToken`: the loan asset to borrow
    ///   - `minOutputAmount`: the borrow amount
    ///   - `targetAddress`: the Aave pool address
    function aaveRefinanceInHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        nonReentrant
        approvedAavePoolOnly(input.targetAddress)
    {
        address aavePool = input.targetAddress;
        address loanAsset = input.outputToken;
        uint256 amount = input.minOutputAmount;
        address collateralToken = input.inputToken;
        uint256 collateralAmount = input.maxInputAmount;
        address borrower = input.user;

        _aaveSupplyInternal(
            aavePool,
            collateralToken,
            collateralAmount,
            borrower
        );

        _aaveBorrowInternal(aavePool, loanAsset, amount, borrower, false);
    }

    /// @notice Get the available balance for a user's deposited asset in Aave
    /// @param aavePool The address of the Aave pool
    /// @param asset The address of the underlying asset
    /// @param user The address of the user to check balance for
    /// @return The user's available balance for the specified asset
    function availableFunds(
        address aavePool,
        address asset,
        address user
    ) external view returns (uint256) {
        if (aavePool == address(0)) revert InvalidAavePoolAddress();
        if (asset == address(0)) revert InvalidAssetAddress();

        (address aTokenAddress, ) = _lookupReserveTokens(aavePool, asset);
        return IERC20(aTokenAddress).balanceOf(user);
    }

    /**
     * @notice Calculate how much of a specific token a user can borrow
     * @param user The user address
     * @param asset The token address to borrow
     * @return availableAmount The maximum amount of the specific token the user can borrow
     */
    function availableBorrow(
        address aavePool,
        address asset,
        address user
    ) external view returns (uint256 availableAmount) {
        IPool pool = IPool(aavePool);
        IPoolAddressesProvider provider = IPoolAddressesProvider(
            pool.ADDRESSES_PROVIDER()
        );
        IPriceOracleGetter oracle = IPriceOracleGetter(
            provider.getPriceOracle()
        );

        // Get user's total available borrow capacity in base currency
        (, , uint256 availableBorrowsBase, , , ) = pool.getUserAccountData(
            user
        );

        // Get the asset price in base currency
        uint256 assetPrice = oracle.getAssetPrice(asset);

        // Get asset decimals
        uint8 assetDecimals = ERC20(asset).decimals();

        // Convert base currency amount to asset amount
        if (assetPrice > 0) {
            availableAmount =
                (availableBorrowsBase * (10 ** assetDecimals)) /
                assetPrice;
        } else {
            availableAmount = 0;
        }

        return availableAmount;
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Generate encoded calldata for Aave interface function calls
    /// @param selector The function selector for the target Aave interface function
    /// @param aavePool The address of the Aave pool
    /// @param asset The address of the underlying asset
    /// @param user The user address for the operation
    /// @param amount The amount for the operation
    /// @param payoutUser Whether to payout to user
    /// @param data Additional calldata for the operation (currently unused)
    /// @return Encoded calldata for the specified function with provided parameters
    /// @dev Supports aaveWithdrawOnBehalfOf and aaveBorrow selectors only
    function generateCalldata(
        bytes4 selector,
        address aavePool,
        address asset,
        address user,
        uint256 amount,
        bool payoutUser,
        bytes calldata data
    ) external view returns (bytes memory) {
        if (selector == WITHDRAW_SELECTOR) {
            return
                abi.encodeWithSelector(
                    selector,
                    aavePool,
                    asset,
                    amount,
                    user,
                    payoutUser
                );
        } else if (selector == BORROW_SELECTOR) {
            return
                abi.encodeWithSelector(
                    selector,
                    aavePool,
                    asset,
                    amount,
                    user,
                    payoutUser
                );
        } else {
            revert UnsupportedSelector();
        }
    }

    /// @notice Previews an Aave refinance-in action by passing through the input/output
    ///         amounts unchanged.
    /// @dev Since Aave supply and borrow amounts are deterministic (no slippage), the
    ///      preview simply mirrors the requested amounts.
    /// @param actionHookInput The action hook input containing the collateral and borrow parameters.
    /// @return A `PreviewAction` with expected tokens/amounts matching the input and `isDeterministic` set to true.
    function previewAaveRefinanceIn(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        if (actionHookInput.inputToken == actionHookInput.outputToken) {
            revert InputOutputTokenCollision();
        }
        PreviewAction memory previewAction = PreviewAction({
            expectedInputToken: actionHookInput.inputToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: actionHookInput.outputToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: true
        });

        return previewAction;
    }

    /// @notice Previews an Aave refinance-out action by passing through the input/output
    ///         amounts unchanged.
    /// @dev Since Aave repay and withdraw amounts are deterministic (no slippage), the
    ///      preview simply mirrors the requested amounts.
    /// @param actionHookInput The action hook input containing the repayment and collateral withdrawal parameters.
    /// @return A `PreviewAction` with expected tokens/amounts matching the input and `isDeterministic` set to true.
    function previewAaveRefinanceOut(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        if (actionHookInput.inputToken == actionHookInput.outputToken) {
            revert InputOutputTokenCollision();
        }
        PreviewAction memory previewAction = PreviewAction({
            expectedInputToken: actionHookInput.inputToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: actionHookInput.outputToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: true
        });

        return previewAction;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    /// @notice Supply assets to Aave on behalf of a user (internal)
    /// @param aavePool_ The address of the Aave pool to supply to
    /// @param asset_ The address of the underlying asset to supply
    /// @param amount_ The amount to be supplied
    /// @param onBehalfOf_ The address that will receive aTokens
    /// @dev Assumes the diamond already holds `amount_` of `asset_`. External wrappers handle user transfers.
    function _aaveSupplyInternal(
        address aavePool_,
        address asset_,
        uint256 amount_,
        address onBehalfOf_
    ) internal {
        if (asset_ == address(0)) revert InvalidAssetAddress();
        if (amount_ == 0) revert InvalidAmount();
        if (onBehalfOf_ == address(0)) revert InvalidUserAddress();

        // Approve Aave pool to spend the tokens
        IERC20(asset_).forceApprove(aavePool_, amount_);
        // Get aToken address for the asset
        (address aTokenAddress, ) = _lookupReserveTokens(aavePool_, asset_);

        // Record aToken balance before supply
        uint256 aTokenBalanceBefore = IERC20(aTokenAddress).balanceOf(
            onBehalfOf_
        );
        uint256 assetBalanceBefore = IERC20(asset_).balanceOf(address(this));

        // Supply to Aave on behalf of the specified user
        IPool(aavePool_).supply(asset_, amount_, onBehalfOf_, 0);

        // Revoke approvals to Aave pool after supply
        IERC20(asset_).forceApprove(aavePool_, 0);

        // Verify aToken balance increased correctly
        uint256 aTokenBalanceAfter = IERC20(aTokenAddress).balanceOf(
            onBehalfOf_
        );
        uint256 assetBalanceAfter = IERC20(asset_).balanceOf(address(this));

        uint256 aTokenReceived = aTokenBalanceAfter - aTokenBalanceBefore;
        if (aTokenReceived + 1 < amount_ || aTokenReceived > amount_ + 1) {
            revert SupplyAmountMismatch();
        }

        if (assetBalanceBefore - assetBalanceAfter != amount_) {
            revert SupplyAssetMismatch();
        }
    }

    /// @notice Withdraw assets from Aave on behalf of another user via aToken transfer
    /// @param aavePool_ The address of the Aave pool to withdraw from
    /// @param asset_ The address of the underlying asset to withdraw
    /// @param amount_ The amount of aTokens to transfer and withdraw
    /// @param user_ The address of the user on whose behalf to withdraw
    /// @param payoutToUser_ If true, transfer withdrawn assets to `user`
    /// @dev This is a workaround since Aave doesn't support direct withdraw on behalf
    /// @dev `user` must have approved this contract to spend their aTokens
    function _aaveWithdrawOnBehalfOfInternal(
        address aavePool_,
        address asset_,
        uint256 amount_,
        address user_,
        bool payoutToUser_
    ) internal {
        if (asset_ == address(0)) revert InvalidAssetAddress();
        if (amount_ == 0) revert InvalidAmount();
        if (user_ == address(0)) revert InvalidUserAddress();

        // Get the underlying asset address from the aToken
        (address aTokenAddress, ) = _lookupReserveTokens(aavePool_, asset_);
        if (user_ != address(this)) {
            IERC20(aTokenAddress).safeTransferFrom(
                user_,
                address(this),
                amount_
            ); // @dev: aTokens support ERC20Permit
        }
        uint256 aTokenBalanceBefore = IERC20(aTokenAddress).balanceOf(
            address(this)
        );
        uint256 assetBalanceBefore = IERC20(asset_).balanceOf(address(this));

        // Withdraw underlying assets from Aave to the specified recipient
        uint256 withdrawalAmount = IPool(aavePool_).withdraw(
            asset_,
            amount_,
            address(this)
        );

        uint256 aTokenBalanceAfter = IERC20(aTokenAddress).balanceOf(
            address(this)
        );
        uint256 assetBalanceAfter = IERC20(asset_).balanceOf(address(this));

        uint256 aTokensUsed = aTokenBalanceBefore - aTokenBalanceAfter;

        if (withdrawalAmount != amount_) revert WithdrawalAmountMismatch();

        if (assetBalanceAfter - assetBalanceBefore != amount_) {
            revert WithdrawalAmountMismatch();
        }

        if (aTokensUsed < amount_) {
            IERC20(aTokenAddress).safeTransfer(user_, amount_ - aTokensUsed);
        }
        // If no further batch operations, transfer assets back to user
        if (
            (atomicTxInitiator() == address(0) &&
                getFlashLoanBorrower() == address(0) &&
                msg.sender != address(this)) || payoutToUser_
        ) {
            IERC20(asset_).safeTransfer(user_, amount_);
        }
    }

    /// @notice Borrow assets from Aave on behalf of a user
    /// @param aavePool_ The address of the Aave pool to borrow from
    /// @param asset_ The address of the underlying asset to borrow
    /// @param amount_ The amount to be borrowed
    /// @param onBehalfOf_ The address that will incur the debt
    /// @param payoutToUser_ If true, transfer borrowed assets to `onBehalfOf`
    /// @dev Debt is assigned to `onBehalfOf`, but borrowed assets go to `to`
    /// @dev Requires credit delegation if `onBehalfOf` != `to`
    function _aaveBorrowInternal(
        address aavePool_,
        address asset_,
        uint256 amount_,
        address onBehalfOf_,
        bool payoutToUser_
    ) internal {
        if (asset_ == address(0)) revert InvalidAssetAddress();
        if (amount_ == 0) revert InvalidAmount();
        if (onBehalfOf_ == address(0)) revert InvalidUserAddress();

        // Check credit delegation allowance if borrowing on behalf of another user
        uint256 allowance = _aaveCheckBorrowAllowance(
            aavePool_,
            asset_,
            2,
            onBehalfOf_
        );
        if (allowance < amount_) revert InsufficientCreditDelegationAllowance();

        /// @dev function does not return actual borrow amount
        IPool(aavePool_).borrow(asset_, amount_, 2, 0, onBehalfOf_);
        if (
            (atomicTxInitiator() == address(0) &&
                getFlashLoanBorrower() == address(0) &&
                msg.sender != address(this)) || payoutToUser_
        ) {
            // Transfer borrowed assets to the user
            IERC20(asset_).safeTransfer(onBehalfOf_, amount_);
        }
    }

    /// @notice Repay debt to Aave on behalf of a user
    /// @param aavePool_ The address of the Aave pool to repay to
    /// @param asset_ The address of the underlying asset being repaid
    /// @param amount_ The amount to repay
    /// @param onBehalfOf_ The address that will spend tokens and whose debt will be repaid
    /// @dev `onBehalfOf` spends their tokens to repay their own debt
    function _aaveRepayInternal(
        address aavePool_,
        address asset_,
        uint256 amount_,
        address onBehalfOf_
    ) internal {
        if (asset_ == address(0)) revert InvalidAssetAddress();
        if (amount_ == 0) revert InvalidAmount();
        if (onBehalfOf_ == address(0)) revert InvalidUserAddress();

        // Approve Aave pool to spend the tokens
        IERC20(asset_).forceApprove(aavePool_, amount_);

        // Repay debt on behalf of the specified user
        uint256 repaidAmount = IPool(aavePool_).repay(
            asset_,
            amount_,
            2,
            onBehalfOf_
        );

        // Revoke approvals to Aave pool after repay
        IERC20(asset_).forceApprove(aavePool_, 0);

        if (repaidAmount != amount_) revert RepaidAssetsMismatch();
    }

    /// @notice Check the borrow allowance (credit delegation) for a user
    /// @param aavePool_ The address of the Aave pool
    /// @param asset_ The address of the underlying asset
    /// @param rateMode_ The interest rate mode: 1 for stable, 2 for variable
    /// @param delegator_ The address that granted the delegation
    /// @return allowance The amount that can be borrowed on behalf of delegator
    function _aaveCheckBorrowAllowance(
        address aavePool_,
        address asset_,
        uint256 rateMode_,
        address delegator_
    ) internal view returns (uint256 allowance) {
        if (asset_ == address(0)) revert InvalidAssetAddress();
        if (rateMode_ != 1 && rateMode_ != 2) revert InvalidRateMode();
        if (delegator_ == address(0)) revert InvalidDelegatorAddress();

        // Get reserve data to find debt token address
        DataTypes.ReserveData memory reserveData = IPool(aavePool_)
            .getReserveData(asset_);

        address debtTokenAddress;
        if (rateMode_ == 1) {
            debtTokenAddress = reserveData.stableDebtTokenAddress;
        } else {
            debtTokenAddress = reserveData.variableDebtTokenAddress;
        }

        // Check allowance on the debt token
        return
            ICreditDelegationToken(debtTokenAddress).borrowAllowance(
                delegator_,
                address(this)
            );
    }

    /// @notice Lookup the aToken and variable debt token addresses for a given underlying asset in Aave
    /// @param aavePool_ The address of the Aave pool
    /// @param asset_ The address of the underlying asset
    /// @return aTokenAddress The address of the corresponding aToken
    /// @return variableDebtTokenAddress The address of the corresponding variable debt token
    function _lookupReserveTokens(
        address aavePool_,
        address asset_
    ) internal view returns (address, address) {
        IPoolAddressesProvider provider = IPoolAddressesProvider(
            IPool(aavePool_).ADDRESSES_PROVIDER()
        );
        IPoolDataProvider dataProvider = IPoolDataProvider(
            provider.getPoolDataProvider()
        );
        (
            address aTokenAddress,
            ,
            address variableDebtTokenAddress
        ) = dataProvider.getReserveTokensAddresses(asset_);
        if (aTokenAddress == address(0)) revert InvalidATokenAddress();
        if (variableDebtTokenAddress == address(0))
            revert InvalidVariableDebtTokenAddress();
        return (aTokenAddress, variableDebtTokenAddress);
    }
}

contracts/facets/external/TermMorphoInte.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {TermMulticallProtection} from "../base/TermMulticallProtection.sol";
import {TermFlashHookFacet} from "../base/TermFlashHookFacet.sol";
import {TermAtomicTxProtection} from "../base/TermAtomicTxProtection.sol";
import {TermMultiContextAuth} from "../base/TermMultiContextAuth.sol";
import {ActionHookInput} from "../../lib/ActionHookInput.sol";
import {PreviewAction} from "../../lib/PreviewAction.sol";
import {Versionable} from "../../lib/Versionable.sol";

import {Authorization, IMorpho, Id, MarketParams, Signature} from "@morpho-org/morpho-blue/src/interfaces/IMorpho.sol";
import {MathLib} from "@morpho-org/morpho-blue/src/libraries/MathLib.sol";
import {IOracle} from "@morpho-org/morpho-blue/src/interfaces/IOracle.sol";
import {MorphoBalancesLib} from "@morpho-org/morpho-blue/src/libraries/periphery/MorphoBalancesLib.sol";

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

/// @author TermLabs
/// @title TermMorphoInterfaceFacet
/// @notice Provides interface functions for interacting with Morpho protocol
/// @dev Implements all major Morpho operations with onBehalfOf pattern
contract TermMorphoInterfaceFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermAtomicTxProtection,
    TermMulticallProtection,
    TermMultiContextAuth,
    Versionable
{
    using SafeERC20 for IERC20;
    using MathLib for uint256;
    using SafeCast for uint256;

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when borrowed assets don't match expected amount
    error BorrowedAssetsMismatch();

    /// @notice Thrown when deadline has expired
    error Expired();

    /// @notice Thrown when the target asset does not match the expected asset
    error IncorrectTargetAsset();

    /// @notice Thrown when amount is zero
    error InvalidAmount();

    /// @notice Thrown when asset address is zero
    error InvalidAssetAddress();

    /// @notice Thrown when collateral asset is not accepted by the collateral manager
    error InvalidCollateralAsset();

    /// @notice Thrown when loan token from morpho market is invalid
    error InvalidLoanToken();

    /// @notice Thrown when market ID is zero
    error InvalidMarketId();

    /// @notice Thrown when Morpho pool address is zero
    error InvalidMorphoPoolAddress();

    /// @notice Thrown when user address is zero
    error InvalidUserAddress();

    /// @notice Thrown when repaid assets don't match expected amount
    error RepaidAssetsMismatch();

    /// @notice Thrown when attempting to supply collateral to self
    error SelfSupplyNotAllowed();

    /// @notice Thrown when supplied assets don't match expected amount
    error SupplyAmountMismatch();

    /// @notice Thrown when unsupported selector is provided for calldata generation
    error UnsupportedSelector();

    // ========================================================================
    // = Constants ============================================================
    // ========================================================================
    uint256 private constant MORPHO_ORACLE_PRICE_SCALE = 1e36;

    // Function selectors for full signature versions (used in generateCalldata)
    bytes4 private constant WITHDRAW_COLLATERAL_SELECTOR =
        bytes4(
            keccak256(
                "morphoWithdrawCollateral(address,(address,address,address,address,uint256),uint256,address,bool)"
            )
        );
    bytes4 private constant BORROW_SELECTOR =
        bytes4(
            keccak256(
                "morphoBorrow(address,(address,address,address,address,uint256),uint256,address,bool)"
            )
        );

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    address immutable deployedMorphoPool;

    // ========================================================================
    // = Modifiers ============================================================
    // ========================================================================

    modifier approvedMorphoPoolOnly(address morphoPool) {
        if (morphoPool != deployedMorphoPool) {
            revert InvalidMorphoPoolAddress();
        }
        _;
    }

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    constructor(address deployedMorphoPool_) {
        if (deployedMorphoPool_ == address(0)) {
            revert InvalidMorphoPoolAddress();
        }
        deployedMorphoPool = deployedMorphoPool_;

        previewMapping[this.morphoRefinanceInHook.selector] = this
            .previewMorphoRefinanceIn
            .selector;
        previewMapping[this.morphoRefinanceOutHook.selector] = this
            .previewMorphoRefinanceOut
            .selector;
    }

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Approves `authorization.authorized` to manage `authorization.authorizer`'s position via EIP712 `signature`
    /// @param morphoPool The address of the Morpho pool
    /// @param authorization The `Authorization` struct
    /// @param signature The signature
    /// @param skipRevert Whether to avoid reverting the call in case the signature is frontrunned
    function morphoSetAuthorizationWithSig(
        address morphoPool,
        Authorization calldata authorization,
        Signature calldata signature,
        bool skipRevert
    ) external onlyMulticallInitiator approvedMorphoPoolOnly(morphoPool) {
        if (morphoPool == address(0)) revert InvalidMorphoPoolAddress();
        if (authorization.authorizer == address(0)) revert InvalidUserAddress();
        if (authorization.deadline <= block.timestamp) revert Expired();
        try
            IMorpho(morphoPool).setAuthorizationWithSig(
                authorization,
                signature
            )
        {} catch (bytes memory returnData) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Supplies `assets` of collateral on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to supply collateral to
    /// @param assets The amount of collateral to supply
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoSupplyCollateral(
        address morphoPool,
        MarketParams memory marketParams,
        uint256 assets,
        bool usePermit2
    ) external approvedMorphoPoolOnly(morphoPool) {
        if (marketParams.collateralToken == address(0))
            revert InvalidCollateralAsset();
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                assets.toUint160(),
                marketParams.collateralToken
            );
        } else {
            // Transfer collateral from the user to this contract
            IERC20(marketParams.collateralToken).safeTransferFrom(
                msg.sender,
                address(this),
                assets
            );
        }
        _morphoSupplyCollateralInternal(
            morphoPool,
            marketParams,
            assets,
            msg.sender
        );
    }

    /// @notice Supplies `assets` of collateral on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to supply collateral to
    /// @param assets The amount of collateral to supply
    /// @param user The address of the account to supply collateral on behalf of
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoSupplyCollateral(
        address morphoPool,
        MarketParams memory marketParams,
        uint256 assets,
        address user,
        bool usePermit2
    )
        external
        onlyUserOrActiveContext(user)
        approvedMorphoPoolOnly(morphoPool)
    {
        if (marketParams.collateralToken == address(0))
            revert InvalidCollateralAsset();
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                user,
                address(this),
                assets.toUint160(),
                marketParams.collateralToken
            );
        } else {
            // Transfer collateral from the user to this contract
            IERC20(marketParams.collateralToken).safeTransferFrom(
                user,
                address(this),
                assets
            );
        }
        _morphoSupplyCollateralInternal(morphoPool, marketParams, assets, user);
    }

    /// @notice Supplies `assets` of the loan asset on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to supply assets to
    /// @param assets The amount of assets to supply
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoSupply(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets,
        bool usePermit2
    ) external approvedMorphoPoolOnly(morphoPool) {
        _morphoSupplyInternal(
            morphoPool,
            marketParams,
            assets,
            msg.sender,
            usePermit2
        );
    }

    /// @notice Supplies `assets` of the loan asset on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to supply assets to
    /// @param assets The amount of assets to supply
    /// @param user The address of the account to supply assets on behalf of
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoSupply(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets,
        address user,
        bool usePermit2
    )
        external
        onlyUserOrActiveContext(user)
        approvedMorphoPoolOnly(morphoPool)
    {
        _morphoSupplyInternal(
            morphoPool,
            marketParams,
            assets,
            user,
            usePermit2
        );
    }

    /// @notice Withdraws `assets` of the collateral asset on behalf of the `user`
    /// @dev Caller must have pre-authorized this contract via IMorpho.setAuthorization
    /// or morphoSetAuthorizationWithSig before calling this function.
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to withdraw collateral from
    /// @param assets The amount of collateral to withdraw
    function morphoWithdrawCollateral(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets
    ) external approvedMorphoPoolOnly(morphoPool) {
        _morphoWithdrawCollateralInternal(
            morphoPool,
            marketParams,
            assets,
            msg.sender,
            true
        );
    }

    /// @notice Withdraws `assets` of the collateral asset on behalf of the `user`
    /// @dev Caller must have pre-authorized this contract via IMorpho.setAuthorization
    /// or morphoSetAuthorizationWithSig before calling this function.
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to withdraw collateral from
    /// @param assets The amount of collateral to withdraw
    /// @param user The address of the account to withdraw collateral on behalf of
    /// @param payoutUser If true, the withdrawn collateral will be transferred to `user`
    function morphoWithdrawCollateral(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets,
        address user,
        bool payoutUser
    )
        external
        onlyUserOrActiveContext(user)
        approvedMorphoPoolOnly(morphoPool)
    {
        _morphoWithdrawCollateralInternal(
            morphoPool,
            marketParams,
            assets,
            user,
            payoutUser
        );
    }

    /// @notice Borrows `assets` of the loan asset on behalf of the `user`
    /// @dev Caller must have pre-authorized this contract via IMorpho.setAuthorization
    /// or morphoSetAuthorizationWithSig before calling this function.
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to borrow assets from
    /// @param assets The amount of assets to borrow
    function morphoBorrow(
        address morphoPool,
        MarketParams memory marketParams,
        uint256 assets
    ) external approvedMorphoPoolOnly(morphoPool) {
        _morphoBorrowInternal(
            morphoPool,
            marketParams,
            assets,
            msg.sender,
            true
        );
    }

    /// @notice Borrows `assets` of the loan asset on behalf of the `user`
    /// @dev Caller must have pre-authorized this contract via IMorpho.setAuthorization
    /// or morphoSetAuthorizationWithSig before calling this function.
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to borrow assets from
    /// @param assets The amount of assets to borrow
    /// @param user The address of the account to borrow assets on behalf of
    /// @param payoutUser If true, the borrowed assets will be transferred to `user`
    function morphoBorrow(
        address morphoPool,
        MarketParams memory marketParams,
        uint256 assets,
        address user,
        bool payoutUser
    )
        external
        onlyUserOrActiveContext(user)
        approvedMorphoPoolOnly(morphoPool)
    {
        _morphoBorrowInternal(
            morphoPool,
            marketParams,
            assets,
            user,
            payoutUser
        );
    }

    /// @notice Repays `assets` of the loan asset on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to repay assets to
    /// @param assets The amount of assets to repay
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoRepay(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets,
        bool usePermit2
    ) external approvedMorphoPoolOnly(morphoPool) {
        if (marketParams.loanToken == address(0)) revert InvalidLoanToken();
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                assets.toUint160(),
                marketParams.loanToken
            );
        } else {
            // Transfer loan tokens from the user to this contract for repayment
            IERC20(marketParams.loanToken).safeTransferFrom(
                msg.sender,
                address(this),
                assets
            );
        }
        _morphoRepayInternal(morphoPool, marketParams, assets, msg.sender);
    }

    /// @notice Repays `assets` of the loan asset on behalf of `user`
    /// @param morphoPool The address of the Morpho pool
    /// @param marketParams The Morpho market to repay assets to
    /// @param assets The amount of assets to repay
    /// @param user The address of the account to repay assets on behalf of
    /// @param usePermit2 Whether Permit2 was used for token approvals
    function morphoRepay(
        address morphoPool,
        MarketParams calldata marketParams,
        uint256 assets,
        address user,
        bool usePermit2
    )
        external
        onlyUserOrActiveContext(user)
        approvedMorphoPoolOnly(morphoPool)
    {
        if (marketParams.loanToken == address(0)) revert InvalidLoanToken();
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                user,
                address(this),
                assets.toUint160(),
                marketParams.loanToken
            );
        } else {
            // Transfer loan tokens from the user to this contract for repayment
            IERC20(marketParams.loanToken).safeTransferFrom(
                user,
                address(this),
                assets
            );
        }
        _morphoRepayInternal(morphoPool, marketParams, assets, user);
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Flash hook that refinances a user out of a Morpho position by repaying
    ///         their debt and withdrawing their collateral.
    /// @dev Decodes the Morpho market ID from `input.additionalCalldata`, resolves the market
    ///      params, then repays `input.maxInputAmount` of loan asset and withdraws
    ///      `input.minOutputAmount` of collateral on behalf of the borrower.
    /// @param input The action hook input where:
    ///   - `user`: the borrower whose Morpho position is being refinanced out
    ///   - `inputToken`: the loan asset to repay
    ///   - `maxInputAmount`: the repayment amount
    ///   - `outputToken`: the collateral token to withdraw
    ///   - `minOutputAmount`: the collateral amount to withdraw
    ///   - `targetAddress`: the Morpho pool address
    ///   - `additionalCalldata`: ABI-encoded `bytes32` Morpho market ID
    function morphoRefinanceOutHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        approvedMorphoPoolOnly(input.targetAddress)
        nonReentrant
    {
        address morphoPool = input.targetAddress;
        address loanAsset = input.inputToken;
        uint256 amount = input.maxInputAmount;
        address collateralToken = input.outputToken;
        uint256 collateralAmount = input.minOutputAmount;
        address borrower = input.user;
        bytes32 marketIdBytes = abi.decode(input.additionalCalldata, (bytes32));
        Id marketId = Id.wrap(marketIdBytes);
        MarketParams memory marketParams = IMorpho(morphoPool).idToMarketParams(
            marketId
        );

        _morphoRepayInternal(morphoPool, marketParams, amount, borrower);
        _morphoWithdrawCollateralInternal(
            morphoPool,
            marketParams,
            collateralAmount,
            borrower,
            false
        );
    }

    /// @notice Flash hook that refinances a user into a Morpho position by supplying
    ///         collateral and borrowing against it.
    /// @dev Decodes the Morpho market ID from `input.additionalCalldata`, resolves the market
    ///      params, then supplies `input.maxInputAmount` of collateral and borrows
    ///      `input.minOutputAmount` of loan asset on behalf of the borrower.
    /// @param input The action hook input where:
    ///   - `user`: the borrower opening the Morpho position
    ///   - `inputToken`: the collateral token to supply
    ///   - `maxInputAmount`: the collateral amount to supply
    ///   - `outputToken`: the loan asset to borrow
    ///   - `minOutputAmount`: the borrow amount
    ///   - `targetAddress`: the Morpho pool address
    ///   - `additionalCalldata`: ABI-encoded `bytes32` Morpho market ID
    function morphoRefinanceInHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        approvedMorphoPoolOnly(input.targetAddress)
        nonReentrant
    {
        address morphoPool = input.targetAddress;
        address loanAsset = input.outputToken;
        uint256 amount = input.minOutputAmount;
        address collateralToken = input.inputToken;
        uint256 collateralAmount = input.maxInputAmount;
        address borrower = input.user;
        bytes32 marketIdBytes = abi.decode(input.additionalCalldata, (bytes32));
        Id marketId = Id.wrap(marketIdBytes);
        MarketParams memory marketParams = IMorpho(morphoPool).idToMarketParams(
            marketId
        );
        _morphoSupplyCollateralInternal(
            morphoPool,
            marketParams,
            collateralAmount,
            borrower
        );
        _morphoBorrowInternal(
            morphoPool,
            marketParams,
            amount,
            borrower,
            false
        );
    }

    // ========================================================================
    // = View Functions  ======================================================
    // ========================================================================

    /// @notice Get the available collateral that can be withdrawn for a user in Morpho
    /// @param morphoPool The address of the Morpho pool
    /// @param user The address of the user to check balance for
    /// @param marketId The market ID to check balance in
    /// @return balance user's available collateral that can be withdrawn from the market
    function availableFunds(
        address morphoPool,
        address user,
        bytes32 marketId
    ) external view returns (uint256) {
        if (morphoPool == address(0)) revert InvalidMorphoPoolAddress();
        if (user == address(0)) revert InvalidUserAddress();
        if (marketId == bytes32(0)) revert InvalidMarketId();
        IMorpho morpho = IMorpho(morphoPool);
        Id wrappedMarketId = Id.wrap(marketId);

        // Get user's position
        uint256 collateralBalance = morpho
            .position(wrappedMarketId, user)
            .collateral;
        uint256 borrowShares = morpho
            .position(wrappedMarketId, user)
            .borrowShares;

        // If user has no borrows, they can withdraw all collateral
        if (borrowShares == 0) {
            return collateralBalance;
        }

        // Get market data to calculate borrowed amount
        MarketParams memory marketParams = morpho.idToMarketParams(
            wrappedMarketId
        );

        uint256 borrowedAssets = MorphoBalancesLib.expectedBorrowAssets(
            morpho,
            marketParams,
            user
        );

        // Get collateral price from oracle
        require(marketParams.oracle != address(0), "Invalid oracle address");
        uint256 collateralPrice = IOracle(marketParams.oracle).price();
        require(collateralPrice > 0, "Invalid price");

        uint256 denominator = collateralPrice.mulDivDown(
            marketParams.lltv,
            1e18
        );
        require(denominator > 0, "Price*LTV rounds to zero");

        // Calculate minimum collateral required to maintain LTV
        // Required collateral value = borrowed amount / LTV
        // Required collateral units = (borrowed amount * PRICE_SCALE) / (collateral price * LTV)
        uint256 requiredCollateral = borrowedAssets.mulDivUp(
            MORPHO_ORACLE_PRICE_SCALE,
            denominator
        );

        // Return withdrawable amount (current collateral - required collateral)
        if (collateralBalance > requiredCollateral) {
            return collateralBalance - requiredCollateral;
        } else {
            return 0; // Cannot withdraw any collateral
        }
    }

    /// @notice Calculates the maximum available borrowing capacity for a user in a specific Morpho market
    /// @dev Computes borrowing capacity based on user's collateral value adjusted by loan-to-value ratio
    /// @param morphoPool Address of the Morpho protocol pool contract
    /// @param user Address of the user to check borrowing capacity for
    /// @param marketId Unique identifier for the specific Morpho market
    /// @return Available borrow capacity in the market's loan token (collateral value × LTV − outstanding debt)
    function availableBorrow(
        address morphoPool,
        address user,
        bytes32 marketId
    ) external view returns (uint256) {
        if (morphoPool == address(0)) revert InvalidMorphoPoolAddress();
        if (user == address(0)) revert InvalidUserAddress();
        if (marketId == bytes32(0)) revert InvalidMarketId();

        IMorpho morpho = IMorpho(morphoPool);
        Id wrappedMarketId = Id.wrap(marketId);
        MarketParams memory marketParams = morpho.idToMarketParams(
            wrappedMarketId
        );
        require(marketParams.oracle != address(0), "Invalid oracle address");
        uint256 collateralPrice = IOracle(marketParams.oracle).price();
        require(collateralPrice > 0, "Invalid price");

        uint256 collateralBalance = morpho
            .position(wrappedMarketId, user)
            .collateral;

        uint256 borrowedAssets = MorphoBalancesLib.expectedBorrowAssets(
            morpho,
            marketParams,
            user
        );

        uint256 borrowCapacity = collateralBalance
            .mulDivDown(collateralPrice, MORPHO_ORACLE_PRICE_SCALE)
            .wMulDown(marketParams.lltv);

        return
            borrowCapacity > borrowedAssets
                ? borrowCapacity - borrowedAssets
                : 0;
    }

    /// @notice Returns the current amount of assets borrowed by a user in a specific Morpho market
    /// @param morphoPool The address of the Morpho pool contract
    /// @param user The address of the user whose borrow balance is being queried
    /// @param marketId The identifier of the market (as a bytes32 value)
    /// @return The current amount of assets borrowed by the user in the specified market
    function currentBorrow(
        address morphoPool,
        address user,
        bytes32 marketId
    ) external view returns (uint256) {
        if (morphoPool == address(0)) revert InvalidMorphoPoolAddress();
        if (user == address(0)) revert InvalidUserAddress();
        if (marketId == bytes32(0)) revert InvalidMarketId();

        IMorpho morpho = IMorpho(morphoPool);
        Id wrappedMarketId = Id.wrap(marketId);
        MarketParams memory marketParams = morpho.idToMarketParams(
            wrappedMarketId
        );
        uint256 borrowedAssets = MorphoBalancesLib.expectedBorrowAssets(
            morpho,
            marketParams,
            user
        );
        return borrowedAssets;
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Generates calldata for Morpho operations
    /// @param selector The function selector for the operation
    /// @param morphoPool The address of the Morpho pool
    /// @param asset The address of the asset (unused but kept for interface compatibility)
    /// @param user The address of the user
    /// @param amount The amount for the operation
    /// @param payoutUser Whether to pay out to the user
    /// @param data Additional data containing the market ID
    function generateCalldata(
        bytes4 selector,
        address morphoPool,
        address asset,
        address user,
        uint256 amount,
        bool payoutUser,
        bytes calldata data
    ) external view approvedMorphoPoolOnly(morphoPool) returns (bytes memory) {
        bytes32 marketIdBytes = abi.decode(data, (bytes32));
        Id marketId = Id.wrap(marketIdBytes);
        MarketParams memory marketParams = IMorpho(morphoPool).idToMarketParams(
            marketId
        );
        if (selector == WITHDRAW_COLLATERAL_SELECTOR) {
            if (marketParams.collateralToken != asset) {
                revert IncorrectTargetAsset();
            }
            return
                abi.encodeWithSelector(
                    selector,
                    morphoPool,
                    marketParams,
                    amount,
                    user,
                    payoutUser
                );
        } else if (selector == BORROW_SELECTOR) {
            if (marketParams.loanToken != asset) {
                revert IncorrectTargetAsset();
            }
            return
                abi.encodeWithSelector(
                    selector,
                    morphoPool,
                    marketParams,
                    amount,
                    user,
                    payoutUser
                );
        } else {
            revert UnsupportedSelector();
        }
    }

    /// @notice Previews a Morpho refinance-out action by resolving the market's loan and
    ///         collateral tokens from the on-chain market params.
    /// @dev Decodes the Morpho market ID from `additionalCalldata` and queries `idToMarketParams`
    ///      to populate the expected input (loan token) and output (collateral token). Amounts
    ///      are passed through unchanged.
    /// @param actionHookInput The action hook input where:
    ///   - `targetAddress`: the Morpho pool address
    ///   - `maxInputAmount`: the repayment amount
    ///   - `minOutputAmount`: the collateral amount to withdraw
    ///   - `additionalCalldata`: ABI-encoded `bytes32` Morpho market ID
    /// @return A `PreviewAction` with the market's loan token as input and collateral token as output.
    function previewMorphoRefinanceOut(
        ActionHookInput calldata actionHookInput
    )
        external
        view
        approvedMorphoPoolOnly(actionHookInput.targetAddress)
        returns (PreviewAction memory)
    {
        bytes32 marketIdBytes = abi.decode(
            actionHookInput.additionalCalldata,
            (bytes32)
        );
        Id marketId = Id.wrap(marketIdBytes);
        MarketParams memory marketParams = IMorpho(
            actionHookInput.targetAddress
        ).idToMarketParams(marketId);

        if (marketParams.loanToken == marketParams.collateralToken) {
            revert InputOutputTokenCollision();
        }

        PreviewAction memory previewAction = PreviewAction({
            expectedInputToken: marketParams.loanToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: marketParams.collateralToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: true
        });
        return previewAction;
    }

    /// @notice Previews a Morpho refinance-in action by resolving the market's collateral and
    ///         loan tokens from the on-chain market params.
    /// @dev Decodes the Morpho market ID from `additionalCalldata` and queries `idToMarketParams`
    ///      to populate the expected input (collateral token) and output (loan token). Amounts
    ///      are passed through unchanged.
    /// @param actionHookInput The action hook input where:
    ///   - `targetAddress`: the Morpho pool address
    ///   - `maxInputAmount`: the collateral amount to supply
    ///   - `minOutputAmount`: the borrow amount
    ///   - `additionalCalldata`: ABI-encoded `bytes32` Morpho market ID
    /// @return A `PreviewAction` with the market's collateral token as input and loan token as output.
    function previewMorphoRefinanceIn(
        ActionHookInput calldata actionHookInput
    )
        external
        view
        approvedMorphoPoolOnly(actionHookInput.targetAddress)
        returns (PreviewAction memory)
    {
        bytes32 marketIdBytes = abi.decode(
            actionHookInput.additionalCalldata,
            (bytes32)
        );
        Id marketId = Id.wrap(marketIdBytes);
        MarketParams memory marketParams = IMorpho(
            actionHookInput.targetAddress
        ).idToMarketParams(marketId);

        if (marketParams.loanToken == marketParams.collateralToken) {
            revert InputOutputTokenCollision();
        }

        PreviewAction memory previewAction = PreviewAction({
            expectedInputToken: marketParams.collateralToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: marketParams.loanToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: true
        });
        return previewAction;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    /// @notice Supplies `assets` of collateral on behalf of `user`
    /// @param morphoPool_ The address of the Morpho pool
    /// @param marketParams_ The Morpho market to supply collateral to
    /// @param assets_ The amount of collateral to supply
    /// @param user_ The address of the account to supply collateral on behalf of
    function _morphoSupplyCollateralInternal(
        address morphoPool_,
        MarketParams memory marketParams_,
        uint256 assets_,
        address user_
    ) internal {
        if (morphoPool_ == address(0)) revert InvalidMorphoPoolAddress();
        if (assets_ == 0) revert InvalidAmount();
        if (marketParams_.collateralToken == address(0))
            revert InvalidAssetAddress();
        if (user_ == address(this)) revert SelfSupplyNotAllowed();

        IERC20(marketParams_.collateralToken).forceApprove(
            morphoPool_,
            assets_
        );
        uint256 collateralBalanceBefore = IERC20(marketParams_.collateralToken)
            .balanceOf(address(this));

        IMorpho(morphoPool_).supplyCollateral(
            marketParams_,
            assets_,
            user_,
            bytes("")
        );

        uint256 collateralBalanceAfter = IERC20(marketParams_.collateralToken)
            .balanceOf(address(this));
        uint256 actualSupplied = collateralBalanceBefore -
            collateralBalanceAfter;
        if (actualSupplied != assets_) revert SupplyAmountMismatch();

        IERC20(marketParams_.collateralToken).forceApprove(morphoPool_, 0);
    }

    /// @notice Supplies `assets` of the loan asset on behalf of `user`
    /// @param morphoPool_ The address of the Morpho pool
    /// @param marketParams_ The Morpho market to supply assets to
    /// @param assets_ The amount of assets to supply
    /// @param user_ The address of the account to supply assets on behalf of
    /// @param usePermit2_ Whether Permit2 was used for token approvals
    function _morphoSupplyInternal(
        address morphoPool_,
        MarketParams memory marketParams_,
        uint256 assets_,
        address user_,
        bool usePermit2_
    ) internal {
        if (assets_ == 0) revert InvalidAmount();
        if (marketParams_.loanToken == address(0)) revert InvalidAssetAddress();
        if (user_ == address(this)) revert SelfSupplyNotAllowed();

        if (usePermit2_) {
            Permit2Lib.PERMIT2.transferFrom(
                user_,
                address(this),
                assets_.toUint160(),
                marketParams_.loanToken
            );
        } else {
            IERC20(marketParams_.loanToken).safeTransferFrom(
                user_,
                address(this),
                assets_
            );
        }

        IERC20(marketParams_.loanToken).forceApprove(morphoPool_, assets_);
        uint256 loanTokenBalanceBefore = IERC20(marketParams_.loanToken)
            .balanceOf(address(this));

        (uint256 assetsSupplied, ) = IMorpho(morphoPool_).supply(
            marketParams_,
            assets_,
            0,
            user_,
            bytes("")
        );

        uint256 loanTokenBalanceAfter = IERC20(marketParams_.loanToken)
            .balanceOf(address(this));
        uint256 actualSupplied = loanTokenBalanceBefore - loanTokenBalanceAfter;
        if (actualSupplied != assets_) revert SupplyAmountMismatch();

        IERC20(marketParams_.loanToken).forceApprove(morphoPool_, 0);

        if (assetsSupplied != assets_) revert SupplyAmountMismatch();
    }

    /// @notice Withdraws `assets` of the collateral asset on behalf of the `user`
    /// @param morphoPool_ The address of the Morpho pool
    /// @param marketParams_ The Morpho market to withdraw collateral from
    /// @param assets_ The amount of collateral to withdraw
    /// @param user_ The address of the account to withdraw collateral on behalf of
    /// @param payoutUser_ If true, the withdrawn collateral will be transferred to `user_`
    function _morphoWithdrawCollateralInternal(
        address morphoPool_,
        MarketParams memory marketParams_,
        uint256 assets_,
        address user_,
        bool payoutUser_
    ) internal {
        if (assets_ == 0) revert InvalidAmount();
        if (marketParams_.collateralToken == address(0))
            revert InvalidAssetAddress();
        if (user_ == address(0)) revert InvalidUserAddress();

        /// @dev function does not return withdrawal amount
        if (
            atomicTxInitiator() != address(0) ||
            getFlashLoanBorrower() != address(0) ||
            msg.sender == address(this)
        ) {
            IMorpho(morphoPool_).withdrawCollateral(
                marketParams_,
                assets_,
                user_,
                payoutUser_ ? user_ : address(this)
            );
        } else {
            IMorpho(morphoPool_).withdrawCollateral(
                marketParams_,
                assets_,
                user_,
                user_
            );
        }
    }

    /// @notice Borrows `assets` of the loan asset on behalf of the `user`
    /// @param morphoPool_ The address of the Morpho pool
    /// @param marketParams_ The Morpho market to borrow assets from
    /// @param assets_ The amount of assets to borrow
    /// @param user_ The address of the account to borrow assets on behalf of
    /// @param payoutUser_ If true, the borrowed assets will be transferred to `user_`
    function _morphoBorrowInternal(
        address morphoPool_,
        MarketParams memory marketParams_,
        uint256 assets_,
        address user_,
        bool payoutUser_
    ) internal {
        if (assets_ == 0) revert InvalidAmount();
        if (marketParams_.loanToken == address(0)) revert InvalidAssetAddress();
        if (user_ == address(0)) revert InvalidUserAddress();

        uint256 borrowedAssets;

        if (
            atomicTxInitiator() != address(0) ||
            getFlashLoanBorrower() != address(0) ||
            msg.sender == address(this)
        ) {
            (borrowedAssets, ) = IMorpho(morphoPool_).borrow(
                marketParams_,
                assets_,
                0,
                user_,
                payoutUser_ ? user_ : address(this)
            );
        } else {
            (borrowedAssets, ) = IMorpho(morphoPool_).borrow(
                marketParams_,
                assets_,
                0,
                user_,
                user_
            );
        }

        if (borrowedAssets != assets_) revert BorrowedAssetsMismatch();
    }

    /// @notice Repays `assets` of the loan asset on behalf of `user`
    /// @param morphoPool_ The address of the Morpho pool
    /// @param marketParams_ The Morpho market to repay assets to
    /// @param assets_ The amount of assets to repay
    /// @param user_ The address of the account to repay assets on behalf of
    function _morphoRepayInternal(
        address morphoPool_,
        MarketParams memory marketParams_,
        uint256 assets_,
        address user_
    ) internal {
        if (assets_ == 0) revert InvalidAmount();
        if (marketParams_.loanToken == address(0)) revert InvalidAssetAddress();
        if (user_ == address(0)) revert InvalidUserAddress();

        IERC20(marketParams_.loanToken).forceApprove(morphoPool_, assets_);
        (uint256 repaidAssets, ) = IMorpho(morphoPool_).repay(
            marketParams_,
            assets_,
            0,
            user_,
            bytes("")
        );
        IERC20(marketParams_.loanToken).forceApprove(morphoPool_, 0);

        if (repaidAssets + 1 < assets_) revert RepaidAssetsMismatch();
    }
}

contracts/facets/flashloan/TermFlashLoan.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IDiamondLoupe} from "../DiamondLoupeFacet.sol";
import {TermFlashBase} from "../base/TermFlashBase.sol";
import {Versionable} from "../../lib/Versionable.sol";

interface InstaFlashReceiverInterface {
    function executeOperation(
        address[] calldata assets,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        bytes calldata data
    ) external returns (bool);
}

/// @author TermLabs
/// @title TermFlashLoanCentralReceiverFacet
/// @notice Central flash loan receiver for Term Finance protocol operations
/// @dev Implements flash loan callback interface for various Term Finance operations
contract TermFlashLoanCentralReceiverFacet is
    InstaFlashReceiverInterface,
    TermFlashBase,
    Versionable
{
    struct TermFlashLoanCallback {
        address callbackFacet;
        bytes4 selector;
    }

    using SafeERC20 for IERC20;
    using Address for address;

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================
    uint256 public constant MAX_OPERATION_DATA = 32768; // 32 KB

    uint256 public constant MAX_PREMIUM_PERCENTAGE = 1000; // 10% (basis points)

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================
    /// @notice Thrown when array lengths of assets, amounts, and premiums do not match
    error ArrayLengthMismatch();

    /// @notice Thrown when callback facet does not match selector mapping
    error CallbackFacetSelectorMismatch();

    /// @notice Thrown when calldata size exceeds maximum allowed limit
    error CalldataTooLarge();

    /// @notice Thrown when flash loan premium exceeds maximum allowed percentage
    error ExcessivePremium();

    /// @notice Thrown when an asset address is invalid (zero address)
    error InvalidAssetAddress();

    /// @notice Thrown when selector is not found in diamond
    error SelectorNotFound();

    /// @notice Thrown when amount is zero
    error ZeroAmount();

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    address immutable flashLoanAggregatorContract;

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    constructor(address flashLoanAggregator_) {
        flashLoanAggregatorContract = flashLoanAggregator_;
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @notice Flash loan callback function that executes various Term Finance operations
    /// @dev Called by the flash loan aggregator with the borrowed funds, routes to appropriate facet
    /// @param assets Array of borrowed asset addresses
    /// @param amounts Array of borrowed amounts
    /// @param premiums Array of flash loan fees
    /// @param initiator Address that initiated the flash loan
    /// @param data Encoded operation parameters containing function selector and operation data
    /// @return success Boolean indicating successful execution
    function executeOperation(
        address[] calldata assets,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        bytes calldata data
    )
        external
        override
        validateCallback(flashLoanAggregatorContract, initiator)
        returns (bool success)
    {
        if (
            assets.length != amounts.length || amounts.length != premiums.length
        ) {
            revert ArrayLengthMismatch();
        }
        for (uint256 i = 0; i < assets.length; i++) {
            if (assets[i] == address(0)) {
                revert InvalidAssetAddress();
            }
            if (amounts[i] == 0) {
                revert ZeroAmount();
            }

            if (premiums[i] > (amounts[i] * MAX_PREMIUM_PERCENTAGE) / 10000) {
                revert ExcessivePremium();
            }
        }

        if (data.length > MAX_OPERATION_DATA) {
            revert CalldataTooLarge();
        }

        // Decode TermFlashLoanCallback from the beginning of calldata
        (TermFlashLoanCallback memory callback, ) = abi.decode(
            data,
            (TermFlashLoanCallback, bytes)
        );

        // Verify that the callback's facet and selector are properly mapped in the diamond
        address actualFacet = IDiamondLoupe(address(this)).facetAddress(
            callback.selector
        );
        if (actualFacet == address(0)) revert SelectorNotFound();
        if (actualFacet != callback.callbackFacet)
            revert CallbackFacetSelectorMismatch();

        // Encode the flash loan parameters with the callback selector and operation data
        bytes memory encodedData = abi.encodePacked(
            callback.selector,
            abi.encode(assets, amounts, premiums, initiator, data)
        );

        // Execute the flash loan operation using the callback's selector
        Address.functionDelegateCall(actualFacet, encodedData);
        return true;
    }
}

//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {IDiamondLoupe} from "../DiamondLoupeFacet.sol";
import {ITermFlashLoan} from "../../interfaces/ITermFlashLoan.sol";
import {PreviewAction} from "../../lib/PreviewAction.sol";
import {Versionable} from "../../lib/Versionable.sol";

import {TermFlashBase} from "../base/TermFlashBase.sol";
import {TermFlashHookFacet} from "../base/TermFlashHookFacet.sol";

import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

interface IFlashLoanAggregator {
    function flashLoan(
        address[] memory _tokens,
        uint256[] memory _amounts,
        uint256 _route,
        bytes calldata _data,
        bytes calldata // kept for future use by instadapp. Currently not used anywhere.
    ) external;
}

/// @title TermFlashLoanExecutorFacet
/// @notice Diamond facet that orchestrates multi-step flash-loan-funded action pipelines.
/// @dev Users submit a `FlashExecuteRequest` containing an ordered list of actions (e.g. repay
///      debt, withdraw collateral, deposit into a vault, borrow on another protocol). The facet:
///      1. Previews the first action to determine the required flash loan amount.
///      2. Borrows that amount from the flash loan aggregator (Instadapp).
///      3. In the callback, sequentially executes each action via `delegatecall`-style routing
///         through the diamond, snapshotting token balances before/after each step.
///      4. Optionally back-propagates minimum output requirements from the final repayment
///         amount through the pipeline to tighten intermediate limits.
///      5. Repays the flash loan (principal + premium) and refunds any surplus to the user.
contract TermFlashLoanExecutorFacet is
    ITermFlashLoan,
    TermFlashBase,
    Versionable
{
    using SafeCast for uint256;
    using SafeERC20 for IERC20;
    using Address for address;

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when actions array in the flash execute request is empty
    error EmptyActions();

    /// @notice Thrown when the preview expected input amount exceeds the user's max input amount
    error ExpectedInputExceedsMax(uint256 actionIndex);

    /// @notice Thrown when the preview expected output amount is below the user's min output amount
    error ExpectedOutputBelowMin(uint256 actionIndex);

    /// @notice Thrown when the final token does not match the expected token during flash loan execution.
    error FinalOutputTokenMismatch();

    /// @notice Thrown when the final output token or amount is incompatible with flash loan repayment
    error FlashloanRepayIncompatible();

    /// @notice Thrown when flash loan amount is insufficient to cover the debt repayment
    error IncorrectFlashLoanAmount();

    /// @notice Thrown when actual input spent exceeds the max input amount for a pipeline step
    error InputAmountExceeded(uint256 actionIndex);

    /// @notice Thrown when the input token and output token for a pipeline step are the same
    error InputTokenMatchesOutputToken(uint256 actionIndex);

    /// @notice Thrown when the current token doesn't match the expected input token for a pipeline step
    error InputTokenMismatch(uint256 actionIndex);

    /// @notice Thrown when flash loan asset doesn't match expected asset
    error InvalidFlashloanAsset();

    /// @notice Thrown when flash loan received doesn't match expected parameters
    error InvalidFlashLoanReceived();

    /// @notice Thrown when the current token doesn't match the user-defined input token at a pipeline step
    error InvalidInputToken(uint256 actionIndex);

    /// @notice Thrown when no tokens are received from a pipeline step
    error NoTokensReceived();

    /// @notice Thrown when actual output gained is below the minimum output amount for a pipeline step
    error OutputAmountInsufficient(uint256 actionIndex);

    /// @notice Thrown when the actual output token doesn't match the user-defined output token
    error OutputTokenMismatch(uint256 actionIndex);

    /// @notice Thrown when a facet selector is not found in the diamond
    error SelectorNotFound();

    /// @notice Thrown when flashloan execute user is not the authorized caller
    error UserNotFlashLoanInitiator();

    /// @notice Thrown when a pipeline step has a zero address as input token
    error ZeroInputToken(uint256 actionIndex);

    /// @notice Thrown when a pipeline step has a zero address as output token
    error ZeroOutputToken(uint256 actionIndex);

    // ========================================================================
    // = Structs  =============================================================
    // ========================================================================

    /// @notice A single step in the flash loan execution pipeline.
    /// @param inputToken The token consumed by this step.
    /// @param maxInputAmount The maximum amount of `inputToken` this step is allowed to spend.
    /// @param outputToken The token produced by this step.
    /// @param minOutputAmount The minimum amount of `outputToken` this step must produce.
    /// @param outputTokenAmountIn Optional extra amount of `outputToken` that is transferred in and added to this step's output after it executes (and before the next step).
    /// @param usePermit2ForOutputTokenIn Whether to use Permit2 for the `outputTokenAmountIn` transfer.
    /// @param method The function selector on the target facet to call for this step.
    /// @param targetAddress The external protocol or contract address the action interacts with.
    /// @param additionalCalldata Extra calldata forwarded to the action (e.g. Permit2 flag, market ID).
    struct Action {
        address inputToken;
        uint256 maxInputAmount;
        address outputToken;
        uint256 minOutputAmount;
        uint256 outputTokenAmountIn; // optional extra outputToken added to this step's output after execution
        bool usePermit2ForOutputTokenIn;
        bytes4 method;
        address targetAddress;
        bytes additionalCalldata;
    }

    /// @notice User-facing request to initiate a flash-loan-funded action pipeline.
    /// @param flashLoanRoute The Instadapp aggregator route ID for sourcing the flash loan.
    /// @param flashLoanInstaData Extra data passed to the Instadapp aggregator (reserved for future use).
    /// @param flashLoanToken The token to borrow via flash loan (must match the first action's input and last action's output).
    /// @param actions The ordered list of pipeline steps to execute within the flash loan callback. Must contain at least 2 actions.
    /// @param backPropagate Whether to back-propagate the flash loan repayment amount through the pipeline to tighten intermediate limits.
    struct FlashExecuteRequest {
        uint256 flashLoanRoute;
        bytes flashLoanInstaData;
        address flashLoanToken;
        Action[] actions;
        bool backPropagate;
    }

    /// @notice Internal execution plan constructed from a `FlashExecuteRequest` after previewing the first action.
    /// @param user The address that initiated the flash loan pipeline.
    /// @param flashLoanToken The token borrowed via flash loan.
    /// @param flashLoanAmount The amount borrowed, determined by previewing the first action.
    /// @param actions The ordered list of pipeline steps to execute.
    /// @param backPropagate Whether to back-propagate minimum output requirements from the repayment amount.
    struct ExecutionPlan {
        address user;
        address flashLoanToken;
        uint256 flashLoanAmount;
        Action[] actions;
        bool backPropagate;
    }

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    address immutable flashLoanAggregatorContract;

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    constructor(address flashLoanAggregator_) {
        flashLoanAggregatorContract = flashLoanAggregator_;
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @notice Entry point for executing a multi-step action pipeline funded by a flash loan.
    /// @dev Sets the caller as the flash loan borrower context, previews the first action to
    ///      determine the required flash loan amount, validates that the first action's input
    ///      token and the last action's output token both match the flash loan token, then
    ///      initiates the flash loan via the aggregator. Execution of the action pipeline
    ///      continues in `flashExecuteCallback`.
    /// @param flashExecuteRequest The request containing the flash loan route, token, ordered
    ///        list of actions, and whether to back-propagate minimum output requirements.
    function flashExecute(
        FlashExecuteRequest memory flashExecuteRequest
    ) external {
        if (flashExecuteRequest.actions.length == 0) {
            revert EmptyActions();
        }

        // Set flashloan context for the borrower who initiated this operation
        _setFlashLoanBorrower(msg.sender);

        TermFlashLoanCallback
            memory termFlashLoanCallback = TermFlashLoanCallback({
                callbackFacet: IDiamondLoupe(address(this)).facetAddress(
                    this.flashExecuteCallback.selector
                ),
                selector: this.flashExecuteCallback.selector
            });

        /// @dev Generate preview of the first action to validate the flash loan input token and amount before initiating the flash loan
        (PreviewAction memory previewAction, ) = _generateActionCalldata(
            msg.sender,
            flashExecuteRequest.actions[0]
        );

        if (
            previewAction.expectedInputToken !=
            flashExecuteRequest.flashLoanToken
        ) {
            revert InvalidInputToken(0);
        }

        if (
            flashExecuteRequest
                .actions[flashExecuteRequest.actions.length - 1]
                .outputToken != flashExecuteRequest.flashLoanToken
        ) {
            revert FinalOutputTokenMismatch();
        }

        ExecutionPlan memory executionPlan = ExecutionPlan({
            user: msg.sender,
            flashLoanToken: flashExecuteRequest.flashLoanToken,
            flashLoanAmount: previewAction.expectedInputAmount,
            actions: flashExecuteRequest.actions,
            backPropagate: flashExecuteRequest.backPropagate
        });

        bytes memory executionPlanData = abi.encode(executionPlan);
        bytes memory flashLoanData = abi.encode(
            termFlashLoanCallback,
            executionPlanData
        );

        IFlashLoanAggregator(flashLoanAggregatorContract).flashLoan(
            _getTokens(flashExecuteRequest.flashLoanToken),
            _getAmounts(previewAction.expectedInputAmount),
            flashExecuteRequest.flashLoanRoute,
            flashLoanData,
            flashExecuteRequest.flashLoanInstaData
        );
    }

    /// @notice Callback invoked by the flash loan aggregator after flash-loaned funds are received
    /// @dev Decodes the execution plan from `data`, validates the flash loan parameters, then
    ///      sequentially executes each action in the pipeline. After all actions complete, repays
    ///      the flash loan (principal + premium) and refunds any surplus to the user. Clears the
    ///      flash loan borrower context on completion.
    /// @param assets The addresses of the flash-loaned assets (must be a single-element array)
    /// @param amounts The amounts of each flash-loaned asset (must be a single-element array)
    /// @param premiums The fee amounts owed on each flash-loaned asset (must be a single-element array)
    /// @param initiator The address that initiated the flash loan (validated via `validateCallback`)
    /// @param data ABI-encoded `(TermFlashLoanCallback, ExecutionPlan)` containing the action pipeline
    /// @return success True if the callback executed and repaid the flash loan successfully
    function flashExecuteCallback(
        address[] calldata assets,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        bytes calldata data
    )
        external
        validateCallback(flashLoanAggregatorContract, initiator)
        returns (bool success)
    {
        (, bytes memory executionPlanData) = abi.decode(
            data,
            (TermFlashLoanCallback, bytes)
        );
        ExecutionPlan memory executionPlan = abi.decode(
            executionPlanData,
            (ExecutionPlan)
        );

        if (_getFlashLoanBorrower() != executionPlan.user) {
            revert UserNotFlashLoanInitiator();
        }

        if (assets.length != 1 || amounts.length != 1 || premiums.length != 1) {
            revert InvalidFlashLoanReceived();
        }

        // Validate that assets[0] is the debt asset
        if (assets[0] != executionPlan.flashLoanToken)
            revert InvalidFlashloanAsset();
        if (amounts[0] != executionPlan.flashLoanAmount)
            revert IncorrectFlashLoanAmount();

        // Calculate amount owing to flash loan provider
        uint256 amountOwing = amounts[0] + premiums[0];

        // Enforce final action produces at least enough to repay the flash loan
        if (executionPlan.backPropagate) {
            executionPlan = _backPropagateMinOutputs(
                executionPlan,
                amountOwing
            );
        } else {
            uint256 lastActionIndex = executionPlan.actions.length - 1;
            uint256 lastDeposit = executionPlan
                .actions[lastActionIndex]
                .outputTokenAmountIn;
            uint256 requiredFinalOutput = amountOwing > lastDeposit
                ? amountOwing - lastDeposit
                : 0;
            if (
                requiredFinalOutput >
                executionPlan.actions[lastActionIndex].minOutputAmount
            ) {
                executionPlan
                    .actions[lastActionIndex]
                    .minOutputAmount = requiredFinalOutput;
            }
        }

        address currentInputToken = assets[0];
        uint256 currentInputAmount = amounts[0];
        uint256 actualInputSpent;
        uint256 actualOutputGained;
        address actualOutputToken;

        for (uint256 i = 0; i < executionPlan.actions.length; i++) {
            // Validate action inputToken
            if (executionPlan.actions[i].inputToken == address(0)) {
                revert ZeroInputToken(i);
            }

            // Validate action outputToken
            if (executionPlan.actions[i].outputToken == address(0)) {
                revert ZeroOutputToken(i);
            }

            // Validate input and output tokens are not the same
            if (
                executionPlan.actions[i].inputToken ==
                executionPlan.actions[i].outputToken
            ) {
                revert InputTokenMatchesOutputToken(i);
            }

            //  Validate current input token matches user defined input token
            if (currentInputToken != executionPlan.actions[i].inputToken) {
                revert InvalidInputToken(i);
            }

            // Allow spend up to max and/or what is available
            if (currentInputAmount < executionPlan.actions[i].maxInputAmount) {
                executionPlan.actions[i].maxInputAmount = currentInputAmount;
            }

            // Execute the action: preview, validate, and perform the on-chain call
            (
                actualOutputToken,
                actualOutputGained,
                actualInputSpent
            ) = _executePipelineStep(
                executionPlan.user,
                executionPlan.actions[i],
                i
            );

            // Revert if more input was consumed than the allowed maximum
            if (actualInputSpent > executionPlan.actions[i].maxInputAmount) {
                revert InputAmountExceeded(i);
            }

            // Revert if output received is below the required minimum
            if (actualOutputGained < executionPlan.actions[i].minOutputAmount) {
                revert OutputAmountInsufficient(i);
            }

            // Transfer in additional output tokens from user where specified
            uint256 outputTokenAmountIn = executionPlan
                .actions[i]
                .outputTokenAmountIn;
            if (outputTokenAmountIn > 0) {
                if (executionPlan.actions[i].usePermit2ForOutputTokenIn) {
                    Permit2Lib.PERMIT2.transferFrom(
                        executionPlan.user,
                        address(this),
                        outputTokenAmountIn.toUint160(),
                        actualOutputToken
                    );
                } else {
                    IERC20(actualOutputToken).safeTransferFrom(
                        executionPlan.user,
                        address(this),
                        outputTokenAmountIn
                    );
                }
                actualOutputGained += outputTokenAmountIn;
            }

            // Refund any unspent input tokens back to the user
            if (currentInputAmount > actualInputSpent) {
                IERC20(currentInputToken).safeTransfer(
                    executionPlan.user,
                    currentInputAmount - actualInputSpent
                );
            }
            currentInputToken = actualOutputToken;
            currentInputAmount = actualOutputGained;
        }

        if (
            currentInputToken != executionPlan.flashLoanToken ||
            currentInputAmount < amountOwing
        ) {
            revert FlashloanRepayIncompatible();
        }

        //repay flashloan
        IERC20(currentInputToken).safeTransfer(msg.sender, amountOwing);

        if (currentInputAmount > amountOwing) {
            IERC20(currentInputToken).safeTransfer(
                executionPlan.user,
                currentInputAmount - amountOwing
            );
        }

        // Clear flashloan context after operations complete
        _clearFlashLoanBorrower();

        return true;
    }

    /// @notice Simulates backpropagation of output requirements across an execution plan.
    /// @param executionPlan The proposed execution plan to validate and tighten
    /// @param amountOwing The flash loan principal + premium the final action must cover
    /// @return The adjusted execution plan with tightened minOutputAmount and maxInputAmount values
    function quoteExecutionPlan(
        ExecutionPlan memory executionPlan,
        uint256 amountOwing
    ) external view returns (ExecutionPlan memory) {
        return _backPropagateMinOutputs(executionPlan, amountOwing);
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    function _getAmounts(
        uint256 flashLoanAmount
    ) internal pure returns (uint256[] memory) {
        uint256[] memory amounts = new uint256[](1);
        amounts[0] = flashLoanAmount;
        return amounts;
    }

    function _getTokens(
        address flashLoanToken
    ) internal pure returns (address[] memory) {
        address[] memory tokens = new address[](1);
        tokens[0] = flashLoanToken;
        return tokens;
    }

    function _executePipelineStep(
        address user,
        Action memory action,
        uint256 index
    ) private returns (address, uint256, uint256) {
        // Generate calldata
        (
            PreviewAction memory previewAction,
            bytes memory encodedCalldata
        ) = _generateActionCalldata(user, action);

        // Validate actual output token matches user defined output token
        if (action.inputToken != previewAction.expectedInputToken) {
            revert InputTokenMismatch(index);
        }

        if (action.maxInputAmount < previewAction.expectedInputAmount) {
            revert ExpectedInputExceedsMax(index);
        }

        // Validate actual output token matches user defined output token
        if (action.outputToken != previewAction.expectedOutputToken) {
            revert OutputTokenMismatch(index);
        }

        if (
            previewAction.isDeterministic &&
            action.minOutputAmount > previewAction.expectedOutputAmount
        ) {
            revert ExpectedOutputBelowMin(index);
        }

        // Execute calldata
        (
            uint256 actualOutputGained,
            uint256 actualInputSpent
        ) = _executeCallAndGetTokenBalances(
                encodedCalldata,
                action.inputToken,
                action.outputToken
            );

        return (action.outputToken, actualOutputGained, actualInputSpent);
    }

    function _getFacetAddress(bytes4 selector) private view returns (address) {
        address facetAddress = IDiamondLoupe(address(this)).facetAddress(
            selector
        );

        if (facetAddress == address(0)) {
            revert SelectorNotFound();
        }

        return facetAddress;
    }

    function _generateActionCalldata(
        address user,
        Action memory action
    ) private view returns (PreviewAction memory, bytes memory) {
        bytes memory encodeGenerateCalldataInput;
        address facetAddress = _getFacetAddress(action.method);
        bytes4 sig = TermFlashHookFacet.generateActionCalldata.selector;
        encodeGenerateCalldataInput = abi.encodeWithSelector(
            sig,
            user,
            action.inputToken,
            action.maxInputAmount,
            action.outputToken,
            action.minOutputAmount,
            action.method,
            action.targetAddress,
            action.additionalCalldata
        );

        bytes memory generateCalldataReturn = Address.functionStaticCall(
            facetAddress,
            encodeGenerateCalldataInput
        );

        return abi.decode(generateCalldataReturn, (PreviewAction, bytes));
    }

    function _backPropagateMinOutputs(
        ExecutionPlan memory executionPlan,
        uint256 amountOwing
    ) private view returns (ExecutionPlan memory) {
        uint256 requiredOut = amountOwing;

        PreviewAction memory previewAction;
        Action memory action;
        for (uint256 i = executionPlan.actions.length; i > 0; ) {
            unchecked {
                --i;
            }

            action = executionPlan.actions[i];
            uint256 originalMinOutput = action.minOutputAmount;
            uint256 outputTokenAmountIn = action.outputTokenAmountIn;
            action.minOutputAmount = requiredOut > outputTokenAmountIn
                ? requiredOut - outputTokenAmountIn
                : 0;

            (previewAction, ) = _generateActionCalldata(
                executionPlan.user,
                action
            );

            // Restore floor protection for non-deterministic actions
            if (
                !previewAction.isDeterministic &&
                originalMinOutput > action.minOutputAmount
            ) {
                action.minOutputAmount = originalMinOutput;
            }

            // Validate actual input token matches user defined input token
            if (action.inputToken != previewAction.expectedInputToken) {
                revert InputTokenMismatch(i);
            }

            // Validate actual output token matches user defined output token
            if (action.outputToken != previewAction.expectedOutputToken) {
                revert OutputTokenMismatch(i);
            }

            if (action.maxInputAmount < previewAction.expectedInputAmount) {
                revert ExpectedInputExceedsMax(i);
            }

            // Pin to exact input
            if (previewAction.isDeterministic) {
                action.maxInputAmount = previewAction.expectedInputAmount;
            }

            requiredOut = previewAction.expectedInputAmount;
            executionPlan.actions[i] = action;
        }

        return executionPlan;
    }

    function _executeCallAndGetTokenBalances(
        bytes memory encodedCalldata,
        address tokenIn,
        address tokenOut
    ) private returns (uint256, uint256) {
        IERC20 tokenInERC20 = IERC20(tokenIn);
        IERC20 tokenOutERC20 = IERC20(tokenOut);

        // Snapshot token balances before execution
        uint256 tokenInBalanceBefore = tokenInERC20.balanceOf(address(this));
        uint256 tokenOutBalanceBefore = tokenOutERC20.balanceOf(address(this));

        // Execute the encoded call against this contract
        Address.functionCall(address(this), encodedCalldata);

        // Verify output tokens were received and revert if not
        uint256 tokenInBalanceAfter = tokenInERC20.balanceOf(address(this));
        uint256 tokenOutBalanceAfter = tokenOutERC20.balanceOf(address(this));
        if (tokenOutBalanceAfter <= tokenOutBalanceBefore) {
            revert NoTokensReceived();
        }

        // Calculate net token deltas from the execution
        uint256 actualOutputGained = tokenOutBalanceAfter -
            tokenOutBalanceBefore;
        uint256 actualInputSpent = tokenInBalanceAfter < tokenInBalanceBefore
            ? tokenInBalanceBefore - tokenInBalanceAfter
            : 0;
        return (actualOutputGained, actualInputSpent);
    }
}

contracts/facets/KyberSwapFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";
import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";

/// @author TermLabs
/// @title KyberSwapFacet
/// @notice This facet enables token swaps via the Kyber Meta Aggregation Router V2 during Term contract operations
contract KyberSwapFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermMultiContextAuth,
    Versionable
{
    using SafeERC20 for ERC20;
    using Address for address;

    // ========================================================================

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when input amount doesn't match expected PT amount
    error InputAmountMismatch();

    /// @notice Thrown when Kyber Meta Aggregation Router V2 address is zero
    error InvalidKyberMetaAggregationRouterV2Address();

    address immutable kyberMetaAggregationRouterV2;

    /// @notice Initializes the swap router with Kyber Meta Aggregation Router V2 address
    /// @param kyberMetaAggregationRouterV2_ Address of the Kyber Meta Aggregation Router V2 contract
    constructor(address kyberMetaAggregationRouterV2_) {
        if (kyberMetaAggregationRouterV2_ == address(0))
            revert InvalidKyberMetaAggregationRouterV2Address();
        kyberMetaAggregationRouterV2 = kyberMetaAggregationRouterV2_;

        previewMapping[this.kyberSwapHook.selector] = this
            .previewKyberSwap
            .selector;
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Executes a token swap via Kyber Meta Aggregation Router V2
    /// @dev This function is called as a flash hook during a Term contract operation
    /// @param input Struct containing the input token address, maximum input amount, output token address
    function kyberSwapHook(
        ActionHookInput calldata input
    ) external nonReentrant onlyFlashLoanContext(input.user) {
        address tokenIn = input.inputToken;
        uint256 amountIn = input.maxInputAmount;
        bytes memory swapCalldata = abi.decode(
            input.additionalCalldata,
            (bytes)
        );
        _kyberSwapInternal(tokenIn, amountIn, swapCalldata);
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Previews the expected outcome of a token swap without executing it.
    /// @dev Returns a PreviewAction struct containing expected input and output tokens and amounts.
    /// @param actionHookInput Struct containing the input token address, maximum input amount, output token address, minimum output amount, and additional calldata for the swap.
    /// @return preview A PreviewAction struct containing expected input and output tokens and amounts, and a flag indicating if the outcome is deterministic.
    function previewKyberSwap(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        if (actionHookInput.inputToken == actionHookInput.outputToken) {
            revert InputOutputTokenCollision();
        }

        PreviewAction memory preview = PreviewAction({
            expectedInputToken: actionHookInput.inputToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: actionHookInput.outputToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: false
        });
        return preview;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    /// @notice Internal function that executes the swap via Kyber Meta Aggregation Router V2
    /// @dev Approves the router, calls it with the calldata, then revokes the approval
    /// @param tokenIn The address of the input token
    /// @param amountIn The amount of input tokens to swap
    /// @param swapCalldata The encoded calldata for the swap
    function _kyberSwapInternal(
        address tokenIn,
        uint256 amountIn,
        bytes memory swapCalldata
    ) internal {
        // Approve Kyber Meta Aggregation Router V2 to spend input tokens
        ERC20(tokenIn).forceApprove(kyberMetaAggregationRouterV2, amountIn);

        // Execute the swap via Kyber Meta Aggregation Router V2
        kyberMetaAggregationRouterV2.functionCall(swapCalldata);
        // Revoke approval after swap
        ERC20(tokenIn).forceApprove(kyberMetaAggregationRouterV2, 0);
    }
}

contracts/facets/MulticallFacet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import {LibDiamond} from "../libraries/LibDiamond.sol";

import {IDiamondLoupe} from "./DiamondLoupeFacet.sol";
import {TermMulticallProtection} from "./base/TermMulticallProtection.sol";
import {Versionable} from "../lib/Versionable.sol";

contract MulticallFacet is TermMulticallProtection, Versionable {
    // Custom ReentrancyGuard storage slot to avoid conflicts with other facets
    bytes32 private constant MULTICALL_REENTRANCY_SLOT =
        keccak256("multicall.reentrancy.guard");
    uint256 private constant NOT_ENTERED = 1;
    uint256 private constant ENTERED = 2;

    // Events for transparency and debugging
    event MulticallExecuted(uint256 callCount, bool[] successes);
    event MulticallFailed(uint256 failedAtIndex, string reason);

    // Custom errors for better gas efficiency
    error EmptyCallsArray();
    error InvalidFunctionSelector(bytes4 selector);
    error FacetNotEnabled(address facet);
    error SubcallFailed(uint256 index, string reason);
    error ReentrancyGuardReentrantCall();

    /**
     * @dev Prevents a contract from calling itself, directly or indirectly.
     */
    modifier nonReentrant() {
        _nonReentrantBefore();
        _;
        _nonReentrantAfter();
    }

    function _nonReentrantBefore() private {
        bytes32 slot = MULTICALL_REENTRANCY_SLOT;
        uint256 status;
        assembly {
            status := sload(slot)
        }
        if (status == ENTERED) {
            revert ReentrancyGuardReentrantCall();
        }
        assembly {
            sstore(slot, 2) // ENTERED = 2
        }
    }

    function _nonReentrantAfter() private {
        bytes32 slot = MULTICALL_REENTRANCY_SLOT;
        assembly {
            sstore(slot, 1) // NOT_ENTERED = 1
        }
    }

    /**
     * @notice Execute multiple calls atomically - reverts on first failure
     * @param calls Array of encoded function calls
     * @return results Array of return data from each call
     */
    function multicall(
        bytes[] calldata calls
    )
        external
        nonReentrant
        initiateMulticallProtection
        returns (bytes[] memory results)
    {
        // Input validation
        if (calls.length == 0) revert EmptyCallsArray();

        // Get diamond storage for direct facet lookup
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        results = new bytes[](calls.length);
        bool[] memory successes = new bool[](calls.length);

        for (uint256 i = 0; i < calls.length; i++) {
            // Validate the function selector and target facet
            _validateCall(calls[i]);

            // Get target facet directly from diamond storage
            bytes4 selector = bytes4(calls[i][:4]);
            address facet = ds
                .selectorToFacetAndPosition[selector]
                .facetAddress;
            require(
                facet != address(0),
                "MulticallFacet: Function does not exist"
            );

            // Direct delegatecall to facet (bypasses diamond fallback)
            (bool ok, bytes memory ret) = facet.delegatecall(calls[i]);
            successes[i] = ok;

            if (!ok) {
                _revert(ret);
            }

            results[i] = ret;
        }

        emit MulticallExecuted(calls.length, successes);
    }

    /**
     * @notice Validate that a call targets an enabled facet and allowed function
     * @param call The encoded function call
     */
    function _validateCall(bytes calldata call) private view {
        if (call.length < 4) revert InvalidFunctionSelector(bytes4(0));

        bytes4 selector = bytes4(call[:4]);

        // Get the facet address for this selector using DiamondLoupe
        IDiamondLoupe loupe = IDiamondLoupe(address(this));
        address facetAddress = loupe.facetAddress(selector);

        // Ensure the selector maps to a valid enabled facet
        if (facetAddress == address(0)) {
            revert InvalidFunctionSelector(selector);
        }

        // Verify the facet is actually enabled by checking if it's in the facets list
        address[] memory enabledFacets = loupe.facetAddresses();
        bool facetEnabled = false;

        for (uint256 i = 0; i < enabledFacets.length; i++) {
            if (enabledFacets[i] == facetAddress) {
                facetEnabled = true;
                break;
            }
        }

        if (!facetEnabled) {
            revert FacetNotEnabled(facetAddress);
        }
    }

    /**
     * @notice External function to safely decode error strings
     * @dev This is called via try/catch to handle malformed data gracefully
     */
    function decodeErrorString(
        bytes memory data
    ) external pure returns (string memory) {
        return abi.decode(data, (string));
    }

    /**
     * @notice Convert uint256 to string for panic code display
     */
    function _uint2str(uint256 _i) private pure returns (string memory str) {
        if (_i == 0) return "0";

        uint256 j = _i;
        uint256 length;
        while (j != 0) {
            length++;
            j /= 10;
        }

        bytes memory bstr = new bytes(length);
        uint256 k = length;
        j = _i;
        while (j != 0) {
            bstr[--k] = bytes1(uint8(48 + (j % 10)));
            j /= 10;
        }

        str = string(bstr);
    }

    /**
     * @notice Test helper function to expose _uint2str for testing
     * @dev This function should only be used for testing purposes
     */
    function uint2strTestHelper(
        uint256 _i
    ) external pure returns (string memory) {
        return _uint2str(_i);
    }
}

contracts/facets/Permit2Facet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {TermMulticallProtection} from "./base/TermMulticallProtection.sol";
import {ITermController} from "../interfaces/ITermController.sol";
import {Versionable} from "../lib/Versionable.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";

import {IAllowanceTransfer} from "permit2/src/interfaces/IAllowanceTransfer.sol";
/// @dev Permit2Lib uses a hardcoded address for PERMIT2, make sure it is the correct address for the chain of deployment.
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

/// @author TermLabs
/// @title Permit2Facet
/// @notice Provides Uniswap Permit2 integration for advanced signature-based token approvals
/// @dev Enables batch permits, allowance transfers, and signature-based token operations via Permit2 protocol
contract Permit2Facet is TermMulticallProtection, Versionable {
    using SafeCast for uint256;

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when deadline has expired
    error Expired();

    /// @notice Thrown when the spender address is invalid
    error InvalidSpender();

    /// @notice Thrown when the owner address is invalid
    error InvalidOwner();

    /// @notice Thrown when amount is zero
    error ZeroAmount();

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Approves the given `amount` of `asset` from the initiator to be spent by `permitSingle.spender` via Permit2 with the given `deadline` & EIP-712 `signature`
    /// @param permitSingle The `PermitSingle` struct
    /// @param signature The signature, serialized
    /// @param skipRevert Whether to avoid reverting the call in case the signature is frontrunned
    function approve2(
        IAllowanceTransfer.PermitSingle calldata permitSingle,
        bytes calldata signature,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (permitSingle.details.expiration <= block.timestamp)
            revert Expired();
        try
            Permit2Lib.PERMIT2.permit(initiator(), permitSingle, signature)
        {} catch (bytes memory returnData) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Approves the Diamond contract to spend tokens using Permit2
    /// @dev Validates that the spender in the permit is the Diamond contract (address(this))
    /// @param permitSingle The Permit2 single permit data containing token, amount, expiration, and nonce
    /// @param owner The address which owns the tokens
    /// @param signature The EIP-712 signature for the permit
    /// @param skipRevert If true, the function will not revert on failure
    function approve2Diamond(
        IAllowanceTransfer.PermitSingle calldata permitSingle,
        address owner,
        bytes calldata signature,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (permitSingle.details.expiration <= block.timestamp)
            revert Expired();
        if (permitSingle.spender != address(this)) revert InvalidSpender();
        try Permit2Lib.PERMIT2.permit(owner, permitSingle, signature) {} catch (
            bytes memory returnData
        ) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Approves a Term contract to spend tokens using Permit2
    /// @dev Validates that the spender is a valid Term contract deployed by an approved Term Controller
    /// @param permitSingle The Permit2 single permit data containing the Term contract as spender, token, amount, expiration, and nonce
    /// @param owner The address which owns the tokens
    /// @param signature The EIP-712 signature for the permit
    /// @param skipRevert If true, the function will not revert on failure
    function approve2TermContract(
        IAllowanceTransfer.PermitSingle calldata permitSingle,
        address owner,
        bytes calldata signature,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (permitSingle.details.expiration <= block.timestamp)
            revert Expired();
        if (owner == address(0)) revert InvalidOwner();
        TermStorage storage ts = LibTermStorage.termStorage();
        bool isValidTermContract;
        for (uint256 i = 0; i < ts.approvedTermControllerList.length; ++i) {
            ITermController termController = ITermController(
                ts.approvedTermControllerList[i]
            );
            if (
                termController.isTermDeployed(permitSingle.spender) ||
                termController.isFactoryDeployed(permitSingle.spender)
            ) {
                isValidTermContract = true;
                break;
            }
        }
        if (!isValidTermContract) revert InvalidSpender();
        try Permit2Lib.PERMIT2.permit(owner, permitSingle, signature) {} catch (
            bytes memory returnData
        ) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Transfers the given `amount` of `asset` from the initiator to the bundler via Permit2
    /// @param asset The address of the ERC20 token to transfer
    /// @param amount The amount of `asset` to transfer from the initiator. Capped at the initiator's balance
    function transferFrom2(
        address asset,
        uint256 amount
    ) external onlyMulticallInitiator {
        address _initiator = initiator();

        if (amount == 0) revert ZeroAmount();

        Permit2Lib.PERMIT2.transferFrom(
            _initiator,
            address(this),
            amount.toUint160(),
            asset
        );
    }
}

