//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {TermMulticallProtection} from "./base/TermMulticallProtection.sol";
import {ITermController} from "../interfaces/ITermController.sol";
import {Versionable} from "../lib/Versionable.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";

import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

/// @author TermLabs
/// @title PermitFacet
/// @notice Provides EIP-2612 permit functionality for gasless token approvals
/// @dev Enables users to approve token spending via signatures instead of transactions
contract PermitFacet is TermMulticallProtection, Versionable {
    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when deadline has expired
    error Expired();

    /// @notice Thrown when the owner address is invalid
    error InvalidOwner();

    /// @notice Thrown when the spender address is invalid
    error InvalidSpender();

    /// @notice Thrown when the asset address is invalid
    error InvalidAsset();

    /// @notice Thrown when signature components are invalid
    error InvalidSignature();

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Calls the permit function on an ERC20 token that supports EIP-2612 permits
    /// @param asset The address of the ERC20 token
    /// @param amount The amount of tokens to approve
    /// @param spender The address which will be approved to spend the tokens
    /// @param deadline The timestamp after which the permit is no longer valid
    /// @param v The recovery byte of the signature
    /// @param r Half of the ECDSA signature pair
    /// @param s Half of the ECDSA signature pair
    /// @param skipRevert If true, the function will not revert on failure
    function permit(
        address asset,
        uint256 amount,
        address spender,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (deadline <= block.timestamp) revert Expired();
        if (asset == address(0)) revert InvalidAsset();
        if (spender == address(0)) revert InvalidSpender();
        address owner = initiator();
        if (owner == address(0)) revert InvalidOwner();
        if (r == bytes32(0) || s == bytes32(0)) revert InvalidSignature();
        if (v != 27 && v != 28) revert InvalidSignature();
        try
            IERC20Permit(asset).permit(
                owner,
                spender,
                amount,
                deadline,
                v,
                r,
                s
            )
        {} catch (bytes memory returnData) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Calls the permit function on an ERC20 token that supports EIP-2612 permits, approving TermDiamond to spend tokens on behalf of the initiator
    /// @param asset The address of the ERC20 token
    /// @param amount The amount of tokens to approve
    /// @param owner The address which owns the tokens
    /// @param deadline The timestamp after which the permit is no longer valid
    /// @param v The recovery byte of the signature
    /// @param r Half of the ECDSA signature pair
    /// @param s Half of the ECDSA signature pair
    /// @param skipRevert If true, the function will not revert on failure
    function permitDiamond(
        address asset,
        uint256 amount,
        address owner,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (deadline <= block.timestamp) revert Expired();
        if (asset == address(0)) revert InvalidAsset();
        if (owner == address(0)) revert InvalidOwner();
        if (r == bytes32(0) || s == bytes32(0)) revert InvalidSignature();
        if (v != 27 && v != 28) revert InvalidSignature();
        try
            IERC20Permit(asset).permit(
                owner,
                address(this),
                amount,
                deadline,
                v,
                r,
                s
            )
        {} catch (bytes memory returnData) {
            if (!skipRevert) _revert(returnData);
        }
    }

    /// @notice Calls the permit function on an ERC20 token that supports EIP-2612 permits, approving a term contract to spend tokens on behalf of the owner
    /// @param asset The address of the ERC20 token
    /// @param amount The amount of tokens to approve
    /// @param owner The address which owns the tokens
    /// @param termContractAddress The address of the term contract to approve as spender
    /// @param deadline The timestamp after which the permit is no longer valid
    /// @param v The recovery byte of the signature
    /// @param r Half of the ECDSA signature pair
    /// @param s Half of the ECDSA signature pair
    /// @param skipRevert If true, the function will not revert on failure
    function permitTermContract(
        address asset,
        uint256 amount,
        address owner,
        address termContractAddress,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s,
        bool skipRevert
    ) external onlyMulticallInitiator {
        if (deadline <= block.timestamp) revert Expired();
        if (asset == address(0)) revert InvalidAsset();
        if (owner == address(0)) revert InvalidOwner();
        if (r == bytes32(0) || s == bytes32(0)) revert InvalidSignature();
        if (v != 27 && v != 28) revert InvalidSignature();
        TermStorage storage ts = LibTermStorage.termStorage();
        bool isValidTermContract;
        for (uint256 i = 0; i < ts.approvedTermControllerList.length; ++i) {
            ITermController termController = ITermController(
                ts.approvedTermControllerList[i]
            );
            if (
                termController.isTermDeployed(termContractAddress) ||
                termController.isFactoryDeployed(termContractAddress)
            ) {
                isValidTermContract = true;
                break;
            }
        }
        if (!isValidTermContract) revert InvalidSpender();
        try
            IERC20Permit(asset).permit(
                owner,
                termContractAddress,
                amount,
                deadline,
                v,
                r,
                s
            )
        {} catch (bytes memory returnData) {
            if (!skipRevert) _revert(returnData);
        }
    }
}

contracts/facets/SwapRouterFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {IPSwapAggregator, SwapData} from "@pendle/core-v2/contracts/router/swap-aggregator/IPSwapAggregator.sol";
import {IPActionMiscV3} from "@pendle/core-v2/contracts/interfaces/IPActionMiscV3.sol";
import {IPActionSwapPTV3} from "@pendle/core-v2/contracts/interfaces/IPActionSwapPTV3.sol";
import {ApproxParams, TokenInput, TokenOutput, LimitOrderData} from "@pendle/core-v2/contracts/interfaces/IPAllActionTypeV3.sol";
import {IPPrincipalToken} from "@pendle/core-v2/contracts/interfaces/IPPrincipalToken.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";
import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";

/// @author TermLabs
/// @title SwapRouterFacet
/// @notice Provides token swap functionality through Pendle protocol
/// @dev Handles swaps involving Pendle Principal Tokens (PT) and regular tokens via Pendle router and aggregator
/// @dev Supports pre-expiry and post-expiry PT operations
contract SwapRouterFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermMultiContextAuth,
    Versionable
{
    using SafeERC20 for ERC20;
    using SafeCast for uint256;

    // ========================================================================

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when both input and output tokens are Pendle Principal Tokens
    error BothTokensCannotBePendlePT();

    /// @notice Thrown when input amount doesn't match expected PT amount
    error InputAmountMismatch();

    /// @notice Thrown when Pendle router address is zero
    error InvalidPendleRouterAddress();

    /// @notice Thrown when Pendle swap aggregator address is zero
    error InvalidPendleSwapAddress();

    /// @notice Parameters for swap operations
    /// @param swapData Encoded swap parameters specific to the swap type
    /// @param isTokenInPendlePT Whether the input token is a Pendle Principal Token
    /// @param isTokenOutPendlePT Whether the output token is a Pendle Principal Token
    struct SwapRouterData {
        bytes swapData;
        bool isTokenInPendlePT;
        bool isTokenOutPendlePT;
    }

    address immutable pendleRouter;
    address immutable pendleSwap;

    /// @notice Initializes the swap router with Pendle protocol addresses
    /// @param pendleRouter_ Address of the Pendle router contract
    /// @param pendleSwap_ Address of the Pendle swap aggregator contract
    constructor(address pendleRouter_, address pendleSwap_) {
        if (pendleRouter_ == address(0)) revert InvalidPendleRouterAddress();
        if (pendleSwap_ == address(0)) revert InvalidPendleSwapAddress();
        pendleRouter = pendleRouter_;
        pendleSwap = pendleSwap_;

        previewMapping[this.swapHook.selector] = this.previewSwap.selector;
    }

    /// @notice Executes a token swap based on the provided parameters
    /// @dev Routes swaps through different Pendle functions based on token types and PT expiry status
    /// @dev Reverts if both input and output tokens are Pendle PTs
    /// @param tokenIn Address of the input token
    /// @param amountIn Amount of input tokens to swap
    /// @param usePermit2 Whether to use Permit2 for token transfer approval
    /// @param data Swap routing data containing swap parameters and token type flags
    function swap(
        address tokenIn,
        uint256 amountIn,
        bool usePermit2,
        SwapRouterData calldata data
    ) external nonReentrant {
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                amountIn.toUint160(),
                tokenIn
            );
        } else {
            ERC20(tokenIn).safeTransferFrom(
                msg.sender,
                address(this),
                amountIn
            );
        }
        _swapInternal(tokenIn, amountIn, msg.sender, data);
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Executes a token swap using the provided input parameters and additional swap data.
    /// @dev Decodes the additional calldata into SwapRouterData and calls the internal swap function.
    /// @param input Struct containing the input token address, maximum input amount, and additional calldata for the swap.
    function swapHook(
        ActionHookInput calldata input
    ) external nonReentrant onlyFlashLoanContext(input.user) {
        address tokenIn = input.inputToken;
        uint256 amountIn = input.maxInputAmount;
        SwapRouterData memory data = abi.decode(
            input.additionalCalldata,
            (SwapRouterData)
        );
        _swapInternal(tokenIn, amountIn, address(this), data);
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Previews a token swap operation without executing it
    /// @dev Returns expected input/output tokens and amounts for the swap
    /// @dev Marks the operation as non-deterministic since actual swap output depends on market conditions
    /// @dev Reverts if input and output tokens are the same
    /// @param actionHookInput The swap parameters containing input/output token addresses and amounts
    /// @return preview A PreviewAction struct containing expected input token, input amount, output token, output amount, and determinism flag
    function previewSwap(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        if (actionHookInput.inputToken == actionHookInput.outputToken) {
            revert InputOutputTokenCollision();
        }

        PreviewAction memory preview = PreviewAction({
            expectedInputToken: actionHookInput.inputToken,
            expectedInputAmount: actionHookInput.maxInputAmount,
            expectedOutputToken: actionHookInput.outputToken,
            expectedOutputAmount: actionHookInput.minOutputAmount,
            isDeterministic: false
        });
        return preview;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    function _swapInternal(
        address tokenIn,
        uint256 amountIn,
        address receiver,
        SwapRouterData memory data
    ) internal {
        if (data.isTokenInPendlePT && data.isTokenOutPendlePT) {
            revert BothTokensCannotBePendlePT();
        }
        if (data.isTokenInPendlePT) {
            ERC20(tokenIn).forceApprove(address(pendleRouter), amountIn);
            uint256 expiry = IPPrincipalToken(tokenIn).expiry();
            if (block.timestamp >= expiry) {
                (
                    ,
                    address market,
                    uint256 netPtIn,
                    uint256 netLpIn,
                    TokenOutput memory output
                ) = abi.decode(
                        data.swapData,
                        (address, address, uint256, uint256, TokenOutput)
                    );
                if (netPtIn != amountIn) revert InputAmountMismatch();
                IPActionMiscV3(pendleRouter).exitPostExpToToken(
                    receiver,
                    market,
                    netPtIn,
                    netLpIn,
                    output
                );
            } else {
                (
                    ,
                    address market,
                    uint256 exactPtIn,
                    TokenOutput memory output,
                    LimitOrderData memory limit
                ) = abi.decode(
                        data.swapData,
                        (address, address, uint256, TokenOutput, LimitOrderData)
                    );
                if (exactPtIn != amountIn) revert InputAmountMismatch();
                IPActionSwapPTV3(pendleRouter).swapExactPtForToken(
                    receiver,
                    market,
                    exactPtIn,
                    output,
                    limit
                );
            }
            ERC20(tokenIn).forceApprove(address(pendleRouter), 0);
        } else if (data.isTokenOutPendlePT) {
            ERC20(tokenIn).forceApprove(address(pendleRouter), amountIn);
            (
                ,
                address market,
                uint256 minPtOut,
                ApproxParams memory guessPtOut,
                TokenInput memory input,
                LimitOrderData memory limit
            ) = abi.decode(
                    data.swapData,
                    (
                        address,
                        address,
                        uint256,
                        ApproxParams,
                        TokenInput,
                        LimitOrderData
                    )
                );
            if (input.netTokenIn != amountIn) {
                revert InputAmountMismatch();
            }
            IPActionSwapPTV3(pendleRouter).swapExactTokenForPt(
                receiver,
                market,
                minPtOut,
                guessPtOut,
                input,
                limit
            );
            ERC20(tokenIn).forceApprove(address(pendleRouter), 0);
        } else {
            ERC20(tokenIn).safeTransfer(pendleSwap, amountIn);
            SwapData memory swapData = abi.decode(data.swapData, (SwapData));
            IPSwapAggregator(pendleSwap).swap(tokenIn, amountIn, swapData);
        }
    }
}

contracts/facets/TermControllerFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";
import {LibAccessControl} from "../libraries/LibAccessControl.sol";
import {Versionable} from "../lib/Versionable.sol";
import {IDiamondLoupe} from "./DiamondLoupeFacet.sol";

/// @author TermLabs
/// @title Term Controller Facet
/// @notice This facet manages approval and revocation of term controller contracts and fee recipients
/// @dev This facet whitelists term controller contracts and fee recipients for use in Term Repos
contract TermControllerFacet is AccessControl, Versionable {
    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    error TermControllerAlreadyApproved();
    error InvalidFacetAddress();
    error InvalidTermController();
    error FeeRecipientAlreadyApproved();
    error InvalidFeeRecipient();

    // ========================================================================
    // = Events  ==============================================================
    // ========================================================================

    event EIP712DomainSeparatorUpdated(bytes32 newDomainSeparator);

    // ========================================================================
    // = Admin Functions ======================================================
    // ========================================================================

    /// @notice Approves a new term controller contract
    /// @param termController The address of the new term controller contract
    function approveTermController(
        address termController
    ) external onlyRole(LibAccessControl.DEVOPS_ROLE) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (s.approvedTermControllers[termController]) {
            revert TermControllerAlreadyApproved();
        }
        s.approvedTermControllers[termController] = true;
        s.approvedTermControllerList.push(termController);
    }

    /// @notice Revokes an existing term controller contract
    /// @param termController The address of the term controller contract to revoke
    function revokeTermController(
        address termController
    ) external onlyRole(LibAccessControl.DEVOPS_ROLE) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (!s.approvedTermControllers[termController]) {
            revert InvalidTermController();
        }
        s.approvedTermControllers[termController] = false;
        // Remove termController from approvedTermControllerList
        uint256 length = s.approvedTermControllerList.length;
        for (uint256 i = 0; i < length; ++i) {
            if (s.approvedTermControllerList[i] == termController) {
                s.approvedTermControllerList[i] = s.approvedTermControllerList[
                    length - 1
                ];
                s.approvedTermControllerList.pop();
                break;
            }
        }
    }

    /// @notice Approves a new fee recipient
    /// @param feeRecipient The address of the fee recipient to approve
    function approveFeeRecipient(
        address feeRecipient
    ) external onlyRole(LibAccessControl.DEVOPS_ROLE) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (s.approvedFeeRecipients[feeRecipient]) {
            revert FeeRecipientAlreadyApproved();
        }
        s.approvedFeeRecipients[feeRecipient] = true;
    }

    /// @notice Revokes an existing fee recipient
    /// @param feeRecipient The address of the fee recipient to revoke
    function revokeFeeRecipient(
        address feeRecipient
    ) external onlyRole(LibAccessControl.DEVOPS_ROLE) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (!s.approvedFeeRecipients[feeRecipient]) {
            revert InvalidFeeRecipient();
        }
        s.approvedFeeRecipients[feeRecipient] = false;
    }

    ///@notice Updates the EIP-712 domain separator used for signing limit orders
    ///@param loanIntentFacetAddress The address of the TermLoanIntentFacet to read the
    function updateEIP712DomainSeparator(
        address loanIntentFacetAddress
    ) external onlyRole(LibAccessControl.ADMIN_ROLE) {
        // Verify facetAddress is a registered diamond facet via loupe
        bytes4[] memory selectors = IDiamondLoupe(address(this))
            .facetFunctionSelectors(loanIntentFacetAddress);
        if (selectors.length == 0) {
            revert InvalidFacetAddress();
        }

        // Read version directly from the facet contract (not through diamond)
        string memory ver = Versionable(loanIntentFacetAddress).version();
        TermStorage storage s = LibTermStorage.termStorage();
        uint256 chainId;
        assembly {
            chainId := chainid()
        }
        s.eip712DomainSeparator = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain("
                    "string name,"
                    "string version,"
                    "uint256 chainId,"
                    "address verifyingContract"
                    ")"
                ),
                keccak256("TermFinance"),
                keccak256(bytes(ver)),
                chainId,
                address(this)
            )
        );
        emit EIP712DomainSeparatorUpdated(s.eip712DomainSeparator);
    }
}

contracts/facets/TermLoanIntentFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermRepoCollateralManager} from "../interfaces/ITermRepoCollateralManager.sol";
import {ITermController} from "../interfaces/ITermController.sol";
import {ITermEventEmitter} from "../interfaces/ITermEventEmitter.sol";
import {ITermRepoServicer} from "../interfaces/ITermRepoServicer.sol";
import {ITermIntent} from "../interfaces/ITermIntent.sol";
import {ITermIntentEvents} from "../interfaces/ITermIntentEvents.sol";

import {ExponentialNoError} from "../lib/ExponentialNoError.sol";
import {Versionable} from "../lib/Versionable.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";
import {IDiamondLoupe} from "./DiamondLoupeFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";

/// @author TermLabs
/// @title Term Loan Intent Facet
/// @notice This facet handles settlement of limit orders for lending and borrowing
/// @dev This facet provides off-chain order settlement functionality with EIP712 signature validation and presigned order support for contract wallets
contract TermLoanIntentFacet is
    TermMultiContextAuth,
    ITermIntent,
    ReentrancyGuard,
    ExponentialNoError,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;
    using Address for address;

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    uint256 private constant YEAR_SECONDS = 360 days;
    address private constant ALLOW_ANY_ADDRESS = address(0);

    // EIP-712 TypeHashes for structs
    // keccak256("RetrieveFundsStruct(bytes4 method,address target,bytes additionalCalldata)")
    bytes32 private constant RETRIEVE_FUNDS_STRUCT_TYPEHASH =
        0x256d2844f30b75f89e6ec9418f35732e254268f054ce2b9f508642c924b76a8a;

    // The type hash for limit orders
    // keccak256("LimitLendOrder(address repoServicer,uint256 purchaseTokenAmount,uint256 offerRate,address maker,address taker,uint256 borrowFee,address feeRecipient,uint256 expiry,uint256 salt,RetrieveFundsStruct retrieveFunds)RetrieveFundsStruct(bytes4 method,address target,bytes additionalCalldata)")
    bytes32 private constant _LEND_LIMIT_ORDER_TYPEHASH =
        0x52a3e557725e0745de62ca9c2f873223f092b8f8fdb4bbf8f3120216ecedd7a9;

    // keccak256("LimitBorrowOrder(address repoServicer,uint256 purchaseTokenAmount,uint256[] collateralAmounts,uint256 offerRate,address maker,address taker,uint256 borrowFee,address feeRecipient,uint256 expiry,uint256 salt,RetrieveFundsStruct[] retrieveFundsList)RetrieveFundsStruct(bytes4 method,address target,bytes additionalCalldata)")
    bytes32 private constant _BORROW_LIMIT_ORDER_TYPEHASH =
        0xa92b0c41d8931853dfcf7e881934d0e47cebb5e838164ed0473362e6958b70a5;

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    /// @notice Initializes the TermIntent state during diamond deployment
    /// @param emitter_ The term event emitter contract
    function initializeTermIntentFacet(ITermEventEmitter emitter_) external {
        TermStorage storage s = LibTermStorage.termStorage();

        if (s.termIntentInitialized) {
            revert AlreadyInitialized();
        }

        // Initialize EIP712 domain separator with correct proxy address (diamond address)
        uint256 chainId;
        assembly {
            chainId := chainid()
        }
        s.eip712DomainSeparator = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain("
                    "string name,"
                    "string version,"
                    "uint256 chainId,"
                    "address verifyingContract"
                    ")"
                ),
                keccak256("TermFinance"),
                keccak256(bytes(version())), // use version from Versionable
                chainId,
                address(this) // diamond address
            )
        );

        if (!s.termIntentInitialized) {
            require(address(emitter_) != address(0), "InvalidEventEmitter");
            // Mark as initialized
            s.termIntentInitialized = true;

            // Set event emitter
            s.emitter = emitter_;
        }
    }

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Calculates the hash for a lend limit order
    /// @param order The lend limit order struct
    /// @return The EIP712 hash of the order
    function getLendOrderHash(
        LimitLendOrder calldata order
    ) external view returns (bytes32) {
        return _getLendOrderHash(order);
    }

    /// @notice Calculates the hash for a borrow limit order
    /// @param order The borrow limit order struct
    /// @return The EIP712 hash of the order
    function getBorrowOrderHash(
        LimitBorrowOrder calldata order
    ) external view returns (bytes32) {
        return _getBorrowOrderHash(order);
    }

    /// @notice Pre-authorizes a lend order hash for maker addresses that cannot sign EIP712 messages
    /// @param order The lend limit order to pre-sign
    function setPreSignedLendOrderHash(
        LimitLendOrder calldata order
    ) external nonReentrant {
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        _validateLendOrderParams(order);
        _validateLimitOrderNotCancelled(
            order.maker,
            servicer.purchaseToken(),
            address(servicer.termRepoToken()),
            order.salt
        );
        _validateRetrieveFunds(order.retrieveFunds);
        if (order.maker != msg.sender) {
            revert InvalidSender(order.maker, msg.sender);
        }

        bytes32 orderHash = _getLendOrderHash(order);
        TermStorage storage s = LibTermStorage.termStorage();
        if (s.preSignedLimitOrders[orderHash] != address(0)) {
            revert AlreadyPreSigned(s.preSignedLimitOrders[orderHash]);
        }
        OrderContext memory orderContext = s.limitOrderContextMapping[
            orderHash
        ];
        if (orderContext.status != ITermIntent.OrderStatus.UNFILLED) {
            revert InvalidOrderStatus();
        }

        s.preSignedLimitOrders[orderHash] = msg.sender;
        emit ITermIntentEvents.PresignedLimitOrderSet(orderHash, msg.sender);
    }

    /// @notice Pre-authorizes a borrow order hash for maker addresses that cannot sign EIP712 messages
    /// @param order The borrow limit order to pre-sign
    function setPreSignedBorrowOrderHash(
        LimitBorrowOrder calldata order
    ) external nonReentrant {
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        _validateBorrowOrderParams(order);
        _validateLimitOrderNotCancelled(
            order.maker,
            address(servicer.termRepoToken()),
            servicer.purchaseToken(),
            order.salt
        );
        for (uint8 i = 0; i < order.retrieveFundsList.length; ++i) {
            _validateRetrieveFunds(order.retrieveFundsList[i]);
        }
        if (order.maker != msg.sender) {
            revert InvalidSender(order.maker, msg.sender);
        }

        bytes32 orderHash = _getBorrowOrderHash(order);
        TermStorage storage s = LibTermStorage.termStorage();
        if (s.preSignedLimitOrders[orderHash] != address(0)) {
            revert AlreadyPreSigned(s.preSignedLimitOrders[orderHash]);
        }
        OrderContext memory orderContext = s.limitOrderContextMapping[
            orderHash
        ];
        if (orderContext.status != ITermIntent.OrderStatus.UNFILLED) {
            revert InvalidOrderStatus();
        }

        s.preSignedLimitOrders[orderHash] = msg.sender;
        emit ITermIntentEvents.PresignedLimitOrderSet(orderHash, msg.sender);
    }

    /// @notice Revokes a pre-signed order hash
    /// @param orderHash The hash of the order to revoke
    function revokePreSignedLimitOrderHash(
        bytes32 orderHash
    ) external nonReentrant {
        TermStorage storage s = LibTermStorage.termStorage();
        address maker = s.preSignedLimitOrders[orderHash];
        if (maker != msg.sender) {
            revert InvalidSender(maker, msg.sender);
        }
        delete s.preSignedLimitOrders[orderHash];
        emit ITermIntentEvents.PresignedLimitOrderRevoked(orderHash);
    }

    /// @notice Settles a lend limit order
    /// @param order The lend limit order to settle
    /// @param fillAmount The amount to fill
    /// @param collateralAmounts Array of collateral amounts
    /// @param signature The signature for the order
    /// @param usePermit2 Permit2 approvals used for token transfers
    function settleLimitLend(
        LimitLendOrder memory order,
        uint256 fillAmount,
        uint256[] memory collateralAmounts,
        Signature memory signature,
        bool usePermit2
    ) external nonReentrant {
        _settleLimitLendInternal(
            order,
            msg.sender,
            fillAmount,
            collateralAmounts,
            signature,
            false,
            usePermit2
        );
    }

    /// @notice Settles a lend limit order with specified taker (diamond multicall use only)
    /// @param order The lend limit order to settle
    /// @param taker The address acting as the taker
    /// @param fillAmount The amount to fill
    /// @param collateralAmounts Array of collateral amounts
    /// @param signature The signature for the order
    function settleLimitLend(
        LimitLendOrder memory order,
        address taker,
        uint256 fillAmount,
        uint256[] memory collateralAmounts,
        Signature memory signature
    ) external requireBatchContext(taker) nonReentrant {
        _settleLimitLendInternal(
            order,
            taker,
            fillAmount,
            collateralAmounts,
            signature,
            true,
            false
        );
    }

    /// @notice Cancels a lend limit order
    /// @param order The lend limit order to cancel
    /// @param signature The signature for the order
    function cancelLimitLend(
        LimitLendOrder calldata order,
        Signature calldata signature
    ) external nonReentrant {
        bytes32 orderHash = _getLendOrderHash(order);
        _cancelOrder(orderHash, order.maker, msg.sender, signature);
    }

    /// @notice Settles a borrow limit order
    /// @param order The borrow limit order to settle
    /// @param fillAmount The amount to fill
    /// @param signature The signature for the order
    /// @param usePermit2 Permit2 approvals used for token transfers
    function settleLimitBorrow(
        LimitBorrowOrder memory order,
        uint256 fillAmount,
        Signature memory signature,
        bool usePermit2
    ) external nonReentrant {
        _settleLimitBorrowInternal(
            order,
            msg.sender,
            fillAmount,
            signature,
            false,
            usePermit2
        );
    }

    /// @notice Settles a borrow limit order with specified taker (diamond multicall use only)
    /// @param order The borrow limit order to settle
    /// @param taker The address acting as the taker
    /// @param fillAmount The amount to fill
    /// @param signature The signature for the order
    function settleLimitBorrow(
        LimitBorrowOrder memory order,
        address taker,
        uint256 fillAmount,
        Signature memory signature
    ) external requireBatchContext(taker) nonReentrant {
        _settleLimitBorrowInternal(
            order,
            taker,
            fillAmount,
            signature,
            true,
            false
        );
    }

    /// @notice Cancels a borrow limit order
    /// @param order The borrow limit order to cancel
    /// @param signature The signature for the order
    function cancelLimitBorrow(
        LimitBorrowOrder calldata order,
        Signature calldata signature
    ) external nonReentrant {
        bytes32 orderHash = _getBorrowOrderHash(order);
        _cancelOrder(orderHash, order.maker, msg.sender, signature);
    }

    /**
     * @notice Cancels all limit orders with salt values below the specified minimum for a given token pair
     * @param makerToken The token that the maker is offering in the order
     * @param takerToken The token that the maker wants to receive in the order
     * @param minValidSalt The new minimum salt value - orders with salt below this value will be cancelled
     */
    function setLimitOrderMakerTokenPairMinSaltValue(
        address makerToken,
        address takerToken,
        uint256 minValidSalt
    ) external nonReentrant {
        TermStorage storage s = LibTermStorage.termStorage();

        if (makerToken == address(0)) {
            revert InvalidParameters("No Maker Token Set");
        }
        if (takerToken == address(0)) {
            revert InvalidParameters("No Taker Token Set");
        }
        if (makerToken == takerToken) {
            revert InvalidParameters("Maker and Taker Token Identical");
        }
        if (minValidSalt == type(uint256).max) {
            revert InvalidParameters("Invalid Min Salt");
        }

        uint256 oldMinValidSalt = s.limitOrderMakerTokenPairMinSalt[msg.sender][
            makerToken
        ][takerToken];

        if (oldMinValidSalt > minValidSalt) {
            revert InvalidMinSalt();
        }

        s.limitOrderMakerTokenPairMinSalt[msg.sender][makerToken][
            takerToken
        ] = minValidSalt;
        s.emitter.emitLimitOrderTokenPairMinSaltValue(
            msg.sender,
            makerToken,
            takerToken,
            minValidSalt
        );
    }

    /**
     * @notice Gets the current minimum salt value for limit orders for a given maker and token pair
     * @param maker The maker address to query
     * @param makerToken The token that the maker is offering in the order
     * @param takerToken The token that the maker wants to receive in the order
     * @return The current minimum salt value
     */
    function getLimitOrderMakerTokenPairMinSaltValue(
        address maker,
        IERC20 makerToken,
        IERC20 takerToken
    ) external view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        return
            s.limitOrderMakerTokenPairMinSalt[maker][address(makerToken)][
                address(takerToken)
            ];
    }

    /// @notice Returns the EIP-712 domain separator used for signing typed structured data.
    /// @return The EIP-712 domain separator as a bytes32 value.
    function DOMAIN_SEPARATOR() external view returns (bytes32) {
        TermStorage storage s = LibTermStorage.termStorage();
        return s.eip712DomainSeparator;
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    // ------------------------------------------------------------------------
    // Hash and Signature Utilities
    // ------------------------------------------------------------------------

    function _getLendOrderHash(
        LimitLendOrder memory order
    ) private view returns (bytes32) {
        return
            _getEIP712Hash(
                keccak256(
                    abi.encode(
                        _LEND_LIMIT_ORDER_TYPEHASH,
                        order.repoServicer,
                        order.purchaseTokenAmount,
                        order.offerRate,
                        order.maker,
                        order.taker,
                        order.borrowFee,
                        order.feeRecipient,
                        order.expiry,
                        order.salt,
                        _hashRetrieveFundsStruct(order.retrieveFunds)
                    )
                )
            );
    }

    function _getBorrowOrderHash(
        LimitBorrowOrder memory order
    ) private view returns (bytes32) {
        return
            _getEIP712Hash(
                keccak256(
                    abi.encode(
                        _BORROW_LIMIT_ORDER_TYPEHASH,
                        order.repoServicer,
                        order.purchaseTokenAmount,
                        keccak256(abi.encodePacked(order.collateralAmounts)),
                        order.offerRate,
                        order.maker,
                        order.taker,
                        order.borrowFee,
                        order.feeRecipient,
                        order.expiry,
                        order.salt,
                        _hashRetrieveFundsArray(order.retrieveFundsList)
                    )
                )
            );
    }

    /// @notice Hashes a single RetrieveFundsStruct per EIP-712 specification
    /// @param item The RetrieveFundsStruct to hash
    /// @return The EIP-712 hash of the struct
    function _hashRetrieveFundsStruct(
        RetrieveFundsStruct memory item
    ) private pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    RETRIEVE_FUNDS_STRUCT_TYPEHASH,
                    item.method,
                    item.target,
                    keccak256(item.additionalCalldata) // bytes are hashed per EIP-712
                )
            );
    }

    /// @notice Hashes an array of RetrieveFundsStruct per EIP-712 specification
    /// @param items The array of RetrieveFundsStruct to hash
    /// @return The EIP-712 hash of the array
    function _hashRetrieveFundsArray(
        RetrieveFundsStruct[] memory items
    ) private pure returns (bytes32) {
        bytes32[] memory hashes = new bytes32[](items.length);
        for (uint256 i = 0; i < items.length; i++) {
            hashes[i] = _hashRetrieveFundsStruct(items[i]);
        }
        return keccak256(abi.encodePacked(hashes));
    }

    function _getEIP712Hash(bytes32 structHash) private view returns (bytes32) {
        TermStorage storage s = LibTermStorage.termStorage();
        return
            keccak256(
                abi.encodePacked(hex"1901", s.eip712DomainSeparator, structHash)
            );
    }

    function _recoverEIP712Signature(
        bytes32 orderHash,
        bytes memory sigData
    ) private pure returns (address) {
        (uint8 v, bytes32 r, bytes32 s) = abi.decode(
            sigData,
            (uint8, bytes32, bytes32)
        );
        return ECDSA.recover(orderHash, v, r, s);
    }

    function _getSignerOfHash(
        bytes32 orderHash,
        Signature memory signature
    ) private view returns (address) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (signature.sigType == SignatureType.EIP712) {
            return _recoverEIP712Signature(orderHash, signature.sigData);
        } else if (signature.sigType == SignatureType.PRESIGN) {
            return s.preSignedLimitOrders[orderHash];
        } else {
            revert InvalidSignature();
        }
    }

    // ------------------------------------------------------------------------
    // Validation Functions
    // ------------------------------------------------------------------------

    function _validateLendOrderParams(
        LimitLendOrder memory order
    ) private view {
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        _validateRepoServicer(servicer);

        if (order.purchaseTokenAmount == 0) {
            revert InvalidPurchaseTokenAmount();
        }
        if (order.expiry < block.timestamp) {
            revert OrderExpired();
        }
        if (order.offerRate == 0) {
            revert InvalidOfferRate();
        }
    }

    function _validateBorrowOrderParams(
        LimitBorrowOrder memory order
    ) private view {
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        _validateRepoServicer(servicer);

        if (order.purchaseTokenAmount == 0) {
            revert InvalidPurchaseTokenAmount();
        }
        if (order.expiry < block.timestamp) {
            revert OrderExpired();
        }
        if (order.offerRate == 0) {
            revert InvalidOfferRate();
        }

        if (
            order.collateralAmounts.length !=
            servicer.termRepoCollateralManager().numOfAcceptedCollateralTokens()
        ) {
            revert InvalidCollateralAmountsInput();
        }
        if (order.retrieveFundsList.length > 0) {
            if (
                order.retrieveFundsList.length != order.collateralAmounts.length
            ) {
                revert InvalidRetrieveFundsListLength();
            }
        }
    }

    function _validateRepoServicer(ITermRepoServicer servicer) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = servicer.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(servicer)) &&
            !termController.isFactoryDeployed(address(servicer))
        ) {
            revert InvalidRepoId();
        }

        if (block.timestamp > servicer.maturityTimestamp()) {
            revert AfterMaturity();
        }
    }

    function _validateOrderSignature(
        bytes32 orderHash,
        address maker,
        Signature memory signature
    ) private view {
        address signer = _getSignerOfHash(orderHash, signature);
        if (signer != maker) {
            revert InvalidSignature();
        }
    }

    function _validateOrderStatus(
        OrderContext memory orderContext
    ) private pure {
        if (
            orderContext.status != ITermIntent.OrderStatus.UNFILLED &&
            orderContext.status != ITermIntent.OrderStatus.PARTIALLY_FILLED
        ) {
            revert InvalidOrderStatus();
        }
    }

    function _validateOrderAuthorization(
        address taker,
        address fulfiller
    ) private pure {
        if (taker != ALLOW_ANY_ADDRESS && fulfiller != taker) {
            revert InvalidTaker(taker, fulfiller);
        }
    }

    function _validateLimitOrderNotCancelled(
        address maker,
        address makerToken,
        address takerToken,
        uint256 salt
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        uint256 minSalt = s.limitOrderMakerTokenPairMinSalt[maker][makerToken][
            takerToken
        ];
        if (salt <= minSalt) {
            revert OrderCancelled();
        }
    }

    function _validateRetrieveFunds(
        RetrieveFundsStruct memory retrieveFunds
    ) private view returns (bool) {
        if (retrieveFunds.method != bytes4(0)) {
            address facetAddress = IDiamondLoupe(address(this)).facetAddress(
                retrieveFunds.method
            );

            // Confirm that method belongs to specified facet
            if (facetAddress == address(0)) {
                revert InvalidRetrieveFundsFunction();
            }
            return true;
        }
        return false;
    }

    // ------------------------------------------------------------------------
    // Calculation and Utility Functions
    // ------------------------------------------------------------------------

    function _validateFillAmount(
        uint256 fillAmount,
        uint256 totalAmount,
        uint256 filledAmount
    ) private pure returns (uint256) {
        uint256 maxFill = totalAmount - filledAmount;
        if (maxFill < fillAmount) {
            revert InsufficientRemainingCapacity(maxFill);
        }
        return fillAmount;
    }

    function _generateRetrieveFundsCalldata(
        RetrieveFundsStruct memory retrieveFunds,
        uint256 amountToRetrieve,
        address token,
        address user
    ) private returns (bytes memory) {
        address facetAddress = IDiamondLoupe(address(this)).facetAddress(
            retrieveFunds.method
        );
        bytes4 sig = bytes4(
            keccak256(
                "generateCalldata(bytes4,address,address,address,uint256,bool,bytes)"
            )
        );

        bytes memory encodeCalldataInput = abi.encodeWithSelector(
            sig,
            retrieveFunds.method,
            retrieveFunds.target,
            token,
            user,
            amountToRetrieve,
            false,
            retrieveFunds.additionalCalldata
        );
        bytes memory returnData = Address.functionCall(
            facetAddress,
            encodeCalldataInput
        );
        return abi.decode(returnData, (bytes));
    }

    // ------------------------------------------------------------------------
    // Order Management
    // ------------------------------------------------------------------------

    function _updateOrderStatus(
        uint256 maxFill,
        uint256 fillAmount,
        bytes32 orderHash,
        OrderContext memory orderContext
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        if (fillAmount == maxFill) {
            orderContext.status = ITermIntent.OrderStatus.FILLED;
        } else {
            orderContext.status = ITermIntent.OrderStatus.PARTIALLY_FILLED;
        }

        orderContext.filledAmount += fillAmount.toUint128();
        s.limitOrderContextMapping[orderHash] = orderContext;
    }

    function _cancelOrder(
        bytes32 orderHash,
        address maker,
        address caller,
        Signature memory signature
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.limitOrderContextMapping[
            orderHash
        ];

        if (
            orderContext.status == ITermIntent.OrderStatus.FILLED ||
            orderContext.status == ITermIntent.OrderStatus.CANCELLED
        ) {
            revert InvalidOrderStatus();
        }

        address signer = _getSignerOfHash(orderHash, signature);
        if (signer != maker) {
            revert InvalidSignature();
        }

        if (maker != caller) {
            revert InvalidSender(maker, caller);
        }

        s.limitOrderContextMapping[orderHash].status = ITermIntent
            .OrderStatus
            .CANCELLED;
        s.emitter.emitIntentCancelled(orderHash);
    }

    // ------------------------------------------------------------------------
    // Settlement Processing
    // ------------------------------------------------------------------------

    /// @notice Internal function for settling lend orders
    function _settleLimitLendInternal(
        LimitLendOrder memory order,
        address borrower,
        uint256 fillAmount,
        uint256[] memory collateralAmounts,
        Signature memory signature,
        bool isRoutedCollateral,
        bool usePermit2
    ) private {
        ITermRepoServicer repoServicer = ITermRepoServicer(order.repoServicer);

        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }

        if (order.maker == borrower) {
            revert MakerCannotBeTaker();
        }

        if (
            collateralAmounts.length !=
            repoServicer
                .termRepoCollateralManager()
                .numOfAcceptedCollateralTokens()
        ) {
            revert InvalidCollateralAmountsInput();
        }

        _validateLendOrderParams(order);

        bytes32 orderHash = _getLendOrderHash(order);
        _validateOrderSignature(orderHash, order.maker, signature);

        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.limitOrderContextMapping[
            orderHash
        ];
        _validateOrderStatus(orderContext);

        _validateLimitOrderNotCancelled(
            order.maker,
            repoServicer.purchaseToken(),
            address(repoServicer.termRepoToken()),
            order.salt
        );
        _validateOrderAuthorization(order.taker, borrower);
        bool retrieveFundsRequested = _validateRetrieveFunds(
            order.retrieveFunds
        );
        if (!s.approvedFeeRecipients[order.feeRecipient]) {
            revert InvalidFeeRecipient();
        }

        // Fill amount cached after validation to prevent stack overflow
        uint256 validatedFillAmount = _validateFillAmount(
            fillAmount,
            order.purchaseTokenAmount,
            orderContext.filledAmount
        );

        _updateOrderStatus(
            order.purchaseTokenAmount - orderContext.filledAmount,
            validatedFillAmount,
            orderHash,
            orderContext
        );

        ITermRepoCollateralManager collateralManager = repoServicer
            .termRepoCollateralManager();
        address termRepoLocker = address(repoServicer.termRepoLocker());
        uint8 i;

        // Diamond needs to approve TermRepoLocker when collateral is routed through it
        if (usePermit2 || isRoutedCollateral) {
            for (i = 0; i < collateralAmounts.length; ++i) {
                if (collateralAmounts[i] != 0) {
                    IERC20(collateralManager.collateralTokens(i)).forceApprove(
                        termRepoLocker,
                        collateralAmounts[i]
                    );
                }
            }
        }

        _settleLendOrder(
            orderHash,
            order,
            borrower,
            validatedFillAmount,
            isRoutedCollateral,
            retrieveFundsRequested,
            collateralAmounts,
            usePermit2
        );

        // Diamond needs to revoke approval to TermRepoLocker when collateral is routed through it after minting
        if (usePermit2 || isRoutedCollateral) {
            for (i = 0; i < collateralAmounts.length; ++i) {
                if (collateralAmounts[i] != 0) {
                    IERC20(collateralManager.collateralTokens(i)).forceApprove(
                        termRepoLocker,
                        0
                    );
                }
            }
        }
    }

    /// @notice Internal function for settling borrow orders
    function _settleLimitBorrowInternal(
        LimitBorrowOrder memory order,
        address lender,
        uint256 fillAmount,
        Signature memory signature,
        bool isRoutedPurchaseToken,
        bool usePermit2
    ) private {
        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }

        if (order.maker == lender) {
            revert MakerCannotBeTaker();
        }

        _validateBorrowOrderParams(order);

        bytes32 orderHash = _getBorrowOrderHash(order);
        _validateOrderSignature(orderHash, order.maker, signature);

        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.limitOrderContextMapping[
            orderHash
        ];
        _validateOrderStatus(orderContext);

        ITermRepoServicer repoServicer = ITermRepoServicer(order.repoServicer);

        _validateLimitOrderNotCancelled(
            order.maker,
            address(repoServicer.termRepoToken()),
            repoServicer.purchaseToken(),
            order.salt
        );
        _validateOrderAuthorization(order.taker, lender);

        bool retrieveFundsRequested;
        uint8 i;
        for (i = 0; i < order.retrieveFundsList.length; ++i) {
            if (_validateRetrieveFunds(order.retrieveFundsList[i])) {
                retrieveFundsRequested = true;
            }
        }
        if (!s.approvedFeeRecipients[order.feeRecipient]) {
            revert InvalidFeeRecipient();
        }

        // Fill amount cached after validation to prevent stack overflow
        uint256 validatedFillAmount = _validateFillAmount(
            fillAmount,
            order.purchaseTokenAmount,
            orderContext.filledAmount
        );

        _updateOrderStatus(
            order.purchaseTokenAmount - orderContext.filledAmount,
            validatedFillAmount,
            orderHash,
            orderContext
        );

        ITermRepoCollateralManager collateralManager = repoServicer
            .termRepoCollateralManager();
        address termRepoLocker = address(repoServicer.termRepoLocker());
        for (i = 0; i < order.collateralAmounts.length; ++i) {
            if (order.collateralAmounts[i] != 0) {
                IERC20(collateralManager.collateralTokens(i)).forceApprove(
                    termRepoLocker,
                    order.collateralAmounts[i]
                );
            }
        }

        _settleBorrowOrder(
            orderHash,
            order,
            lender,
            validatedFillAmount,
            isRoutedPurchaseToken,
            retrieveFundsRequested,
            usePermit2
        );

        for (i = 0; i < order.collateralAmounts.length; ++i) {
            if (order.collateralAmounts[i] != 0) {
                IERC20(collateralManager.collateralTokens(i)).forceApprove(
                    termRepoLocker,
                    0
                );
            }
        }
    }

    function _settleLendOrder(
        bytes32 orderHash,
        LimitLendOrder memory order,
        address borrower,
        uint256 fillAmount,
        bool isRoutedCollateral,
        bool retrieveFundsRequested,
        uint256[] memory collateralAmounts,
        bool usePermit2
    ) private {
        bool isRoutedPurchaseToken = retrieveFundsRequested;
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);

        if (retrieveFundsRequested) {
            // generate retrieveFundsCalldata
            bytes memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
                order.retrieveFunds,
                fillAmount,
                servicer.purchaseToken(),
                order.maker
            );

            // Set settlement context before executing retrieveFunds
            TermStorage storage ts = LibTermStorage.termStorage();
            ts.activeSettlementMaker = order.maker;

            uint256 purchaseTokenBalanceBeforeRetrieveFunds = IERC20(
                servicer.purchaseToken()
            ).balanceOf(address(this));

            // execute retrieveFundsCalldata
            Address.functionCall(address(this), retrieveFundsCalldata);

            uint256 purchaseTokenBalanceAfterRetrieveFunds = IERC20(
                servicer.purchaseToken()
            ).balanceOf(address(this));
            if (
                purchaseTokenBalanceAfterRetrieveFunds <
                purchaseTokenBalanceBeforeRetrieveFunds + fillAmount
            ) {
                revert InsufficientFundsRetrieved();
            }

            // Clear settlement context after execution
            ts.activeSettlementMaker = address(0);
        }

        if (!isRoutedCollateral && usePermit2) {
            ITermRepoCollateralManager collateralManager = servicer
                .termRepoCollateralManager();
            for (uint8 i = 0; i < collateralAmounts.length; ++i) {
                if (collateralAmounts[i] != 0) {
                    Permit2Lib.PERMIT2.transferFrom(
                        borrower,
                        address(this),
                        collateralAmounts[i].toUint160(),
                        collateralManager.collateralTokens(i)
                    );
                }
            }
            isRoutedCollateral = true;
        }

        uint256 termRepoTokenFillAmount = servicer.mintOpenExposureFromIntent(
            borrower, // borrower
            order.maker, // lender
            fillAmount,
            collateralAmounts,
            order.offerRate,
            isRoutedCollateral
        );

        uint256 proratedFee = _settlePurchaseTokensAndFees(
            servicer,
            borrower, // borrower
            order.maker, // lender
            fillAmount,
            order.borrowFee,
            order.feeRecipient,
            isRoutedPurchaseToken,
            false // NOTE: usePermit2 only applies to taker (borrower not lender here)
        );

        _emitLendIntentFilled(
            orderHash,
            servicer,
            order.maker,
            borrower,
            order.offerRate,
            fillAmount,
            termRepoTokenFillAmount,
            proratedFee,
            order.feeRecipient,
            order.purchaseTokenAmount,
            order.expiry,
            order.salt
        );
    }

    function _settleBorrowOrder(
        bytes32 orderHash,
        LimitBorrowOrder memory order,
        address lender,
        uint256 fillAmount,
        bool isRoutedPurchaseToken,
        bool retrieveFundsRequested,
        bool usePermit2
    ) private {
        bool isRoutedCollateral = retrieveFundsRequested;
        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);

        uint256[] memory collateralAmounts = new uint256[](
            order.collateralAmounts.length
        );
        address collateralToken;

        for (uint8 i = 0; i < collateralAmounts.length; ++i) {
            collateralAmounts[i] =
                (order.collateralAmounts[i] * fillAmount) /
                order.purchaseTokenAmount;

            if (!retrieveFundsRequested) {
                continue;
            }
            if (order.retrieveFundsList[i].method != bytes4(0)) {
                collateralToken = servicer
                    .termRepoCollateralManager()
                    .collateralTokens(i);
                // generate retrieveFundsCalldata
                bytes
                    memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
                        order.retrieveFundsList[i],
                        collateralAmounts[i],
                        collateralToken,
                        order.maker
                    );

                // Set settlement context before executing retrieveFunds
                TermStorage storage ts = LibTermStorage.termStorage();
                ts.activeSettlementMaker = order.maker;

                uint256 tokenBalanceBeforeRetrieveFunds = IERC20(
                    collateralToken
                ).balanceOf(address(this));

                // execute retrieveFundsCalldata
                Address.functionCall(address(this), retrieveFundsCalldata);

                uint256 tokenBalanceAfterRetrieveFunds = IERC20(collateralToken)
                    .balanceOf(address(this));

                if (
                    tokenBalanceAfterRetrieveFunds <
                    tokenBalanceBeforeRetrieveFunds + collateralAmounts[i]
                ) {
                    revert InsufficientFundsRetrieved();
                }

                // Clear settlement context after execution
                ts.activeSettlementMaker = address(0);
            } else {
                // retrieve naked collateral into diamond for router settlement
                IERC20(servicer.termRepoCollateralManager().collateralTokens(i))
                    .safeTransferFrom(
                        order.maker,
                        address(this),
                        collateralAmounts[i]
                    );
            }
        }

        uint256 termRepoTokenFillAmount = servicer.mintOpenExposureFromIntent(
            order.maker, // borrower
            lender, // lender
            fillAmount,
            collateralAmounts,
            order.offerRate,
            isRoutedCollateral
        );

        uint256 proratedFee = _settlePurchaseTokensAndFees(
            servicer,
            order.maker, // borrower
            lender, // lender
            fillAmount,
            order.borrowFee,
            order.feeRecipient,
            isRoutedPurchaseToken,
            usePermit2
        );

        _emitBorrowIntentFilled(
            orderHash,
            servicer,
            order.maker,
            lender,
            order.offerRate,
            termRepoTokenFillAmount,
            fillAmount,
            proratedFee,
            order.feeRecipient,
            order.purchaseTokenAmount,
            order.expiry,
            order.salt
        );
    }

    // ------------------------------------------------------------------------
    // Token and Fee Handling
    // ------------------------------------------------------------------------

    function _settlePurchaseTokensAndFees(
        ITermRepoServicer servicer,
        address borrower,
        address lender,
        uint256 fillAmount,
        uint256 borrowFee,
        address feeRecipient,
        bool isRoutedPurchaseToken,
        bool useTransfer2
    ) private returns (uint256) {
        uint256 proratedFee = mul_ScalarTruncate(
            mul_(
                Exp({mantissa: borrowFee}),
                div_(
                    Exp({
                        mantissa: (servicer.redemptionTimestamp() -
                            block.timestamp)
                    }),
                    Exp({mantissa: YEAR_SECONDS})
                )
            ),
            fillAmount
        );

        address purchaseToken = servicer.purchaseToken();

        _executeTokenTransfer(
            purchaseToken,
            isRoutedPurchaseToken,
            lender,
            borrower,
            feeRecipient,
            fillAmount,
            proratedFee,
            useTransfer2
        );

        return proratedFee;
    }

    function _executeTokenTransfer(
        address token,
        bool isRouted,
        address from,
        address to,
        address feeRecipient,
        uint256 amount,
        uint256 fee,
        bool useTransfer2
    ) private {
        if (isRouted) {
            IERC20(token).safeTransfer(to, amount - fee);
            if (fee > 0) {
                IERC20(token).safeTransfer(feeRecipient, fee);
            }
        } else {
            if (useTransfer2) {
                Permit2Lib.PERMIT2.transferFrom(
                    from,
                    to,
                    (amount - fee).toUint160(),
                    token
                );
                if (fee > 0) {
                    Permit2Lib.PERMIT2.transferFrom(
                        from,
                        feeRecipient,
                        fee.toUint160(),
                        token
                    );
                }
            } else {
                IERC20(token).safeTransferFrom(from, to, amount - fee);
                if (fee > 0) {
                    IERC20(token).safeTransferFrom(from, feeRecipient, fee);
                }
            }
        }
    }

    // ------------------------------------------------------------------------
    // Event Emission
    // ------------------------------------------------------------------------

    function _emitLendIntentFilled(
        bytes32 orderHash,
        ITermRepoServicer servicer,
        address maker,
        address taker,
        uint256 offerRate,
        uint256 fillAmount,
        uint256 termRepoTokenFillAmount,
        uint256 proratedBorrowFee,
        address feeRecipient,
        uint256 originalOrderAmount,
        uint256 expiry,
        uint256 salt
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        address purchaseToken = servicer.purchaseToken();
        s.emitter.emitIntentFilled(
            orderHash,
            servicer.termRepoId(),
            purchaseToken,
            maker,
            taker,
            purchaseToken,
            address(servicer.termRepoToken()),
            offerRate,
            fillAmount,
            termRepoTokenFillAmount,
            proratedBorrowFee,
            feeRecipient,
            originalOrderAmount,
            expiry,
            salt
        );
    }

    function _emitBorrowIntentFilled(
        bytes32 orderHash,
        ITermRepoServicer servicer,
        address maker,
        address taker,
        uint256 offerRate,
        uint256 termRepoTokenFillAmount,
        uint256 fillAmount,
        uint256 proratedBorrowFee,
        address feeRecipient,
        uint256 originalOrderAmount,
        uint256 expiry,
        uint256 salt
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        address purchaseToken = servicer.purchaseToken();
        s.emitter.emitIntentFilled(
            orderHash,
            servicer.termRepoId(),
            purchaseToken,
            maker,
            taker,
            address(servicer.termRepoToken()),
            purchaseToken,
            offerRate,
            termRepoTokenFillAmount,
            fillAmount,
            proratedBorrowFee,
            feeRecipient,
            originalOrderAmount,
            expiry,
            salt
        );
    }
}

contracts/facets/TermLoanIntentHookFacet.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermRepoCollateralManager} from "../interfaces/ITermRepoCollateralManager.sol";
import {ITermController} from "../interfaces/ITermController.sol";
import {ITermRepoServicer} from "../interfaces/ITermRepoServicer.sol";
import {ITermIntent} from "../interfaces/ITermIntent.sol";

import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {ExponentialNoError} from "../lib/ExponentialNoError.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";
import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";
import {TermLoanIntentFacet} from "./TermLoanIntentFacet.sol";

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

/// @author TermLabs
/// @title TermLoanIntentHookFacet
/// @notice Diamond facet that exposes loan intent settlement as flash loan hook actions
/// @dev Wraps TermLoanIntentFacet settlement functions for use within flash loan callback contexts.
///      Each hook action is gated by `onlyFlashLoanContext` and delegates to the corresponding
///      TermLoanIntentFacet function via a self-call through the diamond proxy.
contract TermLoanIntentHookFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermMultiContextAuth,
    ITermIntent,
    ExponentialNoError,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    error BorrowFeeTooHigh();
    error EmptyOrderBatch();
    error InconsistentRepoServicer();
    error BatchOrderInsufficientRemainingCapacity(
        uint256 orderIndex,
        uint256 maxFill
    );
    error InvalidCollateralToken();
    error OrderBatchLengthMismatch();

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    constructor() {
        // Register preview function selectors for flash loan hook workflows
        previewMapping[this.settleLimitLendHook.selector] = this
            .previewSettleLimitLend
            .selector;
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Settles a lend limit order as a flash loan hook action
    /// @dev Computes the fill amount from the taker's desired borrow amount (adjusting for borrow fees),
    ///      settles the lend order internally, then pulls purchase tokens from the taker via Permit2 or safeTransferFrom.
    /// @dev WARNING: This function has a side-effect of minting term repo tokens to `input.user` via the
    ///      internal call to `settleLimitLend`. Callers must account for the fact that the taker (input.user)
    ///      will hold newly minted term repo tokens representing their lending position after this call.
    /// @param input The flash loan hook input containing the user, borrow amount, and encoded order data
    ///        (a list of orders, signatures, and fill amounts; all orders must use the same termRepoServicer)
    function settleLimitLendHook(
        ActionHookInput calldata input
    ) external onlyFlashLoanContext(input.user) {
        address taker = input.user;
        address collateralToken = input.inputToken;

        (
            bool usePermit2,
            LimitLendOrder[] memory orders,
            Signature[] memory signatures,
            uint256[] memory fillAmounts
        ) = abi.decode(
                input.additionalCalldata,
                (bool, LimitLendOrder[], Signature[], uint256[])
            );
        uint256 len = orders.length;
        if (len == 0) revert EmptyOrderBatch();
        if (len != signatures.length || len != fillAmounts.length)
            revert OrderBatchLengthMismatch();
        ITermRepoServicer termRepoServicer = ITermRepoServicer(
            orders[0].repoServicer
        );
        _validateRepoServicer(termRepoServicer);

        TermStorage storage ts = LibTermStorage.termStorage();

        address purchaseToken = termRepoServicer.purchaseToken();

        uint256 redemptionTimestamp = termRepoServicer.redemptionTimestamp();

        uint256 totalFillAmount;
        uint256 totalBorrowAmount;
        uint256 maxFill;

        for (uint256 i = 0; i < len; ++i) {
            if (orders[i].repoServicer != address(termRepoServicer)) {
                revert InconsistentRepoServicer();
            }

            if (fillAmounts[i] == 0) {
                revert InvalidFillAmount();
            }

            maxFill = _calculateLimitLendFillAmount(orders[i]);
            if (maxFill < fillAmounts[i]) {
                revert BatchOrderInsufficientRemainingCapacity(i, maxFill);
            }
            totalFillAmount += fillAmounts[i];

            totalBorrowAmount += _calculateBorrowAmountFromFillAmount(
                fillAmounts[i],
                orders[i].borrowFee,
                redemptionTimestamp
            );
        }

        uint256 allocatedCollateral;
        for (uint256 i = 0; i < len; ++i) {
            uint256 collateralAmount;

            if (i == len - 1) {
                collateralAmount = input.maxInputAmount - allocatedCollateral;
            } else {
                collateralAmount =
                    (input.maxInputAmount * fillAmounts[i]) /
                    totalFillAmount;
                allocatedCollateral += collateralAmount;
            }

            uint256[] memory collateralAmounts = _buildCollateralAmountsArray(
                address(termRepoServicer),
                collateralToken,
                collateralAmount
            );

            ts.activeAtomicTxSettlementTaker = taker;

            TermLoanIntentFacet(address(this)).settleLimitLend(
                orders[i],
                taker,
                fillAmounts[i],
                collateralAmounts,
                signatures[i]
            );
            ts.activeAtomicTxSettlementTaker = address(0);
        }

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                taker,
                address(this),
                totalBorrowAmount.toUint160(),
                purchaseToken
            );
        } else {
            IERC20(purchaseToken).safeTransferFrom(
                taker,
                address(this),
                totalBorrowAmount
            );
        }
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /// @notice Previews the expected token inputs and outputs for a lend limit order settlement via flash loan hook
    /// @param actionHookInput The flash loan hook input containing the encoded lend order and signature
    /// @return A PreviewAction struct with the expected collateral input and purchase token output
    function previewSettleLimitLend(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        (, LimitLendOrder[] memory orders, , ) = abi.decode(
            actionHookInput.additionalCalldata,
            (bool, LimitLendOrder[], Signature[], uint256[])
        );

        if (orders.length == 0) {
            revert EmptyOrderBatch();
        }

        address termRepoServicer = orders[0].repoServicer;

        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        address purchaseToken = _termRepoServicer.purchaseToken();

        _validateCollateralToken(_termRepoServicer, actionHookInput.inputToken);
        address collateralToken = actionHookInput.inputToken;

        if (purchaseToken == collateralToken) {
            revert InputOutputTokenCollision();
        }

        return
            PreviewAction({
                expectedInputToken: collateralToken,
                expectedInputAmount: actionHookInput.maxInputAmount,
                expectedOutputToken: purchaseToken,
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    function _validateRepoServicer(ITermRepoServicer servicer) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = servicer.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(servicer)) &&
            !termController.isFactoryDeployed(address(servicer))
        ) {
            revert InvalidRepoId();
        }

        if (block.timestamp > servicer.maturityTimestamp()) {
            revert AfterMaturity();
        }
    }

    function _validateCollateralToken(
        ITermRepoServicer repoServicer,
        address collateralToken
    ) private view {
        if (
            repoServicer
                .termRepoCollateralManager()
                .maintenanceCollateralRatios(collateralToken) == 0
        ) {
            revert InvalidCollateralToken();
        }
    }

    function _buildCollateralAmountsArray(
        address servicer,
        address collateralToken,
        uint256 collateralAmount
    ) internal view returns (uint256[] memory) {
        ITermRepoServicer termRepoServicer = ITermRepoServicer(servicer);
        ITermRepoCollateralManager collateralManager = termRepoServicer
            .termRepoCollateralManager();
        uint256 numCollateralTokens = collateralManager
            .numOfAcceptedCollateralTokens();
        uint256[] memory collateralAmounts = new uint256[](numCollateralTokens);

        bool collateralSupported;
        for (uint256 i = 0; i < numCollateralTokens; i++) {
            if (collateralManager.collateralTokens(i) == collateralToken) {
                collateralAmounts[i] = collateralAmount;
                collateralSupported = true;
                break;
            }
        }

        if (!collateralSupported) {
            revert InvalidCollateralToken();
        }

        return collateralAmounts;
    }

    function _calculateBorrowAmountFromFillAmount(
        uint256 fillAmount,
        uint256 borrowFee,
        uint256 redemptionTimestamp
    ) internal view returns (uint256) {
        if (borrowFee == 0) {
            return fillAmount;
        } else {
            Exp memory feeFactor = mul_(
                Exp({mantissa: borrowFee}),
                div_(
                    Exp({mantissa: redemptionTimestamp - block.timestamp}),
                    Exp({mantissa: 360 days})
                )
            );

            if (feeFactor.mantissa >= expScale) {
                revert BorrowFeeTooHigh();
            }

            // Use the same mul_ScalarTruncate path as
            // TermLoanIntentFacet._settlePurchaseTokensAndFees so that the
            // preview borrowAmount exactly equals fillAmount - proratedFee.
            uint256 proratedFee = mul_ScalarTruncate(feeFactor, fillAmount);

            return fillAmount - proratedFee;
        }
    }

    /// @notice Calculates the actual fill amount for a limit lend order, capped by remaining unfilled capacity
    /// @param order The limit lend order to fill against
    /// @return The actual fill amount (min of requested and remaining capacity)
    /// @custom:reverts NothingToFill if the computed fill amount is zero
    function _calculateLimitLendFillAmount(
        ITermIntent.LimitLendOrder memory order
    ) internal view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        bytes32 orderHash = TermLoanIntentFacet(address(this)).getLendOrderHash(
            order
        );
        ITermIntent.OrderContext memory orderContext = s
            .limitOrderContextMapping[orderHash];
        uint256 maxFill = order.purchaseTokenAmount - orderContext.filledAmount;
        return maxFill;
    }
}

contracts/facets/TermRepoTokenIntentFace.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermController} from "../interfaces/ITermController.sol";
import {ITermRepoServicer} from "../interfaces/ITermRepoServicer.sol";
import {ITermIntent} from "../interfaces/ITermIntent.sol";
import {ITermIntentEvents} from "../interfaces/ITermIntentEvents.sol";

import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {ExponentialNoError} from "../lib/ExponentialNoError.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";
import {TermRepoToken} from "../TermRepoToken.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";
import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";
import {IDiamondLoupe} from "./DiamondLoupeFacet.sol";

/// @author TermLabs
/// @title Term Repo Token Swap Intent Facet
/// @notice This facet handles settlement of repo token swap orders between purchase tokens and repo tokens
/// @dev This facet provides functionality for swapping repo tokens with discount rate calculations, fee handling, and pre-signed order support
contract TermRepoTokenIntentFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermMultiContextAuth,
    ITermIntent,
    ExponentialNoError,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;
    using Address for address;

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    uint256 private constant YEAR_SECONDS = 360 days;
    address private constant ALLOW_ANY_ADDRESS = address(0);

    // EIP-712 TypeHashes for structs
    // keccak256("RetrieveFundsStruct(bytes4 method,address target,bytes additionalCalldata)")
    bytes32 private constant RETRIEVE_FUNDS_STRUCT_TYPEHASH =
        0x256d2844f30b75f89e6ec9418f35732e254268f054ce2b9f508642c924b76a8a;

    // keccak256("RepoTokenSwapOrder(address repoToken,bool makerAssetIsPurchaseToken,uint256 purchaseTokenAmount,uint256 discountRate,address maker,address taker,uint256 makerFee,uint256 takerFee,address feeRecipient,uint256 expiry,uint256 salt,RetrieveFundsStruct retrieveFunds)RetrieveFundsStruct(bytes4 method,address target,bytes additionalCalldata)")
    bytes32 private constant _SWAP_ORDER_TYPEHASH =
        0xcd57a296f280259286f502de3a6bab28e6b10627b6c0a7ab90bc3c6f6b8af807;

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    constructor() {
        // Register preview function selectors for flash loan hook workflows
        previewMapping[this.swapRepoTokenHook.selector] = this
            .previewSwapRepoToken
            .selector;
    }

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Calculates the hash for a swap order
    /// @param order The swap order struct
    /// @return The EIP712 hash of the order
    function getSwapOrderHash(
        RepoTokenSwapOrder calldata order
    ) external view returns (bytes32) {
        return _getSwapOrderHash(order);
    }

    /// @notice Pre-authorizes a swap order hash for maker addresses that cannot sign EIP712 messages
    /// @param order The swap order to pre-sign
    function setPreSignedSwapHash(
        RepoTokenSwapOrder calldata order
    ) external nonReentrant {
        TermRepoToken repoToken = TermRepoToken(order.repoToken);
        (, address purchaseToken, , ) = repoToken.config();
        TermStorage storage s = LibTermStorage.termStorage();

        _validateSwapOrderParams(order);
        if (order.makerAssetIsPurchaseToken) {
            _validateSwapOrderNotCancelled(
                order.maker,
                purchaseToken,
                order.repoToken,
                order.salt
            );
        } else {
            _validateSwapOrderNotCancelled(
                order.maker,
                order.repoToken,
                purchaseToken,
                order.salt
            );
        }
        _validateRetrieveFunds(order.retrieveFunds);
        if (!s.approvedFeeRecipients[order.feeRecipient]) {
            revert InvalidFeeRecipient();
        }

        if (order.maker != msg.sender) {
            revert InvalidSender(order.maker, msg.sender);
        }

        bytes32 orderHash = _getSwapOrderHash(order);
        if (s.preSignedSwapOrders[orderHash] != address(0)) {
            revert AlreadyPreSigned(s.preSignedSwapOrders[orderHash]);
        }
        OrderContext memory orderContext = s.swapOrderContextMapping[orderHash];
        if (orderContext.status != ITermIntent.OrderStatus.UNFILLED) {
            revert InvalidOrderStatus();
        }

        s.preSignedSwapOrders[orderHash] = msg.sender;
        emit ITermIntentEvents.PresignedSwapOrderSet(orderHash, msg.sender);
    }

    /// @notice Revokes a pre-signed order hash
    /// @param orderHash The hash of the order to revoke
    function revokePreSignedSwapOrderHash(
        bytes32 orderHash
    ) external nonReentrant {
        TermStorage storage s = LibTermStorage.termStorage();
        address maker = s.preSignedSwapOrders[orderHash];
        if (maker != msg.sender) {
            revert InvalidSender(maker, msg.sender);
        }
        delete s.preSignedSwapOrders[orderHash];
        emit ITermIntentEvents.PresignedSwapOrderRevoked(orderHash);
    }

    /// @notice Swaps repo tokens
    /// @param order The repo token swap order
    /// @param fillAmount The amount to fill
    /// @param signature The signature for the order
    /// @param usePermit2 Permit2 approvals used for token transfers
    function swapRepoToken(
        RepoTokenSwapOrder memory order,
        uint256 fillAmount,
        Signature memory signature,
        bool usePermit2
    ) external nonReentrant {
        _swapRepoTokenInternal(
            order,
            msg.sender,
            fillAmount,
            signature,
            false,
            usePermit2
        );
    }

    /// @notice Swaps repo tokens with specified taker (diamond multicall use only)
    /// @param order The repo token swap order
    /// @param taker The address acting as the taker
    /// @param fillAmount The amount to fill
    /// @param signature The signature for the order
    function swapRepoToken(
        RepoTokenSwapOrder memory order,
        address taker,
        uint256 fillAmount,
        Signature memory signature
    ) external requireBatchContext(taker) nonReentrant {
        _swapRepoTokenInternal(
            order,
            taker,
            fillAmount,
            signature,
            true,
            false
        );
    }

    /// @notice Cancels a repo token swap order
    /// @param order The repo token swap order to cancel
    /// @param signature The signature for the order
    function cancelRepoTokenSwap(
        RepoTokenSwapOrder calldata order,
        Signature calldata signature
    ) external nonReentrant {
        bytes32 orderHash = _getSwapOrderHash(order);
        _cancelOrder(orderHash, order.maker, msg.sender, signature);
    }

    /**
     * @notice Cancels all swap orders with salt values below the specified minimum for a given token pair
     * @param makerToken The token that the maker is offering in the order
     * @param takerToken The token that the maker wants to receive in the order
     * @param minValidSalt The new minimum salt value - orders with salt below this value will be cancelled
     */
    function setSwapOrderMakerTokenPairMinSaltValue(
        address makerToken,
        address takerToken,
        uint256 minValidSalt
    ) external nonReentrant {
        TermStorage storage s = LibTermStorage.termStorage();

        if (makerToken == address(0)) {
            revert InvalidParameters("No Maker Token Set");
        }
        if (takerToken == address(0)) {
            revert InvalidParameters("No Taker Token Set");
        }
        if (makerToken == takerToken) {
            revert InvalidParameters("Maker and Taker Token Identical");
        }
        if (minValidSalt == type(uint256).max) {
            revert InvalidParameters("Invalid Min Salt");
        }

        uint256 oldMinValidSalt = s.swapOrderMakerTokenPairMinSalt[msg.sender][
            makerToken
        ][takerToken];

        if (oldMinValidSalt > minValidSalt) {
            revert InvalidMinSalt();
        }

        s.swapOrderMakerTokenPairMinSalt[msg.sender][makerToken][
            takerToken
        ] = minValidSalt;
        s.emitter.emitSwapOrderTokenPairMinSaltValue(
            msg.sender,
            makerToken,
            takerToken,
            minValidSalt
        );
    }

    /**
     * @notice Gets the current minimum salt value for swap orders for a given maker and token pair
     * @param maker The maker address to query
     * @param makerToken The token that the maker is offering in the order
     * @param takerToken The token that the maker wants to receive in the order
     * @return The current minimum salt value
     */
    function getSwapOrderMakerTokenPairMinSaltValue(
        address maker,
        IERC20 makerToken,
        IERC20 takerToken
    ) external view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        return
            s.swapOrderMakerTokenPairMinSalt[maker][address(makerToken)][
                address(takerToken)
            ];
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /**
     * @notice Executes a repo token swap as a flash loan hook action
     * @dev Decodes a RepoTokenSwapOrder and Signature from the hook input's additionalCalldata,
     *      calculates the purchase token fill amount from the taker's desired output amount,
     *      performs the swap, and transfers the taker's output tokens back to this contract.
     *      Must be called within a flash loan context for the given user.
     * @param input The action hook input containing the user, output amount, and encoded swap order data
     */
    function swapRepoTokenHook(
        ActionHookInput calldata input
    ) external onlyFlashLoanContext(input.user) nonReentrant {
        address taker = input.user;
        uint256 takerSwapOutputAmount = input.minOutputAmount;
        (
            bool usePermit2,
            RepoTokenSwapOrder memory order,
            Signature memory signature
        ) = abi.decode(
                input.additionalCalldata,
                (bool, RepoTokenSwapOrder, Signature)
            );
        TermRepoToken repoToken = TermRepoToken(order.repoToken);
        (uint256 redemptionTimestamp, address purchaseToken, , ) = repoToken
            .config();
        uint256 redemptionValue = repoToken.redemptionValue();
        address takerToken = order.makerAssetIsPurchaseToken
            ? purchaseToken
            : address(repoToken);

        uint256 purchaseTokenFillAmount = _calculateFillAmountFromBorrowAmount(
            takerSwapOutputAmount,
            order.makerFee,
            redemptionTimestamp,
            redemptionValue,
            order.discountRate,
            order.makerAssetIsPurchaseToken
        );

        bytes32 orderHash = _getSwapOrderHash(order);
        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.swapOrderContextMapping[orderHash];

        _validateFillAmount(
            purchaseTokenFillAmount,
            order.purchaseTokenAmount,
            orderContext.filledAmount
        );

        _swapRepoTokenInternal(
            order,
            taker,
            purchaseTokenFillAmount,
            signature,
            true,
            usePermit2
        );

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                taker,
                address(this),
                takerSwapOutputAmount.toUint160(),
                takerToken
            );
        } else {
            IERC20(takerToken).safeTransferFrom(
                taker,
                address(this),
                takerSwapOutputAmount
            );
        }
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /**
     * @notice Previews a repo token swap by returning the expected input/output tokens and amounts
     * @dev Decodes the swap order from additionalCalldata to determine token directions based on
     *      whether the maker asset is the purchase token or the repo token. Reverts if input and
     *      output tokens are the same.
     * @param actionHookInput The action hook input containing encoded swap order data
     * @return A PreviewAction struct with the expected tokens, amounts, and determinism flag
     */
    function previewSwapRepoToken(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        (, RepoTokenSwapOrder memory order, ) = abi.decode(
            actionHookInput.additionalCalldata,
            (bool, RepoTokenSwapOrder, Signature)
        );
        (
            uint256 redemptionTimestamp,
            address purchaseToken,
            ,

        ) = TermRepoToken(order.repoToken).config();
        uint256 redemptionValue = TermRepoToken(order.repoToken)
            .redemptionValue();
        address expectedInputToken;
        address expectedOutputToken;
        uint256 expectedInputAmount;
        if (order.makerAssetIsPurchaseToken) {
            expectedInputToken = order.repoToken;
            uint256 grossPurchaseTokenFill = _calculateFillAmountFromBorrowAmount(
                    actionHookInput.minOutputAmount,
                    order.makerFee,
                    redemptionTimestamp,
                    redemptionValue,
                    order.discountRate,
                    true
                );
            expectedInputAmount = _calculateRepoTokenAmount(
                redemptionTimestamp,
                redemptionValue,
                grossPurchaseTokenFill,
                order.discountRate
            );
            expectedOutputToken = purchaseToken;
        } else {
            expectedInputToken = purchaseToken;
            expectedInputAmount = _calculateFillAmountFromBorrowAmount(
                actionHookInput.minOutputAmount,
                order.makerFee,
                redemptionTimestamp,
                redemptionValue,
                order.discountRate,
                false
            );
            expectedOutputToken = order.repoToken;
        }

        if (expectedInputToken == expectedOutputToken) {
            revert InputOutputTokenCollision();
        }

        return
            PreviewAction({
                expectedInputToken: expectedInputToken,
                expectedInputAmount: expectedInputAmount,
                expectedOutputToken: expectedOutputToken,
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    // ========================================================================
    // = Internal Functions  ==================================================
    // ========================================================================

    // ------------------------------------------------------------------------
    // Hash and Signature Utilities
    // ------------------------------------------------------------------------

    function _getSwapOrderHash(
        RepoTokenSwapOrder memory order
    ) private view returns (bytes32) {
        return
            _getEIP712Hash(
                keccak256(
                    abi.encode(
                        _SWAP_ORDER_TYPEHASH,
                        order.repoToken,
                        order.makerAssetIsPurchaseToken,
                        order.purchaseTokenAmount,
                        order.discountRate,
                        order.maker,
                        order.taker,
                        order.makerFee,
                        order.takerFee,
                        order.feeRecipient,
                        order.expiry,
                        order.salt,
                        _hashRetrieveFundsStruct(order.retrieveFunds)
                    )
                )
            );
    }

    /// @notice Hashes a single RetrieveFundsStruct per EIP-712 specification
    /// @param item The RetrieveFundsStruct to hash
    /// @return The EIP-712 hash of the struct
    function _hashRetrieveFundsStruct(
        RetrieveFundsStruct memory item
    ) private pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    RETRIEVE_FUNDS_STRUCT_TYPEHASH,
                    item.method,
                    item.target,
                    keccak256(item.additionalCalldata) // bytes are hashed per EIP-712
                )
            );
    }

    function _getEIP712Hash(bytes32 structHash) private view returns (bytes32) {
        TermStorage storage s = LibTermStorage.termStorage();
        return
            keccak256(
                abi.encodePacked(hex"1901", s.eip712DomainSeparator, structHash)
            );
    }

    function _recoverEIP712Signature(
        bytes32 orderHash,
        bytes memory sigData
    ) private pure returns (address) {
        (uint8 v, bytes32 r, bytes32 s) = abi.decode(
            sigData,
            (uint8, bytes32, bytes32)
        );
        return ECDSA.recover(orderHash, v, r, s);
    }

    function _getSignerOfHash(
        bytes32 orderHash,
        Signature memory signature
    ) private view returns (address) {
        TermStorage storage s = LibTermStorage.termStorage();
        if (signature.sigType == SignatureType.EIP712) {
            return _recoverEIP712Signature(orderHash, signature.sigData);
        } else if (signature.sigType == SignatureType.PRESIGN) {
            return s.preSignedSwapOrders[orderHash];
        } else {
            revert InvalidSignature();
        }
    }

    // ------------------------------------------------------------------------
    // Validation Functions
    // ------------------------------------------------------------------------

    function _validateSwapOrderParams(
        RepoTokenSwapOrder memory order
    ) private view {
        TermRepoToken repoToken = TermRepoToken(order.repoToken);
        _validateRepoToken(repoToken);

        if (order.purchaseTokenAmount == 0) {
            revert InvalidPurchaseTokenAmount();
        }
        if (order.expiry < block.timestamp) {
            revert OrderExpired();
        }
        if (order.discountRate == 0) {
            revert InvalidDiscountRate();
        }
    }

    function _validateRepoToken(TermRepoToken repoToken) private view {
        (, , address termRepoServicer, ) = repoToken.config();
        ITermRepoServicer servicer = ITermRepoServicer(termRepoServicer);
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = servicer.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(repoToken)) &&
            !termController.isFactoryDeployed(address(repoToken))
        ) {
            revert InvalidRepoId();
        }

        uint256 maturityTimestamp = servicer.maturityTimestamp();
        if (block.timestamp > maturityTimestamp) {
            revert AfterMaturity();
        }
    }

    function _validateOrderSignature(
        bytes32 orderHash,
        address maker,
        Signature memory signature
    ) private view {
        address signer = _getSignerOfHash(orderHash, signature);
        if (signer != maker) {
            revert InvalidSignature();
        }
    }

    function _validateOrderStatus(
        OrderContext memory orderContext
    ) private pure {
        if (
            orderContext.status != ITermIntent.OrderStatus.UNFILLED &&
            orderContext.status != ITermIntent.OrderStatus.PARTIALLY_FILLED
        ) {
            revert InvalidOrderStatus();
        }
    }

    function _validateOrderAuthorization(
        address taker,
        address fulfiller
    ) private pure {
        if (taker != ALLOW_ANY_ADDRESS && fulfiller != taker) {
            revert InvalidTaker(taker, fulfiller);
        }
    }

    function _validateSwapOrderNotCancelled(
        address maker,
        address makerToken,
        address takerToken,
        uint256 salt
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        uint256 minSalt = s.swapOrderMakerTokenPairMinSalt[maker][makerToken][
            takerToken
        ];
        if (salt <= minSalt) {
            revert OrderCancelled();
        }
    }

    function _validateRetrieveFunds(
        RetrieveFundsStruct memory retrieveFunds
    ) private view returns (bool) {
        if (retrieveFunds.method != bytes4(0)) {
            address facetAddress = IDiamondLoupe(address(this)).facetAddress(
                retrieveFunds.method
            );

            // Confirm that method belongs to specified facet
            if (facetAddress == address(0)) {
                revert InvalidRetrieveFundsFunction();
            }
            return true;
        }
        return false;
    }

    // ------------------------------------------------------------------------
    // Calculation and Utility Functions
    // ------------------------------------------------------------------------

    function _validateFillAmount(
        uint256 fillAmount,
        uint256 totalAmount,
        uint256 filledAmount
    ) private pure returns (uint256) {
        uint256 maxFill = totalAmount - filledAmount;
        if (maxFill < fillAmount) {
            revert InsufficientRemainingCapacity(maxFill);
        }
        return fillAmount;
    }

    function _calculateRepoTokenAmount(
        uint256 redemptionTimestamp,
        uint256 redemptionValue,
        uint256 fillAmount,
        uint256 discountRate
    ) private view returns (uint256) {
        Exp memory repurchaseFactor = _calculateRepurchaseFactor(
            redemptionTimestamp,
            discountRate
        );

        uint256 repoTokenAmount = truncate(
            div_(
                mul_(Exp({mantissa: fillAmount * expScale}), repurchaseFactor),
                Exp({mantissa: redemptionValue})
            )
        );
        return repoTokenAmount;
    }

    function _calculateRepurchaseFactor(
        uint256 redemptionTimestamp,
        uint256 discountRate
    ) private view returns (Exp memory) {
        uint256 dayCountFractionMantissa = ((redemptionTimestamp -
            block.timestamp) * expScale) / YEAR_SECONDS;

        return
            add_(
                Exp({mantissa: expScale}),
                mul_(
                    Exp({mantissa: dayCountFractionMantissa}),
                    Exp({mantissa: discountRate})
                )
            );
    }

    function _calculateFillAmountFromBorrowAmount(
        uint256 desiredSwapOutputAmount,
        uint256 swapFee,
        uint256 redemptionTimestamp,
        uint256 redemptionValue,
        uint256 discountRate,
        bool isPurchaseTokenFill
    ) internal view returns (uint256) {
        if (swapFee >= expScale) {
            revert InvalidFee();
        }
        // Early return for zero: the +1 conservative rounding applied in the branches below would
        // otherwise return 1 for a zero-output request, bypassing the InvalidFillAmount() guard in
        // _swapRepoTokenInternal and silently executing a 1-wei dust fill of the order.
        if (desiredSwapOutputAmount == 0) return 0;
        if (swapFee == 0 && isPurchaseTokenFill) {
            return desiredSwapOutputAmount;
        } else if (isPurchaseTokenFill) {
            // +1 for conservative rounding: div_ truncates (floor), so the gross fill may be 1 wei
            // short of exactly covering desiredSwapOutputAmount after the maker deducts swapFee.
            // Adding 1 ensures ceil(desiredSwapOutputAmount / (1 - swapFee)), guaranteeing the
            // taker receives at least desiredSwapOutputAmount purchase tokens.
            return
                div_(
                    Exp({mantissa: desiredSwapOutputAmount}),
                    sub_(Exp({mantissa: expScale}), Exp({mantissa: swapFee}))
                ).mantissa + 1;
        } else {
            Exp memory repurchaseFactor = _calculateRepurchaseFactor(
                redemptionTimestamp,
                discountRate
            );

            Exp memory purchaseTokenAmount = div_(
                mul_(
                    Exp({mantissa: desiredSwapOutputAmount * expScale}),
                    Exp({mantissa: redemptionValue})
                ),
                repurchaseFactor
            );

            // +1 for conservative rounding: both the repo-to-purchase conversion (div_ above) and the
            // fee grossing (div_ below) truncate independently. Keeping purchaseTokenAmount as an
            // intermediate Exp avoids a second truncation boundary, but the final truncate() still
            // floors by up to 1 wei. Adding 1 ensures the gross fill converts back to at least
            // desiredSwapOutputAmount repo tokens after the maker applies redemptionValue/repurchaseFactor.
            if (swapFee == 0) {
                return truncate(purchaseTokenAmount) + 1;
            } else {
                return
                    truncate(
                        div_(
                            purchaseTokenAmount,
                            sub_(
                                Exp({mantissa: expScale}),
                                Exp({mantissa: swapFee})
                            )
                        )
                    ) + 1;
            }
        }
    }

    function _generateRetrieveFundsCalldata(
        RetrieveFundsStruct memory retrieveFunds,
        uint256 amountToRetrieve,
        address token,
        address user
    ) private returns (bytes memory) {
        address facetAddress = IDiamondLoupe(address(this)).facetAddress(
            retrieveFunds.method
        );
        bytes4 sig = bytes4(
            keccak256(
                "generateCalldata(bytes4,address,address,address,uint256,bool,bytes)"
            )
        );

        bytes memory encodeCalldataInput = abi.encodeWithSelector(
            sig,
            retrieveFunds.method,
            retrieveFunds.target,
            token,
            user,
            amountToRetrieve,
            false,
            retrieveFunds.additionalCalldata
        );
        bytes memory returnData = Address.functionCall(
            facetAddress,
            encodeCalldataInput
        );
        return abi.decode(returnData, (bytes));
    }

    // ------------------------------------------------------------------------
    // Order Management
    // ------------------------------------------------------------------------

    function _updateOrderStatus(
        uint256 maxFill,
        uint256 fillAmount,
        bytes32 orderHash,
        OrderContext memory orderContext
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        if (fillAmount == maxFill) {
            orderContext.status = ITermIntent.OrderStatus.FILLED;
        } else {
            orderContext.status = ITermIntent.OrderStatus.PARTIALLY_FILLED;
        }

        orderContext.filledAmount += fillAmount.toUint128();
        s.swapOrderContextMapping[orderHash] = orderContext;
    }

    function _cancelOrder(
        bytes32 orderHash,
        address maker,
        address caller,
        Signature memory signature
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.swapOrderContextMapping[orderHash];

        if (
            orderContext.status == ITermIntent.OrderStatus.FILLED ||
            orderContext.status == ITermIntent.OrderStatus.CANCELLED
        ) {
            revert InvalidOrderStatus();
        }

        address signer = _getSignerOfHash(orderHash, signature);
        if (signer != maker) {
            revert InvalidSignature();
        }

        if (maker != caller) {
            revert InvalidSender(maker, caller);
        }

        s.swapOrderContextMapping[orderHash].status = ITermIntent
            .OrderStatus
            .CANCELLED;
        s.emitter.emitIntentCancelled(orderHash);
    }

    // ------------------------------------------------------------------------
    // Settlement Processing
    // ------------------------------------------------------------------------

    /// @notice Internal function for swapping repo tokens
    function _swapRepoTokenInternal(
        RepoTokenSwapOrder memory order,
        address taker,
        uint256 fillAmount,
        Signature memory signature,
        bool isRoutedTakerToken,
        bool usePermit2
    ) private {
        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }

        if (order.maker == taker) {
            revert MakerCannotBeTaker();
        }

        _validateSwapOrderParams(order);

        bytes32 orderHash = _getSwapOrderHash(order);
        _validateOrderSignature(orderHash, order.maker, signature);

        TermStorage storage s = LibTermStorage.termStorage();
        OrderContext memory orderContext = s.swapOrderContextMapping[orderHash];
        _validateOrderStatus(orderContext);

        TermRepoToken repoToken = TermRepoToken(order.repoToken);
        (uint256 redemptionTimestamp, address purchaseToken, , ) = repoToken
            .config();
        uint256 redemptionValue = repoToken.redemptionValue();

        if (order.makerAssetIsPurchaseToken) {
            _validateSwapOrderNotCancelled(
                order.maker,
                purchaseToken,
                order.repoToken,
                order.salt
            );
        } else {
            _validateSwapOrderNotCancelled(
                order.maker,
                order.repoToken,
                purchaseToken,
                order.salt
            );
        }

        _validateOrderAuthorization(order.taker, taker);
        bool retrieveFundsRequested = _validateRetrieveFunds(
            order.retrieveFunds
        );
        if (!s.approvedFeeRecipients[order.feeRecipient]) {
            revert InvalidFeeRecipient();
        }

        // Fill amount cached after validation to prevent stack overflow
        uint256 validatedFillAmount = _validateFillAmount(
            fillAmount,
            order.purchaseTokenAmount,
            orderContext.filledAmount
        );

        uint256 repoTokenFillAmount = _calculateRepoTokenAmount(
            redemptionTimestamp,
            redemptionValue,
            fillAmount,
            order.discountRate
        );

        _updateOrderStatus(
            order.purchaseTokenAmount - orderContext.filledAmount,
            validatedFillAmount,
            orderHash,
            orderContext
        );

        bool isRoutedPurchaseToken;
        bool isRoutedRepoToken;
        address makerToken;

        if (order.makerAssetIsPurchaseToken) {
            makerToken = purchaseToken;
            isRoutedRepoToken = isRoutedTakerToken;
        } else {
            makerToken = order.repoToken;
            isRoutedPurchaseToken = isRoutedTakerToken;
        }

        _settleSwap(
            orderHash,
            order,
            isRoutedPurchaseToken,
            isRoutedRepoToken,
            retrieveFundsRequested,
            purchaseToken,
            address(repoToken),
            taker,
            validatedFillAmount,
            repoTokenFillAmount,
            usePermit2
        );
    }

    // ------------------------------------------------------------------------
    // Token and Fee Handling
    // ------------------------------------------------------------------------

    function _settleSwap(
        bytes32 orderHash,
        RepoTokenSwapOrder memory order,
        bool isRoutedPurchaseToken,
        bool isRoutedRepoToken,
        bool retrieveFundsRequested,
        address purchaseToken,
        address repoToken,
        address taker,
        uint256 purchaseTokenAmount,
        uint256 repoTokenAmount,
        bool usePermit2
    ) private {
        if (retrieveFundsRequested) {
            address retrieveFundsToken = order.makerAssetIsPurchaseToken
                ? purchaseToken
                : repoToken;
            uint256 retrieveFundsAmount = order.makerAssetIsPurchaseToken
                ? purchaseTokenAmount
                : repoTokenAmount;
            // generate retrieveFundsCalldata
            bytes memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
                order.retrieveFunds,
                retrieveFundsAmount,
                retrieveFundsToken,
                order.maker
            );

            // Set settlement context before executing retrieveFunds
            TermStorage storage ts = LibTermStorage.termStorage();
            ts.activeSettlementMaker = order.maker;

            uint256 tokenBalanceBeforeRetrieveFunds = IERC20(retrieveFundsToken)
                .balanceOf(address(this));
            // execute retrieveFundsCalldata
            Address.functionCall(address(this), retrieveFundsCalldata);
            uint256 tokenBalanceAfterRetrieveFunds = IERC20(retrieveFundsToken)
                .balanceOf(address(this));

            if (
                tokenBalanceAfterRetrieveFunds <
                tokenBalanceBeforeRetrieveFunds + retrieveFundsAmount
            ) {
                revert InsufficientFundsRetrieved();
            }

            // Clear settlement context after execution
            ts.activeSettlementMaker = address(0);

            if (order.makerAssetIsPurchaseToken) {
                isRoutedPurchaseToken = true;
            } else {
                isRoutedRepoToken = true;
            }
        }

        Exp memory purchaseTokenAmountExp = Exp({
            mantissa: purchaseTokenAmount
        });
        Exp memory repoTokenAmountExp = Exp({mantissa: repoTokenAmount});

        uint256 repoTokenFee = mul_ScalarTruncate(
            repoTokenAmountExp,
            order.makerAssetIsPurchaseToken ? order.takerFee : order.makerFee
        );
        uint256 purchaseTokenFee = mul_ScalarTruncate(
            purchaseTokenAmountExp,
            order.makerAssetIsPurchaseToken ? order.makerFee : order.takerFee
        );

        _executeTokenTransfer(
            repoToken,
            isRoutedRepoToken,
            order.makerAssetIsPurchaseToken ? taker : order.maker,
            order.makerAssetIsPurchaseToken ? order.maker : taker,
            order.feeRecipient,
            repoTokenAmount,
            repoTokenFee,
            order.makerAssetIsPurchaseToken ? usePermit2 : false
        );

        _executeTokenTransfer(
            purchaseToken,
            isRoutedPurchaseToken,
            order.makerAssetIsPurchaseToken ? order.maker : taker,
            order.makerAssetIsPurchaseToken ? taker : order.maker,
            order.feeRecipient,
            purchaseTokenAmount,
            purchaseTokenFee,
            order.makerAssetIsPurchaseToken ? false : usePermit2
        );

        _emitSwapEvent(
            orderHash,
            order,
            repoToken,
            taker,
            purchaseToken,
            order.makerAssetIsPurchaseToken
                ? purchaseTokenAmount
                : repoTokenAmount,
            order.makerAssetIsPurchaseToken
                ? repoTokenAmount
                : purchaseTokenAmount,
            order.makerAssetIsPurchaseToken ? purchaseTokenFee : repoTokenFee,
            order.makerAssetIsPurchaseToken ? repoTokenFee : purchaseTokenFee,
            order.feeRecipient
        );
    }

    function _executeTokenTransfer(
        address token,
        bool isRouted,
        address from,
        address to,
        address feeRecipient,
        uint256 amount,
        uint256 fee,
        bool useTransfer2
    ) private {
        if (isRouted) {
            IERC20(token).safeTransfer(to, amount - fee);
            if (fee > 0) {
                IERC20(token).safeTransfer(feeRecipient, fee);
            }
        } else {
            if (useTransfer2) {
                Permit2Lib.PERMIT2.transferFrom(
                    from,
                    to,
                    (amount - fee).toUint160(),
                    token
                );
                if (fee > 0) {
                    Permit2Lib.PERMIT2.transferFrom(
                        from,
                        feeRecipient,
                        fee.toUint160(),
                        token
                    );
                }
            } else {
                IERC20(token).safeTransferFrom(from, to, amount - fee);
                if (fee > 0) {
                    IERC20(token).safeTransferFrom(from, feeRecipient, fee);
                }
            }
        }
    }

    // ------------------------------------------------------------------------
    // Event Emission
    // ------------------------------------------------------------------------

    function _emitSwapEvent(
        bytes32 orderHash,
        RepoTokenSwapOrder memory order,
        address repoToken,
        address taker,
        address purchaseToken,
        uint256 makerAssetAmount,
        uint256 takerAssetAmount,
        uint256 makerFee,
        uint256 takerFee,
        address feeRecipient
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermIntentEvents.RepoTokenSwapData memory swapData = ITermIntentEvents
            .RepoTokenSwapData({
                repoToken: repoToken,
                purchaseToken: purchaseToken,
                maker: order.maker,
                taker: taker,
                makerToken: order.makerAssetIsPurchaseToken
                    ? purchaseToken
                    : repoToken,
                takerToken: order.makerAssetIsPurchaseToken
                    ? repoToken
                    : purchaseToken,
                discountRate: order.discountRate,
                makerTokenAmountFilled: makerAssetAmount,
                takerTokenAmountFilled: takerAssetAmount,
                makerFee: makerFee,
                takerFee: takerFee,
                feeRecipient: feeRecipient,
                originalOrderAmount: order.purchaseTokenAmount,
                expiry: order.expiry,
                salt: order.salt
            });
        s.emitter.emitRepoTokenSwapFilled(orderHash, swapData);
    }
}

