error InputOutputTokenCollision();

/// @author TermLabs
/// @title Term Router Facet
/// @notice This facet provides centralized access to all DIAMOND_ROLE functions across Term contracts
/// @dev This facet aggregates settlement operations from TermRepoServicer, TermRepoCollateralManager, and TermRepoRolloverManager
contract TermRouterFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermMultiContextAuth,
    ExponentialNoError,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    // ========================================================================
    // = Custom Errors  =======================================================
    // ========================================================================

    error AfterMaturity();
    error CollateralTransferFailed();
    error InsufficientCollateralAmount(uint256 requested, uint256 available);
    error InvalidCollateralToken();
    error InvalidRepoId();
    error InvalidTermController();
    error PurchaseTokenMismatch();
    error ZeroMintAmount();

    // ========================================================================
    // = Deploy ===============================================================
    // ========================================================================

    constructor() {
        previewMapping[this.submitRepurchasePaymentHook.selector] = this
            .previewSubmitRepurchasePayment
            .selector;
    }

    // ========================================================================
    // = TermAuctionBidLocker Functions  ======================================
    // ========================================================================

    /// @notice Locks bid submissions with collateral transfer and approval
    /// @dev Transfers collateral tokens from bidder and approves TermRepoLocker before locking bids
    /// @param termAuctionBidLocker Address of the TermAuctionBidLocker contract
    /// @param bidSubmissions Array of bid submissions to lock. The collateralTokens array in each
    ///        TermAuctionBidSubmission must be the same length and in the same order across all submissions
    /// @param usePermit2 Whether to use Permit2 for token transfers instead of standard ERC20 transfers
    function lockBids(
        address termAuctionBidLocker,
        TermAuctionBidSubmission[] calldata bidSubmissions,
        bool usePermit2
    ) external nonReentrant {
        ITermAuctionBidLocker _termAuctionBidLocker = ITermAuctionBidLocker(
            termAuctionBidLocker
        );
        _validateAuctionBidLocker(_termAuctionBidLocker);

        ITermRepoLocker termRepoLocker = _termAuctionBidLocker
            .termRepoServicer()
            .termRepoLocker();
        TermAuctionBid memory existingBid;
        uint256 collateralRequired;

        // Track cumulative amounts for each collateral token position
        uint256 numCollateralTokens = bidSubmissions.length > 0
            ? bidSubmissions[0].collateralTokens.length
            : 0;
        uint256[] memory totalAmounts = new uint256[](numCollateralTokens);

        if (usePermit2) {
            uint8 i;
            uint8 j;
            for (i = 0; i < bidSubmissions.length; ++i) {
                existingBid = _termAuctionBidLocker.lockedBid(
                    bidSubmissions[i].id
                );
                bool bidExists = existingBid.amount != 0;
                for (
                    j = 0;
                    j < bidSubmissions[i].collateralTokens.length;
                    ++j
                ) {
                    if (bidExists) {
                        if (
                            existingBid.collateralAmounts[j] == 0 &&
                            bidSubmissions[i].collateralAmounts[j] == 0
                        ) {
                            continue;
                        }
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j] >
                            existingBid.collateralAmounts[j]
                            ? bidSubmissions[i].collateralAmounts[j] -
                                existingBid.collateralAmounts[j]
                            : 0;
                    } else {
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j];
                    }
                    if (collateralRequired == 0) {
                        continue;
                    }
                    Permit2Lib.PERMIT2.transferFrom(
                        msg.sender,
                        address(this),
                        collateralRequired.toUint160(),
                        bidSubmissions[i].collateralTokens[j]
                    );
                    // Accumulate the total for this collateral token position
                    totalAmounts[j] += collateralRequired;
                }
            }
        } else {
            uint8 i;
            uint8 j;
            for (i = 0; i < bidSubmissions.length; ++i) {
                existingBid = _termAuctionBidLocker.lockedBid(
                    bidSubmissions[i].id
                );
                bool bidExists = existingBid.amount != 0;
                for (
                    j = 0;
                    j < bidSubmissions[i].collateralTokens.length;
                    ++j
                ) {
                    if (bidExists) {
                        if (
                            existingBid.collateralAmounts[j] == 0 &&
                            bidSubmissions[i].collateralAmounts[j] == 0
                        ) {
                            continue;
                        }
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j] >
                            existingBid.collateralAmounts[j]
                            ? bidSubmissions[i].collateralAmounts[j] -
                                existingBid.collateralAmounts[j]
                            : 0;
                    } else {
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j];
                    }
                    if (collateralRequired == 0) {
                        continue;
                    }
                    IERC20(bidSubmissions[i].collateralTokens[j])
                        .safeTransferFrom(
                            msg.sender,
                            address(this),
                            collateralRequired
                        );
                    // Accumulate the total for this collateral token position
                    totalAmounts[j] += collateralRequired;
                }
            }
        }

        uint8 j;

        // Approve the total amount for each collateral token
        if (bidSubmissions.length > 0) {
            for (j = 0; j < numCollateralTokens; ++j) {
                if (totalAmounts[j] > 0) {
                    IERC20(bidSubmissions[0].collateralTokens[j]).forceApprove(
                        address(termRepoLocker),
                        totalAmounts[j]
                    );
                }
            }
        }

        _termAuctionBidLocker.lockBidsWithReferral(
            msg.sender,
            bidSubmissions,
            address(0)
        );

        // Revoke the approval for each collateral token after locking bids
        if (bidSubmissions.length > 0) {
            for (j = 0; j < numCollateralTokens; ++j) {
                if (totalAmounts[j] > 0) {
                    IERC20(bidSubmissions[0].collateralTokens[j]).forceApprove(
                        address(termRepoLocker),
                        0
                    );
                }
            }
        }
    }
    /// @notice Locks bid submissions with collateral transfer and approval
    /// @dev Transfers collateral tokens from bidder and approves TermRepoLocker before locking bids
    /// @param termAuctionBidLocker Address of the TermAuctionBidLocker contract
    /// @param bidSubmissions Array of bid submissions to lock
    /// @param referralAddress A user address that referred the submitter of this bid
    /// @param usePermit2 Whether to use Permit2 for token transfers instead of standard ERC20 transfers
    function lockBidsWithReferral(
        address termAuctionBidLocker,
        TermAuctionBidSubmission[] calldata bidSubmissions,
        address referralAddress,
        bool usePermit2
    ) external nonReentrant {
        ITermAuctionBidLocker _termAuctionBidLocker = ITermAuctionBidLocker(
            termAuctionBidLocker
        );
        _validateAuctionBidLocker(_termAuctionBidLocker);

        ITermRepoLocker termRepoLocker = _termAuctionBidLocker
            .termRepoServicer()
            .termRepoLocker();
        TermAuctionBid memory existingBid;
        uint256 collateralRequired;

        // Track cumulative amounts for each collateral token position
        uint256 numCollateralTokens = bidSubmissions.length > 0
            ? bidSubmissions[0].collateralTokens.length
            : 0;
        uint256[] memory totalAmounts = new uint256[](numCollateralTokens);

        if (usePermit2) {
            uint8 i;
            uint8 j;
            for (i = 0; i < bidSubmissions.length; ++i) {
                existingBid = _termAuctionBidLocker.lockedBid(
                    bidSubmissions[i].id
                );
                bool bidExists = existingBid.amount != 0;
                for (
                    j = 0;
                    j < bidSubmissions[i].collateralTokens.length;
                    ++j
                ) {
                    if (bidExists) {
                        if (
                            existingBid.collateralAmounts[j] == 0 &&
                            bidSubmissions[i].collateralAmounts[j] == 0
                        ) {
                            continue;
                        }
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j] >
                            existingBid.collateralAmounts[j]
                            ? bidSubmissions[i].collateralAmounts[j] -
                                existingBid.collateralAmounts[j]
                            : 0;
                    } else {
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j];
                    }
                    if (collateralRequired == 0) {
                        continue;
                    }
                    Permit2Lib.PERMIT2.transferFrom(
                        msg.sender,
                        address(this),
                        collateralRequired.toUint160(),
                        bidSubmissions[i].collateralTokens[j]
                    );
                    // Accumulate the total for this collateral token position
                    totalAmounts[j] += collateralRequired;
                }
            }
        } else {
            uint8 i;
            uint8 j;
            for (i = 0; i < bidSubmissions.length; ++i) {
                existingBid = _termAuctionBidLocker.lockedBid(
                    bidSubmissions[i].id
                );
                bool bidExists = existingBid.amount != 0;
                for (
                    j = 0;
                    j < bidSubmissions[i].collateralTokens.length;
                    ++j
                ) {
                    if (bidExists) {
                        if (
                            existingBid.collateralAmounts[j] == 0 &&
                            bidSubmissions[i].collateralAmounts[j] == 0
                        ) {
                            continue;
                        }
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j] >
                            existingBid.collateralAmounts[j]
                            ? bidSubmissions[i].collateralAmounts[j] -
                                existingBid.collateralAmounts[j]
                            : 0;
                    } else {
                        collateralRequired = bidSubmissions[i]
                            .collateralAmounts[j];
                    }
                    if (collateralRequired == 0) {
                        continue;
                    }
                    IERC20(bidSubmissions[i].collateralTokens[j])
                        .safeTransferFrom(
                            msg.sender,
                            address(this),
                            collateralRequired
                        );
                    // Accumulate the total for this collateral token position
                    totalAmounts[j] += collateralRequired;
                }
            }
        }

        uint8 j;

        // Approve the total amount for each collateral token
        if (bidSubmissions.length > 0) {
            for (j = 0; j < numCollateralTokens; ++j) {
                if (totalAmounts[j] > 0) {
                    IERC20(bidSubmissions[0].collateralTokens[j]).forceApprove(
                        address(termRepoLocker),
                        totalAmounts[j]
                    );
                }
            }
        }

        _termAuctionBidLocker.lockBidsWithReferral(
            msg.sender,
            bidSubmissions,
            referralAddress
        );

        // Revoke the approval for each collateral token after locking bids
        if (bidSubmissions.length > 0) {
            for (j = 0; j < numCollateralTokens; ++j) {
                if (totalAmounts[j] > 0) {
                    IERC20(bidSubmissions[0].collateralTokens[j]).forceApprove(
                        address(termRepoLocker),
                        0
                    );
                }
            }
        }
    }

    /// @notice Unlocks specified bid submissions
    /// @dev Delegates to the TermAuctionBidLocker to unlock bids for the caller
    /// @param termAuctionBidLocker Address of the TermAuctionBidLocker contract
    /// @param bidIds Array of bid IDs to unlock
    function unlockBids(
        address termAuctionBidLocker,
        bytes32[] calldata bidIds
    ) external nonReentrant {
        ITermAuctionBidLocker _termAuctionBidLocker = ITermAuctionBidLocker(
            termAuctionBidLocker
        );
        _validateAuctionBidLocker(_termAuctionBidLocker);
        _termAuctionBidLocker.unlockBids(msg.sender, bidIds);
    }

    // ========================================================================
    // = TermAuctionOfferLocker Functions  ====================================
    // ========================================================================

    /// @notice Locks offer submissions with purchase token transfer and approval
    /// @dev Transfers purchase tokens from offerer and approves TermRepoLocker before locking offers
    /// @param termAuctionOfferLocker Address of the TermAuctionOfferLocker contract
    /// @param offerSubmissions Array of offer submissions to lock
    /// @param usePermit2 Whether to use Permit2 for token transfers instead of standard ERC20 transfers
    function lockOffers(
        address termAuctionOfferLocker,
        TermAuctionOfferSubmission[] calldata offerSubmissions,
        bool usePermit2
    ) external nonReentrant {
        ITermAuctionOfferLocker _termAuctionOfferLocker = ITermAuctionOfferLocker(
                termAuctionOfferLocker
            );
        _validateAuctionOfferLocker(_termAuctionOfferLocker);

        ITermRepoLocker termRepoLocker = _termAuctionOfferLocker
            .termRepoServicer()
            .termRepoLocker();
        TermAuctionOffer memory existingOffer;
        uint256 requiredPurchaseTokens;
        uint256 totalPurchaseTokensRequired = 0;
        address purchaseToken = offerSubmissions.length > 0
            ? offerSubmissions[0].purchaseToken
            : address(0);

        if (usePermit2) {
            for (uint8 i = 0; i < offerSubmissions.length; ++i) {
                existingOffer = _termAuctionOfferLocker.lockedOffer(
                    offerSubmissions[i].id
                );
                if (
                    existingOffer.amount == 0 && offerSubmissions[i].amount == 0
                ) {
                    continue;
                }
                requiredPurchaseTokens = offerSubmissions[i].amount >
                    existingOffer.amount
                    ? offerSubmissions[i].amount - existingOffer.amount
                    : 0;
                if (requiredPurchaseTokens > 0) {
                    Permit2Lib.PERMIT2.transferFrom(
                        msg.sender,
                        address(this),
                        requiredPurchaseTokens.toUint160(),
                        offerSubmissions[i].purchaseToken
                    );
                    // Accumulate the total purchase tokens required
                    totalPurchaseTokensRequired += requiredPurchaseTokens;
                }
            }
        } else {
            for (uint8 i = 0; i < offerSubmissions.length; ++i) {
                existingOffer = _termAuctionOfferLocker.lockedOffer(
                    offerSubmissions[i].id
                );

                if (
                    existingOffer.amount == 0 && offerSubmissions[i].amount == 0
                ) {
                    continue;
                }
                requiredPurchaseTokens = offerSubmissions[i].amount >
                    existingOffer.amount
                    ? offerSubmissions[i].amount - existingOffer.amount
                    : 0;
                if (requiredPurchaseTokens > 0) {
                    IERC20(offerSubmissions[i].purchaseToken).safeTransferFrom(
                        msg.sender,
                        address(this),
                        requiredPurchaseTokens
                    );
                    // Accumulate the total purchase tokens required
                    totalPurchaseTokensRequired += requiredPurchaseTokens;
                }
            }
        }

        // Approve the total amount of purchase tokens
        if (totalPurchaseTokensRequired > 0 && purchaseToken != address(0)) {
            IERC20(purchaseToken).forceApprove(
                address(termRepoLocker),
                totalPurchaseTokensRequired
            );
        }

        _termAuctionOfferLocker.lockOffersWithReferral(
            msg.sender,
            offerSubmissions,
            address(0)
        );

        // Revoke the purchase token approval after locking offers
        if (totalPurchaseTokensRequired > 0 && purchaseToken != address(0)) {
            IERC20(purchaseToken).forceApprove(address(termRepoLocker), 0);
        }
    }

    /// @notice Locks offer submissions with purchase token transfer and approval
    /// @dev Transfers purchase tokens from offerer and approves TermRepoLocker before locking offers
    /// @param termAuctionOfferLocker Address of the TermAuctionOfferLocker contract
    /// @param offerSubmissions Array of offer submissions to lock
    /// @param referralAddress A user address that referred the submitter of this offer
    /// @param usePermit2 Whether to use Permit2 for token transfers instead of standard ERC20 transfers
    function lockOffersWithReferral(
        address termAuctionOfferLocker,
        TermAuctionOfferSubmission[] calldata offerSubmissions,
        address referralAddress,
        bool usePermit2
    ) external nonReentrant {
        ITermAuctionOfferLocker _termAuctionOfferLocker = ITermAuctionOfferLocker(
                termAuctionOfferLocker
            );
        _validateAuctionOfferLocker(_termAuctionOfferLocker);

        ITermRepoLocker termRepoLocker = _termAuctionOfferLocker
            .termRepoServicer()
            .termRepoLocker();
        TermAuctionOffer memory existingOffer;
        uint256 requiredPurchaseTokens;
        uint256 totalPurchaseTokensRequired = 0;
        address purchaseToken = offerSubmissions.length > 0
            ? offerSubmissions[0].purchaseToken
            : address(0);

        if (usePermit2) {
            for (uint8 i = 0; i < offerSubmissions.length; ++i) {
                existingOffer = _termAuctionOfferLocker.lockedOffer(
                    offerSubmissions[i].id
                );
                if (
                    existingOffer.amount == 0 && offerSubmissions[i].amount == 0
                ) {
                    continue;
                }
                requiredPurchaseTokens = offerSubmissions[i].amount >
                    existingOffer.amount
                    ? offerSubmissions[i].amount - existingOffer.amount
                    : 0;
                if (requiredPurchaseTokens > 0) {
                    Permit2Lib.PERMIT2.transferFrom(
                        msg.sender,
                        address(this),
                        requiredPurchaseTokens.toUint160(),
                        offerSubmissions[i].purchaseToken
                    );
                    // Accumulate the total purchase tokens required
                    totalPurchaseTokensRequired += requiredPurchaseTokens;
                }
            }
        } else {
            for (uint8 i = 0; i < offerSubmissions.length; ++i) {
                existingOffer = _termAuctionOfferLocker.lockedOffer(
                    offerSubmissions[i].id
                );

                if (
                    existingOffer.amount == 0 && offerSubmissions[i].amount == 0
                ) {
                    continue;
                }
                requiredPurchaseTokens = offerSubmissions[i].amount >
                    existingOffer.amount
                    ? offerSubmissions[i].amount - existingOffer.amount
                    : 0;
                if (requiredPurchaseTokens > 0) {
                    IERC20(offerSubmissions[i].purchaseToken).safeTransferFrom(
                        msg.sender,
                        address(this),
                        requiredPurchaseTokens
                    );
                    // Accumulate the total purchase tokens required
                    totalPurchaseTokensRequired += requiredPurchaseTokens;
                }
            }
        }

        // Approve the total amount of purchase tokens
        if (totalPurchaseTokensRequired > 0 && purchaseToken != address(0)) {
            IERC20(purchaseToken).forceApprove(
                address(termRepoLocker),
                totalPurchaseTokensRequired
            );
        }

        _termAuctionOfferLocker.lockOffersWithReferral(
            msg.sender,
            offerSubmissions,
            referralAddress
        );

        // Revoke the purchase token approval after locking offers
        if (totalPurchaseTokensRequired > 0 && purchaseToken != address(0)) {
            IERC20(purchaseToken).forceApprove(address(termRepoLocker), 0);
        }
    }

    /// @notice Unlocks specified offer submissions
    /// @dev Delegates to the TermAuctionOfferLocker to unlock offers for the caller
    /// @param termAuctionOfferLocker Address of the TermAuctionOfferLocker contract
    /// @param offerIds Array of offer IDs to unlock
    function unlockOffers(
        address termAuctionOfferLocker,
        bytes32[] calldata offerIds
    ) external nonReentrant {
        ITermAuctionOfferLocker _termAuctionOfferLocker = ITermAuctionOfferLocker(
                termAuctionOfferLocker
            );
        _validateAuctionOfferLocker(_termAuctionOfferLocker);
        _termAuctionOfferLocker.unlockOffers(msg.sender, offerIds);
    }

    // ========================================================================
    // = TermRepoServicer Functions  ==========================================
    // ========================================================================

    /// @notice Submit repurchase payment on behalf of a borrower
    /// @param termRepoServicer The address of the TermRepoServicer contract
    /// @param amount The amount of purchase token to submit for repurchase
    /// @param usePermit2 Whether to use Permit2 for token transfer
    function submitRepurchasePayment(
        address termRepoServicer,
        uint256 amount,
        bool usePermit2
    ) external nonReentrant {
        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        _validateRepoServicer(_termRepoServicer);

        ITermRepoLocker termRepoLocker = _termRepoServicer.termRepoLocker();

        //@dev Transfer purchase tokens from msg.sender to this contract
        IERC20 purchaseToken = IERC20(_termRepoServicer.purchaseToken());
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                amount.toUint160(),
                address(purchaseToken)
            );
        } else {
            IERC20(purchaseToken).safeTransferFrom(
                msg.sender,
                address(this),
                amount
            );
        }
        IERC20(purchaseToken).forceApprove(address(termRepoLocker), amount);

        _termRepoServicer.submitRepurchasePayment(msg.sender, amount);

        IERC20(purchaseToken).forceApprove(address(termRepoLocker), 0);
    }

    /// @notice Burn and collapse exposure on behalf of a borrower
    /// @param termRepoServicer The address of the TermRepoServicer contract
    /// @param amountToBurn The amount of TermRepoTokens to burn
    function burnCollapseExposure(
        address termRepoServicer,
        uint256 amountToBurn
    ) external nonReentrant {
        _validateRepoServicer(ITermRepoServicer(termRepoServicer));
        ITermRepoServicer(termRepoServicer).burnCollapseExposure(
            msg.sender,
            amountToBurn
        );
    }

    /// @notice Mint open exposure for settlement
    /// @param termRepoServicer The address of the TermRepoServicer contract
    /// @param repoTokenAmount The amount of repoTokens tokens
    /// @param collateralAmounts Array of collateral amounts
    /// @param usePermit2 Whether to use Permit2 for token transfer
    function mintOpenExposure(
        address termRepoServicer,
        uint256 repoTokenAmount,
        uint256[] calldata collateralAmounts,
        bool usePermit2
    ) external nonReentrant {
        if (repoTokenAmount == 0) {
            revert ZeroMintAmount();
        }
        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        _validateRepoServicer(_termRepoServicer);

        ITermRepoLocker termRepoLocker = _termRepoServicer.termRepoLocker();

        // @dev Transfer collateral tokens from msg.sender to this contract
        ITermRepoCollateralManager termRepoCollateralManager = ITermRepoCollateralManager(
                _termRepoServicer.termRepoCollateralManager()
            );
        address collateralToken;
        uint256 amount;
        for (uint256 index = 0; index < collateralAmounts.length; ++index) {
            collateralToken = termRepoCollateralManager.collateralTokens(index);
            amount = collateralAmounts[index];

            if (usePermit2) {
                Permit2Lib.PERMIT2.transferFrom(
                    msg.sender,
                    address(this),
                    amount.toUint160(),
                    collateralToken
                );
            } else {
                IERC20(collateralToken).safeTransferFrom(
                    msg.sender,
                    address(this),
                    amount
                );
            }

            IERC20(collateralToken).forceApprove(
                address(termRepoLocker),
                amount
            );
        }

        _termRepoServicer.mintOpenExposure(
            msg.sender,
            repoTokenAmount,
            collateralAmounts
        );

        // Revoke approvals after minting
        for (uint256 index = 0; index < collateralAmounts.length; ++index) {
            collateralToken = termRepoCollateralManager.collateralTokens(index);
            IERC20(collateralToken).forceApprove(address(termRepoLocker), 0);
        }

        Exp memory proRate = div_(
            // solhint-disable-next-line not-rely-on-time
            Exp({
                mantissa: (_termRepoServicer.redemptionTimestamp() -
                    block.timestamp)
            }),
            Exp({mantissa: (360 days)})
        );

        Exp memory protocolShareProRated = mul_(
            Exp({mantissa: _termRepoServicer.servicingFee()}),
            proRate
        );

        uint256 protocolMintTokens = mul_ScalarTruncate(
            protocolShareProRated,
            repoTokenAmount
        );
        uint256 minterTokens = repoTokenAmount - protocolMintTokens;

        IERC20(address(_termRepoServicer.termRepoToken())).safeTransfer(
            msg.sender,
            minterTokens
        );
    }

    // @notice Redeem Term Repo Tokens on behalf of a redeemer
    /// @param termRepoServicer The address of the TermRepoServicer contract
    /// @param redeemer The address of the redeemer
    /// @param amountToRedeem The amount of TermRepoTokens to redeem
    function redeemTermRepoTokens(
        address termRepoServicer,
        address redeemer,
        uint256 amountToRedeem
    ) external nonReentrant {
        _validateRepoServicer(ITermRepoServicer(termRepoServicer));
        ITermRepoServicer(termRepoServicer).redeemTermRepoTokens(
            redeemer,
            amountToRedeem
        );
    }

    // ========================================================================
    // = TermRepoCollateralManager Functions  ================================
    // ========================================================================

    /// @notice Lock collateral on behalf of a borrower
    /// @param termRepoCollateralManager The address of the TermRepoCollateralManager contract
    /// @param collateralToken The address of the collateral token to lock
    /// @param amount The amount of collateral token to lock
    function externalLockCollateral(
        address termRepoCollateralManager,
        address collateralToken,
        uint256 amount,
        bool usePermit2
    ) external nonReentrant {
        ITermRepoCollateralManager collateralManager = ITermRepoCollateralManager(
                termRepoCollateralManager
            );
        _validateCollateralManager(collateralManager);
        ITermRepoLocker termRepoLocker = collateralManager.termRepoLocker();

        // @dev Transfer collateral tokens from msg.sender to this contract
        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                msg.sender,
                address(this),
                amount.toUint160(),
                collateralToken
            );
        } else {
            IERC20(collateralToken).safeTransferFrom(
                msg.sender,
                address(this),
                amount
            );
        }
        IERC20(collateralToken).forceApprove(address(termRepoLocker), amount);

        ITermRepoCollateralManager(termRepoCollateralManager)
            .externalLockCollateral(msg.sender, collateralToken, amount);

        IERC20(collateralToken).forceApprove(address(termRepoLocker), 0);
    }

    /// @notice Unlock collateral on behalf of a borrower
    /// @param termRepoCollateralManager The address of the TermRepoCollateralManager contract
    /// @param collateralToken The address of the collateral token to unlock
    /// @param amount The amount of collateral token to unlock
    function externalUnlockCollateral(
        address termRepoCollateralManager,
        address collateralToken,
        uint256 amount
    ) external nonReentrant {
        _validateCollateralManager(
            ITermRepoCollateralManager(termRepoCollateralManager)
        );
        ITermRepoCollateralManager(termRepoCollateralManager)
            .externalUnlockCollateral(msg.sender, collateralToken, amount);
    }

    // ========================================================================
    // = TermRepoRolloverManager Functions  ==================================
    // ========================================================================

    /// @notice Elect rollover on behalf of a borrower
    /// @param termRepoRolloverManager The address of the TermRepoRolloverManager contract
    /// @param termRepoRolloverElectionSubmission A struct containing borrower rollover instructions
    function electRollover(
        address termRepoRolloverManager,
        TermRepoRolloverElectionSubmission
            calldata termRepoRolloverElectionSubmission
    ) external nonReentrant {
        _validateRolloverManager(
            ITermRepoRolloverManager(termRepoRolloverManager)
        );
        ITermRepoRolloverManager(termRepoRolloverManager).electRollover(
            msg.sender,
            termRepoRolloverElectionSubmission
        );
    }

    /// @notice Cancel rollover on behalf of a borrower
    /// @param termRepoRolloverManager The address of the TermRepoRolloverManager contract
    function cancelRollover(
        address termRepoRolloverManager
    ) external nonReentrant {
        _validateRolloverManager(
            ITermRepoRolloverManager(termRepoRolloverManager)
        );
        ITermRepoRolloverManager(termRepoRolloverManager).cancelRollover(
            msg.sender
        );
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Flash hook that repays a Term repo loan and pulls the freed collateral
    ///         back to the router.
    /// @dev Validates the repo servicer, collateral amount, and purchase token match before
    ///      approving the repo locker and calling `submitRepurchasePayment`. After repayment,
    ///      the approval is reset to zero and collateral is transferred from the borrower
    ///      via Permit2 or `safeTransferFrom` depending on `additionalCalldata`.
    /// @dev `TermRepoServicer.submitRepurchasePayment` releases the borrower's collateral directly
    ///      to the borrower's wallet upon full repayment. Consequently, the pre-repayment check
    ///      (`_validateCollateralAmount`) verifies collateral exists in the collateral manager,
    ///      and the post-repayment pull (`safeTransferFrom` / Permit2) reads from the borrower's
    ///      wallet.
    /// @dev WARNING: This hook should only be used for full repayments where the borrower has no
    ///      unprocessed rollover elections. `TermRepoServicer.submitRepurchasePayment` enforces an
    ///      upper bound of `repurchaseExposureLedger - outstandingRolloverAmount`. If the borrower
    ///      has an active rollover election, the repayment amount from the preview will exceed this
    ///      bound and the transaction will revert.
    /// @param input The action hook input where:
    ///   - `user`: the borrower repaying the loan
    ///   - `inputToken`: the purchase token used for repayment
    ///   - `maxInputAmount`: the repayment amount
    ///   - `outputToken`: the collateral token to retrieve
    ///   - `minOutputAmount`: the collateral amount to pull from the borrower
    ///   - `targetAddress`: the `TermRepoServicer` contract address
    ///   - `additionalCalldata`: ABI-encoded `bool` indicating whether to use Permit2
    function submitRepurchasePaymentHook(
        ActionHookInput calldata input
    ) external onlyFlashLoanContext(input.user) nonReentrant {
        address borrower = input.user;
        address purchaseToken = input.inputToken;
        uint256 repaymentAmount = input.maxInputAmount;
        address collateralToken = input.outputToken;
        uint256 collateralAmount = input.minOutputAmount;
        bool usePermit2 = abi.decode(input.additionalCalldata, (bool));

        ITermRepoServicer repoServicer = ITermRepoServicer(input.targetAddress);
        _validateRepoServicer(repoServicer);
        _validateCollateralAmount(
            repoServicer,
            borrower,
            collateralToken,
            collateralAmount
        );
        if (repoServicer.purchaseToken() != purchaseToken) {
            revert PurchaseTokenMismatch();
        }

        ITermRepoLocker termRepoLocker = repoServicer.termRepoLocker();
        IERC20(purchaseToken).forceApprove(
            address(termRepoLocker),
            repaymentAmount
        );

        repoServicer.submitRepurchasePayment(borrower, repaymentAmount);
        ITermRepoCollateralManager collateralManager = repoServicer
            .termRepoCollateralManager();
        if (
            collateralManager.getCollateralBalance(borrower, collateralToken) >
            0
        ) {
            revert CollateralTransferFailed();
        }

        IERC20(purchaseToken).forceApprove(address(termRepoLocker), 0);

        if (usePermit2) {
            Permit2Lib.PERMIT2.transferFrom(
                borrower,
                address(this),
                collateralAmount.toUint160(),
                address(collateralToken)
            );
        } else {
            IERC20(collateralToken).safeTransferFrom(
                borrower,
                address(this),
                collateralAmount
            );
        }
    }

    // ========================================================================
    // = View Functions  ======================================================
    // ========================================================================

    /// @notice Previews a repurchase payment by querying the borrower's full repurchase
    ///         obligation and the first collateral token from the repo servicer.
    /// @dev Validates the repo servicer, then looks up the purchase token, the borrower's
    ///      outstanding repurchase obligation, and the primary collateral token (index 0)
    ///      from the collateral manager. The output amount is passed through from the input.
    /// @dev WARNING: The returned `expectedInputAmount` reflects the borrower's full repurchase
    ///      obligation. If the borrower has an unprocessed rollover election,
    ///      `TermRepoServicer.submitRepurchasePayment` will enforce a lower maximum
    ///      (`repurchaseExposureLedger - outstandingRolloverAmount`), causing the transaction
    ///      to revert. Cancel any pending rollover elections before using this preview.
    /// @param actionHookInput The action hook input where:
    ///   - `user`: the borrower whose obligation is being previewed
    ///   - `targetAddress`: the `TermRepoServicer` contract address
    ///   - `minOutputAmount`: the expected collateral amount to receive
    /// @return A `PreviewAction` with the purchase token and full repurchase obligation as
    ///         input, the primary collateral token as output, and `isDeterministic` set to true.
    function previewSubmitRepurchasePayment(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        address termRepoServicer = actionHookInput.targetAddress;
        address borrower = actionHookInput.user;

        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        address purchaseToken = _termRepoServicer.purchaseToken();
        uint256 repurchaseObligation = _termRepoServicer
            .getBorrowerRepurchaseObligation(borrower);

        _validateCollateralToken(
            _termRepoServicer,
            actionHookInput.outputToken
        );
        address collateralToken = actionHookInput.outputToken;

        if (purchaseToken == collateralToken) {
            revert InputOutputTokenCollision();
        }

        return
            PreviewAction({
                expectedInputToken: purchaseToken,
                expectedInputAmount: repurchaseObligation,
                expectedOutputToken: collateralToken,
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    // ========================================================================
    // = Internal Validation Functions  ======================================
    // ========================================================================

    function _validateAuctionBidLocker(
        ITermAuctionBidLocker auctionBidLocker
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = auctionBidLocker
            .termAuction()
            .controller();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(auctionBidLocker)) &&
            !termController.isFactoryDeployed(address(auctionBidLocker))
        ) {
            revert InvalidRepoId();
        }
    }

    function _validateAuctionOfferLocker(
        ITermAuctionOfferLocker auctionOfferLocker
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = auctionOfferLocker
            .termAuction()
            .controller();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(auctionOfferLocker)) &&
            !termController.isFactoryDeployed(address(auctionOfferLocker))
        ) {
            revert InvalidRepoId();
        }
    }

    function _validateRepoServicer(ITermRepoServicer servicer) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = servicer.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(servicer)) &&
            !termController.isFactoryDeployed(address(servicer))
        ) {
            revert InvalidRepoId();
        }
    }

    function _validateCollateralManager(
        ITermRepoCollateralManager collateralManager
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = collateralManager.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(collateralManager)) &&
            !termController.isFactoryDeployed(address(collateralManager))
        ) {
            revert InvalidRepoId();
        }
    }

    function _validateRolloverManager(
        ITermRepoRolloverManager rolloverManager
    ) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = rolloverManager.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(rolloverManager)) &&
            !termController.isFactoryDeployed(address(rolloverManager))
        ) {
            revert InvalidRepoId();
        }
    }

    function _validateCollateralAmount(
        ITermRepoServicer repoServicer,
        address borrower,
        address collateralToken,
        uint256 collateralAmount
    ) private view {
        uint256 borrowerCollateralBalance = repoServicer
            .termRepoCollateralManager()
            .getCollateralBalance(borrower, collateralToken);
        if (collateralAmount > borrowerCollateralBalance) {
            revert InsufficientCollateralAmount(
                collateralAmount,
                borrowerCollateralBalance
            );
        }
    }

    function _validateCollateralToken(
        ITermRepoServicer repoServicer,
        address collateralToken
    ) private view {
        if (
            repoServicer
                .termRepoCollateralManager()
                .maintenanceCollateralRatios(collateralToken) == 0
        ) {
            revert InvalidCollateralToken();
        }
    }
}

contracts/facets/TermSettlementWithHooks.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermIntent} from "../interfaces/ITermIntent.sol";
import {ITermRepoServicer} from "../interfaces/ITermRepoServicer.sol";
import {TermLoanIntentFacet} from "./TermLoanIntentFacet.sol";
import {TermRepoToken} from "../TermRepoToken.sol";
import {TermRepoTokenIntentFacet} from "./TermRepoTokenIntentFacet.sol";

import {TermAtomicTxProtection} from "./base/TermAtomicTxProtection.sol";
import {Versionable} from "../lib/Versionable.sol";

import {LibTermStorage, TermStorage} from "../libraries/LibTermStorage.sol";
import {IDiamondLoupe} from "./DiamondLoupeFacet.sol";

import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract TermSettlementWithHooksFacet is
    TermAtomicTxProtection,
    ITermIntent,
    Versionable
{
    using Address for address;

    // ========================================================================
    // = Errors  ==============================================================
    // ========================================================================

    /// @notice Thrown when Swap taker asset is repo token
    error InvalidSwapOrderToFill();

    // ========================================================================
    // = APIs =================================================================
    // ========================================================================

    /// @notice Settles a limit lend order by first executing a specified function to retrieve purchase tokens, then settling the order with the retrieved funds, all within the same transaction
    /// @param order The limit lend order to settle
    /// @param fillAmount The amount to fill on the order
    /// @param collateralAmounts The collateral amounts to post (must be length 1)
    /// @param signature The maker's signature authorizing the order
    /// @param retrieveFundsList A list of functions to call to retrieve funds, including the target facet and any additional calldata. The list length must match the length of collateralAmounts, and each function must retrieve the exact amount of purchase tokens needed for that collateral amount.
    function settleLimitLendWithHook(
        LimitLendOrder memory order,
        uint256 fillAmount,
        uint256[] memory collateralAmounts,
        Signature memory signature,
        RetrieveFundsStruct[] memory retrieveFundsList
    ) external initiateAtomicTxProtection {
        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }

        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        if (
            collateralAmounts.length !=
            servicer.termRepoCollateralManager().numOfAcceptedCollateralTokens()
        ) {
            revert InvalidCollateralAmountsInput();
        }
        if (retrieveFundsList.length != collateralAmounts.length) {
            revert InvalidRetrieveFundsListLength();
        }
        for (uint8 i = 0; i < retrieveFundsList.length; ++i) {
            if (
                collateralAmounts[i] > 0 &&
                !_validateRetrieveFunds(retrieveFundsList[i])
            ) {
                revert RetrieveFundsNotSpecified();
            }
        }
        // enforced full fill to avoid unutilized retrieve funds left in diamond
        uint256 maxFill = _calculateLimitLendFillAmount(order);
        if (maxFill < fillAmount) {
            revert InsufficientRemainingCapacity(maxFill);
        }

        TermStorage storage ts = LibTermStorage.termStorage();
        for (uint8 i = 0; i < collateralAmounts.length; ++i) {
            if (collateralAmounts[i] == 0) {
                continue;
            }

            address collateralToken = servicer
                .termRepoCollateralManager()
                .collateralTokens(i);

            // generate retrieveFundsCalldata
            bytes memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
                retrieveFundsList[i],
                collateralAmounts[i],
                collateralToken,
                msg.sender
            );

            // Set settlement context before executing retrieveFunds
            ts.activeAtomicTxSettlementTaker = msg.sender;
            uint256 collateralTokenBalanceBefore = IERC20(collateralToken)
                .balanceOf(address(this));

            // execute retrieveFundsCalldata
            Address.functionCall(address(this), retrieveFundsCalldata);

            uint256 collateralTokenBalanceAfter = IERC20(collateralToken)
                .balanceOf(address(this));

            if (
                collateralTokenBalanceAfter <
                collateralTokenBalanceBefore + collateralAmounts[i]
            ) {
                revert InsufficientFundsRetrieved();
            }

            // Clear settlement context after execution
            ts.activeAtomicTxSettlementTaker = address(0);
        }

        ts.activeAtomicTxSettlementTaker = msg.sender;
        TermLoanIntentFacet(address(this)).settleLimitLend(
            order,
            msg.sender,
            fillAmount,
            collateralAmounts,
            signature
        );
        ts.activeAtomicTxSettlementTaker = address(0);
    }

    /// @notice Settles a limit borrow order by first executing a specified function to retrieve purchase tokens, then settling the order with the retrieved funds, all within the same transaction
    /// @param order The limit borrow order to settle
    /// @param fillAmount The amount to fill on the order
    /// @param signature The maker's signature authorizing the order
    /// @param retrieveFunds The details of the function to call to retrieve funds, including the target facet and any additional calldata
    function settleLimitBorrowWithHook(
        ITermIntent.LimitBorrowOrder memory order,
        uint256 fillAmount,
        ITermIntent.Signature memory signature,
        ITermIntent.RetrieveFundsStruct memory retrieveFunds
    ) external initiateAtomicTxProtection {
        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }
        if (!_validateRetrieveFunds(retrieveFunds)) {
            revert RetrieveFundsNotSpecified();
        }
        // enforced full fill to avoid unutilized retrieve funds left in diamond
        uint256 maxFill = _calculateLimitBorrowFillAmount(order);
        if (maxFill < fillAmount) {
            revert InsufficientRemainingCapacity(maxFill);
        }

        ITermRepoServicer servicer = ITermRepoServicer(order.repoServicer);
        address purchaseToken = servicer.purchaseToken();
        // generate retrieveFundsCalldata
        bytes memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
            retrieveFunds,
            fillAmount,
            purchaseToken,
            msg.sender
        );

        // Set settlement context before executing retrieveFunds
        TermStorage storage ts = LibTermStorage.termStorage();
        ts.activeAtomicTxSettlementTaker = msg.sender;

        uint256 purchaseTokenBalanceBefore = IERC20(purchaseToken).balanceOf(
            address(this)
        );

        // execute retrieveFundsCalldata
        Address.functionCall(address(this), retrieveFundsCalldata);

        uint256 purchaseTokenBalanceAfter = IERC20(purchaseToken).balanceOf(
            address(this)
        );
        if (
            purchaseTokenBalanceAfter < purchaseTokenBalanceBefore + fillAmount
        ) {
            revert InsufficientFundsRetrieved();
        }
        TermLoanIntentFacet(address(this)).settleLimitBorrow(
            order,
            msg.sender,
            fillAmount,
            signature
        );

        // Clear settlement context after execution
        ts.activeAtomicTxSettlementTaker = address(0);
    }

    /// @notice Swaps a specified amount of purchaseTokens for repo tokens from a repo token swap order, by first executing a specified function to retrieve purchase tokens, then performing the swap with the retrieved funds, all within the same transaction
    /// @dev Only supports swap orders where the maker asset is NOT the purchase token (i.e., taker pays purchase tokens for repo tokens)
    /// @param order The repo token swap order to fill
    /// @param fillAmount The amount to fill on the order
    /// @param signature The maker's signature authorizing the order
    /// @param retrieveFunds The details of the function to call to retrieve funds, including the target facet and any additional calldata
    function swapRepoTokenWithHook(
        ITermIntent.RepoTokenSwapOrder memory order,
        uint256 fillAmount,
        ITermIntent.Signature memory signature,
        ITermIntent.RetrieveFundsStruct memory retrieveFunds
    ) external initiateAtomicTxProtection {
        if (fillAmount == 0) {
            revert InvalidFillAmount();
        }
        if (!_validateRetrieveFunds(retrieveFunds)) {
            revert RetrieveFundsNotSpecified();
        }
        if (order.makerAssetIsPurchaseToken) {
            revert InvalidSwapOrderToFill();
        }

        (, address purchaseToken, , ) = TermRepoToken(order.repoToken).config();
        // enforced full fill to avoid unutilized retrieve funds left in diamond
        uint256 maxFill = _calculateRepoTokenSwapFillAmount(order);
        if (maxFill < fillAmount) {
            revert InsufficientRemainingCapacity(maxFill);
        }
        // generate retrieveFundsCalldata
        bytes memory retrieveFundsCalldata = _generateRetrieveFundsCalldata(
            retrieveFunds,
            fillAmount,
            purchaseToken,
            msg.sender
        );

        // Set settlement context before executing retrieveFunds
        TermStorage storage ts = LibTermStorage.termStorage();
        ts.activeAtomicTxSettlementTaker = msg.sender;

        uint256 purchaseTokenBalanceBefore = IERC20(purchaseToken).balanceOf(
            address(this)
        );

        // execute retrieveFundsCalldata
        Address.functionCall(address(this), retrieveFundsCalldata);

        uint256 purchaseTokenBalanceAfter = IERC20(purchaseToken).balanceOf(
            address(this)
        );
        if (
            purchaseTokenBalanceAfter < purchaseTokenBalanceBefore + fillAmount
        ) {
            revert InsufficientFundsRetrieved();
        }

        TermRepoTokenIntentFacet(address(this)).swapRepoToken(
            order,
            msg.sender,
            fillAmount,
            signature
        );

        // Clear settlement context after execution
        ts.activeAtomicTxSettlementTaker = address(0);
    }

    /// @notice Calculates the actual fill amount for a limit lend order, capped by remaining unfilled capacity
    /// @param order The limit lend order to fill against
    /// @return The actual fill amount (min of requested and remaining capacity)
    /// @custom:reverts NothingToFill if the computed fill amount is zero
    function _calculateLimitLendFillAmount(
        ITermIntent.LimitLendOrder memory order
    ) internal view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        bytes32 orderHash = TermLoanIntentFacet(address(this)).getLendOrderHash(
            order
        );
        ITermIntent.OrderContext memory orderContext = s
            .limitOrderContextMapping[orderHash];
        uint256 maxFill = order.purchaseTokenAmount - orderContext.filledAmount;
        return maxFill;
    }

    /// @notice Calculates the actual fill amount for a limit borrow order, capped by remaining unfilled capacity
    /// @param order The limit borrow order to fill against
    /// @return The actual fill amount (min of requested and remaining capacity)
    /// @custom:reverts NothingToFill if the computed fill amount is zero
    function _calculateLimitBorrowFillAmount(
        ITermIntent.LimitBorrowOrder memory order
    ) internal view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        bytes32 orderHash = TermLoanIntentFacet(address(this))
            .getBorrowOrderHash(order);
        ITermIntent.OrderContext memory orderContext = s
            .limitOrderContextMapping[orderHash];
        uint256 maxFill = order.purchaseTokenAmount - orderContext.filledAmount;
        return maxFill;
    }

    /// @notice Calculates the actual fill amount for a repo token swap order, capped by remaining unfilled capacity
    /// @param order The repo token swap order to fill against
    /// @return The actual fill amount (min of requested and remaining capacity)
    /// @custom:reverts NothingToFill if the computed fill amount is zero
    function _calculateRepoTokenSwapFillAmount(
        ITermIntent.RepoTokenSwapOrder memory order
    ) internal view returns (uint256) {
        TermStorage storage s = LibTermStorage.termStorage();
        bytes32 orderHash = TermRepoTokenIntentFacet(address(this))
            .getSwapOrderHash(order);
        ITermIntent.OrderContext memory orderContext = s
            .swapOrderContextMapping[orderHash];
        uint256 maxFill = order.purchaseTokenAmount - orderContext.filledAmount;
        return maxFill;
    }

    function _validateRetrieveFunds(
        RetrieveFundsStruct memory retrieveFunds
    ) private view returns (bool) {
        if (retrieveFunds.method != bytes4(0)) {
            address facetAddress = IDiamondLoupe(address(this)).facetAddress(
                retrieveFunds.method
            );

            // Confirm that method belongs to specified facet
            if (facetAddress == address(0)) {
                revert InvalidRetrieveFundsFunction();
            }
            return true;
        }
        return false;
    }

    function _generateRetrieveFundsCalldata(
        RetrieveFundsStruct memory retrieveFunds,
        uint256 amountToRetrieve,
        address token,
        address user
    ) private returns (bytes memory) {
        address facetAddress = IDiamondLoupe(address(this)).facetAddress(
            retrieveFunds.method
        );
        bytes4 sig = bytes4(
            keccak256(
                "generateCalldata(bytes4,address,address,address,uint256,bool,bytes)"
            )
        );

        bytes memory encodeCalldataInput = abi.encodeWithSelector(
            sig,
            retrieveFunds.method,
            retrieveFunds.target,
            token,
            user,
            amountToRetrieve,
            false,
            retrieveFunds.additionalCalldata
        );
        bytes memory returnData = Address.functionCall(
            facetAddress,
            encodeCalldataInput
        );
        return abi.decode(returnData, (bytes));
    }
}

contracts/facets/TermStrategyFacet.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {Permit2Lib} from "permit2/src/libraries/Permit2Lib.sol";

import {ITermController} from "../interfaces/ITermController.sol";
import {ITermRepoServicer} from "../interfaces/ITermRepoServicer.sol";
import {ITermRepoLocker} from "../interfaces/ITermRepoLocker.sol";
import {ITermRepoCollateralManager} from "../interfaces/ITermRepoCollateralManager.sol";
import {ITermRepoToken} from "../interfaces/ITermRepoToken.sol";
import {TermAtomicTxProtection} from "./base/TermAtomicTxProtection.sol";
import {TermFlashHookFacet} from "./base/TermFlashHookFacet.sol";
import {TermMulticallProtection} from "./base/TermMulticallProtection.sol";
import {TermMultiContextAuth} from "./base/TermMultiContextAuth.sol";
import {TermStorage, LibTermStorage} from "../libraries/LibTermStorage.sol";
import {ActionHookInput} from "../lib/ActionHookInput.sol";
import {ExponentialNoError} from "../lib/ExponentialNoError.sol";
import {PreviewAction} from "../lib/PreviewAction.sol";
import {Versionable} from "../lib/Versionable.sol";

interface IStrategy {
    struct StrategyState {
        address assetVault;
        address eventEmitter;
        address governorAddress;
        ITermController prevTermController;
        ITermController currTermController;
        IDiscountRateAdapter discountRateAdapter;
        uint256 timeToMaturityThreshold;
        uint256 requiredReserveRatio;
        uint256 discountRateMarkup;
        uint256 repoTokenConcentrationLimit;
    }

    function asset() external view returns (address);
    function sellRepoToken(address repoToken, uint256 amount) external;
    function strategyState() external view returns (StrategyState memory);
}

interface IDiscountRateAdapter {
    function getDiscountRate(address repoToken) external view returns (uint256);
    function repoRedemptionHaircut(
        address repoToken
    ) external view returns (uint256);
}

/// @author TermLabs
/// @title Term Strategy Facet
/// @notice This facet provides functionality to interact with strategy contracts for repo token operations
/// @dev This facet allows users to sell repo tokens through approved strategy contracts with automatic asset handling
contract TermStrategyFacet is
    ReentrancyGuard,
    TermFlashHookFacet,
    TermAtomicTxProtection,
    TermMulticallProtection,
    TermMultiContextAuth,
    ExponentialNoError,
    Versionable
{
    using SafeERC20 for IERC20;
    using SafeCast for uint256;

    error AfterMaturity();
    error InvalidCollateralToken();
    error InvalidRepoId();
    error InvalidStrategy();
    error InvalidTermController();
    error NoProceedsReceived();
    error NotEnoughProceedsReceived();
    error PurchaseTokenMismatch();
    error RepoTokensNotFullyConsumed();
    error RepoRedemptionHaircutNotSupported();

    // ========================================================================
    // = Deploy ===============================================================
    // ========================================================================

    constructor() {
        previewMapping[this.mintAndSellRepoTokenHook.selector] = this
            .previewMintAndSellRepoToken
            .selector;
    }

    // ========================================================================
    // = Strategy Functions ===================================================
    // ========================================================================

    /// @notice Sell repo tokens through a strategy contract and receive proceeds
    /// @param strategy The strategy contract to execute the sale through
    /// @param repoToken The address of the repo token to sell
    /// @param repoTokenAmount The amount of repo tokens to sell
    /// @return proceeds The amount of underlying assets received from the sale
    function sellRepoToken(
        IStrategy strategy,
        address repoToken,
        uint256 repoTokenAmount
    ) external nonReentrant returns (uint256 proceeds) {
        IStrategy.StrategyState memory strategyState = strategy.strategyState();
        _validateStrategy(strategy, strategyState);
        address asset = strategy.asset();
        uint256 preProceedsBalance = IERC20(asset).balanceOf(address(this));

        // Transfer repo tokens from user to this contract
        IERC20(repoToken).safeTransferFrom(
            msg.sender,
            address(this),
            repoTokenAmount
        );

        // Check repo token balance before strategy call
        uint256 repoTokenBalanceBefore = IERC20(repoToken).balanceOf(
            address(this)
        );

        IERC20(repoToken).forceApprove(address(strategy), repoTokenAmount);

        // Call the strategy's sellRepoTokenfunction
        strategy.sellRepoToken(repoToken, repoTokenAmount);

        IERC20(repoToken).forceApprove(address(strategy), 0);

        // Check repo token balance after strategy call
        uint256 repoTokenBalanceAfter = IERC20(repoToken).balanceOf(
            address(this)
        );

        // Ensure exact amount was consumed
        if (repoTokenBalanceBefore - repoTokenBalanceAfter != repoTokenAmount) {
            revert RepoTokensNotFullyConsumed();
        }

        uint256 postProceedsBalance = IERC20(asset).balanceOf(address(this));

        // @dev Ensure that proceeds were received and prevents repo token thefts
        if (postProceedsBalance <= preProceedsBalance) {
            revert NoProceedsReceived();
        }
        proceeds = postProceedsBalance - preProceedsBalance;

        IERC20(asset).safeTransfer(msg.sender, proceeds);
    }

    /// @notice Mints Term Repo Tokens and sells them through a strategy in a single transaction
    /// @dev This function enables atomic minting and selling of repo tokens, useful for immediate liquidity provision.
    ///      The minted tokens are sent to the strategy for selling.
    /// @param strategy The strategy contract that will handle the sale of the minted repo tokens
    /// @param termRepoServicer The address of the TermRepoServicer contract for the specific Term
    /// @param borrowAmount The amount of purchase token proceeds the borrower expects to receive from the sale
    /// @param collateralAmounts Array of collateral amounts corresponding to each accepted collateral token in the Term
    /// @param usePermit2 If true, uses Permit2 for token transfers; if false, uses standard ERC20 transferFrom
    function mintAndSellRepoToken(
        IStrategy strategy,
        address termRepoServicer,
        uint256 borrowAmount,
        uint256[] calldata collateralAmounts,
        bool usePermit2
    )
        external
        initiateAtomicTxProtection
        nonReentrant
        returns (uint256 proceeds)
    {
        address borrower = msg.sender;
        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );

        ITermRepoCollateralManager termRepoCollateralManager = ITermRepoCollateralManager(
                _termRepoServicer.termRepoCollateralManager()
            );

        address collateralToken;
        uint256 amount;
        uint8 index;

        // @dev Transfer collateral tokens from msg.sender to this contract
        for (index = 0; index < collateralAmounts.length; ++index) {
            collateralToken = termRepoCollateralManager.collateralTokens(index);
            amount = collateralAmounts[index];
            if (usePermit2) {
                Permit2Lib.PERMIT2.transferFrom(
                    borrower,
                    address(this),
                    amount.toUint160(),
                    collateralToken
                );
            } else {
                IERC20(collateralToken).safeTransferFrom(
                    borrower,
                    address(this),
                    amount
                );
            }
        }

        return
            _mintAndSellRepoTokenInternal(
                strategy,
                termRepoServicer,
                borrower,
                borrowAmount,
                collateralAmounts,
                true
            );
    }

    // ========================================================================
    // = Flash Hook Actions  ==================================================
    // ========================================================================

    /// @notice Flash hook that mints repo tokens using the borrower's collateral and sells
    ///         them into a strategy for purchase token proceeds.
    /// @dev Reads the repo servicer from `targetAddress` and decodes the strategy address
    ///      from `additionalCalldata`. Builds the collateral amounts array, validates the
    ///      purchase token matches the servicer's expected token, then delegates to
    ///      `_mintAndSellRepoTokenInternal` to lock collateral, mint repo tokens, and sell
    ///      them into the strategy.
    /// @param input The action hook input where:
    ///   - `user`: the borrower minting and selling repo tokens
    ///   - `inputToken`: the collateral token to lock
    ///   - `maxInputAmount`: the collateral amount to lock
    ///   - `outputToken`: the purchase token expected as proceeds
    ///   - `minOutputAmount`: the borrow/mint amount
    ///   - `targetAddress`: the TermRepoServicer contract address
    ///   - `additionalCalldata`: ABI-encoded `(address strategy)`
    /// @return proceeds The purchase token amount received from selling the minted repo tokens.
    function mintAndSellRepoTokenHook(
        ActionHookInput calldata input
    )
        external
        onlyFlashLoanContext(input.user)
        nonReentrant
        returns (uint256 proceeds)
    {
        address borrower = input.user;
        address collateralToken = input.inputToken;
        uint256 collateralAmount = input.maxInputAmount;
        address purchaseToken = input.outputToken;
        uint256 borrowAmount = input.minOutputAmount;
        address termRepoServicer = input.targetAddress;
        address strategyAddress = abi.decode(
            input.additionalCalldata,
            (address)
        );

        IStrategy strategy = IStrategy(strategyAddress);

        uint256[] memory collateralAmounts = _buildCollateralAmountsArray(
            termRepoServicer,
            collateralToken,
            collateralAmount
        );

        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        if (_termRepoServicer.purchaseToken() != purchaseToken) {
            revert PurchaseTokenMismatch();
        }

        return
            _mintAndSellRepoTokenInternal(
                strategy,
                termRepoServicer,
                borrower,
                borrowAmount,
                collateralAmounts,
                false
            );
    }

    // ========================================================================
    // = Utility Functions  ===================================================
    // ========================================================================

    /**
     * @notice Previews a mint-and-sell repo token action by returning the expected input/output tokens and amounts
     * @dev Validates that the repo servicer's purchase token matches the strategy's underlying asset.
     *      The strategy address is decoded from the hook input's additionalCalldata.
     * @param actionHookInput The action hook input containing the target repo servicer, encoded strategy address, and token amounts
     * @return A PreviewAction struct with the expected tokens, amounts, and determinism flag
     */
    function previewMintAndSellRepoToken(
        ActionHookInput calldata actionHookInput
    ) external view returns (PreviewAction memory) {
        address termRepoServicerAddr = actionHookInput.targetAddress;
        address strategyAddress = abi.decode(
            actionHookInput.additionalCalldata,
            (address)
        );

        ITermRepoServicer termRepoServicer = ITermRepoServicer(
            termRepoServicerAddr
        );
        IStrategy strategy = IStrategy(strategyAddress);
        if (termRepoServicer.purchaseToken() != strategy.asset()) {
            revert PurchaseTokenMismatch();
        }

        return
            PreviewAction({
                expectedInputToken: actionHookInput.inputToken,
                expectedInputAmount: actionHookInput.maxInputAmount,
                expectedOutputToken: strategy.asset(),
                expectedOutputAmount: actionHookInput.minOutputAmount,
                isDeterministic: true
            });
    }

    function _mintAndSellRepoTokenInternal(
        IStrategy strategy,
        address termRepoServicer,
        address borrower,
        uint256 borrowAmount,
        uint256[] memory collateralAmounts,
        bool payoutToUser
    ) internal returns (uint256 proceeds) {
        IStrategy.StrategyState memory strategyState = strategy.strategyState();
        _validateStrategy(strategy, strategyState);
        ITermRepoServicer _termRepoServicer = ITermRepoServicer(
            termRepoServicer
        );
        _validateRepoServicer(_termRepoServicer);
        if (_termRepoServicer.purchaseToken() != strategy.asset()) {
            revert PurchaseTokenMismatch();
        }
        ITermRepoLocker termRepoLocker = _termRepoServicer.termRepoLocker();

        ITermRepoCollateralManager termRepoCollateralManager = ITermRepoCollateralManager(
                _termRepoServicer.termRepoCollateralManager()
            );

        ITermRepoToken termRepoTokenMinted = _termRepoServicer.termRepoToken();

        // Block repo tokens with redemption haircuts — our pricing doesn't account for them
        if (
            strategyState.discountRateAdapter.repoRedemptionHaircut(
                address(termRepoTokenMinted)
            ) != 0
        ) {
            revert RepoRedemptionHaircutNotSupported();
        }

        address collateralToken;
        uint256 amount;
        uint8 index;

        for (index = 0; index < collateralAmounts.length; ++index) {
            collateralToken = termRepoCollateralManager.collateralTokens(index);
            amount = collateralAmounts[index];
            if (amount > 0) {
                IERC20(collateralToken).forceApprove(
                    address(termRepoLocker),
                    amount
                );
            }
        }

        uint256 discountRate = strategyState
            .discountRateAdapter
            .getDiscountRate(address(termRepoTokenMinted));
        uint256 discountRateMarkup = strategyState.discountRateMarkup;

        Exp memory dayCountFraction = div_(
            // solhint-disable-next-line not-rely-on-time
            Exp({
                mantissa: (_termRepoServicer.redemptionTimestamp() -
                    block.timestamp)
            }),
            Exp({mantissa: (360 days)})
        );

        Exp memory repurchaseFactor = add_(
            Exp({mantissa: expScale}),
            mul_(
                dayCountFraction,
                Exp({mantissa: discountRate + discountRateMarkup})
            )
        );

        uint256 redemptionValue = termRepoTokenMinted.redemptionValue();

        // Back propagate amount of repo tokens to sell from borrowAmount: (borrowAmount * repurchaseFactor) / redemptionValue
        uint256 minAmountOfRepoTokensToSell = truncate(
            div_(
                mul_(
                    Exp({mantissa: borrowAmount * expScale}),
                    repurchaseFactor
                ),
                Exp({mantissa: redemptionValue})
            )
        );

        // Forward-verify: ensure the strategy would pay at least borrowAmount
        uint256 estimatedProceeds = truncate(
            div_(
                Exp({
                    mantissa: mul_(minAmountOfRepoTokensToSell, redemptionValue)
                }),
                repurchaseFactor
            )
        );

        /// @dev This off-by-one adjustment is necessary due to precision loss in division operations.
        // Round up minAmountOfRepoTokensToSell if estimated proceeds are less than borrow amount to ensure we meet the target after the discount
        if (estimatedProceeds < borrowAmount) {
            minAmountOfRepoTokensToSell += 1;
        }

        // Calculate pro-rated servicing fee: servicingFee * (timeToMaturity / 360 days)
        Exp memory proRatedServicingFee = mul_(
            dayCountFraction,
            Exp({mantissa: _termRepoServicer.servicingFee()})
        );

        uint256 amountOfRepoTokensToMint = truncate(
            div_(
                Exp({mantissa: minAmountOfRepoTokensToSell * expScale}),
                sub_(Exp({mantissa: expScale}), proRatedServicingFee)
            )
        );

        uint256 proratedFee = mul_ScalarTruncate(
            proRatedServicingFee,
            amountOfRepoTokensToMint
        );

        uint256 repoTokenBalanceBeforeMint = termRepoTokenMinted.balanceOf(
            address(this)
        );

        _termRepoServicer.mintOpenExposure(
            borrower,
            amountOfRepoTokensToMint,
            collateralAmounts
        );

        uint256 repoTokenBalanceAfterMint = termRepoTokenMinted.balanceOf(
            address(this)
        );
        uint256 actualMintedAmount = repoTokenBalanceAfterMint -
            repoTokenBalanceBeforeMint;

        for (index = 0; index < collateralAmounts.length; ++index) {
            collateralToken = termRepoCollateralManager.collateralTokens(index);
            IERC20(collateralToken).forceApprove(address(termRepoLocker), 0);
        }

        address asset = strategy.asset();
        uint256 preProceedsBalance = IERC20(asset).balanceOf(address(this));

        termRepoTokenMinted.approve(address(strategy), actualMintedAmount);

        // Call the strategy's sellRepoTokenfunction
        strategy.sellRepoToken(
            address(termRepoTokenMinted),
            actualMintedAmount
        );

        termRepoTokenMinted.approve(address(strategy), 0);

        // Check repo token balance after strategy call
        uint256 repoTokenBalanceAfterSellRepoToken = termRepoTokenMinted
            .balanceOf(address(this));

        // Ensure exact amount was consumed
        if (
            repoTokenBalanceAfterMint - repoTokenBalanceAfterSellRepoToken !=
            actualMintedAmount
        ) {
            revert RepoTokensNotFullyConsumed();
        }

        uint256 postProceedsBalance = IERC20(asset).balanceOf(address(this));

        // @dev Ensure that proceeds were received and prevents repo token thefts
        if (postProceedsBalance <= preProceedsBalance) {
            revert NoProceedsReceived();
        }
        proceeds = postProceedsBalance - preProceedsBalance;
        if (proceeds < borrowAmount) {
            revert NotEnoughProceedsReceived();
        }
        if (payoutToUser) {
            IERC20(asset).safeTransfer(borrower, proceeds);
        }

        _emitIntentFilled(
            bytes32(0), // orderHash is not applicable for this flow
            _termRepoServicer,
            address(strategy),
            borrower,
            discountRate + discountRateMarkup,
            proceeds,
            actualMintedAmount,
            proratedFee,
            _termRepoServicer.termController().getTreasuryAddress(),
            0, // originalOrderAmount is not applicable for this flow
            0, // expiry is not applicable for this flow
            0 // salt is not applicable for this flow
        );
    }

    function _validateStrategy(
        IStrategy strategy,
        IStrategy.StrategyState memory strategyState
    ) private view {
        ITermController controller = strategyState.currTermController;
        TermStorage storage s = LibTermStorage.termStorage();
        if (!s.approvedTermControllers[address(controller)]) {
            revert InvalidTermController();
        }
        if (!controller.isTermApproved(address(strategy))) {
            revert InvalidStrategy();
        }
    }

    function _validateRepoServicer(ITermRepoServicer servicer) private view {
        TermStorage storage s = LibTermStorage.termStorage();
        ITermController termController = servicer.termController();
        if (!s.approvedTermControllers[address(termController)]) {
            revert InvalidTermController();
        }
        if (
            !termController.isTermDeployed(address(servicer)) &&
            !termController.isFactoryDeployed(address(servicer))
        ) {
            revert InvalidRepoId();
        }

        if (block.timestamp > servicer.maturityTimestamp()) {
            revert AfterMaturity();
        }
    }

    function _buildCollateralAmountsArray(
        address servicer,
        address collateralToken,
        uint256 collateralAmount
    ) internal view returns (uint256[] memory) {
        ITermRepoServicer termRepoServicer = ITermRepoServicer(servicer);
        ITermRepoCollateralManager collateralManager = termRepoServicer
            .termRepoCollateralManager();
        uint256 numCollateralTokens = collateralManager
            .numOfAcceptedCollateralTokens();
        uint256[] memory collateralAmounts = new uint256[](numCollateralTokens);

        bool collateralSupported;
        for (uint256 i = 0; i < numCollateralTokens; i++) {
            if (collateralManager.collateralTokens(i) == collateralToken) {
                collateralAmounts[i] = collateralAmount;
                collateralSupported = true;
                break;
            }
        }

        if (!collateralSupported) {
            revert InvalidCollateralToken();
        }

        return collateralAmounts;
    }

    function _emitIntentFilled(
        bytes32 orderHash,
        ITermRepoServicer servicer,
        address maker,
        address taker,
        uint256 offerRate,
        uint256 fillAmount,
        uint256 termRepoTokenFillAmount,
        uint256 proratedBorrowFee,
        address feeRecipient,
        uint256 originalOrderAmount,
        uint256 expiry,
        uint256 salt
    ) private {
        TermStorage storage s = LibTermStorage.termStorage();
        address purchaseToken = servicer.purchaseToken();
        s.emitter.emitIntentFilled(
            orderHash,
            servicer.termRepoId(),
            purchaseToken,
            maker,
            taker,
            purchaseToken,
            address(servicer.termRepoToken()),
            offerRate,
            fillAmount,
            termRepoTokenFillAmount,
            proratedBorrowFee,
            feeRecipient,
            originalOrderAmount,
            expiry,
            salt
        );
    }
}

