//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermEventEmitter} from "../interfaces/ITermEventEmitter.sol";
import {ITermIntent} from "../interfaces/ITermIntent.sol";

struct TermStorage {
    // initialization flag for TermIntent
    bool termIntentInitialized;
    // address that initiated multicall
    address multicallInitiator;
    // address of the maker in active settlement context (for retrieveFunds authorization)
    address activeSettlementMaker;
    // address of the atomic transaction sender
    address atomicTxInitiatior;
    // address of the taker in active atomic transaction settlement context
    address activeAtomicTxSettlementTaker;
    // EIP712 domain separator for signing limit orders
    bytes32 eip712DomainSeparator;
    // Global term controller whitelist mapping
    mapping(address => bool) approvedTermControllers;
    // List of approved term controllers for enumeration
    address[] approvedTermControllerList;
    // Approved Fee Recipient Mapping
    mapping(address => bool) approvedFeeRecipients;
    // Global term event emitter
    ITermEventEmitter emitter;
    /// Maps order hash to order execution status and filled amount
    mapping(bytes32 => ITermIntent.OrderContext) limitOrderContextMapping;
    /// Maps order hash to maker address for contract wallets that pre-authorize orders
    mapping(bytes32 => address) preSignedLimitOrders;
    /// Maps order hash to order execution status and filled amount
    mapping(bytes32 => ITermIntent.OrderContext) swapOrderContextMapping;
    /// Maps order hash to maker address for contract wallets that pre-authorize orders
    mapping(bytes32 => address) preSignedSwapOrders;
    /// Maps maker => makerToken => takerToken to minimum valid salt for bulk order cancellation
    mapping(address => mapping(address => mapping(address => uint256))) limitOrderMakerTokenPairMinSalt;
    /// Maps maker => makerToken => takerToken to minimum valid salt for bulk swap order cancellation
    mapping(address => mapping(address => mapping(address => uint256))) swapOrderMakerTokenPairMinSalt;
}

struct TermERC4626VaultManagement {
    mapping(address => mapping(address => bool)) userApprovedERC4626Vaults;
}

struct TermFlashLoanContext {
    // address of the borrower in active flashloan context
    address activeFlashLoanBorrower;
}

library LibTermStorage {
    bytes32 internal constant TERM_STORAGE_POSITION = keccak256("term.storage");
    bytes32 internal constant TERM_ERC4626_VAULT_MANAGEMENT_POSITION =
        keccak256("term.erc4626.vault.management");
    bytes32 internal constant TERM_FLASH_LOAN_CONTEXT_POSITION =
        keccak256("term.flash.loan.context");
    address internal constant UNSET_INITIATOR = address(0);

    function termStorage() internal pure returns (TermStorage storage ts) {
        bytes32 position = TERM_STORAGE_POSITION;
        assembly {
            ts.slot := position
        }
    }

    function termERC4626VaultManagement()
        internal
        pure
        returns (TermERC4626VaultManagement storage tev)
    {
        bytes32 position = TERM_ERC4626_VAULT_MANAGEMENT_POSITION;
        assembly {
            tev.slot := position
        }
    }

    function termFlashLoanContext()
        internal
        pure
        returns (TermFlashLoanContext storage tfc)
    {
        bytes32 position = TERM_FLASH_LOAN_CONTEXT_POSITION;
        assembly {
            tfc.slot := position
        }
    }

    // Validation function that can be called from modifiers
    function requireMulticallInitiator() internal view {
        TermStorage storage ts = termStorage();
        address initiator = ts.multicallInitiator;
        require(initiator != UNSET_INITIATOR, "uninitialized");
        require(msg.sender == initiator, "unauthorized");
    }
}

contracts/TermAuction.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermAuctionBidLocker} from "./interfaces/ITermAuctionBidLocker.sol";
import {ITermAuctionErrors} from "./interfaces/ITermAuctionErrors.sol";
import {ITermAuctionOfferLocker} from "./interfaces/ITermAuctionOfferLocker.sol";
import {ITermController} from "./interfaces/ITermController.sol";
import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {ITermRepoCollateralManager} from "./interfaces/ITermRepoCollateralManager.sol";
import {ITermRepoRolloverManager} from "./interfaces/ITermRepoRolloverManager.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {CompleteAuctionInput} from "./lib/CompleteAuctionInput.sol";
import {TermContractsPausable} from "./lib/TermContractsPausable.sol";
import {ExponentialNoError} from "./lib/ExponentialNoError.sol";
import {TermAuctionBid} from "./lib/TermAuctionBid.sol";
import {TermAuctionOffer} from "./lib/TermAuctionOffer.sol";
import {TermAuctionRevealedBid} from "./lib/TermAuctionRevealedBid.sol";
import {TermAuctionRevealedOffer} from "./lib/TermAuctionRevealedOffer.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Auction
/// @notice This contract calculates a clearing price in a blind double auction and manages auction clearing and settlement
/// @dev This contract belongs to the Term Auction group of contracts and is specific to a Term Repo deployment
contract TermAuction is
    ITermAuctionErrors,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    ExponentialNoError,
    TermContractsPausable,
    Versionable
{
    // ========================================================================
    // = Structs  =============================================================
    // ========================================================================
    /// State used during the `calculateClearingPrice` function
    /// @dev Used to reduce the number of stack variables
    struct ClearingPriceState {
        // Variables describing current loop iteration
        uint256 offerPrice; // p^o_i
        uint256 offerIndex; // idxo(p^o_i)
        uint256 bidIndex; // idxb(p^o_i)
        uint256 cumSumOffers; // cso(p^o_i)
        uint256 cumSumBids; // csb(p^o_i)
        uint256 maxClearingVolume; // maxcv_i
        // Variables describing next loop iteration
        uint256 nextOfferIndex;
        uint256 nextBidIndex;
        uint256 nextCumSumOffers;
        uint256 nextCumSumBids;
        uint256 nextOfferPrice;
        uint256 nextMaxClearingVolume;
        // Auxiliary variables
        bool minCumSumCorrection; // Minimisation correction indicator
        uint256 nextBidPrice; // Next bid price in minimisation
        // Principal quantities of interest
        uint256 clearingPrice; // p_c
    }

    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================
    uint256 public constant THREESIXTY_DAYCOUNT_SECONDS = 360 days;

    // ========================================================================
    // = Access Roles  ========================================================
    // ========================================================================
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    // Auction configuration.
    bytes32 public termRepoId;
    bytes32 public termAuctionId;
    uint256 public auctionEndTime;
    uint256 public dayCountFractionMantissa;
    ITermRepoServicer public termRepoServicer;
    ITermAuctionBidLocker public termAuctionBidLocker;
    ITermAuctionOfferLocker public termAuctionOfferLocker;
    IERC20Metadata public purchaseToken;
    ITermEventEmitter internal emitter;
    ITermController public controller;

    // Completed auction state
    uint256 public clearingPrice;
    uint256 public clearingPricePostProcessingOffset;
    bool public auctionCompleted;
    bool public auctionCancelledForWithdrawal;
    bool public completeAuctionPaused;
    bool internal termContractPaired;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================

    /// @notice This only runs if the auction is closed (after auction end time)
    /// @dev This uses the block timestamp to determine if the auction is closed
    modifier onlyWhileAuctionClosed() {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp <= auctionEndTime) {
            revert AuctionNotClosed();
        }
        _;
    }

    modifier whenCompleteAuctionNotPaused() {
        if (completeAuctionPaused) {
            revert CompleteAuctionPaused();
        }
        _;
    }

    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    // ========================================================================
    // = Deploy (https://docs.openzeppelin.com/contracts/4.x/upgradeable) =
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// Initializes the contract
    /// @dev See: https://docs.openzeppelin.com/contracts/4.x/upgradeable
    function initialize(
        string calldata termRepoId_,
        string calldata auctionId_,
        uint256 auctionEndTime_,
        uint256 termStart_,
        uint256 redemptionTimestamp_,
        IERC20Metadata purchaseToken_,
        address termAuctionInitializer_,
        uint256 clearingPricePostProcessingOffset_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();
        ReentrancyGuardUpgradeable.__ReentrancyGuard_init();

        _grantRole(INITIALIZER_ROLE, termAuctionInitializer_);

        termRepoId = keccak256(abi.encodePacked(termRepoId_));
        termAuctionId = keccak256(abi.encodePacked(auctionId_));

        auctionEndTime = auctionEndTime_;
        dayCountFractionMantissa =
            ((redemptionTimestamp_ - termStart_) * expScale) /
            THREESIXTY_DAYCOUNT_SECONDS;
        purchaseToken = purchaseToken_;
        auctionCompleted = false;
        termContractPaired = false;
        auctionCancelledForWithdrawal = false;
        clearingPricePostProcessingOffset = clearingPricePostProcessingOffset_;
    }

    function pairTermContracts(
        ITermEventEmitter emitter_,
        ITermController controller_,
        ITermRepoServicer termRepoServicer_,
        ITermAuctionBidLocker termAuctionBidLocker_,
        ITermAuctionOfferLocker termAuctionOfferLocker_,
        address devopsMultisigAddress_,
        address adminWallet_,
        address deployerWallet_,
        string calldata version_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        require(deployerWallet_ != address(0), "Zero address deployer wallet");
        emitter = emitter_;
        controller = controller_;

        termRepoServicer = termRepoServicer_;
        termAuctionBidLocker = termAuctionBidLocker_;
        termAuctionOfferLocker = termAuctionOfferLocker_;

        _grantRole(DEVOPS_ROLE, devopsMultisigAddress_);
        _grantRole(ADMIN_ROLE, adminWallet_);

        emitter.emitTermAuctionInitialized(
            termRepoId,
            termAuctionId,
            address(this),
            auctionEndTime,
            deployerWallet_,
            version_
        );
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @notice Calculates an auction's clearing price, assigns bids/offers, and returns unassigned funds
    /// @param completeAuctionInput A struct containing all revealed and unrevealed bids and offers and expired rollover bids
    function completeAuction(
        CompleteAuctionInput calldata completeAuctionInput
    )
        external
        onlyWhileAuctionClosed
        whenCompleteAuctionNotPaused
        whileTermContractsNotPaused(controller)
    {
        if (auctionCompleted) {
            revert AuctionAlreadyCompleted();
        }
        if (auctionCancelledForWithdrawal) {
            revert AuctionCancelledForWithdrawal();
        }
        auctionCompleted = true;

        // Sort bids/offers by price. Orders right on the price
        // edge will be partially filled.
        if (!hasRole(ADMIN_ROLE, msg.sender)) {
            if (
                completeAuctionInput.unrevealedBidSubmissions.length > 0 ||
                completeAuctionInput.unrevealedOfferSubmissions.length > 0
            ) {
                revert InvalidParameters(
                    "All tender prices must be revealed for auction to be complete"
                );
            }
        }

        (
            TermAuctionRevealedBid[] memory sortedBids,
            TermAuctionBid[] memory unrevealedBids
        ) = termAuctionBidLocker.getAllBids(
                completeAuctionInput.revealedBidSubmissions,
                completeAuctionInput.expiredRolloverBids,
                completeAuctionInput.unrevealedBidSubmissions
            );
        (
            TermAuctionRevealedOffer[] memory sortedOffers,
            TermAuctionOffer[] memory unrevealedOffers
        ) = termAuctionOfferLocker.getAllOffers(
                completeAuctionInput.revealedOfferSubmissions,
                completeAuctionInput.unrevealedOfferSubmissions
            );

        // Calculate a clearing price only if both bids and offers exist and market intersects
        if (
            sortedBids.length > 0 &&
            sortedOffers.length > 0 &&
            sortedBids[sortedBids.length - 1].bidPriceRevealed >=
            sortedOffers[0].offerPriceRevealed
        ) {
            (
                ,
                // uint256 clearingPrice_
                uint256 maxAssignable
            ) = _calculateAndStoreClearingPrice(sortedBids, sortedOffers);

            uint256 purchaseTokenDecimals = purchaseToken.decimals();

            // Process revealed bids/offers
            uint256 totalAssignedBids = _assignBids(
                sortedBids,
                maxAssignable,
                purchaseTokenDecimals
            );
            uint256 totalAssignedOffers = _assignOffers(
                sortedOffers,
                maxAssignable,
                purchaseTokenDecimals
            );

            emitter.emitAuctionCompleted(
                termAuctionId, // solhint-disable-next-line not-rely-on-time
                block.timestamp,
                block.number,
                totalAssignedBids,
                totalAssignedOffers,
                clearingPrice
            );

            controller.recordAuctionResult(
                termRepoId,
                termAuctionId,
                clearingPrice
            );
        } else {
            // Return sorted bid funds.
            for (uint256 i = 0; i < sortedBids.length; ++i) {
                if (sortedBids[i].isRollover) {
                    _markRolloverAsProcessed(
                        sortedBids[i].rolloverPairOffTermRepoServicer,
                        sortedBids[i].bidder
                    );
                } else {
                    termAuctionBidLocker.auctionUnlockBid(
                        sortedBids[i].id,
                        sortedBids[i].bidder,
                        sortedBids[i].collateralTokens,
                        sortedBids[i].collateralAmounts
                    );
                }
            }
            // Return sorted offer funds.
            for (uint256 i = 0; i < sortedOffers.length; ++i) {
                termAuctionOfferLocker.unlockOfferPartial(
                    sortedOffers[i].id,
                    sortedOffers[i].offeror,
                    sortedOffers[i].amount
                );
            }

            if (
                sortedBids.length > 0 &&
                sortedOffers.length > 0 &&
                sortedBids[sortedBids.length - 1].bidPriceRevealed <
                sortedOffers[0].offerPriceRevealed
            ) {
                emitter.emitAuctionCancelled(termAuctionId, true, false);
            } else {
                emitter.emitAuctionCancelled(termAuctionId, false, false);
            }
        }

        // Return unrevealed bid funds.
        for (uint256 i = 0; i < unrevealedBids.length; ++i) {
            if (unrevealedBids[i].isRollover) {
                _markRolloverAsProcessed(
                    unrevealedBids[i].rolloverPairOffTermRepoServicer,
                    unrevealedBids[i].bidder
                );
            } else {
                termAuctionBidLocker.auctionUnlockBid(
                    unrevealedBids[i].id,
                    unrevealedBids[i].bidder,
                    unrevealedBids[i].collateralTokens,
                    unrevealedBids[i].collateralAmounts
                );
            }
        }
        // Return unrevealed offer funds.
        for (uint256 i = 0; i < unrevealedOffers.length; ++i) {
            termAuctionOfferLocker.unlockOfferPartial(
                unrevealedOffers[i].id,
                unrevealedOffers[i].offeror,
                unrevealedOffers[i].amount
            );
        }

        assert(termRepoServicer.isTermRepoBalanced());
    }

    // ========================================================================
    // = Admin ================================================================
    // ========================================================================

    /// @notice Cancels an auction and returns all funds to bidders and fulfillBiders
    /// @param completeAuctionInput A struct containing all revealed and unrevealed bids and offers and expired rollover bids
    function cancelAuction(
        CompleteAuctionInput calldata completeAuctionInput
    ) public onlyWhileAuctionClosed onlyRole(ADMIN_ROLE) {
        // Sort bids/offers by price. Orders right on the price
        // edge will be partially filled.
        (
            TermAuctionRevealedBid[] memory sortedBids,
            TermAuctionBid[] memory unrevealedBids
        ) = termAuctionBidLocker.getAllBids(
                completeAuctionInput.revealedBidSubmissions,
                completeAuctionInput.expiredRolloverBids,
                completeAuctionInput.unrevealedBidSubmissions
            );
        (
            TermAuctionRevealedOffer[] memory sortedOffers,
            TermAuctionOffer[] memory unrevealedOffers
        ) = termAuctionOfferLocker.getAllOffers(
                completeAuctionInput.revealedOfferSubmissions,
                completeAuctionInput.unrevealedOfferSubmissions
            );

        // Return revealed bid funds.
        uint256 i = 0;
        for (i = 0; i < sortedBids.length; ++i) {
            if (sortedBids[i].isRollover) {
                _markRolloverAsProcessed(
                    sortedBids[i].rolloverPairOffTermRepoServicer,
                    sortedBids[i].bidder
                );
            } else {
                termAuctionBidLocker.auctionUnlockBid(
                    sortedBids[i].id,
                    sortedBids[i].bidder,
                    sortedBids[i].collateralTokens,
                    sortedBids[i].collateralAmounts
                );
            }
        }
        // Return revealed offer funds.
        for (i = 0; i < sortedOffers.length; ++i) {
            termAuctionOfferLocker.unlockOfferPartial(
                sortedOffers[i].id,
                sortedOffers[i].offeror,
                sortedOffers[i].amount
            );
        }
        // Return unrevealed bid funds.
        for (i = 0; i < unrevealedBids.length; ++i) {
            if (unrevealedBids[i].isRollover) {
                _markRolloverAsProcessed(
                    unrevealedBids[i].rolloverPairOffTermRepoServicer,
                    unrevealedBids[i].bidder
                );
            } else {
                termAuctionBidLocker.auctionUnlockBid(
                    unrevealedBids[i].id,
                    unrevealedBids[i].bidder,
                    unrevealedBids[i].collateralTokens,
                    unrevealedBids[i].collateralAmounts
                );
            }
        }
        // Return unrevealed offer funds.
        for (i = 0; i < unrevealedOffers.length; ++i) {
            termAuctionOfferLocker.unlockOfferPartial(
                unrevealedOffers[i].id,
                unrevealedOffers[i].offeror,
                unrevealedOffers[i].amount
            );
        }

        emitter.emitAuctionCancelled(termAuctionId, false, false);

        assert(termRepoServicer.isTermRepoBalanced());
    }

    /// @notice Cancels an auction and sets auctionCancelledForWithdrawal to true to open unlocking tenders
    function cancelAuctionForWithdrawal(
        address[] calldata rolloverBorrowers,
        address[] calldata rolloverPairOffTermRepoServicer
    ) public onlyWhileAuctionClosed onlyRole(ADMIN_ROLE) {
        for (uint256 i = 0; i < rolloverBorrowers.length; ++i) {
            _markRolloverAsProcessed(
                rolloverPairOffTermRepoServicer[i],
                rolloverBorrowers[i]
            );
        }

        auctionCancelledForWithdrawal = true;
        emitter.emitAuctionCancelled(
            termAuctionId,
            false,
            auctionCancelledForWithdrawal
        );
    }

    // ========================================================================
    // = Helpers ==============================================================
    // ========================================================================
    function _increaseCumSumBids(
        TermAuctionRevealedBid[] memory sortedBids,
        uint256 startIndex,
        uint256 previousCumSumBids,
        uint256 currentPrice
    ) internal pure returns (uint256, uint256) {
        uint256 cumsumBids = previousCumSumBids;
        uint256 i;

        for (
            i = startIndex;
            sortedBids[i].bidPriceRevealed >= currentPrice;
            --i
        ) {
            cumsumBids += sortedBids[i].amount;
            if (i == 0) break;
        }
        return (
            cumsumBids,
            sortedBids[i].bidPriceRevealed < currentPrice ? i + 1 : i
        );
    }

    function _decreaseCumSumBids(
        TermAuctionRevealedBid[] memory sortedBids,
        uint256 startIndex,
        uint256 previousCumSumBids,
        uint256 currentPrice
    ) internal pure returns (uint256, uint256) {
        uint256 cumsumBids = previousCumSumBids;
        uint256 i;

        for (
            i = startIndex;
            i < sortedBids.length &&
                sortedBids[i].bidPriceRevealed < currentPrice;
            i++
        ) cumsumBids -= sortedBids[i].amount;

        return (cumsumBids, i);
    }

    /// Returns the min of two `uint256` values
    /// @param a The first value to compare
    /// @param b The second value to compare
    /// @return The min of the two values
    function _minUint256(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a >= b) {
            return b;
        } else {
            return a;
        }
    }

    /// Calculates the intersection between bid/offer schedules to arrive at a clearing price
    /// @dev Imagine a graph with price along the X-axis and cumsum(bid/offerAmount*price) along the Y-axis. This function finds the point where the supply line crosses the demand line using binary search
    /// @param sortedBids A sorted array of bids used to arrive at a demand schedule
    /// @param sortedOffers A sorted array of offers used to arrive at a supply schedule
    /// @param clearingOffset The offset to apply to the marginal bid and offer indexes when calculating the final clearing price
    /// @return clearingPrice The price at which Term Auction will be cleared
    function _calculateClearingPrice(
        TermAuctionRevealedBid[] memory sortedBids,
        TermAuctionRevealedOffer[] memory sortedOffers,
        uint256 clearingOffset
    ) internal pure returns (uint256, uint256) {
        if (clearingOffset != 1 && clearingOffset != 0) {
            revert ClearingOffsetNot0Or1(clearingOffset);
        }

        // Local function variables are kept in memory
        ClearingPriceState memory state = ClearingPriceState({
            offerPrice: sortedOffers[0].offerPriceRevealed, // p^o_i
            offerIndex: 1, // idxo(offerPrice)
            cumSumOffers: sortedOffers[0].amount, // cso(offerPrice)
            bidIndex: sortedBids.length,
            cumSumBids: 0,
            maxClearingVolume: 0,
            nextOfferIndex: 0,
            nextBidIndex: 0,
            nextCumSumOffers: 0,
            nextCumSumBids: 0,
            nextOfferPrice: 0,
            nextMaxClearingVolume: 0,
            minCumSumCorrection: false,
            nextBidPrice: 0,
            clearingPrice: 0
        });

        // Calculate bidIndex = idxb(offerPrice) and cumSumBids = csb(offerPrice)
        (state.cumSumBids, state.bidIndex) = _increaseCumSumBids(
            sortedBids,
            state.bidIndex - 1,
            0,
            state.offerPrice
        );

        // Calculate initial maximal clearing volume
        state.maxClearingVolume = _minUint256(
            state.cumSumBids,
            state.cumSumOffers
        );

        // Calculate the pre-clearance price: maximise the clearing volume
        while (
            state.offerIndex < sortedOffers.length &&
            state.bidIndex < sortedBids.length
        ) {
            // Initialise the next iteration of the relevant variables
            state.nextOfferIndex = state.offerIndex;
            state.nextBidIndex = state.bidIndex;
            state.nextCumSumOffers = state.cumSumOffers;
            state.nextCumSumBids = state.cumSumBids;
            state.nextOfferPrice = sortedOffers[state.offerIndex]
                .offerPriceRevealed;

            // Obtain next offer index, increase cumulative sum
            while (
                state.nextOfferIndex < sortedOffers.length &&
                sortedOffers[state.nextOfferIndex].offerPriceRevealed ==
                state.nextOfferPrice
            )
                state.nextCumSumOffers += sortedOffers[state.nextOfferIndex++]
                    .amount;

            // Obtain next bid index, decrease cumulative sum
            (state.nextCumSumBids, state.nextBidIndex) = _decreaseCumSumBids(
                sortedBids,
                state.nextBidIndex,
                state.nextCumSumBids,
                state.nextOfferPrice
            );

            state.nextMaxClearingVolume = _minUint256(
                state.nextCumSumBids,
                state.nextCumSumOffers
            );
            if (state.nextMaxClearingVolume > state.maxClearingVolume) {
                state.offerIndex = state.nextOfferIndex;
                state.bidIndex = state.nextBidIndex;
                state.cumSumOffers = state.nextCumSumOffers;
                state.cumSumBids = state.nextCumSumBids;
                state.offerPrice = state.nextOfferPrice;
                state.maxClearingVolume = state.nextMaxClearingVolume;
            } else {
                break;
            }
        }

        // Get next offer price: first offer price higher than the pre-clearance price
        state.nextOfferPrice = (state.offerIndex < sortedOffers.length)
            ? sortedOffers[state.offerIndex].offerPriceRevealed
            : type(uint256).max;

        // Minimise css by minimising csb as long as bid price is smaller than next offer price
        while (state.bidIndex < sortedBids.length) {
            state.nextBidIndex = state.bidIndex;
            state.nextBidPrice = sortedBids[state.bidIndex].bidPriceRevealed;
            state.nextCumSumBids = state.cumSumBids;
            if (state.nextBidPrice < state.nextOfferPrice) {
                while (
                    state.nextBidIndex < sortedBids.length &&
                    sortedBids[state.nextBidIndex].bidPriceRevealed ==
                    state.nextBidPrice
                ) {
                    state.nextCumSumBids -= sortedBids[state.nextBidIndex++]
                        .amount;
                }
                if (state.nextCumSumBids >= state.cumSumOffers) {
                    state.minCumSumCorrection = true;
                    state.cumSumBids = state.nextCumSumBids;
                    state.bidIndex = state.nextBidIndex;
                } else {
                    break;
                }
            } else {
                break;
            }
        }

        // Calculate clearing price: bid price if minimum correction was made and offer price otherwise
        if (state.minCumSumCorrection)
            state.clearingPrice = (state.bidIndex == sortedBids.length)
                ? sortedBids[state.bidIndex - 1].bidPriceRevealed
                : sortedBids[state.bidIndex].bidPriceRevealed;
        else state.clearingPrice = state.offerPrice;

        // The main loop positions `offerIndex` at the first index greater than the price.
        // It needs to be shifted back to get the last index smaller than or equal to the price.
        state.offerIndex--;

        // If non-zero clearing offset, find the offset tender prices and then average them to find the final clearing price.
        if (clearingOffset == 1) {
            uint256 nextOfferPriceIndex = state.offerIndex;
            while (
                nextOfferPriceIndex > 0 &&
                sortedOffers[nextOfferPriceIndex].offerPriceRevealed ==
                sortedOffers[state.offerIndex].offerPriceRevealed
            ) {
                nextOfferPriceIndex -= 1;
            }

            uint256 nextBidPriceIndex = state.bidIndex;

            // In the case that there is no clear, bid index is past end of array, so decrement it to last element.
            if (state.bidIndex == sortedBids.length) {
                nextBidPriceIndex -= 1;
            }

            while (
                nextBidPriceIndex < sortedBids.length - 1 &&
                sortedBids[nextBidPriceIndex].bidPriceRevealed ==
                sortedBids[state.bidIndex].bidPriceRevealed
            ) {
                nextBidPriceIndex += 1;
            }

            state.clearingPrice =
                (sortedOffers[nextOfferPriceIndex].offerPriceRevealed +
                    sortedBids[nextBidPriceIndex].bidPriceRevealed) /
                2;
        } else {
            // In the case that there is no clear, bid index is past end of array, so decrement it to last element.
            if (state.bidIndex == sortedBids.length) {
                state.bidIndex -= 1;
            }
            state.clearingPrice =
                (sortedOffers[state.offerIndex].offerPriceRevealed +
                    sortedBids[state.bidIndex].bidPriceRevealed) /
                2;
        }

        //update state.cumSumOffers
        if (
            sortedOffers[state.offerIndex].offerPriceRevealed <=
            state.clearingPrice
        ) {
            state.offerIndex++;
            while (
                state.offerIndex < sortedOffers.length &&
                sortedOffers[state.offerIndex].offerPriceRevealed <=
                state.clearingPrice
            ) {
                state.cumSumOffers += sortedOffers[state.offerIndex].amount;
                state.offerIndex++;
            }
        } else {
            while (
                sortedOffers[state.offerIndex].offerPriceRevealed >
                state.clearingPrice
            ) {
                state.cumSumOffers -= sortedOffers[state.offerIndex].amount;
                if (state.offerIndex == 0) break;
                state.offerIndex--;
            }
        }

        //update state.cumSumBids
        if (
            state.bidIndex < sortedBids.length &&
            sortedBids[state.bidIndex].bidPriceRevealed < state.clearingPrice
        ) {
            (state.cumSumBids, state.bidIndex) = _decreaseCumSumBids(
                sortedBids,
                state.bidIndex,
                state.cumSumBids,
                state.clearingPrice
            );
        } else if (state.bidIndex > 0) {
            (state.cumSumBids, state.bidIndex) = _increaseCumSumBids(
                sortedBids,
                state.bidIndex - 1,
                state.cumSumBids,
                state.clearingPrice
            );
        }

        return (
            state.clearingPrice,
            _minUint256(state.cumSumBids, state.cumSumOffers)
        );
    }

    /// Finds the index of the first bid with a bidPrice of `price` and calculate the cumsum of the bid amounts up to that index
    /// @param price The price to search for
    /// @param sortedBids An array of sorted bids to search
    /// @param startIndex The index to start searching from
    /// @return i The index of the first bid with a bidPrice of `price`
    /// @return totalAmount The cumsum of the bid amounts up to return index i
    function _findFirstIndexForPrice(
        uint256 price,
        TermAuctionRevealedBid[] memory sortedBids,
        uint256 startIndex
    ) internal pure returns (uint256 i, uint256 totalAmount) {
        i = startIndex;
        totalAmount = sortedBids[i].amount;
        while (true) {
            if (i == 0 || sortedBids[i - 1].bidPriceRevealed != price) {
                break;
            }
            totalAmount += sortedBids[i - 1].amount;
            --i;
        }
        return (i, totalAmount);
    }

    /// Finds the index of the last offer with a offerPrice of `price` and calculate the cumsum of the offer amounts up to that index
    /// @param price The price to search for
    /// @param sortedOffers An array of offers to search
    /// @param startIndex The index to start searching from
    /// @return i The index of the last offer with a offerPrice of `price`
    /// @return totalAmount The cumsum of the offer amounts up to return index i
    function _findLastIndexForPrice(
        uint256 price,
        TermAuctionRevealedOffer[] memory sortedOffers,
        uint256 startIndex
    ) internal pure returns (uint256 i, uint256 totalAmount) {
        i = startIndex;
        totalAmount = sortedOffers[i].amount;
        while (i < (sortedOffers.length - 1)) {
            if (sortedOffers[i + 1].offerPriceRevealed != price) {
                break;
            }
            totalAmount += sortedOffers[i + 1].amount;
            ++i;
        }
        return (i, totalAmount);
    }

    /// Fully assigns a bid
    /// @param bid The bid to assign
    /// @return The amount that was assigned
    function _fullyAssignBid(
        TermAuctionRevealedBid memory bid
    ) internal nonReentrant returns (uint256) {
        uint256 repurchaseAmount = _calculateRepurchasePrice(bid.amount);

        if (!bid.isRollover) {
            termRepoServicer.fulfillBid(
                bid.bidder,
                bid.amount,
                repurchaseAmount,
                bid.collateralTokens,
                bid.collateralAmounts,
                dayCountFractionMantissa
            );
        } else {
            _assignRolloverBid(
                bid.bidder,
                bid.amount,
                repurchaseAmount,
                bid.rolloverPairOffTermRepoServicer
            );
        }

        emitter.emitBidAssigned(termAuctionId, bid.id, bid.amount);

        return bid.amount;
    }

    /// Fully assigns an offer
    /// @param offer The offer to assign
    /// @return The amount that was assigned
    function _fullyAssignOffer(
        TermAuctionRevealedOffer memory offer
    ) internal nonReentrant returns (uint256) {
        uint256 repurchaseAmount = _calculateRepurchasePrice(offer.amount);

        termRepoServicer.fulfillOffer(
            offer.offeror,
            offer.amount,
            repurchaseAmount,
            offer.id
        );

        emitter.emitOfferAssigned(termAuctionId, offer.id, offer.amount);

        return offer.amount;
    }

    /// Partially assigns a bid
    /// @param bid The bid to assign
    /// @param assignedAmount The amount to assign
    /// @return The amount that was assigned
    function _partiallyAssignBid(
        TermAuctionRevealedBid memory bid,
        uint256 assignedAmount
    ) internal nonReentrant returns (uint256) {
        uint256 repurchaseAmount = _calculateRepurchasePrice(assignedAmount);

        if (!bid.isRollover) {
            termRepoServicer.fulfillBid(
                bid.bidder,
                assignedAmount,
                repurchaseAmount,
                bid.collateralTokens,
                bid.collateralAmounts,
                dayCountFractionMantissa
            );
        } else {
            _assignRolloverBid(
                bid.bidder,
                assignedAmount,
                repurchaseAmount,
                bid.rolloverPairOffTermRepoServicer
            );
        }

        emitter.emitBidAssigned(termAuctionId, bid.id, assignedAmount);

        return assignedAmount;
    }

    /// Partially assigns an offer
    /// @param offer The offer to assign
    /// @param assignedAmount The amount to assign
    /// @return The amount that was assigned
    function _partiallyAssignOffer(
        TermAuctionRevealedOffer memory offer,
        uint256 assignedAmount
    ) internal nonReentrant returns (uint256) {
        uint256 repurchaseAmount = _calculateRepurchasePrice(assignedAmount);

        termRepoServicer.fulfillOffer(
            offer.offeror,
            assignedAmount,
            repurchaseAmount,
            offer.id
        );

        // Unlock remaining.
        termAuctionOfferLocker.unlockOfferPartial(
            offer.id,
            offer.offeror,
            offer.amount - assignedAmount
        );

        emitter.emitOfferAssigned(termAuctionId, offer.id, assignedAmount);

        return assignedAmount;
    }

    function _assignRolloverBid(
        address borrower,
        uint256 purchasePrice,
        uint256 repurchasePrice,
        address rolloverPairOffTermRepoServicer
    ) internal {
        ITermRepoCollateralManager currentTermRepoCollateralManager = termRepoServicer
                .termRepoCollateralManager();

        if (termRepoServicer.getBorrowerRepurchaseObligation(borrower) == 0) {
            currentTermRepoCollateralManager.encumberExistingCollateral(
                borrower
            );
        }
        ITermRepoServicer previousTermRepoServicer = ITermRepoServicer(
            rolloverPairOffTermRepoServicer
        );
        uint256 rolloverPaymentToCollapseBorrower = termRepoServicer
            .openExposureOnRolloverNew(
                borrower,
                purchasePrice,
                repurchasePrice,
                address(previousTermRepoServicer.termRepoLocker()),
                dayCountFractionMantissa
            );
        uint256 proportionPreviousLoanPaid = previousTermRepoServicer
            .closeExposureOnRolloverExisting(
                borrower,
                rolloverPaymentToCollapseBorrower
            );
        ITermRepoCollateralManager previousTermRepoCollateralManager = ITermRepoCollateralManager(
                previousTermRepoServicer.termRepoCollateralManager()
            );
        (
            address[] memory collateralTypes,
            uint256[] memory collateralAmounts
        ) = previousTermRepoCollateralManager.transferRolloverCollateral(
                borrower,
                proportionPreviousLoanPaid,
                address(termRepoServicer.termRepoLocker())
            );

        for (uint256 i = 0; i < collateralTypes.length; ++i) {
            if (collateralAmounts[i] > 0) {
                currentTermRepoCollateralManager.acceptRolloverCollateral(
                    borrower,
                    collateralTypes[i],
                    collateralAmounts[i]
                );
            }
        }
    }

    function _markRolloverAsProcessed(
        address rolloverPairOffTermRepoServicer,
        address borrower
    ) internal {
        ITermRepoServicer termRepoServicer_ = ITermRepoServicer(
            rolloverPairOffTermRepoServicer
        );
        ITermRepoRolloverManager rolloverManager = termRepoServicer_
            .termRepoRolloverManager();
        rolloverManager.fulfillRollover(borrower);
    }

    /// Assigns bids up to `maxAssignable`
    /// @dev This method allocates pro-rata across an the marginal price group (pro-rata on the margin) and attempts to prevent residuals from accumulating to a single bid
    /// @param sortedBids An array of sorted bids to process
    /// @param maxAssignable The maximum bid amount that can be assigned across all bidders
    /// @param purchaseTokenDecimals The number of decimals of the purchase token
    /// @return The total amount assigned
    function _assignBids(
        TermAuctionRevealedBid[] memory sortedBids,
        uint256 maxAssignable,
        uint256 purchaseTokenDecimals
    ) internal returns (uint256) {
        // Process revealed bids.
        uint256 totalAssignedBids = 0;
        uint256 innerIndex = 0;
        uint256 i = 0;
        for (uint256 j = sortedBids.length; j > 0; --j) {
            i = j - 1;

            // First, find the sub-range that contains the current price.
            (uint256 k, uint256 priceGroupAmount) = _findFirstIndexForPrice(
                sortedBids[i].bidPriceRevealed,
                sortedBids,
                i
            );
            // NOTE: priceGroupAmount gets changed later on in this function and is used as the "remaining" priceGroupAmount during partial assignment.

            if (
                sortedBids[i].bidPriceRevealed >= clearingPrice &&
                totalAssignedBids < maxAssignable &&
                priceGroupAmount <= (maxAssignable - totalAssignedBids)
            ) {
                // Full assignment for entire price group.

                innerIndex = 0;
                for (; (i - innerIndex) >= k; ++innerIndex) {
                    // NOTE: This loop is actually decrementing!
                    totalAssignedBids += _fullyAssignBid(
                        sortedBids[i - innerIndex]
                    );

                    if (i == innerIndex) {
                        ++innerIndex;
                        break;
                    }
                }
                if (innerIndex > 0) {
                    j -= (innerIndex - 1);
                }
            } else if (
                sortedBids[i].bidPriceRevealed >= clearingPrice &&
                totalAssignedBids < maxAssignable
            ) {
                // Partial assignment for entire price group.

                innerIndex = 0;
                for (; (i - innerIndex) >= k; ++innerIndex) {
                    if ((i - innerIndex) == k) {
                        // Last iteration of loop. Assign remaining amount left to assign.
                        totalAssignedBids += _partiallyAssignBid(
                            sortedBids[i - innerIndex],
                            maxAssignable - totalAssignedBids
                        );
                        priceGroupAmount -= maxAssignable - totalAssignedBids;
                    } else {
                        // Assign an amount based upon the partial assignment ratio.

                        uint256 bidAmount = sortedBids[i - innerIndex].amount;
                        Exp memory partialAssignmentRatio = div_(
                            Exp({
                                mantissa: (maxAssignable - totalAssignedBids) *
                                    10 ** (18 - purchaseTokenDecimals)
                            }),
                            Exp({
                                mantissa: priceGroupAmount *
                                    10 ** (18 - purchaseTokenDecimals)
                            })
                        );
                        uint256 assignedAmount = mul_(
                            partialAssignmentRatio,
                            Exp({
                                mantissa: bidAmount *
                                    10 ** (18 - purchaseTokenDecimals)
                            })
                        ).mantissa / 10 ** (18 - purchaseTokenDecimals);

                        if (assignedAmount == 0) {
                            revert AssignedZeroAmount(
                                sortedBids[i - innerIndex].id
                            );
                        }

                        totalAssignedBids += _partiallyAssignBid(
                            sortedBids[i - innerIndex],
                            assignedAmount
                        );
                        priceGroupAmount -= sortedBids[i - innerIndex].amount;
                    }

                    if (i == innerIndex) {
                        ++innerIndex;
                        break;
                    }
                }
                if (innerIndex > 0) {
                    j -= (innerIndex - 1);
                }
            } else {
                // No assignment.
                if (sortedBids[i].isRollover) {
                    _markRolloverAsProcessed(
                        sortedBids[i].rolloverPairOffTermRepoServicer,
                        sortedBids[i].bidder
                    );
                } else {
                    termAuctionBidLocker.auctionUnlockBid(
                        sortedBids[i].id,
                        sortedBids[i].bidder,
                        sortedBids[i].collateralTokens,
                        sortedBids[i].collateralAmounts
                    );
                }
            }
        }

        return totalAssignedBids;
    }

    /// Assigns offers up to `maxAssignable`
    /// @dev This method allocates pro-rata across an the marginal price group (pro-rata on the margin) and attempts to prevent residuals from accumulating to a single offer
    /// @param sortedOffers An array of sorted offers to process
    /// @param maxAssignable The maximum offer amount that can be assigned across all offers
    /// @param purchaseTokenDecimals The number of decimals of the purchase token
    /// @return The total amount assigned
    function _assignOffers(
        TermAuctionRevealedOffer[] memory sortedOffers,
        uint256 maxAssignable,
        uint256 purchaseTokenDecimals
    ) internal returns (uint256) {
        // Process revealed offers.
        uint256 totalAssignedOffers = 0;
        uint256 innerIndex = 0;
        uint256 i = 0;
        for (i = 0; i < sortedOffers.length; ++i) {
            // First, find the sub-range that contains the current price.
            (uint256 k, uint256 priceGroupAmount) = _findLastIndexForPrice(
                sortedOffers[i].offerPriceRevealed,
                sortedOffers,
                i
            );
            // NOTE: priceGroupAmount gets changed later on in this function and is used as the "remaining" priceGroupAmount during partial assignment.

            if (
                sortedOffers[i].offerPriceRevealed <= clearingPrice &&
                totalAssignedOffers < maxAssignable &&
                priceGroupAmount <= (maxAssignable - totalAssignedOffers)
            ) {
                // Full assignment.
                innerIndex = 0;
                for (; (innerIndex + i) <= k; ++innerIndex) {
                    totalAssignedOffers += _fullyAssignOffer(
                        sortedOffers[innerIndex + i]
                    );
                }
                if (innerIndex > 0) {
                    i += innerIndex - 1;
                }
            } else if (
                sortedOffers[i].offerPriceRevealed <= clearingPrice &&
                totalAssignedOffers < maxAssignable
            ) {
                // Partial assignment.
                innerIndex = 0;
                for (; (innerIndex + i) <= k; innerIndex++) {
                    if ((innerIndex + i) == k) {
                        // Last iteration of loop. Assign remaining amount left to assign.
                        totalAssignedOffers += _partiallyAssignOffer(
                            sortedOffers[innerIndex + i],
                            maxAssignable - totalAssignedOffers
                        );
                        priceGroupAmount -= maxAssignable - totalAssignedOffers;
                    } else {
                        // Assign an amount based upon the partial assignment ratio.

                        uint256 offerAmount = sortedOffers[innerIndex + i]
                            .amount;
                        Exp memory partialAssignmentRatio = div_(
                            Exp({
                                mantissa: (maxAssignable -
                                    totalAssignedOffers) *
                                    10 ** (18 - purchaseTokenDecimals)
                            }),
                            Exp({
                                mantissa: priceGroupAmount *
                                    10 ** (18 - purchaseTokenDecimals)
                            })
                        );
                        uint256 assignedAmount = (innerIndex + i) != k
                            ? mul_(
                                partialAssignmentRatio,
                                Exp({
                                    mantissa: offerAmount *
                                        10 ** (18 - purchaseTokenDecimals)
                                })
                            ).mantissa / 10 ** (18 - purchaseTokenDecimals)
                            : maxAssignable - totalAssignedOffers;

                        totalAssignedOffers += _partiallyAssignOffer(
                            sortedOffers[innerIndex + i],
                            assignedAmount
                        );
                        priceGroupAmount -= sortedOffers[innerIndex + i].amount;
                    }
                }
                if (innerIndex > 0) {
                    i += innerIndex - 1;
                }
            } else {
                // No assignment.

                // Return purchase tokens to offeror.
                termAuctionOfferLocker.unlockOfferPartial(
                    sortedOffers[i].id,
                    sortedOffers[i].offeror,
                    sortedOffers[i].amount
                );
            }
        }

        return totalAssignedOffers;
    }

    /// Calculates repurchase price given a purchase price (equivalent to principal plus interest)
    /// @param purchasePrice The purchase price
    /// @return The repurchase price obtained by applying the clearing rate on an Actual/360 day-count convention
    function _calculateRepurchasePrice(
        uint256 purchasePrice
    ) internal view returns (uint256) {
        Exp memory repurchaseFactor = add_(
            Exp({mantissa: expScale}),
            mul_(
                Exp({mantissa: dayCountFractionMantissa}),
                Exp({mantissa: clearingPrice})
            )
        );

        return
            truncate(
                mul_(
                    Exp({mantissa: purchasePrice * expScale}),
                    repurchaseFactor
                )
            );
    }

    function _calculateAndStoreClearingPrice(
        TermAuctionRevealedBid[] memory sortedBids,
        TermAuctionRevealedOffer[] memory sortedOffers
    ) internal nonReentrant returns (uint256, uint256) {
        (
            uint256 clearingPrice_,
            uint256 maxAssignable
        ) = _calculateClearingPrice(
                sortedBids,
                sortedOffers,
                clearingPricePostProcessingOffset
            );

        clearingPrice = clearingPrice_;

        return (clearingPrice_, maxAssignable);
    }

    // ========================================================================
    // = Pausable =============================================================
    // ========================================================================

    /// @dev This function pauses the TermAuction contract preventing public state changes
    /// @dev See {Pausable-_pause}.
    function pauseCompleteAuction() external onlyRole(ADMIN_ROLE) {
        completeAuctionPaused = true;
        emitter.emitCompleteAuctionPaused(termAuctionId, termRepoId);
    }

    /// Unpuses the TermAuction contract allowing public state changes
    /// @dev See {Pausable-_unpause}.
    function unpauseCompleteAuction() external onlyRole(ADMIN_ROLE) {
        completeAuctionPaused = false;
        emitter.emitCompleteAuctionUnpaused(termAuctionId, termRepoId);
    }

    ///@dev required override by the OpenZeppelin UUPS module
    ///@param impl new impl address for proxy upgrade
    function _authorizeUpgrade(
        address impl
    ) internal override onlyRole(DEVOPS_ROLE) {
        emitter.emitTermContractUpgraded(address(this), impl);
    }
}

contracts/TermAuctionBidLocker.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermAuction} from "./interfaces/ITermAuction.sol";
import {ITermAuctionBidLocker} from "./interfaces/ITermAuctionBidLocker.sol";
import {ITermAuctionBidLockerErrors} from "./interfaces/ITermAuctionBidLockerErrors.sol";
import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {ITermPriceOracle} from "./interfaces/ITermPriceOracle.sol";
import {ITermRepoCollateralManager} from "./interfaces/ITermRepoCollateralManager.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {ExponentialNoError} from "./lib/ExponentialNoError.sol";
import {TermContractsPausable} from "./lib/TermContractsPausable.sol";
import {TermAuctionBid} from "./lib/TermAuctionBid.sol";
import {TermAuctionBidSubmission} from "./lib/TermAuctionBidSubmission.sol";
import {TermAuctionRevealedBid} from "./lib/TermAuctionRevealedBid.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Bid Locker
/// @notice This contract handles and proceesses Term Auction bid submissions
/// @dev This contract belongs to the Term Auction group of contracts and is specific to a Term Repo deployment
contract TermAuctionBidLocker is
    ITermAuctionBidLocker,
    ITermAuctionBidLockerErrors,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    ExponentialNoError,
    ReentrancyGuardUpgradeable,
    TermContractsPausable,
    Versionable
{
    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    uint256 public constant MAX_BID_PRICE = 10000e16; // 10,000%

    uint256 public constant MAX_BID_COUNT = 150;

    uint256 public constant THREESIXTY_DAYCOUNT_SECONDS = 360 days;

    uint256 public constant MINIMUM_ROLLOVER_TENDER_DIVISOR = 10;

    // ========================================================================
    // = Access Roles  ========================================================
    // ========================================================================
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant AUCTIONEER_ROLE = keccak256("AUCTIONEER_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");
    bytes32 public constant ROLLOVER_MANAGER = keccak256("ROLLOVER_MANAGER");
    bytes32 public constant DIAMOND_ROLE = keccak256("DIAMOND_ROLE");

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    // Auction configuration.
    bytes32 public termRepoId;
    bytes32 public termAuctionId;
    uint256 public auctionStartTime;
    uint256 public revealTime;
    uint256 public auctionEndTime;
    uint256 public minimumTenderAmount;
    uint256 public dayCountFractionMantissa;
    address public purchaseToken;
    mapping(IERC20 => bool) public collateralTokens;
    ITermRepoCollateralManager public termRepoCollateralManager;
    ITermRepoServicer public termRepoServicer;
    ITermPriceOracle internal termPriceOracle;
    ITermEventEmitter internal emitter;
    ITermAuction public termAuction;

    // Auction in-progress state
    mapping(bytes32 => TermAuctionBid) internal bids;
    uint256 public bidCount;
    bool internal termContractPaired;
    bool public lockingPaused;
    bool public unlockingPaused;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================
    modifier onlyWhileAuctionOpen() {
        if (
            // solhint-disable-next-line not-rely-on-time
            block.timestamp > revealTime || block.timestamp < auctionStartTime
        ) {
            revert AuctionNotOpen();
        }
        _;
    }
    modifier onlyWhileAuctionRevealing() {
        if (
            // solhint-disable-next-line not-rely-on-time
            block.timestamp < revealTime
        ) {
            revert AuctionNotRevealing();
        }
        _;
    }

    modifier onlyBidder(address bidder, address authedUser) {
        if (authedUser != bidder) {
            revert BidNotOwned();
        }
        _;
    }

    modifier whenLockingNotPaused() {
        if (lockingPaused) {
            revert LockingPaused();
        }
        _;
    }

    modifier whenUnlockingNotPaused() {
        if (unlockingPaused) {
            revert UnlockingPaused();
        }
        _;
    }

    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    // ========================================================================
    // = Deploy (https://docs.openzeppelin.com/contracts/4.x/upgradeable) =====
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string calldata termRepoId_,
        string calldata auctionId_,
        uint256 auctionStartTime_,
        uint256 revealTime_,
        uint256 auctionEndTime_,
        uint256 redemptionTimestamp_,
        uint256 minimumTenderAmount_,
        address purchaseToken_,
        IERC20[] memory collateralTokens_,
        address termInitializer_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();
        ReentrancyGuardUpgradeable.__ReentrancyGuard_init();

        _grantRole(INITIALIZER_ROLE, termInitializer_);

        termRepoId = keccak256(abi.encodePacked(termRepoId_));
        termAuctionId = keccak256(abi.encodePacked(auctionId_));

        if (auctionStartTime_ > revealTime_) {
            revert AuctionStartsAfterReveal(auctionStartTime_, revealTime_);
        }

        auctionStartTime = auctionStartTime_;
        revealTime = revealTime_;
        auctionEndTime = auctionEndTime_;
        minimumTenderAmount = minimumTenderAmount_;
        dayCountFractionMantissa =
            ((redemptionTimestamp_ - auctionEndTime_) * expScale) /
            THREESIXTY_DAYCOUNT_SECONDS;
        purchaseToken = purchaseToken_;
        for (uint256 i = 0; i < collateralTokens_.length; ++i) {
            collateralTokens[collateralTokens_[i]] = true;
        }

        bidCount = 0;
        termContractPaired = false;
    }

    function pairTermContracts(
        address termAuction_,
        ITermRepoServicer termRepoServicer_,
        ITermEventEmitter emitter_,
        ITermRepoCollateralManager termRepoCollateralManager_,
        ITermPriceOracle termPriceOracle_,
        address devopsMultisig_,
        address adminWallet_,
        address termDiamond_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        if (address(termRepoServicer_) == address(0)) {
            revert InvalidTermRepoServicer();
        }
        termRepoServicer = termRepoServicer_;
        termAuction = ITermAuction(termAuction_);
        _grantRole(AUCTIONEER_ROLE, termAuction_);
        _grantRole(DEVOPS_ROLE, devopsMultisig_);
        _grantRole(ADMIN_ROLE, adminWallet_);
        _grantRole(DIAMOND_ROLE, termDiamond_);

        emitter = emitter_;

        termRepoCollateralManager = termRepoCollateralManager_;
        termPriceOracle = termPriceOracle_;

        emitter.emitTermAuctionBidLockerInitialized(
            termRepoId,
            termAuctionId,
            address(this),
            auctionStartTime,
            revealTime,
            MAX_BID_PRICE,
            minimumTenderAmount,
            dayCountFractionMantissa
        );
    }

    /// @param rolloverManager The address of the TermRepoRolloverManager contract
    function pairRolloverManager(
        address rolloverManager
    ) external onlyRole(ADMIN_ROLE) {
        _grantRole(ROLLOVER_MANAGER, rolloverManager);
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @param bidSubmissions An array of Term Auction bid submissions to borrow an amount of money at rate up to but not exceeding the bid rate
    /// @param referralAddress A user address that referred the submitter of this bid
    /// @notice When modifying an existing bid, the collateral tokens in the submission must match the original bid's collateral tokens in the same order
    /// @return A bytes32 array of unique on chain bid ids.
    function lockBidsWithReferral(
        TermAuctionBidSubmission[] calldata bidSubmissions,
        address referralAddress
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        returns (bytes32[] memory)
    {
        if (msg.sender == referralAddress) {
            revert InvalidSelfReferral();
        }

        bytes32[] memory bidIds = new bytes32[](bidSubmissions.length);

        for (uint256 i = 0; i < bidSubmissions.length; ++i) {
            TermAuctionBid storage bid = _lock(
                bidSubmissions[i],
                msg.sender,
                msg.sender
            );
            bidIds[i] = bid.id;
            emitter.emitBidLocked(termAuctionId, bid, referralAddress);
        }
        return bidIds;
    }

    /// @param bidSubmissions An array of Term Auction bid submissions to borrow an amount of money at rate up to but not exceeding the bid rate
    /// @param referralAddress A user address that referred the submitter of this bid
    /// @notice When modifying an existing bid, the collateral tokens in the submission must match the original bid's collateral tokens in the same order
    /// @return A bytes32 array of unique on chain bid ids.
    function lockBidsWithReferral(
        address bidder,
        TermAuctionBidSubmission[] calldata bidSubmissions,
        address referralAddress
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        onlyRole(DIAMOND_ROLE)
        returns (bytes32[] memory)
    {
        if (bidder == referralAddress) {
            revert InvalidSelfReferral();
        }

        bytes32[] memory bidIds = new bytes32[](bidSubmissions.length);

        for (uint256 i = 0; i < bidSubmissions.length; ++i) {
            TermAuctionBid storage bid = _lock(
                bidSubmissions[i],
                bidder,
                msg.sender
            );
            bidIds[i] = bid.id;
            emitter.emitBidLocked(termAuctionId, bid, referralAddress);
        }
        return bidIds;
    }

    /// @param bid A struct containing details of the bid
    function lockRolloverBid(
        TermAuctionBid calldata bid
    )
        external
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        onlyRole(ROLLOVER_MANAGER)
        nonReentrant
    {
        if (
            // solhint-disable-next-line not-rely-on-time
            block.timestamp > revealTime
        ) {
            revert AuctionNotOpen();
        }

        if (bid.amount == 0) {
            if (bids[bid.id].amount == 0) {
                revert NonExistentBid(bid.id);
            }

            delete bids[bid.id];
            bidCount -= 1;
            emitter.emitBidUnlocked(termAuctionId, bid.id);
        } else {
            _lockRolloverBid(bid);
        }
    }

    /// @param bidSubmissions An array of bid submissions
    /// @notice When modifying an existing bid, the collateral tokens in the submission must match the original bid's collateral tokens in the same order
    /// @return A bytes32 array of unique on chain bid ids.
    function lockBids(
        TermAuctionBidSubmission[] calldata bidSubmissions
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        returns (bytes32[] memory)
    {
        bytes32[] memory bidIds = new bytes32[](bidSubmissions.length);
        for (uint256 i = 0; i < bidSubmissions.length; ++i) {
            TermAuctionBid storage bid = _lock(
                bidSubmissions[i],
                msg.sender,
                msg.sender
            );
            bidIds[i] = bid.id;
            emitter.emitBidLocked(termAuctionId, bid, address(0));
        }
        return bidIds;
    }

    /// @param id A bid Id
    /// @return A struct containing details of the locked bid
    function lockedBid(
        bytes32 id
    ) external view returns (TermAuctionBid memory) {
        return bids[id];
    }

    /// @param ids An array of bid ids of the bids to reveal
    /// @param prices An array of the bid prices to reveal
    /// @param nonces An array of nonce values to generate bid price hashes
    function revealBids(
        bytes32[] calldata ids,
        uint256[] calldata prices,
        uint256[] calldata nonces
    ) external onlyWhileAuctionRevealing {
        for (uint256 i = 0; i < ids.length; ++i) {
            _revealBid(ids[i], prices[i], nonces[i]);
        }
    }

    /// @notice unlockBids unlocks multiple bids and returns funds to the bidder
    /// @param ids An array of ids to unlock
    function unlockBids(
        bytes32[] calldata ids
    )
        external
        whenUnlockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
    {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp < auctionStartTime) {
            revert AuctionNotOpen();
        }
        // solhint-disable-next-line not-rely-on-time
        if (
            block.timestamp > revealTime &&
            !termAuction.auctionCancelledForWithdrawal()
        ) {
            revert AuctionNotOpen();
        }

        for (uint256 i = 0; i < ids.length; ++i) {
            _unlock(
                ids[i],
                msg.sender,
                bids[ids[i]].collateralTokens,
                bids[ids[i]].collateralAmounts
            );
        }
    }

    /// @notice unlockBids unlocks multiple bids and returns funds to the bidder
    /// @param ids An array of ids to unlock
    function unlockBids(
        address bidder,
        bytes32[] calldata ids
    )
        external
        onlyRole(DIAMOND_ROLE)
        whenUnlockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
    {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp < auctionStartTime) {
            revert AuctionNotOpen();
        }
        // solhint-disable-next-line not-rely-on-time
        if (
            block.timestamp > revealTime &&
            !termAuction.auctionCancelledForWithdrawal()
        ) {
            revert AuctionNotOpen();
        }

        for (uint256 i = 0; i < ids.length; ++i) {
            _unlock(
                ids[i],
                bidder,
                bids[ids[i]].collateralTokens,
                bids[ids[i]].collateralAmounts
            );
        }
    }

    // ========================================================================
    // = Auction Interface/API ===============================================
    // ========================================================================

    /// @param revealedBids An array of the revealed offer ids
    /// @param expiredRolloverBids An array of the expired rollover bid ids
    /// @param unrevealedBids An array of the unrevealed offer ids
    /// @return An array of TermAuctionRevealedBid structs containing details of the revealed bids
    /// @return An array of TermAuctionBid structs containing details of the unrevealed bids
    function getAllBids(
        bytes32[] calldata revealedBids,
        bytes32[] calldata expiredRolloverBids,
        bytes32[] calldata unrevealedBids
    )
        external
        onlyRole(AUCTIONEER_ROLE)
        returns (TermAuctionRevealedBid[] memory, TermAuctionBid[] memory)
    {
        return _getAllBids(revealedBids, expiredRolloverBids, unrevealedBids);
    }

    /// @param id A bytes32 bid id
    /// @param bidder The address of the bidder
    /// @param bidCollateralTokens The addresses of the token used as collateral
    /// @param amounts The amounts of collateral tokens to unlock
    function auctionUnlockBid(
        bytes32 id,
        address bidder,
        address[] calldata bidCollateralTokens,
        uint256[] calldata amounts
    ) external onlyRole(AUCTIONEER_ROLE) {
        if (bids[id].isRollover) {
            revert RolloverBid();
        }

        emitter.emitBidUnlocked(termAuctionId, id);

        for (uint256 i = 0; i < bidCollateralTokens.length; ++i) {
            // 0 amount is a default for unlocking entire bid
            termRepoCollateralManager.auctionUnlockCollateral(
                bidder,
                bidCollateralTokens[i],
                amounts[i]
            );
        }
    }

    // ========================================================================
    // = Helpers ==============================================================
    // ========================================================================

    function _lock(
        TermAuctionBidSubmission memory bidSubmission,
        address authedUser,
        address sender
    )
        internal
        onlyBidder(bidSubmission.bidder, authedUser)
        returns (TermAuctionBid storage)
    {
        if (bidCount >= MAX_BID_COUNT) {
            revert MaxBidCountReached();
        }
        bool bidExists = bids[bidSubmission.id].amount != 0;
        bytes32 bidId;
        if (bidExists) {
            if (bids[bidSubmission.id].bidder != bidSubmission.bidder) {
                revert BidNotOwned();
            }
            bidId = bidSubmission.id;
        } else {
            bidId = _generateBidId(bidSubmission.id, authedUser);
        }
        if (purchaseToken != bidSubmission.purchaseToken) {
            revert PurchaseTokenNotApproved(bidSubmission.purchaseToken);
        }
        for (uint256 i = 0; i < bidSubmission.collateralTokens.length; ++i) {
            if (!collateralTokens[IERC20(bidSubmission.collateralTokens[i])]) {
                revert CollateralTokenNotApproved(
                    bidSubmission.collateralTokens[i]
                );
            }
            if (bidExists) {
                if (
                    bids[bidId].collateralTokens[i] !=
                    bidSubmission.collateralTokens[i]
                ) {
                    revert CollateralTokenMismatch(
                        bids[bidId].collateralTokens[i],
                        bidSubmission.collateralTokens[i]
                    );
                }
            }
        }
        if (bidSubmission.amount < minimumTenderAmount) {
            revert BidAmountTooLow(bidSubmission.amount);
        }
        if (
            /// @dev check to see if bid has enough collateral to meet initial ratio for purchase price
            _isInInitialCollateralShortFall(
                bidSubmission.amount,
                bidSubmission.collateralTokens,
                bidSubmission.collateralAmounts
            )
        ) {
            revert CollateralAmountTooLow();
        }

        uint256 oldCollateralAmount;

        for (uint256 i = 0; i < bidSubmission.collateralTokens.length; ++i) {
            // Calculate the amount of collateral tokens to lock/unlock.
            if (bidExists) {
                oldCollateralAmount = bids[bidId].collateralAmounts[i];
                if (oldCollateralAmount < bidSubmission.collateralAmounts[i]) {
                    termRepoCollateralManager.auctionLockCollateral(
                        sender,
                        address(bidSubmission.collateralTokens[i]),
                        bidSubmission.collateralAmounts[i] - oldCollateralAmount
                    );
                } else if (
                    oldCollateralAmount > bidSubmission.collateralAmounts[i]
                ) {
                    termRepoCollateralManager.auctionUnlockCollateral(
                        bidSubmission.bidder,
                        address(bidSubmission.collateralTokens[i]),
                        oldCollateralAmount - bidSubmission.collateralAmounts[i]
                    );
                }
            } else {
                termRepoCollateralManager.auctionLockCollateral(
                    sender,
                    address(bidSubmission.collateralTokens[i]),
                    bidSubmission.collateralAmounts[i]
                );
            }
        }

        // slither-disable-start reentrancy-no-eth
        bids[bidId] = TermAuctionBid({
            id: bidId,
            bidder: bidSubmission.bidder,
            bidPriceRevealed: 0,
            bidPriceHash: bidSubmission.bidPriceHash,
            amount: bidSubmission.amount,
            collateralAmounts: bidSubmission.collateralAmounts,
            purchaseToken: bidSubmission.purchaseToken,
            collateralTokens: bidSubmission.collateralTokens,
            isRollover: false,
            rolloverPairOffTermRepoServicer: address(0),
            isRevealed: false
        });
        // slither-disable-end reentrancy-no-eth

        if (!bidExists) {
            bidCount += 1;
        }

        return bids[bidId];
    }

    function _lockRolloverBid(TermAuctionBid memory bid) internal {
        // reject rollover bid if auction is full
        if (bidCount >= MAX_BID_COUNT) {
            revert MaxBidCountReached();
        }

        if (!bid.isRollover) {
            revert NonRolloverBid(bid.id);
        }

        if (
            bid.amount < minimumTenderAmount / MINIMUM_ROLLOVER_TENDER_DIVISOR
        ) {
            revert BidAmountTooLow(bid.amount);
        }

        bool bidExists = bids[bid.id].amount != 0;

        if (purchaseToken != bid.purchaseToken) {
            revert InvalidPurchaseToken();
        }

        // Store bid in auction contract.
        bids[bid.id] = bid;
        if (!bidExists) {
            bidCount += 1;
        }

        emitter.emitBidLocked(termAuctionId, bid, address(0));
    }

    function _unlock(
        bytes32 id,
        address bidder,
        address[] storage bidCollateralTokens,
        uint256[] storage amounts
    ) internal {
        if (bids[id].amount == 0) {
            revert NonExistentBid(id);
        }

        if (bidder != bids[id].bidder) {
            revert BidNotOwned();
        }

        if (bids[id].isRollover) {
            revert RolloverBid();
        }

        for (uint256 i = 0; i < bidCollateralTokens.length; ++i) {
            // 0 amount is a default for unlocking entire bid
            termRepoCollateralManager.auctionUnlockCollateral(
                bidder,
                bidCollateralTokens[i],
                amounts[i]
            );
        }

        // Remove bid from auction contract.
        delete bids[id];
        bidCount -= 1;

        emitter.emitBidUnlocked(termAuctionId, id);
    }

    function _revealBid(bytes32 id, uint256 price, uint256 nonce) internal {
        // Check that price hasn't been modified/revealed.
        if (keccak256(abi.encode(price, nonce)) != bids[id].bidPriceHash) {
            revert BidPriceModified(id);
        }
        if (price > MAX_BID_PRICE) {
            revert TenderPriceTooHigh(id, MAX_BID_PRICE);
        }
        bids[id].bidPriceRevealed = price;
        bids[id].isRevealed = true;

        emitter.emitBidRevealed(termAuctionId, id, price);
    }

    /// @param revealedBids An array of the revealed offer ids
    /// @param expiredRolloverBids An array of the expired rollover bid ids
    /// @param unrevealedBids An array of the unrevealed offer ids
    /// @return An array of TermAuctionRevealedBid structs containing details of the revealed bids
    /// @return An array of TermAuctionBid structs containing details of the unrevealed bids
    function _getAllBids(
        bytes32[] calldata revealedBids,
        bytes32[] calldata expiredRolloverBids,
        bytes32[] calldata unrevealedBids
    )
        internal
        returns (TermAuctionRevealedBid[] memory, TermAuctionBid[] memory)
    {
        if (
            revealedBids.length +
                expiredRolloverBids.length +
                unrevealedBids.length !=
            bidCount
        ) {
            revert BidCountIncorrect(bidCount);
        }

        uint256 i;

        for (i = 0; i < expiredRolloverBids.length; ++i) {
            TermAuctionBid storage expiredRolloverBid = bids[
                expiredRolloverBids[i]
            ];
            if (expiredRolloverBid.amount == 0) {
                revert NonExistentBid(expiredRolloverBids[i]);
            }
            if (!expiredRolloverBid.isRollover) {
                revert NonRolloverBid(expiredRolloverBids[i]);
            }
            ITermRepoServicer pairOffServicer = ITermRepoServicer(
                expiredRolloverBid.rolloverPairOffTermRepoServicer
            );
            // NOTE: Include bid for assignment only if term repurchase window hasn't expired.
            // solhint-disable-next-line not-rely-on-time
            if (block.timestamp > pairOffServicer.endOfRepurchaseWindow()) {
                _processBidForAuction(expiredRolloverBid.id);
            } else {
                revert NonExpiredRolloverBid(expiredRolloverBid.id);
            }
        }

        TermAuctionBid[] memory revealedBidsInShortfall;
        uint256 auctionBidCount;
        uint256 unlockBidCount;
        uint256 revealedBidsInShortfallCount;

        (
            revealedBidsInShortfall,
            auctionBidCount,
            unlockBidCount,
            revealedBidsInShortfallCount
        ) = _processRevealedBidsForValidity(
            revealedBids,
            unrevealedBids.length
        );

        TermAuctionRevealedBid[]
            memory bidsForAuction = _fillRevealedBidsForAuctionClearing(
                revealedBids,
                auctionBidCount
            );
        TermAuctionBid[] memory bidsForUnlocking = new TermAuctionBid[](
            unlockBidCount
        );

        // Add unrevealed bids to bid array for unlocking
        uint256 bidsForUnlockingCounter = 0;
        for (i = 0; i < unrevealedBids.length; ++i) {
            TermAuctionBid storage unrevealedBid = bids[unrevealedBids[i]];
            if (unrevealedBid.amount == 0) {
                revert NonExistentBid(unrevealedBids[i]);
            }
            if (unrevealedBid.isRevealed) {
                revert BidRevealed(unrevealedBids[i]);
            }
            bidsForUnlocking[bidsForUnlockingCounter] = unrevealedBid;
            ++bidsForUnlockingCounter;
            _processBidForAuction(unrevealedBid.id);
        }

        for (i = 0; i < revealedBidsInShortfallCount; ++i) {
            bidsForUnlocking[bidsForUnlockingCounter] = revealedBidsInShortfall[
                i
            ];
            ++bidsForUnlockingCounter;
        }

        assert(bidCount == 0);

        return (bidsForAuction, bidsForUnlocking);
    }

    /// @param bid The TermAuctionBid to convert to TermAuctionRevealedBid
    /// @dev This does not check the hash of the revealed bid price
    function _truncateBidStruct(
        TermAuctionBid memory bid
    ) internal pure returns (TermAuctionRevealedBid memory revealed) {
        return
            TermAuctionRevealedBid({
                id: bid.id,
                bidder: bid.bidder,
                bidPriceRevealed: bid.bidPriceRevealed,
                amount: bid.amount,
                collateralAmounts: bid.collateralAmounts,
                purchaseToken: bid.purchaseToken,
                collateralTokens: bid.collateralTokens,
                isRollover: bid.isRollover,
                rolloverPairOffTermRepoServicer: bid
                    .rolloverPairOffTermRepoServicer
            });
    }

    function _processRevealedBidsForValidity(
        bytes32[] calldata revealedBids,
        uint256 unrevealedBidCount
    ) internal returns (TermAuctionBid[] memory, uint256, uint256, uint256) {
        uint256 auctionBidCount = revealedBids.length;
        uint256 unlockBidCount = unrevealedBidCount;

        TermAuctionBid[] memory revealedBidsInShortFall = new TermAuctionBid[](
            auctionBidCount
        );

        uint256 revealedBidsInShortFallCounter = 0;
        uint256 previousBidPrice = 0;

        for (uint256 i = 0; i < revealedBids.length; ++i) {
            TermAuctionBid storage revealedBid = bids[revealedBids[i]];
            if (revealedBid.amount == 0) {
                revert NonExistentBid(revealedBids[i]);
            }
            if (previousBidPrice > revealedBid.bidPriceRevealed) {
                revert RevealedBidsNotSorted();
            } else {
                previousBidPrice = revealedBid.bidPriceRevealed;
            }
            if (!revealedBid.isRevealed) {
                revert BidNotRevealed(revealedBid.id);
            }
            if (revealedBid.isRollover) {
                ITermRepoServicer pairOffServicer = ITermRepoServicer(
                    revealedBid.rolloverPairOffTermRepoServicer
                );
                // NOTE: Include bid for assignment only if term repurchase window hasn't expired.
                if (
                    // solhint-disable-next-line not-rely-on-time
                    block.timestamp > pairOffServicer.endOfRepurchaseWindow()
                ) {
                    revert RolloverBidExpired(revealedBid.id);
                }

                if (!_isRolloverStillValid(revealedBid, pairOffServicer)) {
                    ++unlockBidCount;
                    revealedBidsInShortFall[
                        revealedBidsInShortFallCounter
                    ] = revealedBid;
                    ++revealedBidsInShortFallCounter;
                    --auctionBidCount;
                    _processBidForAuction(revealedBid.id);
                    continue;
                }
            }

            // If bid is in shortfall, mark for unlocking if not a rollover
            if (
                _isInMaintenanceCollateralShortFall(
                    revealedBid.amount,
                    revealedBid.bidPriceRevealed,
                    revealedBid.collateralTokens,
                    revealedBid.collateralAmounts
                )
            ) {
                emitter.emitBidInShortfall(termAuctionId, revealedBid.id);

                ++unlockBidCount;
                revealedBidsInShortFall[
                    revealedBidsInShortFallCounter
                ] = revealedBid;
                ++revealedBidsInShortFallCounter;
                --auctionBidCount;
                _processBidForAuction(revealedBid.id);
            }
        }
        return (
            revealedBidsInShortFall,
            auctionBidCount,
            unlockBidCount,
            revealedBidsInShortFallCounter
        );
    }

    function _isRolloverStillValid(
        TermAuctionBid storage revealedBid,
        ITermRepoServicer pairOffServicer
    ) internal returns (bool) {
        uint256 borrowerRepurchaseObligation = pairOffServicer
            .getBorrowerRepurchaseObligation(revealedBid.bidder);

        if (borrowerRepurchaseObligation == 0) {
            return false;
        }

        uint256 servicingFeeProRatedMantissa = mul_(
            Exp({mantissa: dayCountFractionMantissa}),
            Exp({mantissa: termRepoServicer.servicingFee()})
        ).mantissa;

        uint256 maxRolloverAmount = truncate(
            div_(
                Exp({mantissa: borrowerRepurchaseObligation * expScale}),
                Exp({mantissa: expScale - servicingFeeProRatedMantissa})
            )
        );
        if (maxRolloverAmount < revealedBid.amount) {
            revealedBid.amount = maxRolloverAmount;
        }

        ///@dev get proportional collateral amount to collateralize rollover

        uint256 proportionMantissa = (revealedBid.amount * expScale) /
            maxRolloverAmount;

        ITermRepoCollateralManager pairOffCollateralManager = pairOffServicer
            .termRepoCollateralManager();

        (
            address[] memory pairOffCollateralTokens,
            uint256[] memory collateralAmounts
        ) = pairOffCollateralManager.getCollateralBalances(revealedBid.bidder);

        uint256 collateralAmount;

        for (uint256 i = 0; i < pairOffCollateralTokens.length; ++i) {
            collateralAmount = mul_ScalarTruncate(
                Exp({mantissa: proportionMantissa}),
                collateralAmounts[i]
            );
            if (collateralAmount != revealedBid.collateralAmounts[i]) {
                revealedBid.collateralAmounts[i] = collateralAmount;
            }
        }
        emitter.emitBidLocked(termAuctionId, revealedBid, address(0));

        return true;
    }

    function _isInInitialCollateralShortFall(
        uint256 bidAmount,
        address[] memory collateralTokens_,
        uint256[] memory collateralAmounts
    ) internal view returns (bool) {
        Exp memory bidAmountUSDValue = termPriceOracle.usdValueOfTokens(
            purchaseToken,
            bidAmount
        );
        Exp memory haircutUSDTotalCollateralValue = Exp({mantissa: 0});
        for (uint256 i = 0; i < collateralTokens_.length; ++i) {
            address collateralToken = collateralTokens_[i];
            uint256 initialCollateralRatio = termRepoCollateralManager
                .initialCollateralRatios(collateralToken);
            if (collateralAmounts[i] == 0) {
                continue;
            }
            Exp memory additionalHairCutUSDCollateralValue = div_(
                termPriceOracle.usdValueOfTokens(
                    collateralToken,
                    collateralAmounts[i]
                ),
                Exp({mantissa: initialCollateralRatio})
            );
            haircutUSDTotalCollateralValue = add_(
                additionalHairCutUSDCollateralValue,
                haircutUSDTotalCollateralValue
            );
        }
        if (lessThanExp(haircutUSDTotalCollateralValue, bidAmountUSDValue)) {
            return true;
        }
        return false;
    }

    function _isInMaintenanceCollateralShortFall(
        uint256 bidAmount,
        uint256 bidPrice,
        address[] memory collateralTokens_,
        uint256[] memory collateralAmounts
    ) internal view returns (bool) {
        uint256 repurchasePrice;
        if (bidPrice == 0) {
            repurchasePrice = bidAmount;
        } else {
            Exp memory repurchaseFactor = add_(
                Exp({mantissa: expScale}),
                mul_(
                    Exp({mantissa: dayCountFractionMantissa}),
                    Exp({mantissa: bidPrice})
                )
            );

            repurchasePrice = truncate(
                mul_(Exp({mantissa: bidAmount * expScale}), repurchaseFactor)
            );
        }

        Exp memory repurchasePriceUSDValue = termPriceOracle.usdValueOfTokens(
            purchaseToken,
            repurchasePrice
        );
        Exp memory haircutUSDTotalCollateralValue = Exp({mantissa: 0});
        for (uint256 i = 0; i < collateralTokens_.length; ++i) {
            address collateralToken = collateralTokens_[i];
            uint256 maintenanceCollateralRatio = termRepoCollateralManager
                .maintenanceCollateralRatios(collateralToken);
            if (collateralAmounts[i] == 0) {
                continue;
            }
            Exp memory additionalHairCutUSDCollateralValue = div_(
                termPriceOracle.usdValueOfTokens(
                    collateralToken,
                    collateralAmounts[i]
                ),
                Exp({mantissa: maintenanceCollateralRatio})
            );
            haircutUSDTotalCollateralValue = add_(
                additionalHairCutUSDCollateralValue,
                haircutUSDTotalCollateralValue
            );
        }
        if (
            lessThanExp(haircutUSDTotalCollateralValue, repurchasePriceUSDValue)
        ) {
            return true;
        }
        return false;
    }

    function _fillRevealedBidsForAuctionClearing(
        bytes32[] calldata revealedBids,
        uint256 auctionBidCount
    ) internal returns (TermAuctionRevealedBid[] memory) {
        TermAuctionRevealedBid[]
            memory bidsForAuction = new TermAuctionRevealedBid[](
                auctionBidCount
            );

        // fill auction bids array
        uint256 bidsForAuctionCounter = 0;
        for (uint256 i = 0; i < revealedBids.length; ++i) {
            TermAuctionBid storage revealedBid = bids[revealedBids[i]];

            if (revealedBid.amount == 0) {
                continue;
            }

            bidsForAuction[bidsForAuctionCounter] = _truncateBidStruct(
                revealedBid
            );

            bidsForAuctionCounter++;
            _processBidForAuction(revealedBid.id);
        }
        return bidsForAuction;
    }

    function _generateBidId(
        bytes32 id,
        address user
    ) internal view returns (bytes32) {
        bytes32 generatedId = keccak256(
            abi.encodePacked(id, user, address(this))
        );
        if (bids[generatedId].amount != 0) {
            revert GeneratingExistingBid(generatedId);
        }
        return generatedId;
    }

    function _processBidForAuction(bytes32 id) internal {
        delete bids[id];
        bidCount -= 1;
    }

    // ========================================================================
    // = Pausable =============================================================
    // ========================================================================

    function pauseLocking() external onlyRole(ADMIN_ROLE) {
        lockingPaused = true;
        emitter.emitBidLockingPaused(termAuctionId, termRepoId);
    }

    function unpauseLocking() external onlyRole(ADMIN_ROLE) {
        lockingPaused = false;
        emitter.emitBidLockingUnpaused(termAuctionId, termRepoId);
    }

    function pauseUnlocking() external onlyRole(ADMIN_ROLE) {
        unlockingPaused = true;
        emitter.emitBidUnlockingPaused(termAuctionId, termRepoId);
    }

    function unpauseUnlocking() external onlyRole(ADMIN_ROLE) {
        unlockingPaused = false;
        emitter.emitBidUnlockingUnpaused(termAuctionId, termRepoId);
    }

    ///@dev required override by the OpenZeppelin UUPS module
    ///@param impl new impl address for proxy upgrade
    function _authorizeUpgrade(
        address impl
    ) internal override onlyRole(DEVOPS_ROLE) {
        emitter.emitTermContractUpgraded(address(this), impl);
    }
}

contracts/TermAuctionOfferLocker.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermAuction} from "./interfaces/ITermAuction.sol";
import {ITermAuctionOfferLocker} from "./interfaces/ITermAuctionOfferLocker.sol";
import {ITermAuctionOfferLockerErrors} from "./interfaces/ITermAuctionOfferLockerErrors.sol";
import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {TermAuctionOffer} from "./lib/TermAuctionOffer.sol";
import {TermContractsPausable} from "./lib/TermContractsPausable.sol";
import {TermAuctionOfferSubmission} from "./lib/TermAuctionOfferSubmission.sol";
import {TermAuctionRevealedOffer} from "./lib/TermAuctionRevealedOffer.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Offer Locker
/// @notice This contract handles and proceesses Term Auction offer submissions
/// @dev This contract belongs to the Term Auction group of contracts and is specific to a Term Repo deployment
contract TermAuctionOfferLocker is
    ITermAuctionOfferLocker,
    ITermAuctionOfferLockerErrors,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    TermContractsPausable,
    Versionable
{
    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================

    uint256 public constant MAX_OFFER_PRICE = 10000e16; // 10,000%

    uint256 public constant MAX_OFFER_COUNT = 150;

    // ========================================================================
    // = Access Roles  ========================================================
    // ========================================================================
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant AUCTIONEER_ROLE = keccak256("AUCTIONEER_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant DIAMOND_ROLE = keccak256("DIAMOND_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    // Auction configuration.
    bytes32 public termRepoId;
    bytes32 public termAuctionId;
    uint256 public auctionStartTime;
    uint256 public revealTime;
    uint256 public auctionEndTime;
    uint256 public minimumTenderAmount;
    IERC20 public purchaseToken;
    mapping(IERC20 => bool) public collateralTokens;
    ITermRepoServicer public termRepoServicer;
    ITermEventEmitter internal emitter;
    ITermAuction public termAuction;

    // Auction in-progress state
    mapping(bytes32 => TermAuctionOffer) internal offers;
    uint256 public offerCount;
    bool internal termContractPaired;
    bool public lockingPaused;
    bool public unlockingPaused;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================

    modifier onlyWhileAuctionOpen() {
        if (
            // solhint-disable-next-line not-rely-on-time
            block.timestamp > revealTime || block.timestamp < auctionStartTime
        ) {
            revert AuctionNotOpen();
        }
        _;
    }
    modifier onlyWhileAuctionRevealing() {
        if (
            // solhint-disable-next-line not-rely-on-time
            block.timestamp < revealTime
        ) {
            revert AuctionNotRevealing();
        }
        _;
    }

    modifier onlyOfferor(address offeror, address authedUser) {
        if (authedUser != offeror) {
            revert OfferNotOwned();
        }
        _;
    }
    modifier onlyExistingOffer(bytes32 id) {
        if (offers[id].amount == 0) {
            revert NonExistentOffer(id);
        }
        _;
    }
    modifier whenLockingNotPaused() {
        if (lockingPaused) {
            revert LockingPaused();
        }
        _;
    }
    modifier whenUnlockingNotPaused() {
        if (unlockingPaused) {
            revert UnlockingPaused();
        }
        _;
    }

    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    // ========================================================================
    // = Deploy (https://docs.openzeppelin.com/contracts/4.x/upgradeable) =====
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string calldata termRepoId_,
        string calldata auctionId_,
        uint256 auctionStartTime_,
        uint256 revealTime_,
        uint256 auctionEndTime_,
        uint256 minimumTenderAmount_,
        IERC20 purchaseToken_,
        IERC20[] memory collateralTokens_,
        address termInitializer_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();
        ReentrancyGuardUpgradeable.__ReentrancyGuard_init();

        _grantRole(INITIALIZER_ROLE, termInitializer_);

        if (auctionStartTime_ > revealTime_) {
            revert AuctionStartsAfterReveal(auctionStartTime_, revealTime_);
        }

        termRepoId = keccak256(abi.encodePacked(termRepoId_));
        termAuctionId = keccak256(abi.encodePacked(auctionId_));

        auctionStartTime = auctionStartTime_;
        revealTime = revealTime_;
        auctionEndTime = auctionEndTime_;
        minimumTenderAmount = minimumTenderAmount_;
        purchaseToken = purchaseToken_;
        address[] memory collateralTokenAddresses = new address[](
            collateralTokens_.length
        );
        for (uint8 i = 0; i < collateralTokens_.length; ++i) {
            collateralTokens[collateralTokens_[i]] = true;
            collateralTokenAddresses[i] = address(collateralTokens_[i]);
        }

        offerCount = 0;
        termContractPaired = false;
    }

    function pairTermContracts(
        address termAuction_,
        ITermEventEmitter emitter_,
        ITermRepoServicer termRepoServicer_,
        address devopsMultisig_,
        address adminWallet_,
        address termDiamond_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        termAuction = ITermAuction(termAuction_);
        _grantRole(AUCTIONEER_ROLE, termAuction_);
        _grantRole(DEVOPS_ROLE, devopsMultisig_);
        _grantRole(ADMIN_ROLE, adminWallet_);
        _grantRole(DIAMOND_ROLE, termDiamond_);

        emitter = emitter_;

        termRepoServicer = termRepoServicer_;

        emitter.emitTermAuctionOfferLockerInitialized(
            termRepoId,
            termAuctionId,
            address(this),
            auctionStartTime,
            revealTime,
            MAX_OFFER_PRICE,
            minimumTenderAmount
        );
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @param offerSubmissions An array of Term Auction offer submissions to lend an amount of money at rate no lower than the offer rate
    /// @param referralAddress A user address that referred the submitter of this offer
    /// @return A bytes32 array of unique on chain offer ids.
    function lockOffersWithReferral(
        TermAuctionOfferSubmission[] calldata offerSubmissions,
        address referralAddress
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        returns (bytes32[] memory)
    {
        if (msg.sender == referralAddress) {
            revert InvalidSelfReferral();
        }

        bytes32[] memory offerIds = new bytes32[](offerSubmissions.length);

        for (uint256 i = 0; i < offerSubmissions.length; ++i) {
            TermAuctionOffer storage offer = _lock(
                offerSubmissions[i],
                msg.sender,
                msg.sender
            );
            offerIds[i] = offer.id;
            emitter.emitOfferLocked(
                termAuctionId,
                offer.id,
                offer.offeror,
                offer.offerPriceHash,
                offer.amount,
                offer.purchaseToken,
                referralAddress
            );
        }
        return offerIds;
    }

    /// @param offeror The address of the offeror
    /// @param offerSubmissions An array of Term Auction offer submissions to lend an amount of money at rate no lower than the offer rate
    /// @param referralAddress A user address that referred the submitter of this offer
    /// @return A bytes32 array of unique on chain offer ids.
    function lockOffersWithReferral(
        address offeror,
        TermAuctionOfferSubmission[] calldata offerSubmissions,
        address referralAddress
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        onlyRole(DIAMOND_ROLE)
        returns (bytes32[] memory)
    {
        if (offeror == referralAddress) {
            revert InvalidSelfReferral();
        }

        bytes32[] memory offerIds = new bytes32[](offerSubmissions.length);

        for (uint256 i = 0; i < offerSubmissions.length; ++i) {
            TermAuctionOffer storage offer = _lock(
                offerSubmissions[i],
                offeror,
                msg.sender
            );
            offerIds[i] = offer.id;
            emitter.emitOfferLocked(
                termAuctionId,
                offer.id,
                offer.offeror,
                offer.offerPriceHash,
                offer.amount,
                offer.purchaseToken,
                referralAddress
            );
        }
        return offerIds;
    }

    /// @param offerSubmissions An array of offer submissions
    /// @return A bytes32 array of unique on chain offer ids.
    function lockOffers(
        TermAuctionOfferSubmission[] memory offerSubmissions
    )
        external
        onlyWhileAuctionOpen
        whenLockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
        returns (bytes32[] memory)
    {
        bytes32[] memory offerIds = new bytes32[](offerSubmissions.length);
        for (uint256 i = 0; i < offerSubmissions.length; ++i) {
            TermAuctionOffer storage offer = _lock(
                offerSubmissions[i],
                msg.sender,
                msg.sender
            );
            offerIds[i] = offer.id;
            emitter.emitOfferLocked(
                termAuctionId,
                offer.id,
                offer.offeror,
                offer.offerPriceHash,
                offer.amount,
                offer.purchaseToken,
                address(0)
            );
        }
        return offerIds;
    }

    /// @param id An offer Id
    /// @return A struct containing the details of the locked offer
    function lockedOffer(
        bytes32 id
    ) external view returns (TermAuctionOffer memory) {
        return offers[id];
    }

    /// @param ids An array offer ids to reveal
    /// @param prices An array of the offer prices to reveal
    /// @param nonces An array of nonce values to generate bid price hashes
    function revealOffers(
        bytes32[] calldata ids,
        uint256[] calldata prices,
        uint256[] calldata nonces
    ) external onlyWhileAuctionRevealing {
        for (uint256 i = 0; i < ids.length; ++i) {
            _revealOffer(ids[i], prices[i], nonces[i]);
        }
    }

    /// @notice unlockOffers unlocks multiple offers and returns funds to the offeror
    /// @param ids An array of offer ids
    function unlockOffers(
        bytes32[] calldata ids
    )
        external
        whenUnlockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
    {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp < auctionStartTime) {
            revert AuctionNotOpen();
        }
        // solhint-disable-next-line not-rely-on-time
        if (
            block.timestamp > revealTime &&
            !termAuction.auctionCancelledForWithdrawal()
        ) {
            revert AuctionNotOpen();
        }

        for (uint256 i = 0; i < ids.length; ++i) {
            if (offers[ids[i]].amount == 0) {
                revert NonExistentOffer(ids[i]);
            }
            if (msg.sender != offers[ids[i]].offeror) {
                revert OfferNotOwned();
            }
            _unlock(ids[i], msg.sender);
        }
    }

    /// @notice unlockOffers unlocks multiple offers and returns funds to the offeror
    /// @param ids An array of offer ids
    function unlockOffers(
        address offeror,
        bytes32[] calldata ids
    )
        external
        onlyRole(DIAMOND_ROLE)
        whenUnlockingNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        nonReentrant
    {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp < auctionStartTime) {
            revert AuctionNotOpen();
        }
        // solhint-disable-next-line not-rely-on-time
        if (
            block.timestamp > revealTime &&
            !termAuction.auctionCancelledForWithdrawal()
        ) {
            revert AuctionNotOpen();
        }

        for (uint256 i = 0; i < ids.length; ++i) {
            if (offers[ids[i]].amount == 0) {
                revert NonExistentOffer(ids[i]);
            }
            if (offeror != offers[ids[i]].offeror) {
                revert OfferNotOwned();
            }
            _unlock(ids[i], offeror);
        }
    }

    // =========================================================================
    // = Auction Interface/API =================================================
    // =========================================================================

    /// @param revealedOffers An array of the revealed offer ids
    /// @param unrevealedOffers An array of the unrevealed offer ids
    /// @return An array of TermAuctionRevealedOffer structs containing details of the revealed offers
    /// @return An array of TermAuctionOffer structs containing details of the unrevealed offers
    function getAllOffers(
        bytes32[] calldata revealedOffers,
        bytes32[] calldata unrevealedOffers
    )
        external
        onlyRole(AUCTIONEER_ROLE)
        returns (TermAuctionRevealedOffer[] memory, TermAuctionOffer[] memory)
    {
        if (revealedOffers.length + unrevealedOffers.length != offerCount) {
            revert OfferCountIncorrect(offerCount);
        }

        TermAuctionRevealedOffer[]
            memory offersForAuction = new TermAuctionRevealedOffer[](
                revealedOffers.length
            );
        TermAuctionOffer[] memory unrevealed = new TermAuctionOffer[](
            unrevealedOffers.length
        );

        uint256 j = 0;
        uint256 previousOfferPrice = 0;
        for (uint256 i = 0; i < revealedOffers.length; ++i) {
            TermAuctionOffer storage revealedOffer = offers[revealedOffers[i]];
            if (revealedOffer.amount == 0) {
                revert NonExistentOffer(revealedOffers[i]);
            }
            if (!revealedOffer.isRevealed) {
                revert OfferNotRevealed(revealedOffer.id);
            }
            if (previousOfferPrice > revealedOffer.offerPriceRevealed) {
                revert RevealedOffersNotSorted();
            } else {
                previousOfferPrice = revealedOffer.offerPriceRevealed;
            }

            offersForAuction[j] = _truncateOfferStruct(
                revealedOffer,
                revealedOffer.offerPriceRevealed
            );
            j++;
            _processOfferForAuction(revealedOffer.id);
        }
        uint256 k = 0;
        for (uint256 i = 0; i < unrevealedOffers.length; ++i) {
            TermAuctionOffer storage unrevealedOffer = offers[
                unrevealedOffers[i]
            ];
            if (unrevealedOffer.amount == 0) {
                revert NonExistentOffer(unrevealedOffers[i]);
            }
            if (unrevealedOffer.isRevealed) {
                revert OfferRevealed(unrevealedOffers[i]);
            }
            unrevealed[k] = unrevealedOffer;
            ++k;
            _processOfferForAuction(unrevealedOffer.id);
        }

        assert(offerCount == 0);

        return (offersForAuction, unrevealed);
    }

    /// @param id An offer Id
    /// @param offeror Address of the offeror
    /// @param amount The amount of purchase tokens to unlock
    function unlockOfferPartial(
        bytes32 id,
        address offeror,
        uint256 amount
    ) public onlyRole(AUCTIONEER_ROLE) {
        termRepoServicer.unlockOfferAmount(offeror, amount);
        emitter.emitOfferUnlocked(termAuctionId, id);
    }

    // ========================================================================
    // = Helpers ==============================================================
    // ========================================================================

    function _lock(
        TermAuctionOfferSubmission memory offerSubmission,
        address authedUser,
        address sender
    )
        internal
        onlyOfferor(offerSubmission.offeror, authedUser)
        returns (TermAuctionOffer storage)
    {
        if (offerCount >= MAX_OFFER_COUNT) {
            revert MaxOfferCountReached();
        }
        bool offerExists = offers[offerSubmission.id].amount != 0;
        bytes32 offerId;
        if (offerExists) {
            if (offers[offerSubmission.id].offeror != offerSubmission.offeror) {
                revert OfferNotOwned();
            }
            offerId = offerSubmission.id;
        } else {
            offerId = _generateOfferId(offerSubmission.id, authedUser);
        }
        if (address(purchaseToken) != offerSubmission.purchaseToken) {
            revert PurchaseTokenNotApproved(offerSubmission.purchaseToken);
        }
        if (offerSubmission.amount < minimumTenderAmount) {
            revert OfferAmountTooLow(offerSubmission.amount);
        }

        uint256 oldLockedAmount = offers[offerId].amount;

        // Store offer in auction contract.
        offers[offerId] = TermAuctionOffer({
            id: offerId,
            offeror: offerSubmission.offeror,
            offerPriceRevealed: 0,
            offerPriceHash: offerSubmission.offerPriceHash,
            amount: offerSubmission.amount,
            purchaseToken: offerSubmission.purchaseToken,
            isRevealed: false
        });
        if (!offerExists) {
            offerCount += 1;
        }

        // Calculate the amount of purchase tokens to lock.
        if (oldLockedAmount < offerSubmission.amount) {
            termRepoServicer.lockOfferAmount(
                sender,
                offerSubmission.offeror,
                offerSubmission.amount - oldLockedAmount
            );
        } else if (oldLockedAmount > offerSubmission.amount) {
            termRepoServicer.unlockOfferAmount(
                offerSubmission.offeror,
                oldLockedAmount - offerSubmission.amount
            );
        }

        return offers[offerId];
    }

    function _unlock(bytes32 id, address offeror) internal {
        uint256 amountToUnlock = offers[id].amount;

        delete offers[id];
        offerCount -= 1;

        emitter.emitOfferUnlocked(termAuctionId, id);

        termRepoServicer.unlockOfferAmount(offeror, amountToUnlock);
    }

    /// @dev Will revert if either the price does not match the offer price or is greater than the max offer price
    /// @param id An offer Id
    /// @param price The price of the offer to reveal
    /// @param nonce The user provided nonce value to generate the bid price hash
    function _revealOffer(bytes32 id, uint256 price, uint256 nonce) internal {
        // Check that price hasn't been modified/revealed.
        if (keccak256(abi.encode(price, nonce)) != offers[id].offerPriceHash) {
            revert OfferPriceModified();
        }
        if (price > MAX_OFFER_PRICE) {
            revert TenderPriceTooHigh(id, MAX_OFFER_PRICE);
        }

        offers[id].offerPriceRevealed = price;
        offers[id].isRevealed = true;

        emitter.emitOfferRevealed(termAuctionId, id, price);
    }

    function _generateOfferId(
        bytes32 id,
        address user
    ) internal view returns (bytes32) {
        bytes32 generatedId = keccak256(
            abi.encodePacked(id, user, address(this))
        );
        if (offers[generatedId].amount != 0) {
            revert GeneratingExistingOffer(generatedId);
        }
        return generatedId;
    }

    function _processOfferForAuction(bytes32 id) internal {
        delete offers[id];
        offerCount -= 1;
    }

    /// @param hidden TermAuctionOffer to convert to TermAuctionRevealedOffer
    /// @param price The revealed price of the offer
    /// @dev This does not check the hash of the revealed offer price
    function _truncateOfferStruct(
        TermAuctionOffer memory hidden,
        uint256 price
    ) internal pure returns (TermAuctionRevealedOffer memory revealed) {
        return
            TermAuctionRevealedOffer({
                id: hidden.id,
                offeror: hidden.offeror,
                offerPriceRevealed: price,
                amount: hidden.amount,
                purchaseToken: hidden.purchaseToken
            });
    }

    // ========================================================================
    // = Pausable =============================================================
    // ========================================================================

    function pauseLocking() external onlyRole(ADMIN_ROLE) {
        lockingPaused = true;
        emitter.emitOfferLockingPaused(termAuctionId, termRepoId);
    }

    function unpauseLocking() external onlyRole(ADMIN_ROLE) {
        lockingPaused = false;
        emitter.emitOfferLockingUnpaused(termAuctionId, termRepoId);
    }

    function pauseUnlocking() external onlyRole(ADMIN_ROLE) {
        unlockingPaused = true;
        emitter.emitOfferUnlockingPaused(termAuctionId, termRepoId);
    }

    function unpauseUnlocking() external onlyRole(ADMIN_ROLE) {
        unlockingPaused = false;
        emitter.emitOfferUnlockingUnpaused(termAuctionId, termRepoId);
    }

    ///@dev required override by the OpenZeppelin UUPS module
    ///@param impl new impl address for proxy upgrade
    function _authorizeUpgrade(
        address impl
    ) internal override onlyRole(DEVOPS_ROLE) {
        emitter.emitTermContractUpgraded(address(this), impl);
    }
}

contracts/TermController.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermController} from "./interfaces/ITermController.sol";
import {ITermControllerEvents} from "./interfaces/ITermControllerEvents.sol";

import {TermAuctionResults} from "./lib/TermAuctionResults.sol";
import {AuctionMetadata} from "./lib/AuctionMetadata.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Controller
/// @notice This contract manages Term Finance protocol permissions and controls
/// @dev This contract operates at the protocol level and governs all instances of a Term Repo
contract TermController is
    ITermController,
    ITermControllerEvents,
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    Versionable
{
    // ========================================================================
    // = Access Roles =========================================================
    // ========================================================================

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant AUCTION_ROLE = keccak256("AUCTION_ROLE");
    bytes32 public constant CONTROLLER_ADMIN_ROLE =
        keccak256("CONTROLLER_ADMIN_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");
    bytes32 public constant FACTORY_DEPLOYER_ROLE =
        keccak256("FACTORY_DEPLOYER_ROLE");
    bytes32 public constant SPECIALIST_ROLE = keccak256("SPECIALIST_ROLE");

    // ========================================================================
    // = State Variables ======================================================
    // ========================================================================

    // Pause state for all Term Finance contracts
    bool public termContractsPaused;

    // Term Finance Treasury Wallet Address
    address internal treasuryWallet;

    // Term Finance Protocol Reserves
    address internal protocolReserveWallet;

    // Mapping which returns true for contract addresses deployed by Term Finance Protocol
    mapping(address => bool) internal termAddresses;

    // Mapping which returns true for term repo contract addresses deployed by factory
    mapping(address => bool) internal factoryDeployedAddresses;

    // Mapping which returns true for external contract addresses approved for integration
    mapping(address => bool) internal approvedExternalAddresses;

    // Mapping which returns true for term repo ids registered in Controller
    mapping(bytes32 => bool) public registeredRepoIds;

    // Mapping which returns true for term auction ids registered in Controller
    mapping(bytes32 => bool) public registeredAuctionIds;

    // Mapping which returns a TermAuctionResults object for each termId.
    mapping(bytes32 => TermAuctionResults) internal termAuctionResults;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================

    modifier onlyInitializerOrFactoryDeployer() {
        require(
            hasRole(INITIALIZER_ROLE, msg.sender) ||
                hasRole(FACTORY_DEPLOYER_ROLE, msg.sender),
            "Unauthorized"
        );
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address treasuryWallet_,
        address protocolReserveWallet_,
        address controllerAdminWallet_,
        address devopsWallet_,
        address adminWallet_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();

        require(
            controllerAdminWallet_ != address(0),
            "controller admin is zero address"
        );

        require(devopsWallet_ != address(0), "devops wallet is zero address");

        require(adminWallet_ != address(0), "admin wallet is zero address");

        _grantRole(CONTROLLER_ADMIN_ROLE, controllerAdminWallet_);
        _grantRole(DEVOPS_ROLE, devopsWallet_);
        _grantRole(ADMIN_ROLE, adminWallet_);

        require(treasuryWallet_ != address(0), "treasury is zero address");
        treasuryWallet = treasuryWallet_;

        require(
            protocolReserveWallet_ != address(0),
            "reserve is zero address"
        );
        protocolReserveWallet = protocolReserveWallet_;
    }

    function pairInitializer(
        address initializer
    ) external onlyRole(ADMIN_ROLE) {
        _grantRole(INITIALIZER_ROLE, initializer);
    }

    function pairFactoryDeployer(
        address factoryDeployer
    ) external onlyRole(ADMIN_ROLE) {
        _grantRole(FACTORY_DEPLOYER_ROLE, factoryDeployer);
    }

    function pairAuction(
        address auction
    ) external onlyInitializerOrFactoryDeployer {
        _grantRole(AUCTION_ROLE, auction);
    }

    // ========================================================================
    // = Interface/API ========================================================
    // ========================================================================

    /// @notice External view function which returns contract address of treasury wallet
    function getTreasuryAddress() external view returns (address) {
        return treasuryWallet;
    }

    /// @notice External view function which returns contract address of protocol reserve
    /// @return The protocol reserve address
    function getProtocolReserveAddress() external view returns (address) {
        return protocolReserveWallet;
    }

    function getTermAuctionResults(
        bytes32 termRepoId
    )
        external
        view
        returns (AuctionMetadata[] memory auctionMetadata, uint8 numOfAuctions)
    {
        auctionMetadata = termAuctionResults[termRepoId].auctionMetadata;
        numOfAuctions = termAuctionResults[termRepoId].numOfAuctions;
    }

    /// @notice External view function which returns whether contract address is deployed by Term Finance Protocol
    /// @param contractAddress The input contract address to query
    /// @return Whether the given address is deployed by Term Finance Protocol
    function isTermDeployed(
        address contractAddress
    ) external view returns (bool) {
        return _isTermDeployed(contractAddress);
    }

    /// @notice External view function which returns whether contract address is deployed by a Term Finance factory
    /// @param contractAddress The input contract address to query
    /// @return Whether the given address is deployed by a Term Finance factory
    function isFactoryDeployed(
        address contractAddress
    ) external view returns (bool) {
        return _isFactoryDeployed(contractAddress);
    }

    /// @notice External view function which returns whether contract address is approved for integration
    /// @param contractAddress The input contract address to query
    /// @return Whether the given address is approved for integration
    function isTermApproved(
        address contractAddress
    ) external view returns (bool) {
        return _isTermApproved(contractAddress);
    }

    /// @param authedUser The address of user to check access for mint exposure
    function verifyMintExposureAccess(
        address authedUser
    ) external view returns (bool) {
        return hasRole(SPECIALIST_ROLE, authedUser);
    }

    // ========================================================================
    // = Admin Functions ======================================================
    // ========================================================================

    /// @notice Admin function to update the Term Finance treasury wallet address
    /// @param newTreasuryWallet The new treasury address
    function updateTreasuryAddress(
        address newTreasuryWallet
    ) external onlyRole(DEVOPS_ROLE) {
        require(
            newTreasuryWallet != treasuryWallet,
            "No change in treasury address"
        );

        address oldTreasuryWallet = treasuryWallet;

        treasuryWallet = newTreasuryWallet;

        emit TreasuryAddressUpdated(oldTreasuryWallet, treasuryWallet);
    }

    /// @notice Admin function to update the Term Finance protocol reserve wallet address
    /// @param newProtocolReserveWallet The new protocol reserve wallet address
    function updateProtocolReserveAddress(
        address newProtocolReserveWallet
    ) external onlyRole(DEVOPS_ROLE) {
        require(
            newProtocolReserveWallet != protocolReserveWallet,
            "No change in protocol reserve address"
        );

        address oldProtocolReserveWallet = protocolReserveWallet;

        protocolReserveWallet = newProtocolReserveWallet;

        emit ProtocolReserveAddressUpdated(
            oldProtocolReserveWallet,
            protocolReserveWallet
        );
    }

    /// @notice Admin function to update the designated controller admin wallet that calls markTermDeployed
    /// @param oldControllerAdminWallet The current controller admin wallet to revoke permissions for
    /// @param newControllerAdminWallet The new controller admin wallet to grant permissions for
    function updateControllerAdminWallet(
        address oldControllerAdminWallet,
        address newControllerAdminWallet
    ) external onlyRole(DEVOPS_ROLE) {
        require(
            oldControllerAdminWallet != address(0),
            "Old Controller Admin Wallet cannot be zero address"
        );
        require(
            newControllerAdminWallet != address(0),
            "New Controller Admin Wallet cannot be zero address"
        );
        require(
            hasRole(CONTROLLER_ADMIN_ROLE, oldControllerAdminWallet),
            "incorrect old controller admin wallet address"
        );

        _revokeRole(CONTROLLER_ADMIN_ROLE, oldControllerAdminWallet);

        _grantRole(CONTROLLER_ADMIN_ROLE, newControllerAdminWallet);
    }

    /// @notice Admin function to add a new Term Finance contract to Controller
    /// @param termContract The new term contract address
    function markTermDeployed(
        address termContract
    ) external onlyRole(CONTROLLER_ADMIN_ROLE) {
        require(!_isTermDeployed(termContract), "Contract is already in Term");

        termAddresses[termContract] = true;
    }

    /// @notice Admin function to remove a contract from Controller
    /// @param termContract The new term contract address
    function unmarkTermDeployed(
        address termContract
    ) external onlyRole(CONTROLLER_ADMIN_ROLE) {
        require(_isTermDeployed(termContract), "Contract is not in Term");

        delete termAddresses[termContract];
    }

    /// @notice Admin function to add a new factory-deployed contract to Controller
    /// @param factoryDeployedContract The factory-deployed contract address
    function markTermFactoryDeployed(
        address factoryDeployedContract
    ) external onlyRole(FACTORY_DEPLOYER_ROLE) {
        require(
            !_isFactoryDeployed(factoryDeployedContract),
            "Contract is already marked deployed by factory"
        );

        factoryDeployedAddresses[factoryDeployedContract] = true;
    }

    /// @notice Admin function to remove a factory-deployed contract from Controller
    /// @param factoryDeployedContract The factory-deployed contract address
    function unmarkTermFactoryDeployed(
        address factoryDeployedContract
    ) external onlyRole(CONTROLLER_ADMIN_ROLE) {
        require(
            _isFactoryDeployed(factoryDeployedContract),
            "Contract is not marked deployed by factory"
        );

        delete factoryDeployedAddresses[factoryDeployedContract];
    }

    /// @notice Admin function to add a new term repo id to Controller
    /// @param repoId The new term repo id
    function registerRepoId(
        bytes32 repoId
    ) external onlyInitializerOrFactoryDeployer {
        registeredRepoIds[repoId] = true;
    }

    /// @notice Admin function to add a new term auction id to Controller
    /// @param auctionId The new term auction id
    function registerAuctionId(
        bytes32 auctionId
    ) external onlyInitializerOrFactoryDeployer {
        registeredAuctionIds[auctionId] = true;
    }

    /// @notice Admin function to add a new external contract to Controller
    /// @param externalContract The new external contract address
    function markTermApproved(
        address externalContract
    ) external onlyRole(ADMIN_ROLE) {
        require(
            !approvedExternalAddresses[externalContract],
            "Contract is already approved"
        );
        approvedExternalAddresses[externalContract] = true;
    }

    /// @notice Admin function to remove an external contract from Controller
    /// @param externalContract The new external contract address
    function unmarkTermApproved(
        address externalContract
    ) external onlyRole(ADMIN_ROLE) {
        require(
            approvedExternalAddresses[externalContract],
            "Contract is not approved"
        );
        delete approvedExternalAddresses[externalContract];
    }

    /// @param authedUser The address of user granted access to create mint exposure
    function grantMintExposureAccess(
        address authedUser
    ) external onlyRole(ADMIN_ROLE) {
        _grantRole(SPECIALIST_ROLE, authedUser);
    }

    /// @param revokedUser The address of user to revoke access to create mint exposure
    function revokeMintExposureAccess(
        address revokedUser
    ) external onlyRole(ADMIN_ROLE) {
        _revokeRole(SPECIALIST_ROLE, revokedUser);
    }

    /// @notice Pauses all Term Finance contracts
    /// @dev Sets the global pause state to true, halting contract operations
    function pauseTermContracts() external onlyRole(ADMIN_ROLE) {
        termContractsPaused = true;
    }

    /// @notice Unpauses all Term Finance contracts
    /// @dev Sets the global pause state to false, resuming contract operations
    function unpauseTermContracts() external onlyRole(ADMIN_ROLE) {
        termContractsPaused = false;
    }

    function recordAuctionResult(
        bytes32 termRepoId,
        bytes32 termAuctionId,
        uint256 auctionClearingRate
    ) external onlyRole(AUCTION_ROLE) {
        TermAuctionResults storage term = termAuctionResults[termRepoId];
        AuctionMetadata memory auctionMetadata = AuctionMetadata({
            termAuctionId: termAuctionId,
            auctionClearingRate: auctionClearingRate,
            auctionClearingBlockTimestamp: block.timestamp
        });
        term.auctionMetadata.push(auctionMetadata);
        term.numOfAuctions++;
    }

    function _isTermDeployed(
        address contractAddress
    ) private view returns (bool) {
        return termAddresses[contractAddress];
    }

    function _isFactoryDeployed(
        address contractAddress
    ) private view returns (bool) {
        return factoryDeployedAddresses[contractAddress];
    }

    function _isTermApproved(
        address contractAddress
    ) private view returns (bool) {
        return approvedExternalAddresses[contractAddress];
    }

    // ========================================================================
    // = Upgrades =============================================================
    // ========================================================================

    // solhint-disable no-empty-blocks
    ///@dev required override by the OpenZeppelin UUPS module
    function _authorizeUpgrade(
        address
    ) internal view override onlyRole(DEVOPS_ROLE) {}
    // solhint-enable no-empty-blocks
}

