//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermRepoLocker} from "./interfaces/ITermRepoLocker.sol";
import {ITermRepoLockerErrors} from "./interfaces/ITermRepoLockerErrors.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {TermContractsPausable} from "./lib/TermContractsPausable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Repo Locker
/// @notice This is the contract in which Term Servicer locks collateral and purchase tokens
/// @dev This contract belongs to the Term Servicer group of contracts and is specific to a Term Repo deployment
contract TermRepoLocker is
    ITermRepoLocker,
    ITermRepoLockerErrors,
    Initializable,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    TermContractsPausable,
    Versionable
{
    using SafeERC20 for IERC20;

    // ========================================================================
    // = Access Roles =========================================================
    // ========================================================================
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");
    bytes32 public constant SERVICER_ROLE = keccak256("SERVICER_ROLE");

    // ========================================================================
    // = State Variables ======================================================
    // ========================================================================
    bytes32 public termRepoId;
    bool public transfersPaused;
    // Boolean indicating if term contracts paired
    bool internal termContractPaired;
    ITermEventEmitter internal emitter;
    ITermRepoServicer internal termRepoServicer;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================

    modifier whileTransfersNotPaused() {
        if (transfersPaused) {
            revert TermRepoLockerTransfersPaused();
        }
        _;
    }

    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string calldata termRepoId_,
        address termInitializer_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();

        termRepoId = keccak256(abi.encodePacked(termRepoId_));

        transfersPaused = false;

        _grantRole(INITIALIZER_ROLE, termInitializer_);
    }

    function pairTermContracts(
        address termRepoCollateralManager_,
        address termRepoServicer_,
        ITermEventEmitter emitter_,
        address devopsMultisig_,
        address adminWallet_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        emitter = emitter_;
        termRepoServicer = ITermRepoServicer(termRepoServicer_);

        _grantRole(SERVICER_ROLE, termRepoCollateralManager_);
        _grantRole(SERVICER_ROLE, termRepoServicer_);
        _grantRole(DEVOPS_ROLE, devopsMultisig_);
        _grantRole(ADMIN_ROLE, adminWallet_);

        emitter.emitTermRepoLockerInitialized(termRepoId, address(this));
    }

    /// @notice Locks tokens from origin wallet
    /// @notice Reverts if caller doesn't have SERVICER_ROLE
    /// @param originWallet The wallet from which to transfer tokens
    /// @param token The address of token being transferred
    /// @param amount The amount of tokens to transfer
    function transferTokenFromWallet(
        address originWallet,
        address token,
        uint256 amount
    )
        external
        override
        whileTransfersNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        onlyRole(SERVICER_ROLE)
    {
        IERC20 tokenInstance = IERC20(token);

        // slither-disable-start arbitrary-send-erc20
        /// @dev This function is permissioned to be only callable by other term contracts. The entry points of calls that end up utilizing this function all use Authenticator to
        /// authenticate that the caller is the owner of the token whose approved this contract to spend the tokens. Therefore there is no risk of another wallet using this function
        /// to transfer somebody else's tokens.
        tokenInstance.safeTransferFrom(originWallet, address(this), amount);
        // slither-disable-end arbitrary-send-erc20
    }

    /// @notice Unlocks tokens to destination wallet
    /// @dev Reverts if caller doesn't have SERVICER_ROLE
    /// @param destinationWallet The wallet to unlock tokens into
    /// @param token The address of token being unlocked
    /// @param amount The amount of tokens to unlock
    function transferTokenToWallet(
        address destinationWallet,
        address token,
        uint256 amount
    )
        external
        override
        whileTransfersNotPaused
        whileTermContractsNotPaused(termRepoServicer.termController())
        onlyRole(SERVICER_ROLE)
    {
        IERC20 tokenInstance = IERC20(token);

        tokenInstance.safeTransfer(destinationWallet, amount);
    }

    // ========================================================================
    // = Pause Functions ======================================================
    // ========================================================================

    function pauseTransfers() external onlyRole(ADMIN_ROLE) {
        transfersPaused = true;
        emitter.emitTermRepoLockerTransfersPaused(termRepoId);
    }

    function unpauseTransfers() external onlyRole(ADMIN_ROLE) {
        transfersPaused = false;
        emitter.emitTermRepoLockerTransfersUnpaused(termRepoId);
    }

    ///@dev required override by the OpenZeppelin UUPS module
    ///@param impl new impl address for proxy upgrade
    function _authorizeUpgrade(
        address impl
    ) internal override onlyRole(DEVOPS_ROLE) {
        emitter.emitTermContractUpgraded(address(this), impl);
    }
}

contracts/TermRepoRolloverManager.sol.content:
//SPDX-License-Identifier: Unlicense
pragma solidity ^0.8.22;

import {ITermAuctionBidLocker} from "./interfaces/ITermAuctionBidLocker.sol";
import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {ITermRepoRolloverManager} from "./interfaces/ITermRepoRolloverManager.sol";
import {ITermRepoRolloverManagerErrors} from "./interfaces/ITermRepoRolloverManagerErrors.sol";
import {ITermRepoCollateralManager} from "./interfaces/ITermRepoCollateralManager.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {ITermController} from "./interfaces/ITermController.sol";
import {ExponentialNoError} from "./lib/ExponentialNoError.sol";
import {TermAuctionBid} from "./lib/TermAuctionBid.sol";
import {TermRepoRolloverElection} from "./lib/TermRepoRolloverElection.sol";
import {TermRepoRolloverElectionSubmission} from "./lib/TermRepoRolloverElectionSubmission.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Repo Rollover Manager
/// @notice This contract accepts and carries out borrower Term Repo rollover instructions
/// @dev This contract belongs to the Term Servicer group of contracts and is specific to a Term Repo deployment
contract TermRepoRolloverManager is
    ITermRepoRolloverManager,
    ITermRepoRolloverManagerErrors,
    ExponentialNoError,
    Initializable,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    Versionable
{
    // ========================================================================
    // = Access Role  =========================================================
    // ========================================================================

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");
    bytes32 public constant ROLLOVER_BID_FULFILLER_ROLE =
        keccak256("ROLLOVER_BID_FULFILLER_ROLE");
    bytes32 public constant DIAMOND_ROLE = keccak256("DIAMOND_ROLE");

    // ========================================================================
    // = State Variables ======================================================
    // ========================================================================
    bytes32 public termRepoId;
    ITermRepoCollateralManager internal termRepoCollateralManager;
    ITermRepoServicer internal termRepoServicer;
    ITermController public termController;
    ITermEventEmitter internal emitter;

    // Mapping that returns true for approved Borrower Rollover Auction Bid Lockers
    mapping(address => bool) internal approvedRolloverAuctionBidLockers;

    // Borrow Rollover Ledger
    // For each borrower wallet address, keep ledger of borrow rollver election addresses.
    mapping(address => TermRepoRolloverElection) internal rolloverElections;

    bool internal termContractPaired;

    // ========================================================================
    // = Modifiers ============================================================
    // ========================================================================

    modifier notPastRepaymentWindow() {
        // solhint-disable-next-line not-rely-on-time
        if (block.timestamp >= termRepoServicer.endOfRepurchaseWindow()) {
            revert EndOfRepurchaseWindowReached();
        }
        _;
    }

    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string calldata termRepoId_,
        ITermRepoServicer termRepoServicer_,
        ITermRepoCollateralManager termRepoCollateralManager_,
        ITermController termController_,
        address termInitializer_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();

        termRepoId = keccak256(abi.encodePacked(termRepoId_));
        termRepoCollateralManager = termRepoCollateralManager_;
        termRepoServicer = termRepoServicer_;
        termController = termController_;

        termContractPaired = false;

        _grantRole(INITIALIZER_ROLE, termInitializer_);
    }

    function pairTermContracts(
        address termRepoServicer_,
        address termDiamond_,
        ITermEventEmitter emitter_,
        address devopsMultisig_,
        address adminWallet_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        emitter = emitter_;
        _grantRole(ROLLOVER_BID_FULFILLER_ROLE, termRepoServicer_);
        _grantRole(DEVOPS_ROLE, devopsMultisig_);
        _grantRole(ADMIN_ROLE, adminWallet_);
        _grantRole(DIAMOND_ROLE, termDiamond_);

        emitter.emitTermRepoRolloverManagerInitialized(
            termRepoId,
            address(this)
        );
    }

    // ========================================================================
    // = APIs  ================================================================
    // ========================================================================

    /// @notice An external function that accepted Term Repo rollover instructions
    /// @param termRepoRolloverElectionSubmission A struct containing borrower rollover instructions
    function electRollover(
        TermRepoRolloverElectionSubmission
            calldata termRepoRolloverElectionSubmission
    ) external notPastRepaymentWindow {
        _electRolloverInternal(msg.sender, termRepoRolloverElectionSubmission);
    }

    /// @notice Allows DIAMOND_ROLE to elect rollover on behalf of a borrower
    /// @param borrower The address of the borrower for whom rollover is being elected
    /// @param termRepoRolloverElectionSubmission A struct containing borrower rollover instructions
    function electRollover(
        address borrower,
        TermRepoRolloverElectionSubmission
            calldata termRepoRolloverElectionSubmission
    ) external notPastRepaymentWindow onlyRole(DIAMOND_ROLE) {
        _electRolloverInternal(borrower, termRepoRolloverElectionSubmission);
    }

    /// @notice A view function that returns borrower rollover instructions
    /// @param borrower The address of the borrower
    /// @return A struct containing borrower rollover instructions
    function getRolloverInstructions(
        address borrower
    ) external view returns (TermRepoRolloverElection memory) {
        return rolloverElections[borrower];
    }

    /// @notice An external function to cancel previously submitted rollover instructions
    function cancelRollover() external {
        address borrower = msg.sender;
        _cancelRolloverInternal(borrower);
    }

    /// @notice Allows DIAMOND_ROLE to cancel rollover on behalf of a borrower
    /// @param borrower The address of the borrower for whom rollover is being cancelled
    function cancelRollover(address borrower) external onlyRole(DIAMOND_ROLE) {
        _cancelRolloverInternal(borrower);
    }

    // ========================================================================
    // = Fulfiller Functions ================================================
    // ========================================================================

    /// @notice An external function called by repo servicer to mark rollover as fulfilled
    /// @param borrower The address of the borrower
    function fulfillRollover(
        address borrower
    ) external onlyRole(ROLLOVER_BID_FULFILLER_ROLE) {
        rolloverElections[borrower].processed = true;
        emitter.emitRolloverProcessed(termRepoId, borrower);
    }

    // ========================================================================
    // = Admin Functions ======================================================
    // ========================================================================

    /// @param auctionBidLocker The ABI for ITermAuctionBidLocker interface
    function approveRolloverAuction(
        ITermAuctionBidLocker auctionBidLocker
    ) external notPastRepaymentWindow onlyRole(ADMIN_ROLE) {
        if (
            !termController.isTermDeployed(address(auctionBidLocker)) &&
            !termController.isFactoryDeployed(address(auctionBidLocker))
        ) {
            revert NotTermContract(address(auctionBidLocker));
        }

        if (
            auctionBidLocker.auctionEndTime() >=
            termRepoServicer.endOfRepurchaseWindow()
        ) {
            revert AuctionEndsAfterRepayment();
        }
        if (
            auctionBidLocker.auctionEndTime() <
            termRepoServicer.maturityTimestamp()
        ) {
            revert AuctionEndsBeforeMaturity();
        }
        if (
            termRepoServicer.purchaseToken() !=
            address(auctionBidLocker.purchaseToken())
        ) {
            revert DifferentPurchaseToken(
                termRepoServicer.purchaseToken(),
                address(auctionBidLocker.purchaseToken())
            );
        }

        uint256 numOfAcceptedCollateralTokens = termRepoCollateralManager
            .numOfAcceptedCollateralTokens();

        for (uint256 i = 0; i < numOfAcceptedCollateralTokens; ++i) {
            IERC20 supportedIERC20Collateral = IERC20(
                termRepoCollateralManager.collateralTokens(i)
            );
            if (!auctionBidLocker.collateralTokens(supportedIERC20Collateral)) {
                revert CollateralTokenNotSupported(
                    address(supportedIERC20Collateral)
                );
            }
        }

        approvedRolloverAuctionBidLockers[address(auctionBidLocker)] = true;

        address termAuction = address(auctionBidLocker.termAuction());

        termRepoServicer.approveRolloverAuction(termAuction);
        termRepoCollateralManager.approveRolloverAuction(termAuction);

        _grantRole(ROLLOVER_BID_FULFILLER_ROLE, termAuction);

        emitter.emitRolloverTermApproved(
            termRepoId,
            auctionBidLocker.termAuctionId()
        );
    }

    /// @param auctionBidLocker The ABI for ITermAuctionBidLocker interface
    function revokeRolloverApproval(
        ITermAuctionBidLocker auctionBidLocker
    ) external onlyRole(ADMIN_ROLE) {
        approvedRolloverAuctionBidLockers[address(auctionBidLocker)] = false;

        emitter.emitRolloverTermApprovalRevoked(
            termRepoId,
            auctionBidLocker.termAuctionId()
        );
    }

    // ========================================================================
    // = Internal =============================================================
    // ========================================================================

    function _electRolloverInternal(
        address borrower,
        TermRepoRolloverElectionSubmission
            calldata termRepoRolloverElectionSubmission
    ) internal {
        uint256 borrowerRepurchaseObligation = termRepoServicer
            .getBorrowerRepurchaseObligation(borrower);
        if (borrowerRepurchaseObligation == 0) {
            revert ZeroBorrowerRepurchaseObligation();
        }
        if (
            !approvedRolloverAuctionBidLockers[
                termRepoRolloverElectionSubmission.rolloverAuctionBidLocker
            ]
        ) {
            revert RolloverAddressNotApproved(
                termRepoRolloverElectionSubmission.rolloverAuctionBidLocker
            );
        }

        if (rolloverElections[borrower].processed) {
            revert RolloverProcessedToTerm();
        }

        if (termRepoRolloverElectionSubmission.rolloverAmount == 0) {
            revert InvalidParameters("Rollover amount cannot be 0");
        }

        if (
            borrowerRepurchaseObligation <
            termRepoRolloverElectionSubmission.rolloverAmount
        ) {
            revert BorrowerRepurchaseObligationInsufficient();
        }

        if (
            rolloverElections[borrower].rolloverAuctionBidLocker !=
            address(0) &&
            rolloverElections[borrower].rolloverAuctionBidLocker !=
            termRepoRolloverElectionSubmission.rolloverAuctionBidLocker
        ) {
            rolloverElections[borrower].rolloverAmount = 0;
            _processRollover(borrower);
        }

        rolloverElections[borrower] = TermRepoRolloverElection({
            rolloverAuctionBidLocker: termRepoRolloverElectionSubmission
                .rolloverAuctionBidLocker,
            rolloverAmount: termRepoRolloverElectionSubmission.rolloverAmount,
            rolloverBidPriceHash: termRepoRolloverElectionSubmission
                .rolloverBidPriceHash,
            processed: false
        });

        ITermAuctionBidLocker auctionBidLocker = ITermAuctionBidLocker(
            termRepoRolloverElectionSubmission.rolloverAuctionBidLocker
        );

        emitter.emitRolloverElection(
            termRepoId,
            auctionBidLocker.termRepoId(),
            borrower,
            termRepoRolloverElectionSubmission.rolloverAuctionBidLocker,
            termRepoRolloverElectionSubmission.rolloverAmount,
            termRepoRolloverElectionSubmission.rolloverBidPriceHash
        );

        _processRollover(borrower);
    }

    function _cancelRolloverInternal(address borrower) internal {
        if (termRepoServicer.getBorrowerRepurchaseObligation(borrower) == 0) {
            revert ZeroBorrowerRepurchaseObligation();
        }

        if (rolloverElections[borrower].rolloverAmount == 0) {
            revert NoRolloverToCancel();
        }

        if (rolloverElections[borrower].processed) {
            revert RolloverProcessedToTerm();
        }

        rolloverElections[borrower].rolloverAmount = 0;

        _processRollover(borrower);

        delete rolloverElections[borrower];

        emitter.emitRolloverCancellation(termRepoId, borrower);
    }

    function _processRollover(address borrowerToRollover) internal {
        TermRepoRolloverElection memory rolloverElection = rolloverElections[
            borrowerToRollover
        ];

        ITermAuctionBidLocker termAuctionBidLocker = ITermAuctionBidLocker(
            rolloverElection.rolloverAuctionBidLocker
        );

        ITermRepoServicer futureTermRepoServicer = termAuctionBidLocker
            .termRepoServicer();

        uint256 servicingFeeProRatedMantissa = mul_(
            Exp({mantissa: termAuctionBidLocker.dayCountFractionMantissa()}),
            Exp({mantissa: futureTermRepoServicer.servicingFee()})
        ).mantissa;

        uint256 bidAmount;

        if (rolloverElection.rolloverAmount > 0) {
            bidAmount = truncate(
                div_(
                    Exp({mantissa: rolloverElection.rolloverAmount * expScale}),
                    Exp({mantissa: expScale - servicingFeeProRatedMantissa})
                )
            );
        } else {
            bidAmount = 0;
        }

        (address[] memory collateralTokens, ) = termRepoCollateralManager
            .getCollateralBalances(borrowerToRollover);

        uint256[] memory collateralAmounts = new uint256[](
            collateralTokens.length
        );

        TermAuctionBid memory termAuctionBid = TermAuctionBid({
            id: keccak256(abi.encodePacked(address(this), borrowerToRollover)),
            bidder: borrowerToRollover,
            bidPriceHash: rolloverElection.rolloverBidPriceHash,
            bidPriceRevealed: 0,
            amount: bidAmount,
            collateralTokens: collateralTokens,
            collateralAmounts: collateralAmounts,
            purchaseToken: termRepoServicer.purchaseToken(),
            isRollover: true,
            rolloverPairOffTermRepoServicer: address(termRepoServicer),
            isRevealed: false
        });

        termAuctionBidLocker.lockRolloverBid(termAuctionBid);
    }

    ///@dev required override by the OpenZeppelin UUPS module
    ///@param impl new impl address for proxy upgrade
    function _authorizeUpgrade(
        address impl
    ) internal override onlyRole(DEVOPS_ROLE) {
        emitter.emitTermContractUpgraded(address(this), impl);
    }
}

contracts/TermRepoServicer.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ITermEventEmitter} from "./interfaces/ITermEventEmitter.sol";
import {ITermRepoServicer} from "./interfaces/ITermRepoServicer.sol";
import {ITermRepoServicerErrors} from "./interfaces/ITermRepoServicerErrors.sol";
import {ITermController} from "./interfaces/ITermController.sol";
import {ITermRepoCollateralManager} from "./interfaces/ITermRepoCollateralManager.sol";
import {ITermRepoLocker} from "./interfaces/ITermRepoLocker.sol";
import {ITermRepoRolloverManager} from "./interfaces/ITermRepoRolloverManager.sol";
import {ITermRepoToken} from "./interfaces/ITermRepoToken.sol";
import {ExponentialNoError} from "./lib/ExponentialNoError.sol";
import {TermAuctionGroup} from "./lib/TermAuctionGroup.sol";
import {TermRepoRolloverElection} from "./lib/TermRepoRolloverElection.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {Versionable} from "./lib/Versionable.sol";

/// @author TermLabs
/// @title Term Repo Servicer
/// @notice This contract maintains records, collects and disburse repurchase payments
/// @dev This contract belongs to the Term Servicer group of contracts and is specific to a Term Repo deployment
contract TermRepoServicer is
    ITermRepoServicer,
    ITermRepoServicerErrors,
    Initializable,
    UUPSUpgradeable,
    AccessControlUpgradeable,
    ExponentialNoError,
    Versionable
{
    // ========================================================================
    // = Constants  ===========================================================
    // ========================================================================
    uint256 public constant YEAR_SECONDS = 60 * 60 * 24 * 360;

    // ========================================================================
    // = Access Roles  ========================================================
    // ========================================================================

    bytes32 public constant AUCTION_LOCKER = keccak256("AUCTION_LOCKER");
    bytes32 public constant AUCTIONEER = keccak256("AUCTIONEER");
    bytes32 public constant COLLATERAL_MANAGER =
        keccak256("COLLATERAL_MANAGER");
    bytes32 public constant DEVOPS_ROLE = keccak256("DEVOPS_ROLE");
    bytes32 public constant ROLLOVER_MANAGER = keccak256("ROLLOVER_MANAGER");
    bytes32 public constant ROLLOVER_TARGET_AUCTIONEER_ROLE =
        keccak256("ROLLOVER_TARGET_AUCTIONEER_ROLE");
    bytes32 public constant INITIALIZER_ROLE = keccak256("INITIALIZER_ROLE");
    bytes32 public constant DIAMOND_ROLE = keccak256("DIAMOND_ROLE");

    // ========================================================================
    // = State Variables  =====================================================
    // ========================================================================

    bytes32 public termRepoId;

    // Total Repurchase Price Owed by all borrowers
    uint256 public totalOutstandingRepurchaseExposure;

    // Total Repurchase Currency locked by TermLocker
    uint256 public totalRepurchaseCollected;

    // block timestamp at which repurchase is due
    uint256 public maturityTimestamp;

    //block timestamp at which repurchase period ends
    uint256 public endOfRepurchaseWindow;

    /// block timestamp at which term repo tokens can be redeemed
    uint256 public redemptionTimestamp;

    /// percentage share of bid amounts charged to bidder
    uint256 public servicingFee;

    /// proportion of redemption value for redemption
    uint256 public shortfallHaircutMantissa;

    /// threshold for determining whether term repo is balanced
    uint256 public termRepoBalancedThreshold;

    // token used for purchase/loans
    address public purchaseToken;

    // collateral manager in same term
    ITermRepoCollateralManager public termRepoCollateralManager;

    // rollover manager in same term
    ITermRepoRolloverManager public termRepoRolloverManager;

    // TermRepoLocker for term funds
    ITermRepoLocker public termRepoLocker;

    // TermRepoToken for current term
    ITermRepoToken public termRepoToken;

    // global term controller contract
    ITermController public termController;

    // global term event emitter
    ITermEventEmitter internal emitter;

    // Repurchase Exposure Ledger
    // For each borrower wallet address, keep ledger of repurchase obligations
    mapping(address => uint256) internal repurchaseExposureLedger;

    bool internal termContractPaired;

    // ========================================================================
    // = Modifiers  ===========================================================
    // ========================================================================
    modifier notTermContractPaired() {
        if (termContractPaired) {
            revert AlreadyTermContractPaired();
        }
        termContractPaired = true;
        _;
    }

    // ========================================================================
    // = Deploy  ==============================================================
    // ========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string calldata termRepoId_,
        uint256 maturityTimestamp_,
        uint256 repurchaseWindow_,
        uint256 redemptionBuffer_,
        uint256 servicingFee_,
        address purchaseToken_,
        ITermController termController_,
        ITermEventEmitter emitter_,
        address termInitializer_
    ) external initializer {
        UUPSUpgradeable.__UUPSUpgradeable_init();
        AccessControlUpgradeable.__AccessControl_init();

        termRepoId = keccak256(abi.encodePacked(termRepoId_));
        totalOutstandingRepurchaseExposure = 0;
        totalRepurchaseCollected = 0;
        maturityTimestamp = maturityTimestamp_;
        endOfRepurchaseWindow = maturityTimestamp_ + repurchaseWindow_;
        redemptionTimestamp =
            maturityTimestamp_ +
            repurchaseWindow_ +
            redemptionBuffer_;
        servicingFee = servicingFee_;

        require(purchaseToken_ != address(0), "Zero address purchase token");
        purchaseToken = purchaseToken_;
        IERC20Metadata purchaseTokenInstance = IERC20Metadata(purchaseToken_);
        uint8 purchaseTokenDecimals = purchaseTokenInstance.decimals();
        termRepoBalancedThreshold =
            10 **
                (purchaseTokenDecimals / 4 < 2 ? 2 : purchaseTokenDecimals / 4);

        termController = termController_;
        emitter = emitter_;

        termContractPaired = false;

        _grantRole(INITIALIZER_ROLE, termInitializer_);
    }

    function pairTermContracts(
        address termRepoLocker_,
        address termRepoCollateralManager_,
        address termRepoToken_,
        address termDiamond_,
        address termAuctionOfferLocker_,
        address termAuction_,
        address rolloverManager_,
        address devopsMultisig_,
        address deployerWallet_,
        string calldata version_
    ) external onlyRole(INITIALIZER_ROLE) notTermContractPaired {
        require(deployerWallet_ != address(0), "Zero address deployer wallet");
        termRepoLocker = ITermRepoLocker(termRepoLocker_);
        termRepoCollateralManager = ITermRepoCollateralManager(
            termRepoCollateralManager_
        );
        termRepoRolloverManager = ITermRepoRolloverManager(rolloverManager_);
        termRepoToken = ITermRepoToken(termRepoToken_);

        _grantRole(AUCTION_LOCKER, termAuctionOfferLocker_);
        _grantRole(AUCTIONEER, termAuction_);
        _grantRole(DEVOPS_ROLE, devopsMultisig_);
        _grantRole(COLLATERAL_MANAGER, termRepoCollateralManager_);
        _grantRole(ROLLOVER_MANAGER, rolloverManager_);
        _grantRole(DIAMOND_ROLE, termDiamond_);

        emitter.emitTermRepoServicerInitialized(
            termRepoId,
            address(this),
            purchaseToken,
            maturityTimestamp,
            endOfRepurchaseWindow,
            redemptionTimestamp,
            servicingFee,
            deployerWallet_,
            version_
        );
    }

