//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IWETHWrappingFacet {
    function unwrapETH(
        uint256 amount,
        address wrappedTokenAddr,
        bool usePermit2
    ) external;
}

/// @title TestETHRejecter
/// @notice Contract with no receive/fallback that calls unwrapETH.
/// @dev When the facet tries to send ETH back to this contract, it fails.
contract TestETHRejecter {
    function callUnwrapETH(
        address facet,
        uint256 amount,
        address wrappedTokenAddr,
        bool usePermit2
    ) external {
        // Approve WETH to facet so safeTransferFrom succeeds
        IERC20(wrappedTokenAddr).approve(facet, amount);
        IWETHWrappingFacet(facet).unwrapETH(
            amount,
            wrappedTokenAddr,
            usePermit2
        );
    }
}

contracts/test/TestInconsistentVault.sol.content:
//SPDX-License-Identifier: CC-BY-NC-ND-4.0
pragma solidity ^0.8.22;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";

/// @notice Vault that is internally inconsistent with shares burned
contract TestInconsistentVault is ERC20Upgradeable, IERC4626 {
    address private _asset;

    function initialize(
        address asset_,
        string memory name_,
        string memory symbol_
    ) public initializer {
        __ERC20_init(name_, symbol_);
        _asset = asset_;
    }

    function asset() external view returns (address) {
        return _asset;
    }

    function totalAssets() external view returns (uint256) {
        return IERC20(_asset).balanceOf(address(this));
    }

    function convertToShares(uint256 assets) public pure returns (uint256) {
        return assets;
    }

    function convertToAssets(uint256 shares) public pure returns (uint256) {
        return shares;
    }

    function maxDeposit(address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function maxMint(address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function maxWithdraw(address owner) external view returns (uint256) {
        return balanceOf(owner);
    }

    function maxRedeem(address owner) external view returns (uint256) {
        return balanceOf(owner);
    }

    function previewDeposit(uint256 assets) external pure returns (uint256) {
        return assets;
    }

    function previewMint(uint256 shares) external pure returns (uint256) {
        return shares;
    }

    function previewWithdraw(uint256 assets) external pure returns (uint256) {
        return assets;
    }

    function previewRedeem(uint256 shares) external pure returns (uint256) {
        return shares;
    }

    function deposit(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares) {
        shares = assets;
        IERC20(_asset).transferFrom(msg.sender, address(this), assets);
        _mint(receiver, shares);
        emit Deposit(msg.sender, receiver, assets, shares);
    }

    function mint(
        uint256 shares,
        address receiver
    ) external returns (uint256 assets) {
        assets = shares;
        IERC20(_asset).transferFrom(msg.sender, address(this), assets);
        _mint(receiver, shares);
        emit Deposit(msg.sender, receiver, assets, shares);
    }

    // Inconsistent: returns different shares burned than actually burned
    function withdraw(
        uint256 assets,
        address receiver,
        address owner
    ) external returns (uint256 shares) {
        uint256 actualSharesBurned = assets;
        uint256 reportedShares = (assets * 110) / 100; // Report 10% more shares burned

        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, actualSharesBurned);
        }
        _burn(owner, actualSharesBurned);
        IERC20(_asset).transfer(receiver, assets);

        shares = reportedShares; // Return inconsistent value
        emit Withdraw(msg.sender, receiver, owner, assets, actualSharesBurned);
    }

    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) external returns (uint256 assets) {
        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }
        assets = shares;
        uint256 reportedShares = (assets * 90) / 100; // Report 10% more shares burned
        _burn(owner, reportedShares);

        IERC20(_asset).transfer(receiver, assets);
        emit Withdraw(msg.sender, receiver, owner, assets, reportedShares);
    }
}

