        address borrower,
        address token,
        uint256 amount
    ) external {
        _collateralBalances[borrower][token] = amount;
    }

    function getCollateralBalance(
        address borrower,
        address token
    ) external view returns (uint256) {
        return _collateralBalances[borrower][token];
